-- بيانات مقرر فيزياء 1 (المقرر 101، قيد الإعداد) — الجزء 2 من 2. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-phys1-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L1-O30'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما قوة الجاذبية الأرضية (الوزن)؟', null, null, '["قوة مجال تنتج عن الجاذبية الأرضية بين جسمين","قوة تلامس يؤثر بها سطح في جسم موضوع عليه","ممانعة الجسم لأي تغيير في حالته الحركية","كمية المادة في الجسم، وتقاس بالكيلوجرام"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 103 — جدول بعض أنواع القوى: الوزن (Weight)'),
('mcq', 2, 'أفلتّ كتابًا من يدك فسقط نحو الأرض. ما مسبّب قوة الجاذبية الأرضية التي تؤثر في الكتاب؟', null, null, '["الهواء المحيط بالكتاب","يدك التي كانت تمسك الكتاب","كتلة الأرض التي تجذب الكتاب","سرعة الكتاب في أثناء سقوطه"]'::jsonb, 'تذكر', 'تحديد المسبب', 'سهل', 'الكتاب ص 97 — المسبب في حالة الجاذبية الأرضية'),
('mcq', 3, 'متى تؤثر قوة الجاذبية الأرضية في كتاب؟', null, null, '["في أثناء سقوطه سقوطًا حرًّا فقط","عندما يكون ملامسًا لسطح الأرض فقط","عندما يكون متحركًا إلى أسفل فقط","سواء كان ساكنًا على طاولة أم ساقطًا في الهواء"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 96 و105 — قوة الجاذبية تؤثر سواء وُجد تلامس أم لا'),
('mcq', 4, 'لماذا تُصنَّف قوة الجاذبية الأرضية قوة مجال؟', null, null, '["لأنها تنشأ عن تلامس الجسم مع سطح الأرض","لأنها تؤثر في الأجسام دون حاجة إلى تلامس بينها","لأنها تؤثر في الأجسام المتحركة فقط","لأن مقدارها متساوٍ لجميع الأجسام"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 96–97 — قوى المجال: الجاذبية الأرضية ومسببها'),
('mcq', 5, 'يبيّن الشكل الآتي يدًا تدفع كتابًا على سطح طاولة، ومخطط الجسم الحر للكتاب بثلاثة أسهم مرقمة. أيّ الأسهم يمثل قوة الجاذبية الأرضية، وما مسببها؟', null, '[{"src":"qimg/phys1/c4l1-o30-book-table.svg","alt":"على اليسار طاولة عليها كتاب، وتلامس الكتاب من جهته اليسرى يد تدفعه، وتحتها عبارة: يد تدفع كتابًا على طاولة. على اليمين مخطط جسم حر: نقطة يخرج منها ثلاثة أسهم زرقاء: السهم 1 إلى أعلى، والسهم 2 أفقي نحو اليمين وهو أقصر، والسهم 3 إلى أسفل مساوٍ للسهم 1 طولًا."}]'::jsonb, '["السهم 3، ومسببه سطح الطاولة","السهم 1، ومسببه كتلة الأرض","السهم 3، ومسببه كتلة الأرض","السهم 2، ومسببه اليد"]'::jsonb, 'تطبيق', 'تفسير مخطط', 'متوسط', 'الكتاب ص 96–97 — قوى المجال: الجاذبية الأرضية ومسببها'),
('mcq', 6, 'تفاحة معلقة ساكنة بغصن شجرة. قوة الجاذبية الأرضية المؤثرة فيها تنتج عن الجاذبية بين أيّ جسمين؟', null, null, '["التفاحة والأرض","التفاحة والغصن","الغصن والأرض","التفاحة والهواء المحيط بها"]'::jsonb, 'فهم', 'تحديد طرفي القوة', 'صعب', 'الكتاب ص 103 — جدول بعض أنواع القوى: الوزن (Weight)'),
('mcq', 7, 'قوة الجاذبية الأرضية المؤثرة في شخص كتلته 70 kg تساوي 686 N. ماذا يمثّل المقدار 686 N؟', null, null, '["كتلة الشخص مقيسة بوحدة النيوتن","القصور الذاتي للشخص","التسارع الذي يكتسبه الشخص إذا سقط","وزن الشخص، أي قوة جذب الأرض له"]'::jsonb, 'فهم', 'تفسير قيمة', 'سهل', 'الكتاب ص 100 — جدول القوى الشائعة'),
('essay', 1, 'عرّف قوة الجاذبية الأرضية، ثم أجب: (أ) هل هي قوة تلامس أم قوة مجال؟ ولماذا؟ (ب) ما مسببها؟ (ج) هل تؤثر في كتاب ساكن على طاولة؟ وضّح.', null, null, null, 'فهم', 'تعريف وتفسير', 'متوسط', 'الكتاب ص 96–97 — قوى المجال: الجاذبية الأرضية ومسببها'),
('essay', 2, 'يبيّن الشكل الآتي تفاحتين متماثلتين: (a) معلقة ساكنة بغصن شجرة، و(b) سقطت من الغصن وهي تتحرك نحو الأرض. (أ) هل تؤثر قوة الجاذبية الأرضية في كلٍّ من التفاحتين؟ (ب) ما مسببها في الحالتين؟ (ج) ما القوة الأخرى التي تؤثر في التفاحة (a) فقط، وما نوعها؟ (د) لماذا تسقط التفاحة (b) ولا تسقط التفاحة (a)؟ (أهمل مقاومة الهواء)', null, '[{"src":"qimg/phys1/c4l1-o30-apple.svg","alt":"شكلان متجاوران. الشكل (a): غصن شجرة تتدلى منه تفاحة خضراء معلقة بعنقها، وتحتها سطح الأرض. الشكل (b): غصن شجرة وتفاحة خضراء في الهواء بين الغصن والأرض، وبجانبها سهم أحمر إلى أسفل مكتوب عنده v، وتحتها سطح الأرض."}]'::jsonb, null, 'تطبيق', 'مقارنة حالتين', 'متوسط', 'الكتاب ص 96–97 — قوى المجال: الجاذبية الأرضية ومسببها'),
('essay', 3, 'أرسلت مركبة مجسًّا إلى سطح القمر، فقال طالب: «سجّل الميزان النابضي على القمر قراءة أقل؛ إذن فقدَ المجسّ جزءًا من كتلته». (أ) ما الذي يقيسه الميزان النابضي فعلًا؟ (ب) قيّم عبارة الطالب. (ج) ما الذي تغيّر بانتقال المجسّ من الأرض إلى القمر ولماذا؟', null, null, null, 'تقويم', 'تقييم عبارة', 'صعب', 'الكتاب ص 105 — الوزن على القمر والموازين')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O30') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الوزن (قوة الجاذبية الأرضية) قوة مجال تنتج عن الجاذبية الأرضية بين جسمين، كالأرض والجسم.', '["","هذا وصف القوة العمودية، وهي قوة تلامس.","هذا تعريف القصور الذاتي، وهو ليس قوة.","هذا وصف الكتلة، وهي ليست قوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-19T07:48:34.566Z"}'::jsonb),
('mcq', 2, 2, 'عندما يسقط الكتاب من يدك يكون المسبب كتلة الأرض التي تؤثر بقوة مجال في الكتاب.', '["الهواء قد يؤثر بقوة مقاومة، لكنه ليس مسبب قوة الجاذبية.","اليد لم تعد تلامس الكتاب بعد إفلاته، فلا تؤثر فيه.","","السرعة ليست قوة ولا مسببًا لقوة؛ إنها نتيجة لتسارع الكتاب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.567Z"}'::jsonb),
('mcq', 3, 3, 'قوة الجاذبية الأرضية تؤثر في الكتاب سواء كان في حالة تلامس مع الأرض أم لا، وتؤثر في الجسم حتى لو لم يسقط سقوطًا حرًّا؛ فهي تؤثر فيه سواء كان ساكنًا على طاولة أم ساقطًا في الهواء.', '["قوة الجاذبية تؤثر في الجسم حتى لو لم يسقط سقوطًا حرًّا، كالكتاب الساكن على الطاولة.","قوة الجاذبية قوة مجال لا تحتاج إلى تلامس، فتؤثر في الكتاب وهو في الهواء.","تؤثر قوة الجاذبية في الجسم مهما كان اتجاه حركته، وحتى إذا كان ساكنًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-19T07:48:34.567Z"}'::jsonb),
('mcq', 4, 1, 'قوة المجال تؤثر في الأجسام بغض النظر عن وجود تلامس بينها من عدمه، والجاذبية الأرضية تؤثر في الكتاب سواء لامس الأرض أم لا، فهي قوة مجال.', '["لو احتاجت إلى تلامس لكانت قوة تلامس؛ والجاذبية تؤثر في الأجسام الساقطة في الهواء.","","الجاذبية تؤثر في الأجسام الساكنة أيضًا.","مقدار الوزن يختلف باختلاف كتلة الجسم، وليس هذا سبب التصنيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-19T07:48:34.567Z"}'::jsonb),
('mcq', 5, 2, 'قوة الجاذبية الأرضية تتجه إلى أسفل وهي السهم 3، ومسببها كتلة الأرض التي تؤثر بقوة مجال في الكتاب.', '["السهم 3 هو قوة الجاذبية فعلًا، لكن مسببها كتلة الأرض لا الطاولة؛ فالطاولة تؤثر بقوة إلى أعلى.","السهم 1 يتجه إلى أعلى، وهو القوة التي تؤثر بها الطاولة في الكتاب.","","السهم 2 هو قوة اليد (قوة تلامس)، لا قوة الجاذبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.567Z"}'::jsonb),
('mcq', 6, 0, 'الوزن قوة مجال تنتج عن الجاذبية بين جسمين، وفي هذه الحالة هما التفاحة (النظام) والأرض (المسبب بكتلتها).', '["","الغصن يلامس التفاحة ويؤثر فيها بقوة تلامس إلى أعلى، وليس هو مسبب الوزن.","هذه القوة تؤثر في الغصن لا في التفاحة.","الهواء لا يسبب قوة الجاذبية الأرضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.567Z"}'::jsonb),
('mcq', 7, 3, 'قوة الجاذبية الأرضية المؤثرة في الشخص هي وزنه، وهي قوة تقاس بالنيوتن، ومقدارها هنا 686 N.', '["الكتلة تقاس بالكيلوجرام (70 kg) وليست قوة.","القصور الذاتي ممانعة الجسم لتغيير حالته الحركية، وليس قوة ولا يقاس بالنيوتن.","التسارع يقاس بوحدة m/s² لا بالنيوتن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.567Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوة الجاذبية الأرضية (الوزن) قوة مجال تنتج عن الجاذبية الأرضية بين جسمين. (أ) قوة مجال؛ لأنها تؤثر في الأجسام سواء كانت في حالة تلامس مع الأرض أم لا. (ب) مسببها كتلة الأرض. (ج) نعم، تؤثر فيه؛ فقوة الجاذبية تؤثر في الجسم حتى لو لم يسقط سقوطًا حرًّا، والكتاب لا يسقط لأن الطاولة تؤثر فيه بقوة إلى أعلى.', '["التعريف","قوة مجال مع التعليل","المسبب: كتلة الأرض","تؤثر في الكتاب الساكن مع التوضيح"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"النوع والتعليل","marks":1.5},{"element":"المسبب","marks":1},{"element":"الكتاب الساكن","marks":1.5}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–4 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيفها قوة تلامس","القول إنها لا تؤثر إلا في الأجسام الساقطة","جعل المسبب الهواء أو الطاولة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.568Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نعم، تؤثر قوة الجاذبية الأرضية في التفاحتين؛ لأنها تؤثر في الجسم سواء لامس شيئًا أم لا، وسواء سقط أم لم يسقط. (ب) المسبب في الحالتين كتلة الأرض. (ج) تؤثر في التفاحة (a) قوة يؤثر بها الغصن (عنق التفاحة) إلى أعلى، وهي قوة تلامس. (د) في (a) تتوازن قوة الغصن إلى أعلى مع قوة الجاذبية إلى أسفل فتبقى ساكنة، وفي (b) لا يلامسها شيء، فقوة الجاذبية هي القوة الوحيدة، فتتسارع إلى أسفل.', '["الجاذبية تؤثر في الحالتين","المسبب كتلة الأرض","قوة الغصن قوة تلامس","تفسير السقوط بالقوة الوحيدة غير الموازنة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2},{"element":"(د)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الجاذبية لا تؤثر في التفاحة المعلقة","عدّ قوة الغصن قوة مجال","تفسير السقوط بزوال الغصن دون ذكر القوة المحصلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.568Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) يقيس الميزان النابضي الوزن، أي قوة الجاذبية المؤثرة في الجسم، لأن قوة النابض تساوي مقدار الوزن عند الاتزان. (ب) العبارة خاطئة؛ فكتلة المجسّ (كمية المادة فيه) لم تتغير، والكتلة ليست قوة. (ج) تغيّر وزنه؛ لأن قوة الجاذبية تنتج عن الجاذبية بين الجسم والكوكب الذي يوجد عليه، وقيمة $g$ على سطح القمر أقل كثيرًا منها على سطح الأرض، فيصبح الوزن على القمر أقل إلى نحو السدس رغم أن الكتلة لم تتغير.', '["الميزان يقيس الوزن","الكتلة لم تتغير","الوزن تغيّر بسبب اختلاف جاذبية القمر"]'::jsonb, '[]'::jsonb, '[{"element":"ما يقيسه الميزان","marks":1.5},{"element":"تقييم العبارة","marks":1.5},{"element":"تفسير التغير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–4 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الكتلة والوزن","القول إن الجاذبية تنعدم على القمر","القول إن الكتلة تقل لأن الوزن قل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-19T07:48:34.569Z"}'::jsonb)
