from (values
('mcq', 1, 'ما اتجاه قوة الجاذبية الأرضية المؤثرة في جسم قريب من سطح الأرض؟', null, null, '["في اتجاه حركة الجسم دائمًا","عمودي على سطح التلامس للخارج","إلى أسفل في اتجاه مركز الأرض","إلى أعلى بعيدًا عن مركز الأرض"]'::jsonb, 'تذكر', 'تذكر اتجاه', 'سهل', 'الكتاب ص 103 — جدول بعض أنواع القوى: الوزن (Weight)'),
('mcq', 2, 'قُذفت كرة رأسيًّا إلى أعلى. ما اتجاه قوة الجاذبية الأرضية المؤثرة فيها وهي صاعدة؟ (أهمل مقاومة الهواء)', null, null, '["إلى أسفل، كما هي في أثناء هبوطها","إلى أعلى، في اتجاه حركتها","لا تؤثر فيها حتى تبدأ بالهبوط","أفقي، عمودي على اتجاه حركتها"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 103 — جدول بعض أنواع القوى: الوزن (Weight)'),
('mcq', 3, 'يمثّل كل شكل من الأشكال الآتية الأرض وثلاثة أجسام عند مواقع مختلفة حولها، مع أسهم لقوة الجاذبية الأرضية المؤثرة فيها. أيّ الأشكال يمثل اتجاهات قوة الجاذبية تمثيلًا صحيحًا؟', null, '[{"src":"qimg/phys1/c4l1-o31-earth-panels.svg","alt":"أربعة أشكال مرقمة، في كل منها دائرة خضراء تمثل الأرض بنقطة في مركزها، وثلاث نقاط سوداء على محيطها: أعلاها، وعلى يمينها، وأسفل يسارها، ولكل نقطة سهم أزرق. الشكل (1): الأسهم الثلاثة رأسية نحو أسفل الصفحة. الشكل (2): الأسهم الثلاثة تتجه للخارج بعيدًا عن المركز. الشكل (3): الأسهم الثلاثة تتجه نحو مركز الدائرة. الشكل (4): الأسهم الثلاثة مماسية للدائرة."}]'::jsonb, '["الشكل (1)","الشكل (3)","الشكل (2)","الشكل (4)"]'::jsonb, 'فهم', 'اختيار شكل', 'صعب', 'الكتاب ص 103 — جدول بعض أنواع القوى: الوزن (Weight)'),
('mcq', 4, 'كرة تسقط سقوطًا حرًّا قرب سطح الأرض. ما اتجاه كلٍّ من قوة الجاذبية الأرضية المؤثرة فيها وتسارعها؟', null, null, '["القوة إلى أسفل، والتسارع إلى أعلى","القوة إلى أعلى، والتسارع إلى أسفل","القوة إلى أسفل، والتسارع صفر","القوة والتسارع كلاهما إلى أسفل"]'::jsonb, 'فهم', 'ربط القوة بالتسارع', 'متوسط', 'الكتاب ص 105 — استخدام قانون نيوتن الثاني (الشكل 4-8)'),
('mcq', 5, 'صندوق ساكن على سطح مائل يميل بزاوية $30^\circ$ عن الأفقي، ومن مركزه أربعة أسهم مرقمة كما في الشكل الآتي. أيّ الأسهم يمثل اتجاه قوة الجاذبية الأرضية المؤثرة في الصندوق؟', null, '[{"src":"qimg/phys1/c4l1-o31-incline-dirs.svg","alt":"سطح مائل يرتفع نحو اليمين بزاوية 30° عند قاعدته اليسرى، وعليه صندوق مربع ساكن، ومن مركز الصندوق أربعة أسهم زرقاء متساوية الطول: السهم 1 رأسي إلى أسفل، والسهم 2 عمودي على السطح المائل نحو داخله (إلى أسفل يمينًا)، والسهم 3 موازٍ للسطح نحو أسفل الميل (إلى اليسار)، والسهم 4 عمودي على السطح المائل للخارج (إلى أعلى يسارًا)."}]'::jsonb, '["السهم 1","السهم 2","السهم 3","السهم 4"]'::jsonb, 'تطبيق', 'تحديد اتجاه من شكل', 'متوسط', 'الكتاب ص 103 — جدول بعض أنواع القوى: الوزن (Weight)'),
('mcq', 6, 'كرة معلقة بخيط وساكنة. ما اتجاه كلٍّ من قوة الجاذبية الأرضية وقوة الشد المؤثرتين فيها؟', null, null, '["كلتاهما إلى أسفل","الجاذبية إلى أعلى، والشد إلى أسفل","الجاذبية إلى أسفل، والشد إلى أعلى","كلتاهما إلى أعلى"]'::jsonb, 'فهم', 'تحديد اتجاه', 'سهل', 'الكتاب ص 103 — جدول بعض أنواع القوى: الوزن (Weight)'),
('mcq', 7, 'اختير الاتجاه $+y$ إلى أعلى لدراسة حركة جسم. ما إشارة قوة الجاذبية الأرضية المؤثرة في الجسم في معادلات الحركة؟', null, null, '["موجبة؛ لأن مقدار القوة لا يكون سالبًا","موجبة إذا كان الجسم صاعدًا، وسالبة إذا كان هابطًا","صفر عندما يكون الجسم ساكنًا على الأرض","سالبة؛ لأنها إلى أسفل عكس الاتجاه الموجب"]'::jsonb, 'تطبيق', 'تحديد الإشارة', 'متوسط', 'الكتاب ص 97 و108 — اختيار الاتجاه الموجب وإشارة الوزن'),
('essay', 1, 'بيّن اتجاه قوة الجاذبية الأرضية المؤثرة في كل جسم مما يأتي: (أ) كتاب ساكن على طاولة. (ب) مظلي يهبط بسرعة منتظمة. (ج) صندوق على سطح مائل. ثم فسّر لماذا يكون اتجاهها واحدًا في الحالات الثلاث رغم اختلاف حركة الأجسام والسطوح.', null, null, null, 'فهم', 'تحديد اتجاه وتفسير', 'متوسط', 'الكتاب ص 103 — جدول بعض أنواع القوى: الوزن (Weight)'),
('essay', 2, 'يبيّن الشكل الآتي الأرض وثلاثة أشخاص A وB وC يقفون عند مواقع مختلفة على سطحها. (أ) صف اتجاه قوة الجاذبية الأرضية المؤثرة في كل شخص بالنسبة إلى الشكل (إلى أسفل الصفحة، نحو اليسار، ...). (ب) لماذا يشعر كل منهم أن قوة الجاذبية «إلى أسفل» رغم اختلاف الاتجاهات في الشكل؟ (ج) ماذا تستنتج عن معنى عبارة «إلى أسفل» في وصف اتجاه الوزن؟', null, '[{"src":"qimg/phys1/c4l1-o31-earth-people.svg","alt":"دائرة خضراء كبيرة تمثل الأرض، وفي مركزها نقطة مكتوب عندها: مركز الأرض. على محيطها ثلاث نقاط برتقالية تمثل أشخاصًا: A أعلى الدائرة، وB على يمين الدائرة، وC أسفل الدائرة."}]'::jsonb, null, 'تطبيق', 'تحليل شكل', 'صعب', 'الكتاب ص 103 — جدول بعض أنواع القوى: الوزن (Weight)'),
('essay', 3, 'قارن بين اتجاه قوة الجاذبية الأرضية واتجاه السرعة المتجهة لكرة في الحالات الآتية (أهمل مقاومة الهواء): (أ) تسقط من السكون. (ب) قُذفت رأسيًّا إلى أعلى وما زالت صاعدة. (ج) تتدحرج على أرض أفقية. ثم استنتج: هل يعتمد اتجاه قوة الجاذبية على اتجاه حركة الجسم؟', null, null, null, 'تحليل', 'مقارنة واستنتاج', 'صعب', 'الكتاب ص 103 و105 — اتجاه الوزن')
