('mcq', 2, 0, 'قوة الجاذبية الأرضية تتجه دائمًا إلى أسفل نحو مركز الأرض؛ فهي إلى أسفل والكرة صاعدة، كما هي في أثناء هبوطها، ولذلك تتباطأ الكرة وهي صاعدة.', '["","اتجاه الجاذبية لا يتبع اتجاه الحركة؛ ولو كانت إلى أعلى لازدادت سرعة الكرة الصاعدة.","الجاذبية تؤثر في الكرة طوال الوقت، وهي سبب تباطئها في أثناء الصعود.","قوة الجاذبية رأسية إلى أسفل نحو مركز الأرض لا أفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-19T07:48:34.570Z"}'::jsonb),
('mcq', 3, 1, 'قوة الجاذبية الأرضية تتجه نحو مركز الأرض، فيكون «أسفل» عند كل موقع هو الاتجاه نحو المركز؛ وهذا ما في الشكل (3) حيث تتجه الأسهم الثلاثة نحو مركز الدائرة.', '["في الشكل (1) تتجه الأسهم كلها نحو أسفل الصفحة لا نحو مركز الأرض، وهذا خطأ عند الجسمين الجانبي والسفلي.","","في الشكل (2) تتجه الأسهم بعيدًا عن مركز الأرض.","في الشكل (4) الأسهم مماسية للدائرة لا نحو المركز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.570Z"}'::jsonb),
('mcq', 4, 3, 'في السقوط الحر تكون قوة الجاذبية الأرضية هي القوة الوحيدة، وتتجه إلى أسفل، والتسارع في اتجاه القوة المحصلة، فالقوة والتسارع كلاهما إلى أسفل.', '["التسارع في اتجاه القوة المحصلة، والمحصلة هنا هي الوزن المتجه إلى أسفل.","قوة الجاذبية تتجه إلى أسفل نحو مركز الأرض لا إلى أعلى.","الكرة تؤثر فيها قوة محصلة غير صفرية، فتسارعها لا يساوي صفرًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-19T07:48:34.570Z"}'::jsonb),
('mcq', 5, 0, 'قوة الجاذبية الأرضية تتجه رأسيًّا إلى أسفل نحو مركز الأرض مهما كان ميل السطح، وهذا هو السهم 1.', '["","السهم 2 عمودي على السطح المائل نحو داخله، لكن الجاذبية رأسية لا عمودية على السطح.","السهم 3 موازٍ للسطح إلى أسفل الميل، وليس رأسيًّا.","السهم 4 عمودي على السطح للخارج، وهو اتجاه القوة العمودية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.570Z"}'::jsonb),
('mcq', 6, 2, 'قوة الجاذبية الأرضية إلى أسفل نحو مركز الأرض، وقوة الشد تؤثر موازية للخيط ومبتعدة عن الجسم، أي إلى أعلى؛ ولأن الكرة ساكنة فالقوتان متساويتان مقدارًا.', '["الشد يؤثر موازيًا للخيط ومبتعدًا عن الجسم، فهو إلى أعلى هنا.","الاتجاهان مقلوبان؛ فالجاذبية نحو مركز الأرض.","","الجاذبية لا تتجه إلى أعلى أبدًا قرب سطح الأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.570Z"}'::jsonb),
('mcq', 7, 3, 'قوة الجاذبية الأرضية تتجه دائمًا إلى أسفل، فإذا اختير الاتجاه إلى أعلى موجبًا كانت إشارتها سالبة مهما كانت حركة الجسم.', '["المقدار موجب، لكن الإشارة في المعادلات تعبّر عن الاتجاه بالنسبة إلى المحور المختار.","اتجاه الجاذبية لا يتغير بتغير اتجاه الحركة، فلا تتغير إشارتها.","قوة الجاذبية تؤثر في الجسم الساكن أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.571Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في الحالات الثلاث تتجه قوة الجاذبية الأرضية رأسيًّا إلى أسفل نحو مركز الأرض. (أ) إلى أسفل. (ب) إلى أسفل. (ج) رأسيًّا إلى أسفل وليس عموديًّا على السطح المائل. والتفسير: قوة الجاذبية قوة مجال مسببها كتلة الأرض، فهي تجذب كل جسم نحو مركز الأرض، ولا يعتمد اتجاهها على حركة الجسم ولا على السطح الذي يلامسه.', '["(أ) إلى أسفل","(ب) إلى أسفل","(ج) رأسيًّا لا عموديًّا على السطح","التفسير: نحو مركز الأرض بغض النظر عن الحركة والسطح"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–4 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الوزن عموديًّا على السطح المائل","جعل الوزن إلى أعلى للمظلي لأنه يهبط بسرعة منتظمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.571Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الشخص A (أعلى الأرض): قوة الجاذبية نحو أسفل الصفحة. الشخص B (يمين الأرض): نحو اليسار. الشخص C (أسفل الأرض): نحو أعلى الصفحة. (ب) لأن قوة الجاذبية عند كل موقع تتجه نحو مركز الأرض، أي نحو الأرض التي يقف عليها الشخص، فيراها كل منهم «إلى أسفل» نحو قدميه. (ج) «إلى أسفل» تعني في اتجاه مركز الأرض، لا اتجاهًا ثابتًا في الفضاء.', '["اتجاه A","اتجاه B","اتجاه C","التفسير بالاتجاه نحو المركز","الاستنتاج"]'::jsonb, '[]'::jsonb, '[{"element":"A","marks":1},{"element":"B","marks":1},{"element":"C","marks":1},{"element":"التفسير","marks":1.5},{"element":"الاستنتاج","marks":1.5}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الأسهم الثلاثة نحو أسفل الصفحة","القول إن الشخص C يسقط بعيدًا عن الأرض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.571Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) السرعة المتجهة إلى أسفل، وقوة الجاذبية إلى أسفل (في اتجاه واحد). (ب) السرعة المتجهة إلى أعلى، وقوة الجاذبية إلى أسفل (متعاكسان)، ولذلك تتباطأ الكرة. (ج) السرعة المتجهة أفقية، وقوة الجاذبية رأسية إلى أسفل (متعامدان). الاستنتاج: اتجاه قوة الجاذبية الأرضية ثابت دائمًا إلى أسفل نحو مركز الأرض، ولا يعتمد على اتجاه حركة الجسم.', '["(أ) متفقان","(ب) متعاكسان","(ج) متعامدان","الاستنتاج"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1.5},{"element":"(ج)","marks":1.5},{"element":"الاستنتاج","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الجاذبية إلى أعلى في أثناء الصعود","القول إن الجاذبية لا تؤثر في الكرة المتدحرجة أفقيًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-19T07:48:34.572Z"}'::jsonb)
