('mcq', 2, 1, 'الحرف السفلي $g$ يشير إلى الجاذبية، فالرمز $\boldsymbol{F}_{g}$ يعني القوة الناتجة عن الجاذبية الأرضية، تمييزًا لها عن القوى الأخرى.', '["القوة تقاس بالنيوتن، والجرام وحدة كتلة.","","الكتلة رمزها m وليست جزءًا من رمز القوة.","قوة الجاذبية كمية متجهة، ولذلك يُكتب رمزها بخط عريض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.572Z"}'::jsonb),
('mcq', 3, 0, '$\boldsymbol{g}$ تسارع الجاذبية الأرضية (يساوي تقريبًا 9.80 m/s² قرب سطح الأرض)، و$\boldsymbol{F}_{g}$ قوة الجاذبية الأرضية (الوزن) وتقاس بالنيوتن، ويرتبطان بالعلاقة $\boldsymbol{F}_{g} = m\boldsymbol{g}$.', '["","المعنيان مقلوبان.","الرمزان لكميتين مختلفتين: تسارع وقوة.","$g$ ليس رمز الكتلة؛ الكتلة رمزها $m$ وتقاس بالكيلوجرام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.573Z"}'::jsonb),
('mcq', 4, 2, 'السهم 2 يتجه إلى أسفل ويمثل قوة الجاذبية الأرضية المؤثرة في الكرة، ورمزها $\boldsymbol{F}_{g}$.', '["$\\boldsymbol{F}_{\\text{thrust}}$ رمز قوة الدفع، ولا يوجد ما يدفع الكرة.","$\\boldsymbol{F}_{\\text{N}}$ رمز القوة العمودية التي يؤثر بها سطح، والكرة لا تستند إلى سطح.","","$\\boldsymbol{F}_{\\text{T}}$ رمز الشد، وهو مكتوب فعلًا عند السهم المتجه إلى أعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.573Z"}'::jsonb),
('mcq', 5, 1, 'تؤثر في الشخص قوة النابض إلى أعلى (موجبة) وقوة الجاذبية الأرضية إلى أسفل (سالبة)، ولأنه متزن فالمحصلة صفر: $F_{\text{sp}} - F_{g} = 0$، أي أن قوة النابض تساوي مقدار الوزن.', '["$F_{\\text{T}}$ رمز الشد، ولا يوجد حبل؛ والقوة إلى أسفل هي الوزن.","","$g$ تسارع وليس قوة، فلا يُطرح من قوة.","بالمقادير يجب طرح الوزن لأنه في الاتجاه السالب؛ والجمع يعني أن القوتين في الاتجاه نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.573Z"}'::jsonb),
('mcq', 6, 3, 'الوزن رمزه $\boldsymbol{F}_{g}$، وهو قوة مجال تنتج عن الجاذبية الأرضية، واتجاهه إلى أسفل نحو مركز الأرض.', '["هذا وصف القوة العمودية.","الرمز والاتجاه صحيحان، لكن الوزن قوة مجال لا تلامس.","النوع والاتجاه صحيحان، لكن $\\boldsymbol{g}$ رمز التسارع لا القوة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.573Z"}'::jsonb),
('mcq', 7, 0, '$\boldsymbol{F}_{g}$ في مخطط الجسم الحر للكتاب هو قوة الجاذبية الأرضية التي تؤثر بها الأرض في الكتاب، أي وزن الكتاب.', '["","قوة الكتاب في الطاولة تؤثر في الطاولة لا في الكتاب، فلا تُرسم في مخطط الجسم الحر للكتاب.","قوة الطاولة في الكتاب هي $\\boldsymbol{F}_{\\text{N}}$ المتجهة إلى أعلى.","مخطط الجسم الحر يحوي قوى فقط؛ والتسارع ليس قوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.573Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوة الجاذبية الأرضية: $\boldsymbol{F}_{g}$، كمية متجهة، وحدتها N. تسارع الجاذبية الأرضية: $\boldsymbol{g}$، كمية متجهة، وحدتها m/s². الكتلة: $m$، كمية قياسية، وحدتها kg. ولذلك يُكتب الرمزان الأولان بخط عريض والثالث بخط مائل عادي.', '["الرموز الثلاثة","تصنيف متجه/قياسي","الوحدات"]'::jsonb, '[]'::jsonb, '[{"element":"الرموز","marks":1.5},{"element":"التصنيف","marks":1.5},{"element":"الوحدات","marks":1.5}]'::jsonb, '[{"level":"4.5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–3.5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الوزن $g$","عدّ الكتلة كمية متجهة","قياس الوزن بالكيلوجرام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4.5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.573Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) السهم 1: قوة الدفع $\boldsymbol{F}_{\text{thrust}}$، مسببها محرك الطائرة المسيّرة (مراوحها). السهم 2: قوة الجاذبية الأرضية (الوزن) $\boldsymbol{F}_{g}$، مسببها كتلة الأرض. (ب) لأن الطائرة ترتفع بسرعة متجهة منتظمة، فتسارعها صفر والقوة المحصلة صفر، فالقوتان متساويتان مقدارًا. (ج) $F_{\text{المحصلة}} = F_{\text{thrust}} - F_{g} = 0$.', '["تسمية السهمين برموزهما ومسببيهما","تعليل تساوي الطولين","العلاقة بالرموز والإشارات"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":1.5},{"element":"(ج)","marks":1.5}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–4 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الوزن $\\boldsymbol{g}$ بدل $\\boldsymbol{F}_{g}$","رسم سهم الدفع أطول لأن الطائرة تتحرك إلى أعلى","جمع الوزن مع الدفع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.574Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأخطاء: (1) الرمز $g$ رمز تسارع الجاذبية الأرضية لا الوزن؛ رمز الوزن $\boldsymbol{F}_{g}$ ويُكتب بخط عريض لأنه متجه. (2) الوحدة kg وحدة الكتلة، والوزن قوة تقاس بالنيوتن N. الكتابة الصحيحة: «وزن الحقيبة $F_{g} = 49\ \text{N}$» (أو: كتلة الحقيبة $m = 5.0\ \text{kg}$ إذا كان المقصود الكتلة). العلاقة: $\boldsymbol{F}_{g} = m\boldsymbol{g}$، فالوزن يساوي الكتلة مضروبة في تسارع الجاذبية الأرضية.', '["خطأ الرمز","خطأ الوحدة","الكتابة الصحيحة","العلاقة بين الوزن والكتلة"]'::jsonb, '[]'::jsonb, '[{"element":"الرمز","marks":1.5},{"element":"الوحدة","marks":1.5},{"element":"الكتابة الصحيحة","marks":1},{"element":"العلاقة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–4 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح الوحدة دون الرمز","القول إن الوزن والكتلة كمية واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.574Z"}'::jsonb)
