('mcq', 3, 'ما القوة المحصلة التي تؤثر في كرة كتلتها 0.50 kg تسقط سقوطًا حرًّا؟ ($g = 9.80\ \text{m/s}^2$)', null, null, '["4.9 N","0.50 N","0 N","0.051 N"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 105 و125 — استخدام قانون نيوتن الثاني، إتقان حل المسائل'),
('mcq', 4, 'يبيّن الشكل الآتي النموذجين التصويري والفيزيائي لكرة تسقط سقوطًا حرًّا. لماذا يساوي تسارع الكرة $g$؟', null, '[{"src":"qimg/phys1/c4l1-o33-freefall.svg","alt":"على اليسار كرة تحيط بها دائرة متقطعة مكتوب عندها: النظام، وبجانبها سهم أحمر إلى أسفل مكتوب عنده v، وسهم بنفسجي إلى أسفل مكتوب عنده a. وتحتها عبارة: كرة تسقط سقوطًا حرًّا. على اليمين مخطط جسم حر: نقطة يخرج منها سهم أزرق واحد إلى أسفل مكتوب عنده F_g، وفي الأسفل سهم صغير إلى أعلى مكتوب عنده +y."}]'::jsonb, '["لأن سرعة الكرة المتجهة ثابتة في أثناء السقوط","لأن الكرة لا تؤثر فيها أي قوة في أثناء سقوطها","لأن قوة الجاذبية الأرضية هي القوة الوحيدة المؤثرة فيها","لأن كتلة الكرة صغيرة جدًّا مقارنة بكتلة الأرض"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 105 — استخدام قانون نيوتن الثاني (الشكل 4-8)'),
('mcq', 5, 'كرتان تسقطان سقوطًا حرًّا، كتلة الثانية مثلا كتلة الأولى. كيف تقارن قوة الجاذبية المؤثرة في كل منهما وتسارع كل منهما؟', null, null, '["قوتاهما متساويتان، وتسارع الثانية نصف تسارع الأولى","قوة الثانية مثلا قوة الأولى، وتسارعهما متساويان","قوة الثانية مثلا قوة الأولى، وتسارعها مثلا تسارع الأولى","قوتاهما متساويتان، وتسارعهما متساويان"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 105 — استخدام قانون نيوتن الثاني (الشكل 4-8)'),
('mcq', 6, 'على سطح القمر يكون مقدار $g$ أقل كثيرًا منه على سطح الأرض. ماذا يحدث لقوة الجاذبية المؤثرة في جسم نُقل من الأرض إلى القمر؟', null, null, '["تقل؛ لأن $g$ أصغر والكتلة ثابتة","تقل؛ لأن كتلة الجسم تقل على القمر","لا تتغير؛ لأن الكتلة لا تتغير","تزداد؛ لأن الجسم يصبح أخف"]'::jsonb, 'فهم', 'تطبيق علاقة', 'متوسط', 'الكتاب ص 105 — استخدام قانون نيوتن الثاني (الشكل 4-8)'),
('mcq', 7, 'صخرة كتلتها 2.0 kg، ومقدار قوة الجاذبية الأرضية المؤثرة فيها 19.6 N. ما تسارعها عندما تسقط سقوطًا حرًّا؟', null, null, '["0.10 m/s²","39 m/s²","9.8 m/s²","19.6 m/s²"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 105 — استخدام قانون نيوتن الثاني (الشكل 4-8)'),
('essay', 1, 'استنتج صيغة قوة الجاذبية الأرضية $\boldsymbol{F}_{g} = m\boldsymbol{g}$ من قانون نيوتن الثاني لكرة كتلتها m تسقط سقوطًا حرًّا، موضحًا: (أ) القوى المؤثرة في الكرة. (ب) القوة المحصلة. (ج) تسارع الكرة. (د) خطوات الاستنتاج. (هـ) اتجاه كل من القوة والتسارع.', null, null, null, 'فهم', 'استنتاج', 'صعب', 'الكتاب ص 105 — استخدام قانون نيوتن الثاني (الشكل 4-8)'),
('essay', 2, 'كرة كتلتها 1.0 kg. (أ) احسب القوة المحصلة المؤثرة فيها وهي تسقط سقوطًا حرًّا. (ب) وُضعت الكرة نفسها ساكنة على طاولة: هل تتغير قوة الجاذبية الأرضية المؤثرة فيها؟ ولماذا؟ (ج) ما القوة المحصلة المؤثرة فيها وهي على الطاولة؟ ولماذا لا تساوي وزنها في هذه الحالة؟ ($g = 9.80\ \text{m/s}^2$)', null, null, null, 'تطبيق', 'حساب وتفسير', 'متوسط', 'الكتاب ص 105 و125 — إتقان حل المسائل (48)'),
('essay', 3, 'رائد فضاء كتلته 60.0 kg. (أ) احسب وزنه على سطح الأرض ($g = 9.80\ \text{m/s}^2$). (ب) احسب وزنه على سطح القمر حيث مقدار تسارع الجاذبية 1.62 m/s². (ج) ما كتلته على القمر؟ (د) استخدم نتائجك لتفسير سبب تمكّنه من القفز أعلى على القمر بسرعة الانطلاق نفسها.', null, null, null, 'تحليل', 'حساب ومقارنة', 'صعب', 'الكتاب ص 105 و128 — الوزن على القمر')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O33') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الكرة لا تلامس شيئًا، ومقاومة الهواء مهملة، فالقوة المحصلة هي قوة الجاذبية الأرضية $\boldsymbol{F}_{g}$ وحدها.', '["عدم التلامس يلغي قوى التلامس فقط؛ وقوة الجاذبية قوة مجال تؤثر دون تلامس.","","مقاومة الهواء مهملة في السقوط الحر.","لا تؤثر في الكرة بعد إفلاتها أي قوة دفع؛ فاليد لم تعد تلامسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.575Z"}'::jsonb),
('mcq', 2, 3, 'بالتعويض: $\boldsymbol{g} = \frac{\boldsymbol{F}_{g}}{m}$، وبضرب الطرفين في $m$ نحصل على $\boldsymbol{F}_{g} = m\boldsymbol{g}$.', '["قُسمت الكتلة على التسارع بدل ضربها فيه.","قُلبت العلاقة؛ القسمة على الكتلة تعطي التسارع لا القوة.","الكتلة تساوي القوة مقسومة على التسارع لا مضروبة فيه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.575Z"}'::jsonb),
('mcq', 3, 0, '$F_{\text{المحصلة}} = F_{g} = mg = (0.50\ \text{kg})(9.80\ \text{m/s}^2) = 4.9\ \text{N}$ إلى أسفل.', '["","استُخدمت الكتلة على أنها قوة دون ضربها في $g$.","القوة المحصلة لا تساوي صفرًا؛ فالجاذبية وحدها تؤثر في الكرة.","قُسمت الكتلة على $g$ بدل ضربها فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.575Z"}'::jsonb),
('mcq', 4, 2, 'قوة الجاذبية الأرضية هي القوة الوحيدة المؤثرة في الكرة، فتكون هي القوة المحصلة، والتسارع الذي تُكسبه للكرة هو تسارع السقوط الحر $\boldsymbol{g}$؛ ولذلك $\boldsymbol{F}_{g} = m\boldsymbol{g}$.', '["السرعة المتجهة تتزايد في السقوط الحر؛ ولو كانت ثابتة لكان التسارع صفرًا.","تؤثر في الكرة قوة الجاذبية الأرضية؛ ولولاها لما تسارعت.","","صغر الكتلة لا يحدد التسارع؛ فكل الأجسام في السقوط الحر تتسارع بالمقدار $g$ نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.575Z"}'::jsonb),
('mcq', 5, 1, '$F_{g} = mg$، فمضاعفة الكتلة تضاعف قوة الجاذبية، أي أن قوة الثانية مثلا قوة الأولى. والتسارع $a = \frac{F_{g}}{m} = \frac{2mg}{2m} = g$ للكرتين، فتسارعهما متساويان.', '["قوة الجاذبية تتناسب مع الكتلة، فلا تتساوى القوتان.","","مضاعفة القوة يقابلها مضاعفة الكتلة، فيبقى التسارع $g$.","القوتان غير متساويتين لأن الكتلتين مختلفتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.576Z"}'::jsonb),
('mcq', 6, 0, '$F_{g} = mg$، والكتلة لا تتغير بتغير المكان، و$g$ على القمر أصغر، فتقل قوة الجاذبية (الوزن) إلى أقل من السدس تقريبًا.', '["","الكتلة كمية المادة في الجسم ولا تتغير بنقله إلى القمر.","ثبات الكتلة لا يعني ثبات الوزن؛ فالوزن يعتمد على $g$ أيضًا.","الشعور بالخفة سببه نقص الوزن لا زيادته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.576Z"}'::jsonb),
('mcq', 7, 2, '$a = \frac{F_{g}}{m} = \frac{19.6\ \text{N}}{2.0\ \text{kg}} = 9.8\ \text{m/s}^2$، وهو تسارع السقوط الحر $g$.', '["قُسمت الكتلة على القوة بدل قسمة القوة على الكتلة.","ضُربت القوة في الكتلة بدل القسمة عليها.","","أُخذ مقدار القوة على أنه التسارع دون القسمة على الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.576Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الكرة لا تلامس أي جسم، ومقاومة الهواء مهملة، فالقوة الوحيدة هي قوة الجاذبية الأرضية $\boldsymbol{F}_{g}$. (ب) $\boldsymbol{F}_{\text{المحصلة}} = \boldsymbol{F}_{g}$. (ج) تسارع الكرة هو تسارع السقوط الحر $\boldsymbol{a} = \boldsymbol{g}$. (د) $\boldsymbol{F}_{\text{المحصلة}} = m\boldsymbol{a}$، وبالتعويض: $\boldsymbol{F}_{g} = m\boldsymbol{g}$. (هـ) القوة والتسارع كلاهما إلى أسفل.', '["الجاذبية القوة الوحيدة","المحصلة = الوزن","التسارع $a = g$","التعويض في القانون","القوة والتسارع إلى أسفل"]'::jsonb, '["$\\boldsymbol{F}_{\\text{المحصلة}} = m\\boldsymbol{a}$","$\\boldsymbol{F}_{\\text{المحصلة}} = \\boldsymbol{F}_{g}$، $\\boldsymbol{a} = \\boldsymbol{g}$","$\\boldsymbol{F}_{g} = m\\boldsymbol{g}$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":2},{"element":"(هـ)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إضافة قوة هواء أو قوة دفع","عدم تبرير أن $a = g$","إهمال اتجاه القوة والتسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.577Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $F_{\text{المحصلة}} = F_{g} = mg = (1.0\ \text{kg})(9.80\ \text{m/s}^2) = 9.8\ \text{N}$ إلى أسفل. (ب) لا تتغير؛ فـ $F_{g} = mg$ يعتمد على الكتلة و$g$ فقط، وكلاهما لم يتغير، والجاذبية تؤثر في الجسم حتى لو لم يسقط سقوطًا حرًّا، فوزنها 9.8 N. (ج) القوة المحصلة صفر؛ لأن الكرة ساكنة (تسارعها صفر)، إذ تؤثر فيها الطاولة بقوة إلى أعلى تساوي وزنها، فلم تعد الجاذبية القوة الوحيدة.', '["حساب 9.8 N","الوزن لا يتغير مع التعليل","المحصلة صفر على الطاولة مع التعليل"]'::jsonb, '["$F_{g} = mg = (1.0)(9.80) = 9.8\\ \\text{N}$","على الطاولة: $F_{\\text{المحصلة}} = F_{\\text{N}} - F_{g} = 0$"]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الوزن يصبح صفرًا على الطاولة","الخلط بين الوزن والقوة المحصلة","كتابة 1.0 N"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-19T07:48:34.577Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $F_{g} = mg = (60.0)(9.80) = 588\ \text{N}$. (ب) $F_{g} = (60.0)(1.62) = 97.2\ \text{N}$. (ج) كتلته 60.0 kg لم تتغير. (د) وزنه على القمر أقل كثيرًا (نحو سدس وزنه على الأرض)، فالقوة التي تعيده إلى أسفل أصغر، والتسارع إلى أسفل $\frac{F_{g}}{m} = 1.62\ \text{m/s}^2$ أصغر، فيصل إلى ارتفاع أكبر قبل أن يتوقف.', '["588 N","97.2 N","الكتلة ثابتة 60.0 kg","التفسير بصغر الوزن والتسارع"]'::jsonb, '["على الأرض: $F_{g} = (60.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 588\\ \\text{N}$","على القمر: $F_{g} = (60.0\\ \\text{kg})(1.62\\ \\text{m/s}^2) = 97.2\\ \\text{N}$"]'::jsonb, '[{"element":"(أ)","marks":1.5},{"element":"(ب)","marks":1.5},{"element":"(ج)","marks":1},{"element":"(د)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكتلة تتغير على القمر","ضرب 60.0 في 9.80 ثم القسمة على 6 والتقريب الخاطئ","تفسير القفز بزيادة قوة العضلات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.577Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O33') and x.type = v.type and x.number = v.number
