select (select id from public.objectives where code = 'P1-C4-L1-O34'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أصيص أزهار يسقط سقوطًا حرًّا (أهمل مقاومة الهواء). أيّ مخططات الجسم الحر الآتية رُسم رسمًا صحيحًا؟', null, '[{"src":"qimg/phys1/c4l1-o34-pot-fbds.svg","alt":"أربعة مخططات جسم حر مرقمة لأصيص يسقط، وفي كل منها سهم صغير إلى أعلى مكتوب عنده +y. المخطط (1): نقطة منها سهم F_g إلى أسفل وسهم F_N مساوٍ له إلى أعلى. المخطط (2): سهم F_g فوق النقطة يتجه إلى أسفل وينتهي عند النقطة. المخطط (3): نقطة منها سهم واحد F_g إلى أسفل. المخطط (4): نقطة منها سهمان متجاوران إلى أسفل متساويان طولًا: F_g، وF مع الحرف السفلي «المحصلة»."}]'::jsonb, '["المخطط (1)","المخطط (2)","المخطط (3)","المخطط (4)"]'::jsonb, 'تطبيق', 'اختيار مخطط', 'سهل', 'الكتاب ص 97–98 — مخططات الجسم الحر، مسألة تدريبية 1'),
('mcq', 2, 'مظلي يهبط خلال الهواء بسرعة متجهة منتظمة، ويؤثر فيه الهواء بقوة معيقة $\boldsymbol{F}_{d}$ إلى أعلى. أيّ مخططات الجسم الحر الآتية رُسم رسمًا صحيحًا؟', null, '[{"src":"qimg/phys1/c4l1-o34-parachute-fbds.svg","alt":"أربعة مخططات جسم حر مرقمة لمظلي، وفي كل منها سهم صغير إلى أعلى مكتوب عنده +y. المخطط (1): نقطة منها سهم واحد F_g إلى أسفل. المخطط (2): سهم F_d إلى أعلى، وسهم F_g إلى أسفل مساوٍ له طولًا. المخطط (3): سهم F_d إلى أعلى قصير، وسهم F_g إلى أسفل أطول منه بكثير. المخطط (4): سهمان متجاوران كلاهما إلى أسفل متساويان طولًا: F_g وF_d."}]'::jsonb, '["المخطط (1)","المخطط (2)","المخطط (3)","المخطط (4)"]'::jsonb, 'تطبيق', 'اختيار مخطط', 'متوسط', 'الكتاب ص 98 و110 — مسألة تدريبية 2 (هبوط مظلي)، القوة المعيقة'),
('mcq', 3, 'سلك يسحب صندوقًا أفقيًّا نحو اليمين بسرعة متجهة منتظمة على سطح أفقي، والسطح يؤثر بقوة تقاوم حركة الصندوق. أيّ مخططات الجسم الحر الآتية رُسم رسمًا صحيحًا؟', null, '[{"src":"qimg/phys1/c4l1-o34-box-fbds.svg","alt":"أربعة مخططات جسم حر مرقمة لصندوق، في كل منها محوران صغيران +x نحو اليمين و+y إلى أعلى. المخطط (1): نقطة منها F_N إلى أعلى وF_g إلى أسفل متساويان، وF_T نحو اليمين، ولا يوجد سهم آخر أفقي. المخطط (2): F_N وF_g متساويان، وسهمان متوازيان نحو اليمين متساويان: F_T وf_f. المخطط (3): F_N إلى أعلى قصير وF_g إلى أسفل أطول منه، وF_T نحو اليمين وf_f نحو اليسار متساويان. المخطط (4): F_N وF_g متساويان، وF_T نحو اليمين وf_f نحو اليسار متساويان."}]'::jsonb, '["المخطط (1)","المخطط (2)","المخطط (3)","المخطط (4)"]'::jsonb, 'تطبيق', 'اختيار مخطط', 'متوسط', 'الكتاب ص 98 — مسألة تدريبية 3 (سلك يسحب صندوقًا)'),
('mcq', 4, 'دلو ماء يُرفع إلى أعلى بحبل، وسرعته تتناقص (أهمل مقاومة الهواء). أيّ مخططات الجسم الحر الآتية رُسم رسمًا صحيحًا؟', null, '[{"src":"qimg/phys1/c4l1-o34-bucket-fbds.svg","alt":"أربعة مخططات جسم حر مرقمة لدلو، وفي كل منها سهم صغير إلى أعلى مكتوب عنده +y. المخطط (1): سهم F_T إلى أعلى قصير، وسهم F_g إلى أسفل أطول منه. المخطط (2): F_T إلى أعلى وF_g إلى أسفل متساويان طولًا. المخطط (3): F_T إلى أعلى طويل، وF_g إلى أسفل أقصر منه. المخطط (4): F_T إلى أعلى قصير وF_g إلى أسفل أطول منه، وبجانب F_g سهم إضافي قصير إلى أسفل مكتوب عنده F مع الحرف السفلي «المحصلة»."}]'::jsonb, '["المخطط (1)","المخطط (2)","المخطط (3)","المخطط (4)"]'::jsonb, 'تطبيق', 'اختيار مخطط', 'صعب', 'الكتاب ص 104 — مراجعة 12 (دلو يُرفع بسرعة متناقصة)'),
('mcq', 5, 'رسم طالب مخطط الجسم الحر لكرة معلقة بخيط وساكنة كما في الشكل الآتي. ما الخطأ في رسمه؟', null, '[{"src":"qimg/phys1/c4l1-o34-ball-wrong.svg","alt":"على اليسار كرة معلقة بخيط رأسي مربوط بسقف، وتحتها عبارة: كرة معلقة ساكنة. على اليمين مخطط رسمه طالب: نقطة، وفوقها سهم أزرق مكتوب عنده F_T يبدأ من أعلى ويتجه إلى أسفل حتى ينتهي عند النقطة، وسهم أزرق آخر يبدأ من النقطة ويتجه إلى أسفل مكتوب عنده F_g. وفي الأسفل سهم صغير إلى أعلى مكتوب عنده +y."}]'::jsonb, '["يجب أن يتجه سهم قوة الجاذبية إلى أعلى ليوازن الشد","يجب إضافة سهم للقوة المحصلة إلى أسفل","سهم الشد يتجه نحو الجسم، والصحيح أن يبدأ منه ويتجه إلى أعلى","يجب إضافة قوة عمودية يؤثر بها الخيط في الكرة"]'::jsonb, 'تحليل', 'اكتشاف خطأ', 'متوسط', 'الكتاب ص 97–98 — مخططات الجسم الحر ومسائل تدريبية'),
('mcq', 6, 'ترفع بيدك كيسًا مملوءًا بالسكر إلى أعلى بسرعة متجهة منتظمة. أيّ وصف لمخطط الجسم الحر للكيس صحيح؟', null, null, '["سهم قوة اليد إلى أعلى (مسببها اليد)، وسهم الوزن إلى أسفل (مسببه كتلة الأرض)، متساويان طولًا","سهم قوة اليد إلى أعلى أطول من سهم الوزن إلى أسفل؛ لأن الكيس يتحرك إلى أعلى","سهم قوة اليد إلى أعلى، وسهم قوة الكيس في اليد إلى أسفل، متساويان طولًا","سهم واحد للوزن إلى أسفل فقط؛ لأن اليد جزء من النظام"]'::jsonb, 'تطبيق', 'وصف مخطط مع المسببات', 'صعب', 'الكتاب ص 104 — مراجعة 11 (كيس سكر يُرفع باليد)'),
('mcq', 7, 'أيّ مما يأتي يصف طريقة رسم مخطط الجسم الحر وصفًا صحيحًا؟', null, null, '["يُرسم الجسم كما هو، وتُرسم القوى التي يؤثر بها في الأجسام الأخرى","يُمثَّل الجسم بنقطة، وتُرسم الأسهم متجهة نحوه بأطوال متساوية","يُمثَّل الجسم بنقطة، وتُرسم القوة المحصلة سهمًا مع بقية القوى","يُمثَّل الجسم بنقطة، وكل قوة بسهم يبدأ منها ويتجه بعيدًا عنها بطول يتناسب مع مقدارها"]'::jsonb, 'فهم', 'خطوات إجرائية', 'سهل', 'الكتاب ص 97–98 — مخططات الجسم الحر ومسائل تدريبية'),
('essay', 1, 'يُنزَل دلو بحبل إلى أسفل بسرعة متجهة منتظمة (أهمل مقاومة الهواء). (أ) حدّد النظام والمحيط الخارجي. (ب) سمِّ جميع القوى المؤثرة في الدلو مع مسبب كل منها ونوعها (تلامس أو مجال). (ج) ارسم مخطط الجسم الحر محددًا الاتجاه الموجب ومراعيًا أطوال الأسهم. (د) ما القوة المحصلة؟', null, null, null, 'تطبيق', 'رسم مخطط', 'متوسط', 'الكتاب ص 98 — مسألة تدريبية 5 (إنزال دلو)'),
('essay', 2, 'تدفع بيدك صندوقًا أفقيًّا نحو اليمين على أرض أفقية فيتسارع نحو اليمين، والأرض تؤثر فيه بقوة احتكاك. (أ) سمِّ القوى المؤثرة في الصندوق ومسبب كل منها. (ب) ارسم مخطط الجسم الحر مبيّنًا العلاقة بين أطوال الأسهم الأفقية وأطوال الأسهم الرأسية. (ج) حدّد اتجاه القوة المحصلة، ولماذا لا تُرسم سهمًا على مخطط الجسم الحر نفسه؟', null, null, null, 'تطبيق', 'رسم مخطط', 'صعب', 'الكتاب ص 97–98 — مخططات الجسم الحر ومسائل تدريبية'),
('essay', 3, 'يمثّل الشكل الآتي مخطط جسم حر رسمه طالب لسيارة تسير بسرعة متجهة ثابتة على طريق أفقي. (أ) حدّد ثلاثة أخطاء في المخطط. (ب) صف المخطط الصحيح وصفًا كاملًا (القوى، ومسبباتها، وأطوال الأسهم).', null, '[{"src":"qimg/phys1/c4l1-o34-car-wrong.svg","alt":"على اليسار سيارة على طريق أفقي، وتحتها سهم أحمر نحو اليمين مكتوب عنده v، وعبارة: سيارة تسير بسرعة متجهة ثابتة. على اليمين مخطط رسمه طالب: نقطة يخرج منها سهم F_thrust نحو اليمين وسهم F_g إلى أسفل؛ وعلى يسار النقطة سهم مكتوب عنده f_f يبدأ بعيدًا عنها ويتجه نحو اليمين حتى ينتهي عند النقطة، وطوله مساوٍ لطول سهم الدفع؛ وتحت النقطة سهم أزرق قصير نحو اليمين مكتوب عنده F مع الحرف السفلي «المحصلة». لا يوجد سهم إلى أعلى. وفي الأسفل محوران صغيران +x نحو اليمين و+y إلى أعلى."}]'::jsonb, null, 'تقويم', 'اكتشاف أخطاء وتصحيحها', 'صعب', 'الكتاب ص 97–98 — مخططات الجسم الحر ومسائل تدريبية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
