insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'في السقوط الحر لا يلامس الأصيص أي جسم، فتؤثر فيه قوة واحدة هي قوة الجاذبية الأرضية، تُرسم سهمًا يبدأ من النقطة ويتجه إلى أسفل بعيدًا عنها، وهذا هو المخطط (3).', '["المخطط (1) يحوي قوة عمودية لا وجود لها؛ فالأصيص لا يلامس أي سطح.","في المخطط (2) رُسم سهم الوزن متجهًا نحو النقطة، والصحيح أن يبدأ السهم من الجسم ويتجه بعيدًا عنه.","","في المخطط (4) رُسمت القوة المحصلة سهمًا إضافيًّا كأنها قوة أخرى، مع أنها هنا هي الوزن نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-19T07:48:34.578Z"}'::jsonb),
('mcq', 2, 1, 'السرعة المتجهة منتظمة، فالتسارع صفر والقوة المحصلة صفر؛ لذا تؤثر فيه قوتان متعاكستان متساويتان: القوة المعيقة $\boldsymbol{F}_{d}$ إلى أعلى وقوة الجاذبية إلى أسفل، بسهمين متساويين طولًا يبدآن من النقطة، وهذا هو المخطط (2).', '["المخطط (1) ينقصه سهم القوة المعيقة $\\boldsymbol{F}_{d}$ إلى أعلى.","","في المخطط (3) سهم الوزن أطول من سهم القوة المعيقة $\\boldsymbol{F}_{d}$، فتكون المحصلة إلى أسفل ويتسارع المظلي، وهذا يخالف السرعة المنتظمة.","في المخطط (4) رُسمت القوة المعيقة إلى أسفل، والهواء يؤثر في المظلي إلى أعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.578Z"}'::jsonb),
('mcq', 3, 3, 'تؤثر في الصندوق أربع قوى: الشد نحو اليمين، والاحتكاك نحو اليسار عكس الحركة، والقوة العمودية إلى أعلى، والوزن إلى أسفل. ولأن السرعة منتظمة فالمحصلة صفر، فيتساوى سهما الشد والاحتكاك، ويتساوى سهما القوة العمودية والوزن، وهذا هو المخطط (4).', '["المخطط (1) ينقصه سهم قوة الاحتكاك؛ وبدونه تكون المحصلة نحو اليمين ويتسارع الصندوق.","في المخطط (2) رُسم الاحتكاك في اتجاه الحركة، والصحيح أنه يعاكسها.","في المخطط (3) سهم القوة العمودية أقصر من سهم الوزن، فتكون هناك محصلة رأسية إلى أسفل، والصندوق لا يتسارع رأسيًّا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.579Z"}'::jsonb),
('mcq', 4, 0, 'الدلو يتحرك إلى أعلى وسرعته تتناقص، فتسارعه إلى أسفل، والقوة المحصلة إلى أسفل؛ لذا يكون سهم الوزن أطول من سهم الشد، دون رسم القوة المحصلة سهمًا على المخطط، وهذا هو المخطط (1).', '["","في المخطط (2) الشد يساوي الوزن، وهذا يعني سرعة منتظمة لا متناقصة.","في المخطط (3) الشد أكبر من الوزن، فتكون المحصلة إلى أعلى ويزداد مقدار سرعة الدلو.","في المخطط (4) أطوال الشد والوزن صحيحة، لكن رُسمت القوة المحصلة سهمًا إضافيًّا كأنها قوة ثالثة، وهي ليست قوة مستقلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-19T07:48:34.579Z"}'::jsonb),
('mcq', 5, 2, 'في مخطط الجسم الحر تُرسم الأسهم دائمًا بحيث تبدأ من الجسم وتشير بعيدًا عنه. والخيط يسحب الكرة إلى أعلى، فسهم الشد يجب أن يبدأ من النقطة ويتجه إلى أعلى، لا أن يأتي من أعلى ويتجه نحو النقطة.', '["قوة الجاذبية تتجه دائمًا إلى أسفل؛ والشد هو الذي يتجه إلى أعلى ويوازنها.","الكرة ساكنة، فالقوة المحصلة صفر، ولا تُرسم المحصلة سهمًا على مخطط الجسم الحر.","","الخيط يؤثر بقوة شد فقط؛ والقوة العمودية يؤثر بها سطح يستند إليه الجسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.579Z"}'::jsonb),
('mcq', 6, 0, 'السرعة المتجهة منتظمة، فالقوة المحصلة صفر؛ تؤثر في الكيس (النظام) قوة اليد إلى أعلى ومسببها اليد، وقوة الجاذبية إلى أسفل ومسببها كتلة الأرض، ويُرسم السهمان متساويين طولًا.', '["","الحركة إلى أعلى بسرعة منتظمة لا تحتاج إلى محصلة؛ فاتجاه الحركة لا يحدد أطول الأسهم.","قوة الكيس في اليد تؤثر في اليد لا في الكيس، فلا تُرسم في مخطط الجسم الحر للكيس.","النظام هو الكيس فقط، واليد من المحيط الخارجي وتؤثر فيه بقوة تلامس يجب رسمها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.579Z"}'::jsonb),
('mcq', 7, 3, 'في مخطط الجسم الحر يُمثَّل الجسم بنقطة، وتُمثَّل كل قوة تؤثر فيه بسهم يشير إلى اتجاهها ويبدأ من الجسم متجهًا بعيدًا عنه، ويكون طوله متناسبًا مع مقدار القوة، مع تسمية كل قوة واختيار اتجاه موجب.', '["يُرسم في المخطط ما يؤثر في الجسم من قوى، لا ما يؤثر به هو في غيره، ويُمثَّل الجسم بنقطة.","الأسهم تشير بعيدًا عن الجسم حتى لقوى الدفع، وأطوالها تتناسب مع مقادير القوى.","القوة المحصلة ليست قوة إضافية تؤثر في الجسم، فلا تُرسم مع القوى على المخطط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.579Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) النظام: الدلو؛ المحيط الخارجي: الحبل والأرض (بكتلتها). (ب) قوة الشد $\boldsymbol{F}_{\text{T}}$ إلى أعلى، مسببها الحبل، قوة تلامس؛ قوة الجاذبية الأرضية $\boldsymbol{F}_{g}$ إلى أسفل، مسببها كتلة الأرض، قوة مجال. (ج) نقطة يخرج منها سهم أزرق إلى أعلى مكتوب عنده $\boldsymbol{F}_{\text{T}}$، وسهم أزرق إلى أسفل مساوٍ له طولًا مكتوب عنده $\boldsymbol{F}_{g}$، وسهم الاتجاه الموجب $+y$ إلى أعلى. (د) القوة المحصلة صفر؛ لأن السرعة المتجهة منتظمة فالتسارع صفر، رغم أن الدلو يتحرك إلى أسفل.', '["النظام والمحيط","القوتان ومسبباهما ونوعاهما","مخطط صحيح بأسهم متساوية تبدأ من النقطة و+y","المحصلة صفر مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم سهم الوزن أطول لأن الدلو يتحرك إلى أسفل","رسم الأسهم متجهة نحو النقطة","إغفال تحديد المسبب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.580Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) قوة اليد نحو اليمين (مسببها اليد)، وقوة الاحتكاك $\boldsymbol{f}_{f}$ نحو اليسار (مسببها الأرض)، والقوة العمودية $\boldsymbol{F}_{\text{N}}$ إلى أعلى (مسببها الأرض)، وقوة الجاذبية $\boldsymbol{F}_{g}$ إلى أسفل (مسببها كتلة الأرض). (ب) نقطة تخرج منها أربعة أسهم تبدأ منها: سهم قوة اليد نحو اليمين أطول من سهم الاحتكاك نحو اليسار (لأن الصندوق يتسارع نحو اليمين)، وسهما $\boldsymbol{F}_{\text{N}}$ و$\boldsymbol{F}_{g}$ متساويان (لا تسارع رأسي)، مع محورين $+x$ نحو اليمين و+y إلى أعلى. (ج) القوة المحصلة نحو اليمين في اتجاه التسارع، ومقدارها الفرق بين قوة اليد والاحتكاك. لا تُرسم على المخطط لأنها ليست قوة إضافية بل مجموع القوى المرسومة، ويمكن رسمها منفصلة عن المخطط.', '["القوى الأربع ومسبباتها","سهم اليد أطول من الاحتكاك","السهمان الرأسيان متساويان","اتجاه المحصلة وسبب عدم رسمها"]'::jsonb, '[]'::jsonb, '[{"element":"القوى والمسببات","marks":2},{"element":"الأسهم الأفقية","marks":1.5},{"element":"الأسهم الرأسية","marks":1},{"element":"المحصلة","marks":1.5}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الاحتكاك في اتجاه الحركة","رسم سهم قوة اليد متجهًا نحو النقطة من اليسار","رسم القوة المحصلة سهمًا خامسًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.580Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الأخطاء: (1) لم تُرسم القوة العمودية $\boldsymbol{F}_{\text{N}}$ التي يؤثر بها الطريق إلى أعلى، فبقي الوزن وحده رأسيًّا. (2) سهم الاحتكاك مرسوم متجهًا نحو النقطة، والصحيح أن يبدأ من النقطة ويتجه نحو اليسار بعيدًا عنها. (3) رُسمت القوة المحصلة سهمًا على المخطط، مع أنها ليست قوة إضافية، وهي هنا صفر لأن السرعة المتجهة ثابتة. (ب) نقطة تخرج منها أربعة أسهم: $\boldsymbol{F}_{\text{thrust}}$ نحو اليمين (القوة التي تحرّك السيارة) و$\boldsymbol{f}_{f}$ نحو اليسار (القوة التي تعيق حركتها) متساويان طولًا، و$\boldsymbol{F}_{\text{N}}$ إلى أعلى (مسببها الطريق) و$\boldsymbol{F}_{g}$ إلى أسفل (مسببها كتلة الأرض) متساويان طولًا.', '["غياب القوة العمودية","سهم الاحتكاك نحو الجسم","رسم المحصلة على المخطط وهي صفر","وصف المخطط الصحيح بأطوال متساوية"]'::jsonb, '[]'::jsonb, '[{"element":"الخطأ 1","marks":1},{"element":"الخطأ 2","marks":1},{"element":"الخطأ 3","marks":1},{"element":"المخطط الصحيح","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ تساوي سهمي الدفع والاحتكاك خطأً","عدم ملاحظة غياب القوة العمودية","القول إن المحصلة نحو اليمين لأن السيارة تتحرك نحو اليمين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.580Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
