from (values
('mcq', 1, 'أيّ القوى الآتية قوة مجال؟', null, null, '["قوة الاحتكاك بين صندوق والأرض","قوة الشد في حبل يسحب عربة","القوة التي يجذب بها مغناطيس مسمارًا عن بُعد","القوة العمودية التي تؤثر بها طاولة في كتاب"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 96 و104 — قوى التلامس وقوى المجال، مراجعة 9'),
