('mcq', 5, 'قال طالب: «التسارع قوة؛ لأنه يرافق دائمًا القوة المحصلة». أيّ مما يأتي يقيّم قوله تقييمًا صحيحًا؟', null, null, '["قوله خاطئ؛ فالتسارع نتيجة للقوة المحصلة وليس قوة، ويقاس بـ m/s²","قوله صحيح؛ لأن التسارع يقاس بالنيوتن مثل القوى","قوله صحيح؛ فالتسارع قوة مجال تؤثر دون تلامس","قوله خاطئ؛ لأن التسارع كمية قياسية ليس لها اتجاه"]'::jsonb, 'تقويم', 'تقييم عبارة', 'صعب', 'الكتاب ص 99 و104 — القوة والتسارع، مراجعة 9'),
('mcq', 6, 'يبيّن الشكل الآتي كرة معلقة بخيط ودائرة حول النظام، ومخطط الجسم الحر للكرة. ما نوع كل من القوتين المؤثرتين في الكرة؟', null, '[{"src":"qimg/phys1/c4l1-o35-hanging-system.svg","alt":"على اليسار كرة معلقة بخيط رأسي مربوط بسقف، وحول الكرة دائرة متقطعة يقطعها الخيط، وتحتها عبارة: النظام: الكرة. على اليمين مخطط جسم حر: نقطة يخرج منها سهم أزرق إلى أعلى مكتوب عنده F_T، وسهم أزرق مساوٍ له طولًا إلى أسفل مكتوب عنده F_g، وفي الأسفل سهم صغير إلى أعلى مكتوب عنده +y."}]'::jsonb, '["$\\boldsymbol{F}_{\\text{T}}$ قوة مجال، و$\\boldsymbol{F}_{g}$ قوة تلامس","$\\boldsymbol{F}_{\\text{T}}$ و$\\boldsymbol{F}_{g}$ كلتاهما قوتا تلامس","$\\boldsymbol{F}_{\\text{T}}$ قوة تلامس، و$\\boldsymbol{F}_{g}$ قوة مجال","$\\boldsymbol{F}_{\\text{T}}$ و$\\boldsymbol{F}_{g}$ كلتاهما قوتا مجال"]'::jsonb, 'تطبيق', 'تصنيف من شكل', 'متوسط', 'الكتاب ص 97 — الشكل 4-2 (الدائرة حول النظام ومواقع التلامس)'),
('mcq', 7, 'كم قوة مجال توجد في القائمة الآتية: الاحتكاك، النابض، الدفع، الشد، العمودية، الوزن؟', null, null, '["لا توجد قوة مجال بينها","قوة واحدة هي الوزن","قوتان هما الوزن والاحتكاك","ثلاث قوى هي الوزن والدفع والنابض"]'::jsonb, 'تحليل', 'تصنيف قائمة', 'صعب', 'الكتاب ص 96 و103 — جدول بعض أنواع القوى'),
('essay', 1, 'صنّف كلًّا مما يأتي إلى: قوة تلامس، أو قوة مجال، أو ليست قوة: الوزن، الكتلة، القصور الذاتي، الدفع باليد، الدفع (Thrust)، مقاومة الهواء، قوة النابض، التسارع.', null, null, null, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 104 — مراجعة 9'),
('essay', 2, 'يبيّن الشكل الآتي كرة ساكنة على راحة اليد، ودائرة متقطعة مرسومة حول النظام، ومخطط الجسم الحر للكرة بسهمين مرقمين. (أ) سمِّ القوتين 1 و2 ومسبب كل منهما. (ب) صنّف كل قوة إلى تلامس أو مجال. (ج) كيف تساعد الدائرة المرسومة حول النظام على التمييز بين قوى التلامس وقوى المجال؟', null, '[{"src":"qimg/phys1/c4l1-o35-ball-hand.svg","alt":"على اليسار كرة ساكنة على راحة يد، وحول الكرة دائرة متقطعة تلامس اليد، وتحتها عبارة: كرة ساكنة على راحة اليد. على اليمين مخطط جسم حر: نقطة يخرج منها سهم أزرق إلى أعلى مرقم 1، وسهم أزرق مساوٍ له طولًا إلى أسفل مرقم 2، وفي الأسفل سهم صغير إلى أعلى مكتوب عنده +y."}]'::jsonb, null, 'تحليل', 'تصنيف وتفسير', 'متوسط', 'الكتاب ص 97 — الشكل 4-2b'),
