from (values
('mcq', 1, 2, 'القوة التي يجذب بها مغناطيس مسمارًا عن بُعد قوة مجال؛ فالقوى المغناطيسية تؤثر دون تلامس بين الجسمين.', '["الاحتكاك قوة تلامس بين السطحين المتلامسين.","الشد قوة تلامس يؤثر بها حبل متصل بالجسم.","","القوة العمودية قوة تلامس يؤثر بها سطح في جسم يلامسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-19T07:48:34.581Z"}'::jsonb),
('mcq', 2, 0, 'مقاومة الهواء قوة تلامس؛ لأن جزيئات الهواء تلامس المظلي وتؤثر فيه.', '["","جذب الأرض للحجر قوة جاذبية، وهي قوة مجال تؤثر دون تلامس.","القوة المغناطيسية بين جسمين متباعدين قوة مجال.","جذب الأرض للطائرة قوة جاذبية تؤثر دون تلامس، فهي قوة مجال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-19T07:48:34.581Z"}'::jsonb),
('mcq', 3, 1, 'القصور الذاتي ممانعة الجسم لأي تغيير في حالته من حيث السكون أو الحركة، وهو ليس قوة؛ أما بقية الخيارات فقوى تلامس.', '["قوة النابض قوة تلامس يؤثر بها النابض في الجسم المتصل به.","","الدفع باليد قوة تلامس.","مقاومة الهواء قوة تلامس يؤثر بها الهواء في الجسم المتحرك خلاله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.581Z"}'::jsonb),
('mcq', 4, 3, 'الوزن قوة مجال (جاذبية تؤثر دون تلامس)، والكتلة ليست قوة (كمية المادة في الجسم)، والدفع باليد قوة تلامس.', '["الوزن لا يحتاج إلى تلامس فهو قوة مجال، والكتلة ليست قوة أصلًا.","الكتلة ليست قوة، فلا تُصنَّف قوة مجال.","الوزن قوة (قوة الجاذبية الأرضية) وتُقاس بالنيوتن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.581Z"}'::jsonb),
('mcq', 5, 0, 'التسارع ليس قوة، بل هو نتيجة لتأثير القوة المحصلة في الجسم: $\boldsymbol{a} = \frac{\boldsymbol{F}_{\text{المحصلة}}}{m}$، ووحدته m/s² لا النيوتن؛ فقوله خاطئ.', '["","التسارع يقاس بوحدة m/s²، والنيوتن وحدة القوة.","التسارع ليس قوة أصلًا، فلا يُصنَّف قوة مجال.","الحكم صحيح لكن التعليل خاطئ؛ فالتسارع كمية متجهة في اتجاه القوة المحصلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.582Z"}'::jsonb),
('mcq', 6, 2, 'الخيط يلامس الكرة عند حدود الدائرة المرسومة حول النظام، فقوة الشد $\boldsymbol{F}_{\text{T}}$ قوة تلامس؛ أما قوة الجاذبية $\boldsymbol{F}_{g}$ فتؤثر دون أي تلامس، فهي قوة مجال.', '["التصنيفان مقلوبان؛ فالخيط يلامس الكرة، والأرض لا تلامسها.","الأرض لا تلامس الكرة، فقوة الجاذبية ليست قوة تلامس.","","الخيط يلامس الكرة فعلًا عند حدود النظام، فالشد قوة تلامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.582Z"}'::jsonb),
('mcq', 7, 1, 'الوزن وحده قوة مجال لأنه ينتج عن الجاذبية الأرضية ويؤثر دون تلامس؛ أما الاحتكاك والنابض والدفع والشد والعمودية فكلها قوى تلامس.', '["الوزن قوة مجال لأنه يؤثر في الجسم سواء لامس الأرض أم لا.","","الاحتكاك قوة تلامس تنشأ بين سطحين متلامسين.","الدفع والنابض قوتا تلامس يؤثر بهما جسم يلامس النظام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.582Z"}'::jsonb),
('essay', 1, null::int, null, null, 'قوى تلامس: الدفع باليد، والدفع (Thrust)، ومقاومة الهواء، وقوة النابض. قوة مجال: الوزن. ليست قوة: الكتلة، والقصور الذاتي، والتسارع.', '["قوى التلامس الأربع","قوة المجال (الوزن)","الكميات الثلاث التي ليست قوى"]'::jsonb, '[]'::jsonb, '[{"element":"قوى التلامس","marks":2},{"element":"قوة المجال","marks":1},{"element":"ليست قوى","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف الكتلة أو التسارع قوة","تصنيف مقاومة الهواء قوة مجال لأن الهواء غير مرئي","تصنيف القصور الذاتي قوة تدفع الجسم إلى الأمام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.582Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) القوة 1: قوة اليد في الكرة إلى أعلى، مسببها اليد. القوة 2: قوة الجاذبية الأرضية $\boldsymbol{F}_{g}$ إلى أسفل، مسببها كتلة الأرض. (ب) القوة 1 قوة تلامس، والقوة 2 قوة مجال. (ج) تُحدَّد المواقع التي يلامس فيها المحيطُ الخارجي النظامَ على حدود الدائرة؛ فكل قوة يؤثر بها جسم يلامس النظام عند هذه الحدود (كاليد) قوة تلامس، أما القوة التي يؤثر بها جسم لا يلامس الدائرة (كالأرض) فهي قوة مجال.', '["تسمية القوتين ومسببيهما","التصنيف","دور الدائرة في تحديد مواقع التلامس"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية القوة 1 وزنًا","عدّ قوة اليد قوة مجال لأنها لا تُرى","عدم ربط الدائرة بمواقع التلامس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.582Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) التصنيف خاطئ؛ فالكتلة والقصور الذاتي ليسا قوتين أصلًا. الكتلة كمية المادة في الجسم وتقاس بالكيلوجرام، والقصور الذاتي ممانعة الجسم لأي تغيير في حالته من حيث السكون أو الحركة. وعدم الحاجة إلى تلامس لا يجعل الكمية قوة مجال. (ب) القوة سحب أو دفع يؤثر به جسم (المسبب) في جسم آخر (النظام) فيغيّر سرعته المتجهة، وتقاس بالنيوتن؛ أما القصور الذاتي فخاصية للجسم نفسه لا مسبب خارجي لها ولا تغيّر حركته. (ج) قوة مجال: الوزن، مسببه كتلة الأرض (أو القوة المغناطيسية ومسببها المغناطيس). قوة تلامس: القوة العمودية التي تؤثر بها طاولة في كتاب، مسببها الطاولة.', '["الحكم بأن التصنيف خاطئ مع التعليل","الفرق بين القصور الذاتي والقوة","مثال لقوة مجال مع المسبب","مثال لقوة تلامس مع المسبب"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"مثال المجال","marks":1},{"element":"مثال التلامس","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول تصنيف الطالب","القول إن القصور الذاتي قوة تُبقي الجسم متحركًا","ذكر مثال دون مسبب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.583Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
