from (values
('mcq', 1, 'إذا أثّرت القوة المحصلة نفسها في أجسام مختلفة الكتل، فكيف يتغير تسارع الجسم مع كتلته؟', null, null, '["يتناسب طرديًّا مع الكتلة","يتناسب عكسيًّا مع الكتلة","لا يعتمد على الكتلة","يتناسب طرديًّا مع مربع الكتلة"]'::jsonb, 'فهم', 'تحديد علاقة', 'سهل', 'الكتاب ص 103 — قانون نيوتن الثاني'),
('mcq', 2, 'يمثّل الشكل الآتي منحنى (التسارع – القوة) لثلاثة أجسام A وB وC. أيّ الأجسام كتلته أكبر؟', null, '[{"src":"qimg/phys1/c4l1-o36-three-lines.svg","alt":"منحنى بياني محوره الأفقي القوة (N) من 0 إلى 3 بخطوة 0.5، ومحوره الرأسي التسارع (m/s²) من 0 إلى 6 بخطوة 1. ثلاثة خطوط مستقيمة تبدأ من نقطة الأصل: الخط A (أسود) يصل إلى النقطة (3, 6)، والخط B (برتقالي) يصل إلى النقطة (3, 3)، والخط C (أخضر) يصل إلى النقطة (3, 2)."}]'::jsonb, '["الجسم A؛ لأن ميل خطه الأكبر","الجسم B؛ لأن خطه بين الخطين الآخرين","متساوية؛ لأن خطوطها تمر بنقطة الأصل","الجسم C؛ لأن ميل خطه الأصغر"]'::jsonb, 'تحليل', 'تفسير ميل', 'متوسط', 'الكتاب ص 99 — الشكل 4-4b: ميل منحنى (التسارع – القوة) يساوي 1/m'),
('mcq', 3, 'يمثّل الشكل الآتي منحنى (التسارع – القوة) لعربة. ما كتلة العربة؟', null, '[{"src":"qimg/phys1/c4l1-o36-one-line.svg","alt":"منحنى بياني محوره الأفقي القوة (N) من 0 إلى 4.5 بخطوة 0.5، ومحوره الرأسي التسارع (m/s²) من 0 إلى 2.5 بخطوة 0.25. خط مستقيم برتقالي يبدأ من نقطة الأصل ويمر بالنقاط (1, 0.5) و(2, 1) و(3, 1.5) و(4, 2)."}]'::jsonb, '["2.0 kg","0.50 kg","8.0 kg","4.0 kg"]'::jsonb, 'تحليل', 'حساب من الميل', 'صعب', 'الكتاب ص 99 — الشكل 4-4b: ميل منحنى (التسارع – القوة) يساوي 1/m'),
('mcq', 4, 'تؤثر قوة مقدارها 1 N في مكعب خشبي فتُكسبه تسارعًا معيّنًا، وعندما تؤثر القوة نفسها في مكعب آخر تُكسبه ثلاثة أمثال ذلك التسارع. ماذا تستنتج عن كتلة المكعب الثاني؟', null, null, '["تساوي ثلاثة أمثال كتلة الأول","تساوي كتلة الأول","تساوي ثلث كتلة الأول","تساوي تسعة أمثال كتلة الأول"]'::jsonb, 'تطبيق', 'استنتاج', 'سهل', 'الكتاب ص 104 — مراجعة 14'),
('mcq', 5, 'تؤثر قوة ثابتة في عربة فتُكسبها تسارعًا مقداره 1.8 m/s². وُضعت فوقها عربتان مماثلتان لها (فصارت ثلاث عربات)، وأثّرت فيها القوة نفسها. ما التسارع الجديد؟', null, null, '["0.60 m/s²","0.90 m/s²","1.8 m/s²","5.4 m/s²"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 99 — الشكل 4-4b: ميل منحنى (التسارع – القوة) يساوي 1/m'),
('mcq', 6, 'أيّ الأشكال الآتية يمثّل العلاقة بين تسارع جسم (a) وكتلته (m) عند ثبات القوة المحصلة المؤثرة فيه؟', null, '[{"src":"qimg/phys1/c4l1-o36-shapes.svg","alt":"أربعة أشكال مرقمة، في كل منها محور أفقي مكتوب عنده m ومحور رأسي مكتوب عنده a. الشكل (1): خط مستقيم يبدأ من نقطة الأصل ويتزايد. الشكل (2): منحنى يبدأ مرتفعًا قرب المحور الرأسي ويتناقص بسرعة ثم ببطء مقتربًا من المحور الأفقي دون أن يلمسه. الشكل (3): خط أفقي. الشكل (4): خط مستقيم يتناقص من أعلى اليسار حتى يلمس المحور الأفقي."}]'::jsonb, '["الشكل (1)","الشكل (2)","الشكل (3)","الشكل (4)"]'::jsonb, 'تحليل', 'اختيار شكل بياني', 'متوسط', 'الكتاب ص 99 و103 — العلاقة العكسية بين التسارع والكتلة'),
('mcq', 7, 'في تجربة أُثّر فيها بقوة محصلة ثابتة في أجسام مختلفة الكتل، مُثّل التسارع بيانيًّا مقابل مقلوب الكتلة كما في الشكل الآتي. ماذا يمثّل ميل الخط، وما مقداره؟', null, '[{"src":"qimg/phys1/c4l1-o36-a-invm.svg","alt":"منحنى بياني محوره الأفقي مقلوب الكتلة (kg⁻¹) من 0 إلى 2 بخطوة 0.5، ومحوره الرأسي التسارع (m/s²) من 0 إلى 12 بخطوة 2. خط مستقيم برتقالي يبدأ من نقطة الأصل ويمر بالنقاط (0.5, 3) و(1, 6) و(1.5, 9) و(2, 12)."}]'::jsonb, '["الكتلة، ومقدارها 6.0 kg","مقلوب الكتلة، ومقداره 6.0 kg⁻¹","القوة المحصلة، ومقدارها 0.17 N","القوة المحصلة، ومقدارها 6.0 N"]'::jsonb, 'تحليل', 'تفسير ميل', 'متوسط', 'الكتاب ص 99 — الشكل 4-4b: ميل منحنى (التسارع – القوة) يساوي 1/m'),
('essay', 1, 'يمثّل الشكل الآتي منحنى (التسارع – القوة) لعربة واحدة، ولعربتين متماثلتين وُضعت إحداهما فوق الأخرى، ولثلاث عربات. (أ) احسب ميل كل خط. (ب) استخدم العلاقة بين الميل والكتلة لحساب كتلة كل مجموعة. (ج) قارن تسارع العربتين والعربات الثلاث بتسارع العربة الواحدة عند القوة نفسها. (د) ماذا تستنتج عن العلاقة بين التسارع والكتلة عند ثبات القوة؟', null, '[{"src":"qimg/phys1/c4l1-o36-carts-essay.svg","alt":"منحنى بياني محوره الأفقي القوة (N) من 0 إلى 1.5 بخطوة 0.25، ومحوره الرأسي التسارع (m/s²) من 0 إلى 6 بخطوة 1. ثلاثة خطوط مستقيمة تبدأ من نقطة الأصل وتنتهي عند القوة 1.5 N بنقاط معلّمة: خط أسود مكتوب عنده «عربة» ينتهي عند (1.5, 6)، وخط برتقالي مكتوب عنده «عربتان» ينتهي عند (1.5, 3)، وخط أخضر مكتوب عنده «ثلاث عربات» ينتهي عند (1.5, 2)."}]'::jsonb, null, 'تحليل', 'تفسير منحنى وحساب', 'صعب', 'الكتاب ص 99 — الشكل 4-4b: ميل منحنى (التسارع – القوة) يساوي 1/m'),
('essay', 2, 'أثّرت قوة محصلة ثابتة في أجسام مختلفة الكتل، فسُجّلت النتائج في الجدول الآتي. (أ) احسب حاصل ضرب الكتلة في التسارع لكل جسم، وماذا تلاحظ؟ (ب) صف العلاقة بين التسارع والكتلة. (ج) توقّع تسارع جسم كتلته 3.0 kg تؤثر فيه القوة نفسها.', '{"headers":["الكتلة (kg)","التسارع (m/s²)"],"rows":[["0.50","6.0"],["1.0","3.0"],["1.5","2.0"],["2.0","1.5"]]}'::jsonb, null, null, 'تطبيق', 'تحليل بيانات', 'متوسط', 'الكتاب ص 99 و103 — العلاقة العكسية بين التسارع والكتلة'),
('essay', 3, 'تؤثر قوة مقدارها 1 N في مكعب A فتُكسبه تسارعًا مقداره a، وتؤثر القوة نفسها في مكعب B فتُكسبه تسارعًا مقداره 3a. (أ) ما نسبة كتلة A إلى كتلة B؟ (ب) إذا أُلصق المكعبان معًا وأثّرت فيهما القوة نفسها، فما تسارعهما بدلالة a؟ (ج) فسّر لماذا يقل التسارع عند لصق المكعبين، مستخدمًا ميل منحنى (التسارع – القوة).', null, null, null, 'تحليل', 'استنتاج وحساب', 'صعب', 'الكتاب ص 104 — مراجعة 14')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
