insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'من قانون نيوتن الثاني $a = \frac{F_{\text{المحصلة}}}{m}$، فعند ثبات القوة المحصلة يتناسب التسارع عكسيًّا مع الكتلة: كلما زادت الكتلة قلّ التسارع.', '["زيادة الكتلة تقلل التسارع لا تزيده.","","التسارع يعتمد على الكتلة؛ فالجسم الأكبر كتلة يحتاج إلى قوة أكبر للتسارع نفسه.","العلاقة عكسية مع الكتلة نفسها لا طردية مع مربعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.583Z"}'::jsonb),
('mcq', 2, 3, 'ميل منحنى (التسارع – القوة) يساوي مقلوب الكتلة $\frac{1}{m}$، فأصغر ميل يقابل أكبر كتلة. ميل الخط C هو الأصغر، فالجسم C كتلته أكبر.', '["الخط A ميله الأكبر، فكتلته الأصغر.","ميل الخط B أكبر من ميل الخط C، فكتلته أصغر من كتلة C.","مرور الخطوط بنقطة الأصل يعني أن التسارع يتناسب طرديًّا مع القوة، أما الكتلة فيحددها الميل المختلف لكل خط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.584Z"}'::jsonb),
('mcq', 3, 0, 'الميل $= \frac{\Delta a}{\Delta F} = \frac{2.0\ \text{m/s}^2}{4.0\ \text{N}} = 0.50\ \text{kg}^{-1}$، والميل يساوي $\frac{1}{m}$، فإن $m = \frac{1}{0.50} = 2.0\ \text{kg}$.', '["","هذه قيمة الميل نفسه (مقلوب الكتلة)، ولم يُحسب مقلوبه.","ضُربت القوة في التسارع عند النقطة الأخيرة (4.0 × 2.0) بدل قسمة القوة على التسارع.","أُخذت قيمة القوة عند النقطة الأخيرة على أنها الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.584Z"}'::jsonb),
('mcq', 4, 2, 'عند ثبات القوة يتناسب التسارع عكسيًّا مع الكتلة: $m = \frac{F}{a}$، فإذا تضاعف التسارع ثلاث مرات كانت الكتلة ثلث كتلة المكعب الأول.', '["العلاقة عكسية؛ فالتسارع الأكبر يقابل كتلة أصغر لا أكبر.","لو تساوت الكتلتان لتساوى التسارعان تحت تأثير القوة نفسها.","","العلاقة عكسية بسيطة مع الكتلة لا مع مربعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.584Z"}'::jsonb),
('mcq', 5, 0, 'الكتلة أصبحت ثلاثة أمثال، والقوة ثابتة، فيصبح التسارع ثلث قيمته: $\frac{1.8}{3} = 0.60\ \text{m/s}^2$.', '["","هذا تسارع عربتين (نصف التسارع)، لا ثلاث عربات.","التسارع يتغير بتغير الكتلة عند ثبات القوة.","ضُرب التسارع في 3 بدل القسمة؛ فالعلاقة عكسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.585Z"}'::jsonb),
('mcq', 6, 1, '$a = \frac{F_{\text{المحصلة}}}{m}$، فعند ثبات القوة يتناسب التسارع عكسيًّا مع الكتلة؛ فيقل التسارع كلما زادت الكتلة على شكل منحنى يقترب من المحور الأفقي ولا يقطعه، وهو الشكل (2).', '["الشكل (1) يمثل تناسبًا طرديًّا، أي تزايد التسارع بزيادة الكتلة.","","الشكل (3) يمثل تسارعًا لا يعتمد على الكتلة.","الشكل (4) خط مستقيم يقطع المحور الأفقي، أي أن التسارع يصبح صفرًا عند كتلة معيّنة، وهذا ليس تناسبًا عكسيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.585Z"}'::jsonb),
('mcq', 7, 3, '$a = F_{\text{المحصلة}} \times \frac{1}{m}$، فميل خط (التسارع – مقلوب الكتلة) يساوي القوة المحصلة: $\frac{12\ \text{m/s}^2}{2.0\ \text{kg}^{-1}} = 6.0\ \text{N}$.', '["الكتلة متغيرة في التجربة وليست ثابتة، والميل وحدته N لا kg.","مقلوب الكتلة هو المتغير على المحور الأفقي، لا الميل.","حُسب مقلوب الميل (2.0 ÷ 12) بدل الميل نفسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.585Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) عربة: $\frac{6.0}{1.5} = 4.0\ \text{kg}^{-1}$؛ عربتان: $\frac{3.0}{1.5} = 2.0\ \text{kg}^{-1}$؛ ثلاث عربات: $\frac{2.0}{1.5} = \frac{4}{3} \approx 1.3\ \text{kg}^{-1}$. (ب) الميل $= \frac{1}{m}$، فالكتل: $\frac{1}{4.0} = 0.25\ \text{kg}$، و$\frac{1}{2.0} = 0.50\ \text{kg}$، و$\frac{3}{4} = 0.75\ \text{kg}$. (ج) عند القوة 1.5 N: تسارع العربتين 3.0 m/s² أي نصف تسارع العربة الواحدة (6.0 m/s²)، وتسارع الثلاث 2.0 m/s² أي ثلثه. (د) عند ثبات القوة يتناسب التسارع عكسيًّا مع الكتلة: مضاعفة الكتلة تنصّف التسارع.', '["الميول الثلاثة","الكتل من مقلوب الميل","المقارنة: النصف والثلث","الاستنتاج: علاقة عكسية"]'::jsonb, '["الميل $= \\frac{\\Delta a}{\\Delta F}$","$m = \\frac{1}{\\text{الميل}}$","مقارنة التسارعات عند 1.5 N"]'::jsonb, '[{"element":"(أ)","marks":1.5},{"element":"(ب)","marks":1.5},{"element":"(ج)","marks":1.5},{"element":"(د)","marks":1.5}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["أخذ الميل على أنه الكتلة","حساب الميل بقسمة القوة على التسارع","استنتاج علاقة طردية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.585Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $0.50 \times 6.0 = 3.0$، $1.0 \times 3.0 = 3.0$، $1.5 \times 2.0 = 3.0$، $2.0 \times 1.5 = 3.0$؛ حاصل الضرب ثابت ويساوي 3.0 N، وهو القوة المحصلة. (ب) العلاقة عكسية: التسارع يتناسب عكسيًّا مع الكتلة ($a = \frac{F}{m}$)؛ فمضاعفة الكتلة تنصّف التسارع. (ج) $a = \frac{3.0\ \text{N}}{3.0\ \text{kg}} = 1.0\ \text{m/s}^2$.', '["حواصل الضرب = 3.0","ربط الثابت بالقوة المحصلة","العلاقة العكسية","التوقع 1.0 m/s²"]'::jsonb, '["$m a = 3.0\\ \\text{N}$ لكل الصفوف","$a = \\frac{F}{m} = \\frac{3.0}{3.0} = 1.0\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة التسارع على الكتلة بدل الضرب","استنتاج علاقة طردية لأن القيم مرتبة","التوقع بالطرح الخطي (0.0 أو قيمة سالبة)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.586Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $m = \frac{F}{a}$: $m_A = \frac{1}{a}$ و$m_B = \frac{1}{3a}$، فالنسبة $m_A : m_B = 3 : 1$. (ب) الكتلة الكلية $\frac{1}{a} + \frac{1}{3a} = \frac{4}{3a}$، فالتسارع $= \frac{1}{4/(3a)} = \frac{3}{4}a = 0.75a$. (ج) ميل منحنى (التسارع – القوة) يساوي $\frac{1}{m}$؛ لصق المكعبين يزيد الكتلة فيقل الميل، فتُكسب القوةُ نفسها المجموعةَ تسارعًا أصغر من تسارع أي منهما منفردًا.', '["نسبة الكتلتين 3:1","الكتلة الكلية","التسارع 0.75a","التفسير بالميل 1/m"]'::jsonb, '["$m_A = \\frac{1}{a}$، $m_B = \\frac{1}{3a}$","الكتلة الكلية $= \\frac{4}{3a}$","التسارع $= \\frac{3}{4}a$"]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل كتلة B ثلاثة أمثال كتلة A","جمع التسارعين (4a)","أخذ متوسط التسارعين (2a)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.586Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O36') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L1-O37'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يُحسب التسارع المتوسط للقطعة الخشبية في تجربة «القوة والكتلة» من العلاقة $\bar{a} = \frac{-2\Delta d}{(\Delta t)^2}$، حيث $\Delta d$ المسافة التي تقطعها القطعة من العلامة و$\Delta t$ زمن قطعها. على أيّ افتراض تعتمد هذه العلاقة؟', null, null, '["أن القطعة تتحرك بسرعة متجهة ثابتة طوال المسافة المقيسة","أن القطعة تبدأ حركتها من السكون عند العلامة ثم تتسارع","أن قوة الاحتكاك المؤثرة في القطعة تساوي صفرًا","أن تسارع القطعة ثابت، وأنها تتوقف تمامًا في نهاية $\\Delta t$"]'::jsonb, 'فهم', 'تحديد المحصلة', 'متوسط', 'الكتاب ص 122–123 — مختبر الفيزياء: القوة والكتلة (التحليل 2 و5)'),
('mcq', 2, 'في إحدى مجموعات البيانات سُجّلت نتائج المحاولات الثلاث في الجدول الآتي. احسب التسارع المتوسط للقطعة الخشبية باستخدام العلاقة $\bar{a} = \frac{-2\Delta d}{(\Delta t)^2}$ بعد حساب متوسطي المسافة والزمن.', '{"headers":["المحاولة","$\\Delta d$ (m)","$\\Delta t$ (s)"],"rows":[["1","3.1","2.1"],["2","3.3","1.9"],["3","3.2","2.0"]]}'::jsonb, null, '["$-1.6\\ \\text{m/s}^2$","$-0.80\\ \\text{m/s}^2$","$-3.2\\ \\text{m/s}^2$","$+1.6\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب من جدول', 'متوسط', 'الكتاب ص 122–123 — مختبر الفيزياء: القوة والكتلة'),
('mcq', 3, 'قطعة خشبية كتلتها 0.80 kg، وتسارعها المتوسط في أثناء انزلاقها $-1.6\ \text{m/s}^2$. ما القوة المحصلة المؤثرة فيها؟', null, null, '["$-0.50\\ \\text{N}$","$-2.0\\ \\text{N}$","$-1.3\\ \\text{N}$","$-7.8\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 122–123 — مختبر الفيزياء: القوة والكتلة'),
('mcq', 4, 'مُثّلت نتائج التجربة بيانيًّا: مقدار القوة المحصلة على المحور الرأسي مقابل كتلة القطعة الخشبية على المحور الأفقي، كما في الشكل الآتي. ماذا تستنتج من الرسم؟', null, '[{"src":"qimg/phys1/c4l1-o37-fm-graph.svg","alt":"منحنى بياني محوره الأفقي الكتلة (kg) من 0 إلى 2.4 بخطوة 0.4، ومحوره الرأسي مقدار القوة المحصلة (N) من 0 إلى 3.6 بخطوة 0.6. أربع نقاط قياس: (0.5, 0.76) و(1.0, 1.48) و(1.5, 2.27) و(2.0, 2.97)، وخط مستقيم برتقالي أفضل ملاءمة يبدأ من نقطة الأصل ويمر قريبًا من النقاط الأربع."}]'::jsonb, '["مقدار القوة المحصلة يتناسب عكسيًّا مع الكتلة","مقدار القوة المحصلة (الاحتكاك) يتناسب طرديًّا مع الكتلة","مقدار القوة المحصلة لا يعتمد على كتلة القطعة","تسارع القطعة يزداد بزيادة كتلتها"]'::jsonb, 'تحليل', 'استنتاج من رسم بياني', 'صعب', 'الكتاب ص 122–123 — مختبر الفيزياء: القوة والكتلة'),
('mcq', 5, 'يمثّل الشكل الآتي مقدار القوة المحصلة المؤثرة في قطع خشبية مختلفة الكتل في أثناء انزلاقها، مقابل كتلها. ماذا يمثّل ميل الخط، وما مقداره تقريبًا؟', null, '[{"src":"qimg/phys1/c4l1-o37-fm-slope.svg","alt":"منحنى بياني محوره الأفقي الكتلة (kg) من 0 إلى 2.0 بخطوة 0.4، ومحوره الرأسي مقدار القوة المحصلة (N) من 0 إلى 4.0 بخطوة 0.8. أربع نقاط قياس: (0.4, 0.81) و(0.8, 1.58) و(1.2, 2.42) و(1.6, 3.19)، وخط مستقيم برتقالي أفضل ملاءمة يبدأ من نقطة الأصل ويمر بالنقاط تقريبًا."}]'::jsonb, '["مقدار التسارع المتوسط للقطع، ويساوي تقريبًا 2.0 m/s²","مقلوب التسارع المتوسط، ويساوي تقريبًا 0.50 s²/m","تسارع الجاذبية الأرضية، ويساوي 9.80 m/s²","الكتلة المتوسطة للقطع، وتساوي تقريبًا 1.0 kg"]'::jsonb, 'تحليل', 'تفسير ميل', 'متوسط', 'الكتاب ص 122–123 — مختبر الفيزياء: القوة والكتلة'),
('mcq', 6, 'أيّ مما يأتي مصدر خطأ محتمل في تجربة «القوة والكتلة»؟', null, null, '["استخدام قطع خشبية مختلفة الكتل","تكرار القياس ثلاث مرات لكل كتلة","تأخر استجابة من يشغّل ساعة الإيقاف ويوقفها","قياس كتلة القطعة بالميزان قبل دفعها"]'::jsonb, 'تطبيق', 'مصادر الخطأ', 'سهل', 'الكتاب ص 122–123 — مختبر الفيزياء: القوة والكتلة'),
('mcq', 7, 'لماذا تكون قيمة التسارع المتوسط $\bar{a}$ المحسوبة في هذه التجربة سالبة، إذا اعتُبر اتجاه الحركة موجبًا؟', null, null, '["لأن كتلة القطعة تقل في أثناء انزلاقها","لأن القطعة تتباطأ، فتسارعها عكس اتجاه حركتها","لأن المسافة المقيسة سالبة دائمًا","لأن الزمن يُقاس من لحظة التوقف إلى لحظة البدء"]'::jsonb, 'فهم', 'تفسير إشارة', 'سهل', 'الكتاب ص 122–123 — مختبر الفيزياء: القوة والكتلة'),
('essay', 1, 'يبيّن الجدول الآتي متوسطات المسافة والزمن لأربع قطع خشبية مختلفة الكتل في تجربة «القوة والكتلة». (أ) احسب التسارع المتوسط لكل قطعة باستخدام $\bar{a} = \frac{-2\Delta d}{(\Delta t)^2}$. (ب) احسب القوة المحصلة المؤثرة في كل قطعة. (ج) ماذا تلاحظ على قيم التسارع للكتل المختلفة؟', '{"headers":["كتلة القطعة (kg)","متوسط $\\Delta d$ (m)","متوسط $\\Delta t$ (s)"],"rows":[["0.50","4.2","2.4"],["1.00","4.0","2.3"],["1.50","4.3","2.4"],["2.00","4.0","2.3"]]}'::jsonb, null, null, 'تطبيق', 'معالجة بيانات', 'متوسط', 'الكتاب ص 122–123 — مختبر الفيزياء: القوة والكتلة'),
('essay', 2, 'في تجربة «القوة والكتلة» حصلت على القيم الآتية لمقدار القوة المحصلة: 0.73 N، و1.5 N، و2.2 N، و3.0 N للكتل 0.50 kg، و1.00 kg، و1.50 kg، و2.00 kg على الترتيب. (أ) صف كيف تمثّل هذه البيانات بيانيًّا (المحاور، والنقاط، وخط أفضل ملاءمة). (ب) ما نوع العلاقة التي تتوقع الحصول عليها؟ (ج) ماذا يمثّل ميل الخط وما قيمته تقريبًا؟ (د) ما استنتاجك عن العلاقة بين قوة الاحتكاك وكتلة الجسم المنزلق؟', null, null, null, 'تحليل', 'تمثيل بياني واستنتاج', 'صعب', 'الكتاب ص 122–123 — مختبر الفيزياء: القوة والكتلة'),
('essay', 3, '(أ) اذكر مصدرين للخطأ في تجربة «القوة والكتلة»، واقترح طريقة لتقليل أثر كل منهما. (ب) هل تؤثر سرعة إطلاق القطعة الخشبية في القوة المحصلة المؤثرة فيها؟ فسّر إجابتك بالاعتماد على نتائج التجربة. (ج) لماذا يُطلب تكرار القياس ثلاث مرات لكل كتلة؟', null, null, null, 'تقويم', 'تقويم تجربة', 'صعب', 'الكتاب ص 122–123 — مختبر الفيزياء: القوة والكتلة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O37') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'القطعة تمر بالعلامة بسرعة $v_i$ وتتباطأ بتسارع ثابت حتى تتوقف ($v_f = 0$)؛ فالمسافة $\Delta d = \frac{v_i}{2}\Delta t$ والتسارع $\bar{a} = \frac{0 - v_i}{\Delta t}$، وبحذف $v_i$ نحصل على $\bar{a} = \frac{-2\Delta d}{(\Delta t)^2}$. فالعلاقة تفترض تسارعًا ثابتًا وسرعة نهائية صفرًا.', '["لو كانت السرعة المتجهة ثابتة لكان التسارع صفرًا، والقطعة في التجربة تتباطأ حتى تتوقف.","القطعة تمر بالعلامة وهي متحركة وتنتهي ساكنة؛ ولو بدأت من السكون وتسارعت لكانت إشارة التسارع موجبة.","الاحتكاك هو القوة المحصلة التي تسبب التباطؤ؛ ولو انعدم لما توقفت القطعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.587Z"}'::jsonb),
('mcq', 2, 0, 'متوسط المسافة $\frac{3.1 + 3.3 + 3.2}{3} = 3.2\ \text{m}$، ومتوسط الزمن $\frac{2.1 + 1.9 + 2.0}{3} = 2.0\ \text{s}$، فإن $\bar{a} = \frac{-2(3.2)}{(2.0)^2} = -1.6\ \text{m/s}^2$.', '["","حُذف العدد 2 من البسط.","لم يُربَّع الزمن في المقام.","أُهملت الإشارة السالبة؛ فالقطعة تتباطأ وتسارعها عكس حركتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.587Z"}'::jsonb),
('mcq', 3, 2, '$F_{\text{المحصلة}} = m\bar{a} = (0.80\ \text{kg})(-1.6\ \text{m/s}^2) = -1.28 \approx -1.3\ \text{N}$، والإشارة السالبة تعني أنها (قوة الاحتكاك) في عكس اتجاه الحركة.', '["قُسمت الكتلة على التسارع بدل ضربها فيه.","قُسم التسارع على الكتلة بدل ضربهما.","","استُخدم تسارع الجاذبية 9.80 m/s² بدل التسارع المتوسط المقيس، فحُسب ما يشبه الوزن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.587Z"}'::jsonb),
('mcq', 4, 1, 'النقاط تقع تقريبًا على خط مستقيم يمر بنقطة الأصل، فمقدار القوة المحصلة (قوة الاحتكاك) يتناسب طرديًّا مع الكتلة: مضاعفة الكتلة تضاعف القوة، ويبقى التسارع ثابتًا تقريبًا.', '["في التناسب العكسي تقل القوة بزيادة الكتلة، والرسم يبيّن تزايدها.","","القوة تزداد بوضوح بزيادة الكتلة، فهي تعتمد عليها.","الخط مستقيم يمر بالأصل، أي أن نسبة القوة إلى الكتلة (التسارع) ثابتة لا متزايدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.588Z"}'::jsonb),
('mcq', 5, 0, '$F = m\bar{a}$، فميل خط (القوة – الكتلة) يساوي مقدار التسارع المتوسط: $\frac{3.2\ \text{N}}{1.6\ \text{kg}} \approx 2.0\ \text{m/s}^2$.', '["","حُسب مقلوب الميل (الكتلة ÷ القوة) بدل الميل.","التسارع هنا ناتج عن الاحتكاك وقيمته من الرسم نحو 2.0 m/s²، لا تسارع الجاذبية.","الكتلة على المحور الأفقي، والميل نسبة القوة إلى الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.588Z"}'::jsonb),
('mcq', 6, 2, 'زمن استجابة الشخص عند تشغيل ساعة الإيقاف لحظة مرور القطعة بالعلامة وإيقافها لحظة توقفها يسبب خطأ في قياس $\Delta t$، وهذا يؤثر كثيرًا في التسارع لأن الزمن مربَّع في العلاقة.', '["تغيير الكتلة هو المتغير المستقل المقصود في التجربة، لا مصدر خطأ.","تكرار القياس وأخذ المتوسط يقلل الخطأ ولا يسببه.","","قياس الكتلة خطوة لازمة في التجربة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.588Z"}'::jsonb),
('mcq', 7, 1, 'القطعة تتباطأ حتى تتوقف بسبب قوة الاحتكاك المعاكسة لحركتها، فيكون تسارعها في عكس اتجاه الحركة (الموجب)، أي سالبًا.', '["كتلة القطعة لا تتغير في أثناء الانزلاق.","","المسافة المقيسة في اتجاه الحركة موجبة، والإشارة السالبة في العلاقة تعبّر عن التباطؤ.","الزمن يُقاس من لحظة المرور بالعلامة حتى التوقف، وهو موجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.588Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) 0.50 kg: $\bar{a} = \frac{-2(4.2)}{(2.4)^2} = -1.5\ \text{m/s}^2$؛ 1.00 kg: $\frac{-2(4.0)}{(2.3)^2} = -1.5\ \text{m/s}^2$؛ 1.50 kg: $\frac{-2(4.3)}{(2.4)^2} = -1.5\ \text{m/s}^2$؛ 2.00 kg: $\frac{-2(4.0)}{(2.3)^2} = -1.5\ \text{m/s}^2$. (ب) $F_{\text{المحصلة}} = m\bar{a}$: نحو $-0.73\ \text{N}$، و$-1.5\ \text{N}$، و$-2.2\ \text{N}$، و$-3.0\ \text{N}$ على الترتيب. (ج) التسارع متقارب جدًّا (نحو $-1.5\ \text{m/s}^2$) لجميع الكتل، أي أنه لا يعتمد تقريبًا على الكتلة، بينما تزداد القوة المحصلة (الاحتكاك) بزيادة الكتلة.', '["أربع قيم للتسارع","أربع قيم للقوة المحصلة بإشاراتها","ملاحظة ثبات التسارع تقريبًا"]'::jsonb, '["$\\bar{a} = \\frac{-2\\Delta d}{(\\Delta t)^2}$ لكل صف","$F_{\\text{المحصلة}} = m\\bar{a}$ لكل صف"]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تربيع الزمن","إهمال الإشارة السالبة","ضرب الكتلة في $g$ بدل التسارع المقيس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.589Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الكتلة (kg) على المحور الأفقي ومقدار القوة المحصلة (N) على المحور الرأسي بتدريج مناسب، وتعيين النقاط الأربع، ثم رسم خط مستقيم أفضل ملاءمة يمر قريبًا منها ومن نقطة الأصل. (ب) علاقة خطية طردية تمر بنقطة الأصل. (ج) الميل $= \frac{\Delta F}{\Delta m} \approx \frac{3.0 - 0.73}{2.00 - 0.50} \approx 1.5\ \text{m/s}^2$، وهو مقدار التسارع المتوسط (التباطؤ) للقطع، لأن $F = m\bar{a}$. (د) قوة الاحتكاك (القوة المحصلة على القطعة المنزلقة) تتناسب طرديًّا مع كتلة الجسم، فمضاعفة الكتلة تضاعف قوة الاحتكاك، ويبقى التسارع ثابتًا تقريبًا.', '["المحاور والنقاط وخط أفضل ملاءمة","علاقة طردية خطية","الميل = التسارع ≈ 1.5 m/s²","الاستنتاج: الاحتكاك ∝ الكتلة"]'::jsonb, '["الميل $= \\frac{3.0 - 0.73}{2.00 - 0.50} \\approx 1.5\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"(أ)","marks":1.5},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2},{"element":"(د)","marks":1.5}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع الكتلة على المحور الرأسي","توصيل النقاط بخط متعرج بدل خط أفضل ملاءمة","تفسير الميل بأنه الكتلة أو $g$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.589Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) 1- زمن استجابة الشخص عند تشغيل ساعة الإيقاف وإيقافها: يقلل بالتدريب وتكرار القياس وأخذ المتوسط، أو بجعل الشخص نفسه يشغّل الساعة ويوقفها. 2- عدم انتظام السطح أو انحراف القطعة عن المسار المستقيم: يقلل باختيار سطح أملس منتظم وتحديد مسار مستقيم. (ومن المصادر أيضًا تحديد لحظة التوقف بدقة وقياس المسافة). (ب) لا تؤثر تقريبًا؛ فالقوة المحصلة بعد الإطلاق هي قوة الاحتكاك فقط، ونتائج التجربة تبيّن أنها تعتمد على الكتلة (والسطح)، ويبقى التسارع ثابتًا تقريبًا، فزيادة سرعة الإطلاق تزيد المسافة والزمن فقط ولا تغيّر $\bar{a}$ ولا $F = m\bar{a}$. (ج) لتقليل أثر الأخطاء العشوائية بأخذ متوسط القياسات، فتكون النتائج أكثر موثوقية.', '["مصدرا خطأ مع طريقتي تقليل","سرعة الإطلاق لا تؤثر في القوة المحصلة مع التعليل","سبب تكرار القياس"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":3},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة بجميع عناصرها"},{"level":"2–5 درجات","description":"إجابة صحيحة جزئيًا: بعض العناصر صحيحة مع نقص أو خطأ في غيرها"},{"level":"1 درجة","description":"عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر تغيير الكتلة مصدرًا للخطأ","القول إن الدفع الأقوى يزيد القوة المحصلة في أثناء الانزلاق","عدم ربط التكرار بأخذ المتوسط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.589Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L1-O37') and x.type = v.type and x.number = v.number
