insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L2-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يصبح وزن رائد الفضاء على سطح القمر أقل كثيرًا من وزنه على سطح الأرض. ما سبب ذلك؟', null, null, '["قيمة $g$ على سطح القمر أقل كثيرًا منها على سطح الأرض","كتلة رائد الفضاء تقل عندما ينتقل إلى سطح القمر","القمر لا يؤثر بقوة جاذبية في الأجسام الموجودة على سطحه","رائد الفضاء يرتدي على القمر بدلة أخف من بدلته على الأرض"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 105 — الوزن على سطح القمر'),
('mcq', 2, 'جسم كتلته 5.00 kg، ووزنه على سطح كوكب ما 18.5 N. ما مقدار تسارع الجاذبية على سطح ذلك الكوكب؟', null, null, '["$92.5\\ \\text{m/s}^2$","$0.270\\ \\text{m/s}^2$","$3.70\\ \\text{m/s}^2$","$1.89\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 125 — التقويم 52 (حساب تسارع الجاذبية من الوزن)'),
('mcq', 3, 'صخرة وزنها على سطح الأرض 147 N. ما وزنها على سطح القمر إذا كان تسارع الجاذبية هناك 1.62 m/s²؟', null, null, '["147 N","24.3 N","90.7 N","238 N"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 105 — الوزن على سطح القمر'),
('mcq', 4, 'يمثل المنحنى الآتي العلاقة بين الوزن والكتلة لأجسام مختلفة في مكانين مختلفين A وB. ماذا يمثل ميل كل خط؟', null, '[{"src":"qimg/phys1/c4l2-o01-weight-mass-lines.svg","alt":"منحنى بياني محوره الأفقي الكتلة (kg) من 0 إلى 10 بخطوة 2، ومحوره الرأسي الوزن (N) من 0 إلى 100 بخطوة 20. يخرج من نقطة الأصل خطان مستقيمان: الخط A باللون الأزرق يمر بالنقطة (10، 98)، والخط B باللون البرتقالي يمر بالنقطة (10، 16.2)."}]'::jsonb, '["كتلة الجسم في ذلك المكان","القوة المحصلة المؤثرة في الجسم","مقلوب تسارع الجاذبية في ذلك المكان","تسارع الجاذبية $g$ في ذلك المكان"]'::jsonb, 'فهم', 'قراءة منحنى', 'متوسط', 'الكتاب ص 105 — العلاقة بين الوزن والكتلة'),
('mcq', 5, 'صعد متسلق إلى قمة جبل مرتفع جدًا حيث قيمة $g$ أقل قليلًا منها عند مستوى سطح البحر. ماذا يحدث لوزنه ولكتلته عند القمة؟', null, null, '["يقل وزنه قليلًا وتبقى كتلته ثابتة","تقل كتلته قليلًا ويبقى وزنه ثابتًا","يقل كل من وزنه وكتلته بالنسبة نفسها","يبقى كل من وزنه وكتلته ثابتًا تمامًا"]'::jsonb, 'فهم', 'استنتاج', 'سهل', 'الكتاب ص 107 — تغير الوزن بتغير g'),
('mcq', 6, 'ينتقل جسم من سطح الأرض إلى سطح كوكب تسارع الجاذبية عليه مِثلَي قيمته على الأرض. كيف يتغير وزن الجسم؟', null, null, '["يبقى مساويًا لوزنه على الأرض","يصبح نصف وزنه على الأرض","يصبح مثلي وزنه على الأرض","يصبح أربعة أمثال وزنه على الأرض"]'::jsonb, 'فهم', 'استنتاج', 'سهل', 'الكتاب ص 105 — الوزن على الكواكب الأخرى'),
('mcq', 7, 'الجسم A كتلته 2.00 kg ويقع على سطح الأرض ($g = 9.80\ \text{m/s}^2$)، والجسم B كتلته 10.0 kg ويقع على سطح القمر ($g = 1.62\ \text{m/s}^2$). أي العبارات الآتية صحيحة؟', null, null, '["وزن B أكبر من وزن A لأن كتلة B أكبر","وزنا الجسمين متساويان لأن كلًا منهما على سطح جرم سماوي","لا يمكن المقارنة بين الوزنين لأن الجسمين في مكانين مختلفين","وزن A أكبر من وزن B رغم أن كتلة A أصغر"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 124 — اعتماد الوزن على g والكتلة'),
('essay', 1, 'قارن بين القوة اللازمة لرفع صخرة كتلتها 10.0 kg بسرعة منتظمة على سطح الأرض، والقوة اللازمة لرفعها بسرعة منتظمة على سطح القمر، علمًا بأن تسارع الجاذبية على القمر 1.62 m/s². ثم فسّر الفرق.', null, null, null, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 111 — المراجعة 21 (جاذبية القمر)'),
('essay', 2, 'إذا كان تسارع الجاذبية على سطح عطارد يعادل 0.38 من قيمته على سطح الأرض: (أ) فما وزن جسم كتلته 6.0 kg على سطح عطارد؟ (ب) وإذا كان تسارع الجاذبية على سطح بلوتو يساوي 0.08 من مثيله على سطح عطارد، فما وزن جسم كتلته 7.0 kg على سطح بلوتو؟ (ج) ماذا تستنتج عن تغير الوزن من كوكب إلى آخر؟', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 126 — التقويم 54 (الوزن على عطارد وبلوتو)'),
('essay', 3, 'قال طالب: «وزن الجسم صفة ثابتة له مثل كتلته، فلا يتغير أينما ذهب». قوّم هذه العبارة، مستعينًا بمثال عددي لشخص كتلته 70.0 kg على سطح الأرض وعلى سطح القمر ($g = 1.62\ \text{m/s}^2$).', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 105 — الوزن والكتلة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
