insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الوزن $F_g = mg$؛ والكتلة $m$ ثابتة، فيتناسب الوزن طرديًا مع $g$. وبما أن $g$ على سطح القمر أقل كثيرًا منها على سطح الأرض، يصبح الوزن هناك نحو السدس تقريبًا.', '["","الكتلة لا تتغير بتغير المكان؛ والذي يتغير هو التسارع الناتج عن الجاذبية $g$.","القمر يؤثر بقوة جاذبية في الأجسام على سطحه، لكنها أصغر لأن $g$ هناك أصغر؛ ولو انعدمت لما كان للجسم وزن إطلاقًا.","البدلة لا تفسر النقص الكبير؛ فالوزن يقل لأن $g$ على القمر أصغر، حتى لو بقيت الكتلة الكلية كما هي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.590Z"}'::jsonb),
('mcq', 2, 2, 'من $F_g = mg$: $g = \frac{F_g}{m} = \frac{18.5\ \text{N}}{5.00\ \text{kg}} = 3.70\ \text{m/s}^2$.', '["ضُربت الكتلة في الوزن بدل قسمة الوزن على الكتلة.","قُسمت الكتلة على الوزن، أي مقلوب العلاقة الصحيحة.","","قُسم الوزن على 9.80 m/s² كأن الجسم على الأرض، فنتج عدد لا يمثل تسارع الجاذبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.590Z"}'::jsonb),
('mcq', 3, 1, 'الكتلة $m = \frac{F_g}{g} = \frac{147\ \text{N}}{9.80\ \text{m/s}^2} = 15.0\ \text{kg}$ ولا تتغير، ووزنها على القمر $F_g = (15.0\ \text{kg})(1.62\ \text{m/s}^2) = 24.3\ \text{N}$.', '["هذا وزنها على الأرض؛ فالوزن يتغير بتغير $g$ مع أن الكتلة ثابتة.","","قُسم الوزن على 1.62 بدل إيجاد الكتلة ثم ضربها في $g$ للقمر.","ضُرب الوزن (لا الكتلة) في 1.62."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.591Z"}'::jsonb),
('mcq', 4, 3, 'الميل $= \frac{\Delta F_g}{\Delta m} = g$ لأن $F_g = mg$؛ فالميل هو تسارع الجاذبية في ذلك المكان. ميل الخط A يساوي 9.8 N/kg (أي 9.8 m/s²) ويمثل الأرض، وميل B يساوي 1.62 m/s² تقريبًا ويمثل مكانًا جاذبيته أقل كالقمر.', '["الكتلة هي المتغير على المحور الأفقي، وليست الميل.","الخطان يمثلان الوزن مقابل الكتلة، والميل نسبة الوزن إلى الكتلة لا القوة المحصلة.","الميل = الوزن ÷ الكتلة $= g$، وليس الكتلة ÷ الوزن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-19T07:48:34.591Z"}'::jsonb),
('mcq', 5, 0, '$F_g = mg$: الكتلة ثابتة، فإذا قلت $g$ قليلًا قل الوزن قليلًا. لذلك لا يتغير وزن الجسم كثيرًا من مكان إلى آخر على سطح الأرض لأن $g$ ثابتة تقريبًا.', '["","العكس هو الصحيح؛ الكتلة لا تعتمد على المكان، والوزن يعتمد على $g$.","الكتلة لا تتغير بتغير المكان، فلا تقل مع الوزن.","الوزن $F_g = mg$ يتغير عندما تتغير $g$ ولو قليلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.591Z"}'::jsonb),
('mcq', 6, 2, '$F_g = mg$ والكتلة ثابتة؛ فإذا تضاعفت $g$ تضاعف الوزن: $F_{g2} = m(2g) = 2F_{g1}$.', '["الوزن يعتمد على $g$، فلا يبقى ثابتًا إذا تغيرت $g$.","العلاقة طردية لا عكسية؛ مضاعفة $g$ تضاعف الوزن.","","الوزن يتناسب مع $g$ تناسبًا طرديًا بسيطًا، لا مع مربعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.591Z"}'::jsonb),
('mcq', 7, 3, '$F_{gA} = (2.00)(9.80) = 19.6\ \text{N}$، و$F_{gB} = (10.0)(1.62) = 16.2\ \text{N}$؛ إذن وزن A أكبر مع أن كتلته أصغر، لأن الوزن يعتمد على الكتلة و$g$ معًا.', '["المقارنة بالكتلة وحدها خطأ؛ فالوزن $mg$ يعتمد أيضًا على $g$: وزن B هو 16.2 N فقط.","الوزنان مختلفان: 19.6 N و16.2 N.","يمكن المقارنة بحساب $F_g = mg$ لكل جسم، فالوزن قوة تقاس بالنيوتن في أي مكان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.591Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عند الرفع بسرعة منتظمة تكون القوة المحصلة صفرًا، فالقوة اللازمة تساوي الوزن. على الأرض: $F = mg = (10.0)(9.80) = 98.0\ \text{N}$. على القمر: $F = (10.0)(1.62) = 16.2\ \text{N}$. القوة على القمر أقل بنحو 6 مرات ($98.0 \div 16.2 \approx 6.0$) لأن $g$ هناك أقل، أما الكتلة فلم تتغير.', '["القوة اللازمة تساوي الوزن لأن السرعة منتظمة (القوة المحصلة صفر)","على الأرض 98.0 N","على القمر 16.2 N","التفسير: الوزن يتناسب مع $g$ والكتلة ثابتة"]'::jsonb, '["السرعة منتظمة $\\Leftarrow$ $\\boldsymbol{F}_{\\text{المحصلة}} = 0$، إذن $F = F_g = mg$","الأرض: $F = (10.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 98.0\\ \\text{N}$","القمر: $F = (10.0\\ \\text{kg})(1.62\\ \\text{m/s}^2) = 16.2\\ \\text{N}$","النسبة $\\frac{98.0}{16.2} \\approx 6.0$"]'::jsonb, '[{"element":"تبرير أن القوة تساوي الوزن","marks":1},{"element":"حساب القوة على الأرض","marks":1},{"element":"حساب القوة على القمر","marks":1},{"element":"التفسير بتغير g وثبات الكتلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان مع تبرير وتفسير صحيحين"},{"level":"2–3 درجات","description":"حسابان صحيحان دون تفسير كامل"},{"level":"درجة واحدة","description":"حساب واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استخدام 9.80 m/s² للقمر أيضًا","القول إن كتلة الصخرة تقل على القمر","إضافة قوة زائدة على الوزن مع أن السرعة منتظمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.592Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تسارع الجاذبية على عطارد $g = 0.38 \times 9.80\ \text{m/s}^2 \approx 3.7\ \text{m/s}^2$، فالوزن $F_g = mg = (6.0\ \text{kg})(3.7\ \text{m/s}^2) \approx 22\ \text{N}$. (ب) تسارع الجاذبية على بلوتو $g = 0.08 \times 3.7\ \text{m/s}^2 \approx 0.3\ \text{m/s}^2$ (رقم معنوي واحد؛ لأن العدد 0.08 فيه رقم معنوي واحد)، فالوزن $F_g = (7.0\ \text{kg})(0.3\ \text{m/s}^2) \approx 2\ \text{N}$. (ج) الوزن يتغير من كوكب إلى آخر لأنه يساوي $mg$ و$g$ تختلف من كوكب إلى آخر، بينما تبقى الكتلة ثابتة.', '["$g$ على عطارد ≈ 3.7 m/s²","وزن 6.0 kg على عطارد ≈ 22 N","وزن 7.0 kg على بلوتو ≈ 2 N (رقم معنوي واحد)","الاستنتاج: الوزن يتغير بتغير $g$ والكتلة ثابتة"]'::jsonb, '["عطارد: $g = 0.38 \\times 9.80 = 3.724 \\approx 3.7\\ \\text{m/s}^2$","$F_g = mg = (6.0)(3.724) = 22.3 \\approx 22\\ \\text{N}$ (رقمان معنويان)","بلوتو: $g = 0.08 \\times 3.724 = 0.298 \\approx 0.3\\ \\text{m/s}^2$ (رقم معنوي واحد)","$F_g = (7.0)(0.298) = 2.09 \\approx 2\\ \\text{N}$ (رقم معنوي واحد)"]'::jsonb, '[{"element":"حساب الوزن على عطارد","marks":2},{"element":"حساب الوزن على بلوتو","marks":2},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان واستنتاج صحيح"},{"level":"3–4 درجات","description":"حساب واحد صحيح مع استنتاج، أو حسابان دون استنتاج"},{"level":"1–2 درجة","description":"إيجاد g لعطارد فقط أو استنتاج صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الكتلة في 0.38 دون ضربها في 9.80","نسبة بلوتو إلى الأرض مباشرة بدل نسبتها إلى عطارد","كتابة وزن بلوتو بأكثر من رقم معنوي واحد مع أن 0.08 فيه رقم معنوي واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.592Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. الكتلة ثابتة لا تعتمد على المكان، أما الوزن فهو قوة جذب الجرم السماوي للجسم $F_g = mg$، فيتغير بتغير $g$. مثال: على الأرض $F_g = (70.0)(9.80) = 686\ \text{N}$، وعلى القمر $F_g = (70.0)(1.62) = 113\ \text{N}$، مع أن الكتلة 70.0 kg في الحالتين.', '["الحكم: العبارة خاطئة","الكتلة ثابتة والوزن $mg$ يعتمد على $g$","الوزن على الأرض 686 N","الوزن على القمر 113 N"]'::jsonb, '["الأرض: $F_g = (70.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 686\\ \\text{N}$","القمر: $F_g = (70.0\\ \\text{kg})(1.62\\ \\text{m/s}^2) = 113.4 \\approx 113\\ \\text{N}$"]'::jsonb, '[{"element":"الحكم الصحيح مع التعليل","marks":2},{"element":"الحسابان","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح بتعليل وحسابين صحيحين"},{"level":"2–3 درجات","description":"حكم صحيح مع تعليل دون مثال عددي صحيح"},{"level":"درجة واحدة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","الخلط بين الكتلة والوزن في الوحدات","القول إن الكتلة تقل على القمر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.592Z"}'::jsonb)
