('mcq', 2, 'ما الوحدة الدولية لكل من الكتلة والوزن؟', null, null, '["الكتلة والوزن كلاهما بالكيلوجرام","الكتلة بالنيوتن والوزن بالكيلوجرام","الكتلة والوزن كلاهما بالنيوتن","الكتلة بالكيلوجرام والوزن بالنيوتن"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 105 — وحدتا الكتلة والوزن'),
('mcq', 3, 'نُقل صندوق من سطح الأرض إلى سطح القمر. أيّ الكميات الآتية تبقى ثابتة؟', null, null, '["كتلة الصندوق نفسه","وزن الصندوق على السطح","قراءة ميزان نابضي يوضع عليه الصندوق","القوة اللازمة لرفعه بسرعة منتظمة"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 105 — ثبات الكتلة وتغير الوزن'),
('mcq', 4, 'أيّ العبارات الآتية تميّز تمييزًا صحيحًا بين الكتلة والوزن؟', null, null, '["الكتلة قوة تعتمد على $g$، والوزن كمية ثابتة لا تعتمد على المكان","الكتلة والوزن اسمان لكمية واحدة تختلف وحدتها فقط","الكتلة ثابتة لا تعتمد على المكان، والوزن قوة $mg$ تعتمد عليه","الكتلة تتغير بتغير $g$، والوزن ثابت ما دام الجسم لم يتغير"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 124 — اعتماد الوزن على g والكتلة'),
('mcq', 5, 'سجّل طالب في الجدول الآتي كتلة جسم واحد ووزنه في ثلاثة أماكن. أي صف يحتوي على خطأ مفهومي؟', '{"headers":["المكان","الكتلة (kg)","الوزن (N)"],"rows":[["الأرض","4.00","39.2"],["القمر","4.00","6.48"],["الكوكب X","1.51","14.8"]]}'::jsonb, null, '["صف الأرض وحده","صف القمر وحده","صفّا القمر والكوكب X","صف الكوكب X وحده"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 105 — ثبات الكتلة وتغير الوزن'),
('mcq', 6, 'يريد رائد فضاء أن يُكسب صندوقًا تسارعًا أفقيًا مقداره 2.0 m/s² على سطح أملس تمامًا. كيف تقارَن القوة الأفقية اللازمة على سطح القمر بالقوة اللازمة على سطح الأرض؟', null, null, '["القوة على القمر أصغر لأن وزن الصندوق هناك أصغر","متساويتان لأن كتلة الصندوق لا تتغير","القوة على القمر أكبر لأن الصندوق يطفو هناك","القوة على القمر صفر لأن الجاذبية هناك ضعيفة"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 105 — ثبات الكتلة'),
('mcq', 7, 'رائد فضاء في مركبة بعيدة جدًا عن أي كوكب أو نجم، حيث يكاد تسارع الجاذبية يساوي صفرًا. ماذا يمكن القول عن كتلته ووزنه هناك؟', null, null, '["كتلته كما هي، ووزنه يقارب الصفر","كتلته تقارب الصفر، ووزنه كما هو","كتلته ووزنه كلاهما يقاربان الصفر","كتلته ووزنه كلاهما كما كانا على الأرض"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 105 — الوزن والكتلة'),
('essay', 1, 'يبين ميزانك المنزلي أن وزنك 585 N. (أ) ما كتلتك؟ (ب) ما كتلتك على سطح القمر؟ (ج) كيف تكون قراءة الميزان نفسه على سطح القمر، علمًا بأن تسارع الجاذبية هناك 1.6 m/s²؟', null, null, null, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 109 — المسألة 19'),
('essay', 2, 'قارن بين الكتلة والوزن من حيث: التعريف أو العلاقة، والوحدة الدولية، ونوع الكمية (قياسية أم متجهة)، واعتمادها على المكان.', null, null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 105 — الوزن والكتلة'),
('essay', 3, 'جسم كتلته 2.0 kg موضوع على سطح أفقي أملس تمامًا. (أ) احسب وزنه على سطح الأرض وعلى سطح القمر ($g = 1.62\ \text{m/s}^2$). (ب) احسب القوة الأفقية اللازمة لإكسابه تسارعًا 3.0 m/s² في كل من المكانين. (ج) ماذا تستنتج من النتائج عن الكتلة والوزن؟', null, null, null, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 105 — ثبات الكتلة وتغير الوزن')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
