select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الكتلة مقدار ثابت لا يتغير بتغير مكان الجسم، فتبقى 80.0 kg على القمر؛ أما وزنه فيقل لأن $g$ هناك أصغر.', '["قُسمت الكتلة على 6 كأنها الوزن الذي يقل إلى السدس؛ الكتلة لا تتغير.","","قُسمت الكتلة على $g$، وهذا خلط بين الكتلة والوزن.","ضُربت الكتلة في تسارع الجاذبية على القمر (1.62 m/s²) فنتج وزن بالنيوتن تقريبًا، لا كتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.593Z"}'::jsonb),
('mcq', 2, 3, 'الكيلوجرام هو الوحدة الدولية للكتلة، ولأن الوزن قوة فوحدته الدولية النيوتن ($1\ \text{N} = 1\ \text{kg}\cdot\text{m/s}^2$).', '["الوزن قوة، فوحدته النيوتن لا الكيلوجرام.","هذا عكس الصحيح.","الكتلة ليست قوة، فوحدتها الكيلوجرام.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.593Z"}'::jsonb),
('mcq', 3, 0, 'الكتلة لا تعتمد على المكان، أما الوزن وكل ما يساويه (قراءة الميزان النابضي، قوة الرفع بسرعة منتظمة) فيتغير بتغير $g$.', '["","الوزن $mg$ يقل لأن $g$ على القمر أصغر.","الميزان النابضي يقيس الوزن، فتقل قراءته على القمر.","هذه القوة تساوي الوزن، فتقل على القمر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.593Z"}'::jsonb),
('mcq', 4, 2, 'الكتلة ثابتة للجسم أينما وُجد، والوزن $F_g = mg$ قوة جذب تتغير بتغير $g$ من مكان إلى آخر.', '["هذا عكس الصحيح؛ الوزن هو القوة التي تعتمد على $g$.","هما كميتان مختلفتان: إحداهما ثابتة والأخرى قوة تتغير بتغير المكان.","","الكتلة لا تتغير بتغير $g$، والوزن هو الذي يتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.594Z"}'::jsonb),
('mcq', 5, 3, 'الجسم نفسه في الأماكن الثلاثة، فيجب أن تبقى كتلته 4.00 kg. أما في صف الكوكب X فقد تغيرت الكتلة إلى 1.51 kg، وهذا خطأ؛ الصحيح أن تبقى الكتلة 4.00 kg ويختلف الوزن فقط.', '["قيم صف الأرض متسقة: $(4.00)(9.80) = 39.2\\ \\text{N}$.","قيم صف القمر متسقة: الكتلة 4.00 kg لم تتغير، والوزن أقل لأن $g$ أصغر.","صف القمر صحيح؛ فتغير الوزن وحده ليس خطأ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-19T07:48:34.594Z"}'::jsonb),
('mcq', 6, 1, 'على سطح أملس أفقي: $\boldsymbol{F}_{\text{المحصلة}} = m\boldsymbol{a}$، والكتلة نفسها في المكانين، فالقوة اللازمة متساوية. الوزن وحده هو الذي يختلف.', '["القوة الأفقية اللازمة للتسارع تعتمد على الكتلة ($F = ma$) لا على الوزن.","","الصندوق لا يطفو على القمر، وكتلته لم تتغير، فلا تزيد القوة.","تُكسب القوة المحصلة الجسم تسارعًا حسب كتلته، فلا يتسارع الصندوق دون قوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.594Z"}'::jsonb),
('mcq', 7, 0, '$F_g = mg$: إذا قاربت $g$ الصفر قارب الوزن الصفر، أما الكتلة فثابتة لا تعتمد على المكان.', '["","الكتلة لا تنعدم بابتعاد الجسم عن الكواكب، والوزن هو الذي يتغير.","الكتلة لا تعتمد على $g$، فلا تقارب الصفر.","الوزن $mg$ يقارب الصفر عندما تقارب $g$ الصفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.594Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $m = \frac{F_g}{g} = \frac{585}{9.80} = 59.7\ \text{kg}$. (ب) تبقى الكتلة 59.7 kg على القمر لأن الكتلة لا تتغير بتغير المكان. (ج) يقرأ الميزان الوزن: $F_g = (59.7)(1.6) \approx 96\ \text{N}$، أي أقل كثيرًا من قراءته على الأرض.', '["الكتلة 59.7 kg","الكتلة على القمر 59.7 kg (لا تتغير)","قراءة الميزان على القمر ≈ 96 N"]'::jsonb, '["$m = \\frac{585\\ \\text{N}}{9.80\\ \\text{m/s}^2} = 59.7\\ \\text{kg}$","الكتلة ثابتة: 59.7 kg","$F_g = (59.7\\ \\text{kg})(1.6\\ \\text{m/s}^2) = 95.5 \\approx 96\\ \\text{N}$"]'::jsonb, '[{"element":"حساب الكتلة","marks":1},{"element":"ثبات الكتلة على القمر مع التعليل","marks":2},{"element":"قراءة الميزان على القمر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابات صحيحة للأجزاء الثلاثة مع التعليل"},{"level":"2–3 درجات","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الكتلة على 6 على القمر","ضرب 585 في 1.6 مباشرة","إعطاء قراءة الميزان بالكيلوجرام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.594Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الكتلة: مقدار ثابت للجسم، وحدتها الكيلوجرام (kg)، كمية قياسية، لا تعتمد على المكان. الوزن: قوة جذب الأرض (أو الجرم السماوي) للجسم $\boldsymbol{F}_g = m\boldsymbol{g}$، وحدته النيوتن (N)، كمية متجهة اتجاهها إلى أسفل نحو مركز الجرم، ويعتمد على المكان لأن $g$ تتغير من مكان إلى آخر.', '["الوزن قوة $\\boldsymbol{F}_g = m\\boldsymbol{g}$ والكتلة ثابتة","الوحدتان: kg للكتلة، N للوزن","الكتلة قياسية والوزن متجه إلى أسفل","الكتلة لا تعتمد على المكان والوزن يعتمد عليه"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف/العلاقة","marks":1},{"element":"الوحدة","marks":1},{"element":"نوع الكمية","marks":1},{"element":"الاعتماد على المكان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الجوانب الأربعة"},{"level":"2–3 درجات","description":"مقارنة صحيحة في جانبين أو ثلاثة"},{"level":"درجة واحدة","description":"جانب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الوزن كمية قياسية","القول إن الكتلة تتغير على القمر","كتابة وحدة الوزن kg"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.595Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) على الأرض $F_g = (2.0)(9.80) = 19.6 \approx 20\ \text{N}$، وعلى القمر $F_g = (2.0)(1.62) = 3.24 \approx 3.2\ \text{N}$. (ب) $F = ma = (2.0)(3.0) = 6.0\ \text{N}$ في المكانين. (ج) الوزن تغير لأن $g$ تغيرت، أما القوة اللازمة للتسارع الأفقي فلم تتغير لأنها تعتمد على الكتلة، والكتلة ثابتة.', '["الوزن على الأرض ≈ 20 N","الوزن على القمر ≈ 3.2 N","القوة الأفقية 6.0 N في المكانين","الاستنتاج: الكتلة ثابتة والوزن يتغير"]'::jsonb, '["$F_g = mg = (2.0)(9.80) = 19.6 \\approx 20\\ \\text{N}$","$F_g = (2.0)(1.62) = 3.24 \\approx 3.2\\ \\text{N}$","$F_{\\text{المحصلة}} = ma = (2.0)(3.0) = 6.0\\ \\text{N}$ في المكانين"]'::jsonb, '[{"element":"حساب الوزنين","marks":2},{"element":"حساب القوة الأفقية","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة واستنتاج صحيح"},{"level":"2–3 درجات","description":"حسابات صحيحة دون استنتاج أو العكس"},{"level":"درجة واحدة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استخدام الوزن بدل الكتلة في $F = ma$","استنتاج أن القوة الأفقية أقل على القمر","عدم تقريب النتائج إلى رقمين معنويين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.595Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
