('mcq', 2, 'تزن دراجة نارية 2450 N على سطح الأرض. ما كتلتها؟', null, null, '["$2.40 \\times 10^4\\ \\text{kg}$","$2.45 \\times 10^3\\ \\text{kg}$","$2.50 \\times 10^2\\ \\text{kg}$","$4.00 \\times 10^{-3}\\ \\text{kg}$"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 125 — التقويم 51'),
('mcq', 3, 'وُضع تلفاز كتلته 7.50 kg على ميزان نابضي في مكان ما، فكانت قراءة الميزان 78.4 N. ما تسارع الجاذبية في ذلك المكان؟', null, null, '["$588\\ \\text{m/s}^2$","$10.5\\ \\text{m/s}^2$","$0.0957\\ \\text{m/s}^2$","$9.80\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 125 — التقويم 52'),
('mcq', 4, 'يرفع حبل صندوقًا كتلته 5.0 kg رأسيًا بتسارع مقداره 2.0 m/s² إلى أعلى، كما في مخطط الجسم الحر الآتي (الاتجاه الموجب إلى أعلى). ما مقدار قوة الشد في الحبل؟', null, '[{"src":"qimg/phys1/c4l2-o03-fbd-rope-up.svg","alt":"مخطط جسم حر لصندوق صغير: سهم أزرق طويل يخرج من الصندوق إلى أعلى مكتوب عنده F_T، وسهم أزرق أقصر يخرج منه إلى أسفل مكتوب عنده F_g. على يمين الشكل سهم بنفسجي إلى أعلى مكتوب عنده a يمثل التسارع، وعلى يساره سهم أسود إلى أعلى مكتوب عنده +y يمثل الاتجاه الموجب."}]'::jsonb, '["49 N","39 N","10 N","59 N"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 105 — قانون نيوتن الثاني مع قوة الجاذبية'),
('mcq', 5, 'ما القوة المحصلة المؤثرة في كرة كتلتها 1.0 kg تسقط سقوطًا حرًا؟ (أهمل مقاومة الهواء)', null, null, '["9.8 N إلى أسفل","0 N لعدم وجود قوة محصلة","9.8 N إلى أعلى","1.0 N إلى أسفل"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 125 — التقويم 48'),
('mcq', 6, 'تُنزل رافعة صندوقًا كتلته 200 kg بحبل رأسي، فيتسارع الصندوق إلى أسفل بمقدار 1.5 m/s²، كما في المخطط الآتي (الاتجاه الموجب إلى أعلى). ما مقدار قوة الشد في الحبل؟', null, '[{"src":"qimg/phys1/c4l2-o03-fbd-crane-down.svg","alt":"مخطط جسم حر لصندوق: سهم أزرق إلى أعلى مكتوب عنده F_T، وسهم أزرق أطول قليلًا إلى أسفل مكتوب عنده F_g. على يمين الشكل سهم بنفسجي إلى أسفل مكتوب عنده a يمثل التسارع، وعلى يساره سهم أسود إلى أعلى مكتوب عنده +y."}]'::jsonb, '["$1.96 \\times 10^3\\ \\text{N}$","$1.66 \\times 10^3\\ \\text{N}$","$2.26 \\times 10^3\\ \\text{N}$","$3.00 \\times 10^2\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 105 — قانون نيوتن الثاني مع قوة الجاذبية'),
('mcq', 7, 'تُسحب كرة كتلتها 2.0 kg رأسيًا إلى أعلى بقوة مقدارها 30.0 N. ما تسارع الكرة؟ (أهمل مقاومة الهواء، واعتبر الاتجاه الموجب إلى أعلى)', null, null, '["$+15\\ \\text{m/s}^2$","$+25\\ \\text{m/s}^2$","$+5.2\\ \\text{m/s}^2$","$+14\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 105 — قانون نيوتن الثاني مع قوة الجاذبية'),
('essay', 1, 'يبين الشكل الآتي مكعبًا خشبيًا كتلته 1.2 kg معلقًا بميزان نابضي علوي، وتتدلى منه كرة كتلتها 3.0 kg معلقة بميزان نابضي سفلي، والنظام ساكن. ما قراءة كل من الميزانين؟ (أهمل كتلة الميزانين)', null, '[{"src":"qimg/phys1/c4l2-o03-two-scales.svg","alt":"سقف أفقي يتدلى منه ميزان نابضي مكتوب بجانبه «الميزان العلوي»، ويتدلى منه مكعب خشبي مكتوب عليه 1.2 kg، ثم ميزان نابضي ثانٍ مكتوب بجانبه «الميزان السفلي»، ويتدلى منه كرة مكتوب عليها 3.0 kg."}]'::jsonb, null, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 106 — المسألة 18'),
('essay', 2, 'قفز غواص كتلته 65 kg من قمة برج ارتفاعه 10.0 m إلى بركة ماء (أهمل مقاومة الهواء). (أ) أوجد سرعة الغواص لحظة ارتطامه بسطح الماء. (ب) إذا توقف الغواص بعد أن قطع 2.0 m تحت سطح الماء بتسارع ثابت، فأوجد القوة المحصلة المؤثرة فيه في أثناء توقفه، ثم القوة التي يؤثر بها الماء فيه.', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 126 — التقويم 55'),
('essay', 3, 'يُرفع صندوق كتلته 25 kg رأسيًا بحبل لا يتحمل قوة شد أكبر من 300 N. (أ) ارسم مخطط الجسم الحر للصندوق موضحًا الاتجاه الموجب. (ب) ما أكبر تسارع إلى أعلى يمكن أن يكتسبه الصندوق دون أن ينقطع الحبل؟', null, null, null, 'تحليل', 'حل مسألة', 'متوسط', 'الكتاب ص 105 — قانون نيوتن الثاني مع قوة الجاذبية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
