select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, '$F_g = mg = (4.0\ \text{kg})(9.80\ \text{m/s}^2) = 39.2 \approx 39\ \text{N}$ (رقمان معنويان).', '["","قُسمت الكتلة على $g$ بدل ضربها فيه.","هذا مقدار الكتلة نفسه؛ والوزن قوة تساوي $mg$.","جُمعت الكتلة مع $g$ بدل ضربهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.595Z"}'::jsonb),
('mcq', 2, 2, '$m = \frac{F_g}{g} = \frac{2450\ \text{N}}{9.80\ \text{m/s}^2} = 250\ \text{kg} = 2.50 \times 10^2\ \text{kg}$.', '["ضُرب الوزن في $g$ بدل القسمة عليه.","اعتُبر الوزن بالنيوتن كتلة بالكيلوجرام.","","قُسم $g$ على الوزن، أي مقلوب العلاقة الصحيحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.596Z"}'::jsonb),
('mcq', 3, 1, 'التلفاز ساكن، فقراءة الميزان تساوي وزنه: $g = \frac{F_g}{m} = \frac{78.4\ \text{N}}{7.50\ \text{kg}} = 10.45 \approx 10.5\ \text{m/s}^2$.', '["ضُرب الوزن في الكتلة بدل القسمة.","","قُسمت الكتلة على الوزن، أي مقلوب العلاقة.","افترض أن المكان على سطح الأرض دون استعمال البيانات المعطاة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.596Z"}'::jsonb),
('mcq', 4, 3, '$\boldsymbol{F}_{\text{المحصلة}} = \boldsymbol{F}_{\text{T}} + \boldsymbol{F}_g$، وبالإشارات: $F_{\text{T}} - mg = ma$، إذن $F_{\text{T}} = m(a + g) = (5.0)(2.0 + 9.80) = 59\ \text{N}$.', '["هذه قوة الشد لو كان الصندوق ساكنًا أو يتحرك بسرعة منتظمة (تساوي الوزن فقط).","استُخدم $m(g - a)$ كأن التسارع إلى أسفل.","هذه القوة المحصلة $ma$ فقط، وقد أُهمل الوزن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-19T07:48:34.596Z"}'::jsonb),
('mcq', 5, 0, 'في السقوط الحر القوة الوحيدة هي الوزن، و$\boldsymbol{a} = \boldsymbol{g}$: $\boldsymbol{F}_{\text{المحصلة}} = \boldsymbol{F}_g = m\boldsymbol{g}$، مقدارها $(1.0)(9.80) = 9.8\ \text{N}$ إلى أسفل.', '["","الكرة تتسارع، فلا يمكن أن تكون القوة المحصلة صفرًا.","القوة المحصلة هي الوزن واتجاهه إلى أسفل لا إلى أعلى.","هذا مقدار الكتلة وليس القوة؛ لم يُضرب في $g$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.596Z"}'::jsonb),
('mcq', 6, 1, 'باختيار الموجب إلى أعلى: $\boldsymbol{a} = -1.5\ \text{m/s}^2$. $F_{\text{T}} - mg = ma$، إذن $F_{\text{T}} = m(g + a) = (200)(9.80 + (-1.5)) = (200)(8.3) = 1660\ \text{N} = 1.66 \times 10^3\ \text{N}$.', '["هذه قيمة الوزن؛ تصح لو كان التسارع صفرًا.","","استُخدم $m(g + a)$ كأن التسارع إلى أعلى.","هذه القوة المحصلة $ma$ وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-19T07:48:34.596Z"}'::jsonb),
('mcq', 7, 2, '$F_{\text{المحصلة}} = F - mg = 30.0 - (2.0)(9.80) = 10.4\ \text{N}$، و$a = \frac{10.4}{2.0} = +5.2\ \text{m/s}^2$ (إلى أعلى).', '["قُسمت القوة المؤثرة على الكتلة وأُهمل الوزن.","جُمع الوزن مع القوة كأنهما في اتجاه واحد: $(30.0 + 19.6) \\div 2.0$.","","طُرحت الكتلة (2.0) من القوة بدل طرح الوزن: $(30.0 - 2.0) \\div 2.0$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.597Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الميزان السفلي يحمل الكرة فقط: $F = (3.0)(9.80) = 29.4 \approx 29\ \text{N}$. الميزان العلوي يحمل المكعب والكرة معًا: $F = (1.2 + 3.0)(9.80) = 41.2 \approx 41\ \text{N}$. في الحالتين النظام ساكن، فالقوة المحصلة صفر وقراءة الميزان تساوي الوزن الذي يحمله.', '["الميزان السفلي ≈ 29 N","الميزان العلوي ≈ 41 N","التبرير: النظام متزن فالقراءة تساوي الوزن المحمول"]'::jsonb, '["الميزان السفلي يحمل الكرة وحدها: $F_{\\text{الميزان}} = (3.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 29.4 \\approx 29\\ \\text{N}$","الميزان العلوي يحمل المكعب والكرة معًا: $F_{\\text{الميزان}} = (1.2\\ \\text{kg} + 3.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 41.2 \\approx 41\\ \\text{N}$"]'::jsonb, '[{"element":"قراءة الميزان السفلي","marks":1},{"element":"قراءة الميزان العلوي","marks":2},{"element":"التبرير بالاتزان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"قراءتان صحيحتان مع تبرير"},{"level":"2–3 درجات","description":"قراءة واحدة صحيحة مع تبرير، أو القراءتان دون تبرير"},{"level":"درجة واحدة","description":"قراءة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الميزان العلوي يقرأ وزن المكعب وحده","جعل الميزانين يقرآن القيمة نفسها","إعطاء القراءة بالكيلوجرام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.597Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) باعتبار الاتجاه الموجب إلى أسفل في أثناء السقوط: $v_f^2 = v_i^2 + 2ad = 0 + 2(9.80)(10.0) = 196$، إذن $v_f = 14.0\ \text{m/s}$ إلى أسفل. (ب) باعتبار الاتجاه الموجب إلى أعلى: يدخل الغواص الماء بسرعة $v_i = -14.0\ \text{m/s}$ ويتوقف ($v_f = 0$) بعد إزاحة $d = -2.0\ \text{m}$، فتسارعه $a = \frac{v_f^2 - v_i^2}{2d} = \frac{0 - 196}{2(-2.0)} = +49\ \text{m/s}^2$، أي 49 m/s² إلى أعلى. القوة المحصلة $F_{\text{المحصلة}} = ma = (65)(49) \approx 3.2 \times 10^3\ \text{N}$ إلى أعلى. وقوة الماء $F$ تحقق $F - mg = ma$، إذن $F = m(a + g) = 65(49 + 9.80) \approx 3.8 \times 10^3\ \text{N}$ إلى أعلى.', '["سرعة الارتطام 14.0 m/s","تسارع التوقف 49 m/s² إلى أعلى","القوة المحصلة $\\approx 3.2 \\times 10^3$ N إلى أعلى","قوة الماء $\\approx 3.8 \\times 10^3$ N إلى أعلى"]'::jsonb, '["(أ) الموجب إلى أسفل: $v_f = \\sqrt{2gd} = \\sqrt{2(9.80)(10.0)} = 14.0\\ \\text{m/s}$","(ب) الموجب إلى أعلى: $a = \\frac{0 - (-14.0)^2}{2(-2.0)} = +49\\ \\text{m/s}^2$","$F_{\\text{المحصلة}} = ma = (65)(49) = 3185 \\approx 3.2 \\times 10^3\\ \\text{N}$ إلى أعلى","$F = F_{\\text{المحصلة}} + mg = 3185 + 637 = 3822 \\approx 3.8 \\times 10^3\\ \\text{N}$ إلى أعلى"]'::jsonb, '[{"element":"سرعة الارتطام","marks":1},{"element":"تسارع التوقف","marks":1},{"element":"القوة المحصلة","marks":1},{"element":"قوة الماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الأربعة صحيحة مع الاتجاهات"},{"level":"2–3 درجات","description":"جزءان أو ثلاثة صحيحة"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار قوة الماء مساوية للقوة المحصلة","نسيان الجذر التربيعي عند حساب السرعة","إهمال اتجاه التسارع في الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.597Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) مخطط الجسم الحر: الصندوق نقطة، يخرج منها سهم $\boldsymbol{F}_{\text{T}}$ إلى أعلى وسهم $\boldsymbol{F}_g$ إلى أسفل، وسهم $+y$ إلى أعلى، و$\boldsymbol{F}_{\text{T}}$ أطول لأن التسارع إلى أعلى. (ب) $F_{\text{T}} - mg = ma$، إذن $a = \frac{F_{\text{T}}}{m} - g = \frac{300}{25} - 9.80 = 12 - 9.80 = 2.2\ \text{m/s}^2$ إلى أعلى.', '["مخطط صحيح بقوتين متعاكستين و$F_{\\text{T}}$ أطول","اتجاه موجب محدد","معادلة نيوتن الثانية بالإشارات","أكبر تسارع 2.2 m/s² إلى أعلى"]'::jsonb, '["$+y$ إلى أعلى: $F_{\\text{T}} - mg = ma$","$mg = (25)(9.80) = 245\\ \\text{N}$","$a = \\frac{300 - 245}{25} = 2.2\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"مخطط الجسم الحر","marks":1},{"element":"كتابة المعادلة بالإشارات","marks":1},{"element":"الحساب الصحيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"مخطط صحيح وحساب صحيح"},{"level":"2–3 درجات","description":"حساب صحيح بلا مخطط أو مخطط صحيح مع خطأ حسابي"},{"level":"درجة واحدة","description":"مخطط صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 300 N على الكتلة دون طرح $g$ (12 m/s²)","رسم القوة المحصلة على مخطط الجسم الحر","رسم الأسهم متساوية الطول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-19T07:48:34.597Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
