insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L2-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالوزن الظاهري لجسم؟', null, null, '["قوة جذب الأرض للجسم، وتساوي حاصل ضرب كتلته في تسارع الجاذبية","مقدار المادة في الجسم، ولا يتغير بتغير مكانه","وزن تحس به أو تقيسه نتيجة قوة تلامس تكسب الجسم تسارعًا","قوة الممانعة التي يؤثر بها مائع في جسم يتحرك خلاله"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 124 — تعريف الوزن الظاهري'),
('mcq', 2, 'ماذا تسمى القوة التي يؤثر بها الميزان في شخص يقف عليه داخل مصعد؟', null, null, '["الوزن الظاهري","الوزن الحقيقي","القوة المعيقة","قوة الجاذبية الأرضية"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 107 — الوزن الظاهري'),
('mcq', 3, 'ما نوع القوة التي تمثل الوزن الظاهري لشخص يقف على ميزان؟', null, null, '["قوة مجال تؤثر بها الأرض في الشخص","قوة تلامس يؤثر بها الميزان في الشخص","قوة مجال يؤثر بها الشخص في الأرض","قوة تلامس يؤثر بها الشخص في الأرض"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 124 — تعريف الوزن الظاهري'),
('mcq', 4, 'ما الوحدة الدولية التي يقاس بها الوزن الظاهري؟', null, null, '["الكيلوجرام (kg)","المتر/ثانية² (m/s²)","الكيلوجرام·متر (kg·m)","النيوتن (N)"]'::jsonb, 'تذكر', 'تذكر وحدة', 'سهل', 'الكتاب ص 107 — الوزن الظاهري'),
('mcq', 5, 'يبين المخطط الآتي القوى المؤثرة في شخص يقف على ميزان داخل مصعد يتسارع إلى أعلى. أي القوتين تمثل الوزن الظاهري للشخص؟', null, '[{"src":"qimg/phys1/c4l2-o04-fbd-elev.svg","alt":"مخطط جسم حر: نقطة تمثل الشخص، يخرج منها سهم أزرق إلى أعلى مكتوب عنده F_الميزان وسهم أزرق أقصر إلى أسفل مكتوب عنده F_g. على يمين الشكل سهم بنفسجي إلى أعلى مكتوب عنده a يمثل التسارع، وعلى يساره سهم أسود إلى أعلى مكتوب عنده +y."}]'::jsonb, '["$\\boldsymbol{F}_g$ لأنها قوة جذب الأرض للشخص","$\\boldsymbol{F}_g$ لأنها القوة الأقصر في المخطط","$\\boldsymbol{F}_g$ و$\\boldsymbol{F}_{\\text{الميزان}}$ معًا لأن مجموعهما هو الوزن الظاهري","$\\boldsymbol{F}_{\\text{الميزان}}$ لأنها القوة التي يؤثر بها الميزان في الشخص"]'::jsonb, 'فهم', 'قراءة مخطط', 'متوسط', 'الكتاب ص 107 — الوزن الظاهري — الشكل 4-11'),
('mcq', 6, 'شخص ساكن يقف على ميزان بقدم واحدة، بينما يستند بقدمه الأخرى إلى الأرض. لماذا لا يقرأ الميزان وزنه الحقيقي؟', null, null, '["لأن الأرض تدعمه بقوة تلامس أخرى فتقل قوة الميزان","لأن كتلته تتوزع بين القدمين فتقل كتلته على الميزان","لأن قوة جذب الأرض له تقل عندما يرفع قدمه","لأن الميزان لا يقرأ إلا عندما يتحرك الشخص بسرعة منتظمة"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 107 — قوى التلامس الأخرى وقراءة الميزان'),
('mcq', 7, 'شخص يقف على ميزان داخل مصعد انقطع حبله فأصبح يسقط سقوطًا حرًا. ما وزن الشخص الظاهري في أثناء السقوط؟', null, null, '["يساوي وزنه الحقيقي لأن كتلته لم تتغير","صفر، مع أن وزنه الحقيقي لم يتغير","مِثلَي وزنه الحقيقي لأن تسارعه يساوي $g$","صفر لأن وزنه الحقيقي أصبح صفرًا"]'::jsonb, 'فهم', 'استنتاج', 'صعب', 'الكتاب ص 129 — الأسئلة الممتدة 8 (السقوط الحر)'),
('essay', 1, 'عرّف كلًا من الوزن الحقيقي والوزن الظاهري، واكتب العلاقة الرياضية التي تحسب كلًا منهما لشخص كتلته $m$ يقف على ميزان في مصعد يتسارع بتسارع $a$ إلى أعلى.', null, null, null, 'تذكر', 'تعريف', 'متوسط', 'الكتاب ص 107 — الوزن الظاهري'),
('essay', 2, 'تقف ساكنًا على ميزان منزلي. فسّر كيف تتغير قراءة الميزان مقارنة بوزنك الحقيقي في كل حالة: (أ) يضغط زميلك على كتفيك إلى أسفل. (ب) تستند بمرفقيك إلى طاولة فتؤثر الطاولة فيك بقوة إلى أعلى. وما العلاقة بين ذلك وتعريف الوزن الظاهري؟', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 107 — قوى التلامس الأخرى وقراءة الميزان'),
('essay', 3, 'قال طالب: «الوزن الظاهري هو الوزن الحقيقي نفسه، لكنه مقيس بميزان غير دقيق». قوّم هذه العبارة مستعينًا بتعريف الوزن الظاهري وبمثال.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 108 — الوزن الحقيقي والوزن الظاهري')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
