select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الوزن الظاهري هو الوزن الذي تحس به أو تقيسه نتيجة تأثير قوة تلامس في الجسم تكسبه تسارعًا، مثل القوة التي يؤثر بها الميزان فيك وأنت في مصعد.', '["هذا تعريف الوزن الحقيقي $F_g = mg$.","هذا وصف الكتلة لا الوزن الظاهري.","","هذا تعريف القوة المعيقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.598Z"}'::jsonb),
('mcq', 2, 0, 'تسمى القوة التي يؤثر بها الميزان في الشخص الوزن الظاهري، وهي قوة تلامس قد تزيد أو تقل عن الوزن الحقيقي حسب تسارع المصعد.', '["","الوزن الحقيقي قوة جذب الأرض للشخص، لا قوة الميزان.","القوة المعيقة يؤثر بها مائع في جسم متحرك خلاله.","قوة الجاذبية تؤثر بها الأرض، والميزان يؤثر بقوة تلامس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.598Z"}'::jsonb),
('mcq', 3, 1, 'الوزن الظاهري هو القوة التي يؤثر بها الميزان في الشخص، وهي قوة تلامس لأنها تنشأ عن تلامس قدمي الشخص مع سطح الميزان.', '["قوة المجال من الأرض هي الوزن الحقيقي.","","هذه رد فعل لقوة جذب الأرض للشخص، وليست قوة الميزان.","القوة المقصودة يؤثر بها الميزان في الشخص لا العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.598Z"}'::jsonb),
('mcq', 4, 3, 'الوزن الظاهري قوة، فيقاس بالنيوتن مثل أي قوة: $1\ \text{N} = 1\ \text{kg}\cdot\text{m/s}^2$.', '["الكيلوجرام وحدة الكتلة، والوزن الظاهري قوة.","هذه وحدة التسارع.","هذه ليست وحدة القوة؛ وحدة القوة kg·m/s² أي النيوتن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.598Z"}'::jsonb),
('mcq', 5, 3, 'الوزن الظاهري هو القوة التي يؤثر بها الميزان في الشخص، أي $\boldsymbol{F}_{\text{الميزان}}$. وفي هذه الحالة هي أكبر من $\boldsymbol{F}_g$ لأن التسارع إلى أعلى.', '["$\\boldsymbol{F}_g$ هي الوزن الحقيقي لا الظاهري.","طول السهم لا يحدد أي القوتين هي الوزن الظاهري؛ والوزن الظاهري هو قوة الميزان.","مجموع القوتين هو القوة المحصلة لا الوزن الظاهري؛ الوزن الظاهري قوة الميزان وحدها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.599Z"}'::jsonb),
('mcq', 6, 0, 'يقرأ الميزان وزنك الحقيقي إذا كانت قوته هي القوة الوحيدة المؤثرة فيك إلى أعلى. وعند وجود قوة تلامس أخرى (من الأرض) يتقاسم الميزان والأرض دعمك، فتقل قوة الميزان وتكون قراءته أقل من وزنك.', '["","الكتلة لا تتوزع ولا تتغير؛ الذي يتغير هو توزع قوى التلامس إلى أعلى.","الوزن الحقيقي $mg$ لا يتغير بطريقة الوقوف.","الميزان يقرأ وزنك وأنت ساكن إذا كانت قوته هي القوة الوحيدة إلى أعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.599Z"}'::jsonb),
('mcq', 7, 1, 'في السقوط الحر $\boldsymbol{a} = \boldsymbol{g}$، فتكون القوة المحصلة هي الوزن وحده: $F_{\text{الميزان}} - mg = m(-g)$ (الموجب إلى أعلى) $\Leftarrow F_{\text{الميزان}} = 0$. الوزن الظاهري صفر والوزن الحقيقي $mg$ كما هو.', '["الوزن الظاهري هو قوة الميزان، وهي تنعدم في السقوط الحر.","","التسارع إلى أسفل يقلل الوزن الظاهري لا يزيده.","الوزن الحقيقي $mg$ لا ينعدم؛ الأرض ما زالت تجذب الشخص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.599Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الوزن الحقيقي: قوة جذب الأرض للجسم، $F_g = mg$. الوزن الظاهري: الوزن الذي تحس به أو تقيسه نتيجة قوة تلامس تكسب الجسم تسارعًا، وهو القوة التي يؤثر بها الميزان. في المصعد المتسارع إلى أعلى (الموجب إلى أعلى): $F_{\text{الميزان}} - mg = ma$، إذن $F_{\text{الميزان}} = m(a + g)$.', '["تعريف الوزن الحقيقي $F_g = mg$","تعريف الوزن الظاهري (قوة الميزان / قوة تلامس)","$F_{\\text{الميزان}} = m(a + g)$"]'::jsonb, '["$+y$ إلى أعلى: $\\boldsymbol{F}_{\\text{المحصلة}} = \\boldsymbol{F}_{\\text{الميزان}} + \\boldsymbol{F}_g$","$ma = F_{\\text{الميزان}} - mg$","$F_{\\text{الميزان}} = m(a + g)$"]'::jsonb, '[{"element":"تعريف الوزن الحقيقي","marks":1},{"element":"تعريف الوزن الظاهري","marks":1},{"element":"العلاقة الرياضية للوزن الظاهري","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريفان صحيحان وعلاقة صحيحة"},{"level":"درجتان","description":"تعريفان صحيحان دون العلاقة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الوزن الظاهري بأنه الكتلة","كتابة $F_{\\text{الميزان}} = m(g - a)$ للتسارع إلى أعلى","الخلط بين الوزن الظاهري والقوة المحصلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.599Z"}'::jsonb),
('essay', 2, null::int, null, null, 'أنت ساكن في الحالتين، فالقوة المحصلة صفر. (أ) القوى إلى أسفل: وزنك وقوة زميلك؛ فيجب أن تكون قوة الميزان إلى أعلى مساوية لمجموعهما، فتزيد القراءة على وزنك. (ب) القوى إلى أعلى: قوة الميزان وقوة الطاولة؛ ومجموعهما يساوي وزنك، فتقل قراءة الميزان عن وزنك. الميزان يقيس القوة التي يؤثر بها فيك (الوزن الظاهري)، ولا تساوي وزنك الحقيقي إلا إذا كانت القوة الوحيدة إلى أعلى ولم تتسارع.', '["الاتزان: القوة المحصلة صفر","(أ) القراءة أكبر من الوزن","(ب) القراءة أقل من الوزن","الربط: الميزان يقيس قوته فيك (الوزن الظاهري)"]'::jsonb, '[]'::jsonb, '[{"element":"استخدام شرط الاتزان","marks":1},{"element":"الحالة (أ)","marks":1},{"element":"الحالة (ب)","marks":1},{"element":"الربط بالتعريف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح للحالتين مع الربط بالتعريف"},{"level":"2–3 درجات","description":"حالة واحدة صحيحة مع تعليل أو الحالتان دون تعليل"},{"level":"درجة واحدة","description":"حكم صحيح في حالة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الوزن الحقيقي يزيد عند الضغط على الكتفين","إغفال قوة الطاولة في الحالة (ب)","الخلط بين الوزن الظاهري والكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.599Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. الوزن الظاهري ليس خطأ قياس، بل هو قوة حقيقية مختلفة: القوة التي يؤثر بها الميزان (قوة تلامس) في الجسم، وتعتمد على تسارع الجسم. أما الوزن الحقيقي فهو قوة جذب الأرض $mg$. مثال: شخص كتلته 75.0 kg في مصعد ساكن يقرأ الميزان 735 N (يساوي وزنه)، وإذا تسارع المصعد إلى أعلى بمقدار 2.00 m/s² قرأ الميزان الدقيق نفسه $75.0(2.00 + 9.80) = 885\ \text{N}$ مع أن وزنه الحقيقي ما زال 735 N.', '["الحكم: العبارة خاطئة","الوزن الظاهري قوة الميزان (تلامس) والحقيقي قوة الجاذبية","الوزن الظاهري يعتمد على التسارع","مثال صحيح"]'::jsonb, '["ساكن: $F_{\\text{الميزان}} = mg = (75.0)(9.80) = 735\\ \\text{N}$","متسارع إلى أعلى: $F_{\\text{الميزان}} = m(a + g) = 75.0(11.8) = 885\\ \\text{N}$"]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"التمييز بين القوتين","marks":1},{"element":"ربط الوزن الظاهري بالتسارع","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح بتعليل كامل ومثال"},{"level":"2–3 درجات","description":"حكم صحيح بتعليل ناقص أو بلا مثال"},{"level":"درجة واحدة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة","القول إن الوزن الحقيقي يتغير في المصعد","تقديم مثال لا يتضمن تسارعًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.600Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
