('mcq', 6, 'الشخص A كتلته 60 kg ويقف ساكنًا على سطح القمر، والشخص B كتلته 60 kg ويقف على ميزان في مصعد على الأرض يتسارع إلى أعلى. أيّ العبارات الآتية صحيحة؟', null, null, '["الوزنان الحقيقيان متساويان لأن الكتلتين متساويتان","الوزن الحقيقي لـ A أكبر لأن A ساكن","لا يمكن المقارنة لأن أحدهما يتسارع والآخر ساكن","الوزن الحقيقي لـ B أكبر من الوزن الحقيقي لـ A"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 105 — الوزن الحقيقي والظاهري'),
