('mcq', 4, 2, '$\boldsymbol{F}_{\text{الميزان}}$ هي الوزن الظاهري، و$\boldsymbol{F}_g$ هي الوزن الحقيقي. السهم $\boldsymbol{F}_{\text{الميزان}}$ أقصر، فالوزن الظاهري أقل من الحقيقي (والمصعد يتسارع إلى أسفل).', '["السهم $\\boldsymbol{F}_{\\text{الميزان}}$ (الوزن الظاهري) أقصر من $\\boldsymbol{F}_g$، فهو أقل.","السهمان مختلفان في الطول، فالقوتان غير متساويتين.","","الوزن الحقيقي $mg$ لا يتغير؛ الذي قلّ هو قوة الميزان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.601Z"}'::jsonb),
('mcq', 5, 0, 'الوزن الحقيقي (735 N) ثابت، والميزان يقرأ الوزن الظاهري (700 N) الذي يقل عن الحقيقي لأن المصعد يتسارع إلى أسفل.', '["","جذب الأرض للشخص (الوزن الحقيقي) لم يتغير.","الكتلة ثابتة لا تتأثر بالحركة.","الميزان سليم؛ هو يقرأ الوزن الظاهري الذي يختلف عن الحقيقي عندما يتسارع المصعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.601Z"}'::jsonb),
('mcq', 6, 3, 'الوزن الحقيقي $mg$ لا يعتمد على التسارع بل على $g$: B على الأرض $(60)(9.80) \approx 590\ \text{N}$، وA على القمر $(60)(1.62) \approx 97\ \text{N}$.', '["الوزن الحقيقي $mg$ يعتمد على $g$ أيضًا، و$g$ على القمر أصغر.","السكون لا يزيد الوزن الحقيقي، و$g$ على القمر أصغر.","يمكن المقارنة لأن الوزن الحقيقي $mg$ لا يعتمد على التسارع، فيكفي معرفة الكتلة و$g$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.602Z"}'::jsonb),
('mcq', 7, 2, 'كلاهما قوة وحدتها النيوتن، لكن الحقيقي قوة مجال (جذب الأرض) ثابتة، والظاهري قوة تلامس (من الميزان) تتغير بتغير التسارع.', '["الوزن الظاهري قوة تلامس من الميزان لا قوة مجال.","الوزن الحقيقي قوة مجال من الأرض لا قوة تلامس.","","الوزن الحقيقي لا يتغير بالتسارع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.602Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الوزن الحقيقي: قوة جذب الأرض للشخص، قوة مجال، $F_g = mg$، لا يتأثر بتسارع المصعد. الوزن الظاهري: القوة التي يؤثر بها الميزان في الشخص، قوة تلامس، $F_{\text{الميزان}} = m(a + g)$ باعتبار الموجب إلى أعلى، يزيد على الحقيقي إذا تسارع المصعد إلى أعلى ويقل عنه إذا تسارع إلى أسفل ويساويه إذا كان التسارع صفرًا.', '["المصدر: الأرض مقابل الميزان","النوع: مجال مقابل تلامس","العلاقتان $mg$ و$m(a + g)$","الحقيقي ثابت والظاهري يتغير بالتسارع"]'::jsonb, '[]'::jsonb, '[{"element":"المصدر","marks":1},{"element":"النوع","marks":1},{"element":"العلاقة","marks":1},{"element":"التأثر بالتسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الجوانب الأربعة"},{"level":"2–3 درجات","description":"جانبان أو ثلاثة صحيحة"},{"level":"درجة واحدة","description":"جانب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الوزن الحقيقي يتغير بالتسارع","الخلط في مصدر القوتين","كتابة $F_{\\text{الميزان}} = ma$ فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.602Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $F_g = (50.0)(9.80) = 490\ \text{N}$. (ب) الوزن الظاهري (540 N) أكبر من الحقيقي (490 N) بمقدار 50 N. (ج) $F_{\text{الميزان}} - mg = ma$، إذن $a = \frac{540 - 490}{50.0} = +1.0\ \text{m/s}^2$، أي إلى أعلى.', '["الوزن الحقيقي 490 N","الظاهري أكبر من الحقيقي","$a = +1.0\\ \\text{m/s}^2$ (إلى أعلى)"]'::jsonb, '["$F_g = mg = (50.0)(9.80) = 490\\ \\text{N}$","$F_{\\text{المحصلة}} = F_{\\text{الميزان}} - F_g = 540 - 490 = 50\\ \\text{N}$","$a = \\frac{50}{50.0} = +1.0\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"الوزن الحقيقي","marks":1},{"element":"المقارنة","marks":1},{"element":"مقدار التسارع واتجاهه","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة صحيحة للأجزاء الثلاثة"},{"level":"2–3 درجات","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 540 على 50.0 مباشرة واعتبارها التسارع","القول إن التسارع إلى أسفل","اعتبار 540 N الوزن الحقيقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.602Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $F_g = (1.0)(9.80) = 9.8\ \text{N}$. (ب) الوزن الظاهري 9.3 N أقل من الحقيقي 9.8 N. (ج) الموجب إلى أعلى: $a = \frac{9.3 - 9.8}{1.0} = -0.5\ \text{m/s}^2$، أي أن المصعد يتسارع إلى أسفل بمقدار 0.5 m/s² تقريبًا؛ فإما أنه يتحرك إلى أسفل وتزداد سرعته، وإما أنه يتحرك إلى أعلى وتتناقص سرعته.', '["الوزن الحقيقي 9.8 N","الظاهري أقل من الحقيقي","التسارع ≈ 0.5 m/s² إلى أسفل","احتمالا الحركة: هبوط متزايد أو صعود متباطئ"]'::jsonb, '["$F_g = mg = 9.8\\ \\text{N}$","$a = \\frac{F_{\\text{الميزان}} - mg}{m} = \\frac{9.3 - 9.8}{1.0} = -0.5\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"الوزن الحقيقي","marks":1},{"element":"المقارنة","marks":1},{"element":"التسارع واتجاهه","marks":1},{"element":"احتمالا الحركة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"تحديد التسارع إلى أسفل دون ذكر الاحتمالين"},{"level":"درجة واحدة","description":"الوزن الحقيقي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استنتاج أن المصعد يهبط بالضرورة","استنتاج أن كتلة الجسم قلت","جعل التسارع إلى أعلى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.602Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
