from (values
('mcq', 1, 'يبين الشكل الآتي شخصًا يقف على ميزان داخل مصعد، ويوضح السهم الأحمر اتجاه السرعة المتجهة للمصعد، والسهم البنفسجي اتجاه تسارعه. كيف تُقارَن قراءة الميزان بوزن الشخص الحقيقي في هذه اللحظة؟', null, '[{"src":"qimg/phys1/c4l2-o06-elev-vup-aup.svg","alt":"مصعد معلّق بحبل، وفي داخله شخص يقف على ميزان موضوع على أرضية المصعد. على يسار المصعد سهم أسود رأسي إلى أعلى مكتوب عنده +y يمثل الاتجاه الموجب. على يمين المصعد سهم أحمر إلى أعلى مكتوب عنده v يمثل السرعة المتجهة، وبجانبه سهم بنفسجي إلى أعلى مكتوب عنده a يمثل التسارع."}]'::jsonb, '["أقل من وزنه الحقيقي","مساوية لوزنه الحقيقي","أكبر من وزنه الحقيقي","تساوي صفرًا"]'::jsonb, 'تحليل', 'استنتاج من شكل', 'سهل', 'الكتاب ص 107 — الوزن الظاهري في مصعد يتسارع إلى أعلى'),
('mcq', 2, 'يبين الشكل الآتي مصعدًا يتحرك إلى أعلى (السهم الأحمر) بينما تسارعه إلى أسفل (السهم البنفسجي)، أي أنه يتباطأ قرب الطابق الأخير. كيف تُقارَن قراءة الميزان بوزن الشخص الحقيقي؟', null, '[{"src":"qimg/phys1/c4l2-o06-elev-vup-adown.svg","alt":"مصعد معلّق بحبل، وفي داخله شخص يقف على ميزان موضوع على أرضية المصعد. على يسار المصعد سهم أسود رأسي إلى أعلى مكتوب عنده +y يمثل الاتجاه الموجب. على يمين المصعد سهم أحمر إلى أعلى مكتوب عنده v يمثل السرعة المتجهة، وبجانبه سهم بنفسجي إلى أسفل مكتوب عنده a يمثل التسارع."}]'::jsonb, '["أقل من وزنه الحقيقي","أكبر من وزنه الحقيقي لأنه يصعد","مساوية لوزنه الحقيقي لأنه يصعد","أكبر من وزنه ثم تساويه"]'::jsonb, 'تحليل', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 109 — المسألة 20b'),
('mcq', 3, 'يبين الشكل الآتي مصعدًا يهبط بسرعة متجهة منتظمة. كيف تُقارَن قراءة الميزان بوزن الشخص الحقيقي؟', null, '[{"src":"qimg/phys1/c4l2-o06-elev-vdown-const.svg","alt":"مصعد معلّق بحبل، وفي داخله شخص يقف على ميزان موضوع على أرضية المصعد. على يسار المصعد سهم أسود رأسي إلى أعلى مكتوب عنده +y يمثل الاتجاه الموجب. على يمين المصعد سهم أحمر إلى أسفل مكتوب عنده v يمثل السرعة المتجهة، وتحته مكتوب باللون البنفسجي a = 0."}]'::jsonb, '["أقل من وزنه الحقيقي لأنه يهبط","مساوية لوزنه الحقيقي","أكبر من وزنه الحقيقي لأنه يتحرك","تساوي صفرًا لأنه يهبط"]'::jsonb, 'فهم', 'استنتاج من شكل', 'سهل', 'الكتاب ص 109 — المسألة 20d'),
('mcq', 4, 'يقترب مصعد هابط من الطابق الأرضي فتتناقص سرعته، كما في الشكل الآتي (الأحمر للسرعة المتجهة، والبنفسجي للتسارع). بماذا يشعر الراكب الواقف على الميزان، وما قراءة الميزان؟', null, '[{"src":"qimg/phys1/c4l2-o06-elev-vdown-aup.svg","alt":"مصعد معلّق بحبل، وفي داخله شخص يقف على ميزان موضوع على أرضية المصعد. على يسار المصعد سهم أسود رأسي إلى أعلى مكتوب عنده +y يمثل الاتجاه الموجب. على يمين المصعد سهم أحمر إلى أسفل مكتوب عنده v يمثل السرعة المتجهة، وبجانبه سهم بنفسجي إلى أعلى مكتوب عنده a يمثل التسارع."}]'::jsonb, '["يشعر أنه أخف، والقراءة أقل من وزنه","لا يشعر بتغير، والقراءة تساوي وزنه","يشعر بانعدام وزنه، والقراءة صفر","يشعر أنه أثقل، والقراءة أكبر من وزنه"]'::jsonb, 'تحليل', 'استنتاج من شكل', 'صعب', 'الكتاب ص 126 — التقويم 53e'),
('mcq', 5, 'يمثل المنحنى الآتي السرعة المتجهة لمصعد يصعد من الطابق الأرضي (الاتجاه الموجب إلى أعلى). في أي فترة زمنية تكون قراءة ميزان يقف عليه شخص في المصعد أقل من وزنه الحقيقي؟', null, '[{"src":"qimg/phys1/c4l2-o06-vt-elevator.svg","alt":"منحنى (السرعة المتجهة – الزمن) باللون الأحمر؛ المحور الأفقي الزمن (s) من 0 إلى 12 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 3 بخطوة 0.5. يبدأ الخط من (0، 0) ويرتفع خطيًا إلى (2، 2)، ثم يبقى أفقيًا عند 2 m/s حتى (8، 2)، ثم ينخفض خطيًا إلى (10، 0)، ويبقى صفرًا حتى 12 s."}]'::jsonb, '["من 0 s إلى 2 s","من 8 s إلى 10 s","من 2 s إلى 8 s","من 10 s إلى 12 s"]'::jsonb, 'تحليل', 'قراءة منحنى', 'صعب', 'الكتاب ص 109 — المسألة 20 — الوزن الظاهري وتسارع المصعد'),
('mcq', 6, 'قال طالب: «تقل قراءة الميزان في المصعد كلما تحرك المصعد إلى أسفل». أي تصحيح لهذه العبارة صحيح علميًا؟', null, null, '["العبارة صحيحة؛ فالقراءة تقل في كل حالات الهبوط","تزيد القراءة في كل حالات الهبوط وتقل في كل حالات الصعود","لا تتغير القراءة أبدًا؛ لأن الوزن الحقيقي ثابت","تقل عند التسارع إلى أسفل، وتساوي الوزن في الهبوط المنتظم"]'::jsonb, 'تقويم', 'تصحيح مفهوم', 'متوسط', 'الكتاب ص 107 — الوزن الظاهري'),
('mcq', 7, 'في أي الحالات الآتية تكون قراءة الميزان في المصعد أكبر من الوزن الحقيقي للشخص الواقف عليه؟', null, null, '["المصعد يبدأ الصعود من السكون","المصعد يبدأ الهبوط من السكون","المصعد يصعد بسرعة منتظمة","المصعد يتباطأ ليتوقف وهو يصعد"]'::jsonb, 'تحليل', 'تصنيف حالات', 'سهل', 'الكتاب ص 107 — الوزن الظاهري في مصعد يتسارع إلى أعلى'),
('essay', 1, 'تقف على ميزان في مصعد سريع يصعد بك من الطابق الأرضي إلى أعلى بناية، ثم يهبط بك إلى حيث انطلقت. قسّم الرحلة إلى ست مراحل: (1) بدء الصعود، (2) صعود بسرعة منتظمة، (3) تباطؤ قرب القمة، (4) بدء الهبوط، (5) هبوط بسرعة منتظمة، (6) تباطؤ قرب الطابق الأرضي. حدد في كل مرحلة اتجاه التسارع، وهل الوزن الظاهري أكبر من الوزن الحقيقي أم أقل منه أم يساويه، ثم ارسم مخطط الجسم الحر لمرحلة واحدة منها (الموجب إلى أعلى).', null, null, null, 'تحليل', 'تحليل حالات', 'صعب', 'الكتاب ص 111 — المراجعة 22 (الوزن الحقيقي والظاهري)'),
('essay', 2, 'يمثل المنحنى الآتي السرعة المتجهة لمصعد يهبط من الطابق العاشر حتى يتوقف (الاتجاه الموجب إلى أعلى). حدد في كل من الفترات: 0–3 s، و3–9 s، و9–12 s اتجاه تسارع المصعد ومقداره، ثم قارن بين الوزن الظاهري والوزن الحقيقي لشخص يقف على ميزان في المصعد.', null, '[{"src":"qimg/phys1/c4l2-o06-vt-down.svg","alt":"منحنى (السرعة المتجهة – الزمن) باللون الأحمر؛ المحور الأفقي الزمن (s) من 0 إلى 12 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من سالب 4 إلى 1 بخطوة 1. يبدأ الخط من (0، 0) وينخفض خطيًا حتى يبلغ سالب 3 m/s عند 3 s، ثم يبقى أفقيًا عند سالب 3 m/s حتى 9 s، ثم يرتفع خطيًا إلى الصفر عند 12 s."}]'::jsonb, null, 'تحليل', 'قراءة منحنى', 'متوسط', 'الكتاب ص 126 — التقويم 53 — الوزن الظاهري وتسارع المصعد'),
('essay', 3, 'يقف شخص على ميزان داخل مصعد مغلق لا يرى خارجه، فلاحظ أن قراءة الميزان تساوي وزنه الحقيقي تمامًا مدة 10 s. هل يستطيع أن يستنتج أن المصعد ساكن؟ فسّر إجابتك باستخدام قانون نيوتن الثاني، واذكر جميع الحالات الممكنة لحركة المصعد.', null, null, null, 'تقويم', 'استنتاج', 'متوسط', 'الكتاب ص 107 — ما دام المصعد متزنًا فإن الميزان يقرأ وزنك')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
