select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الموجب إلى أعلى: $F_{\text{الميزان}} - mg = ma$، و$a > 0$ (التسارع إلى أعلى)، إذن $F_{\text{الميزان}} = m(g + a) > mg$؛ فقراءة الميزان أكبر من الوزن الحقيقي.', '["القراءة تقل عن الوزن عندما يكون التسارع إلى أسفل، والتسارع هنا إلى أعلى.","تتساوى القراءة مع الوزن عندما يكون التسارع صفرًا فقط.","","تنعدم القراءة في السقوط الحر فقط ($\\boldsymbol{a} = \\boldsymbol{g}$ إلى أسفل)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.603Z"}'::jsonb),
('mcq', 2, 0, 'الموجب إلى أعلى: التسارع إلى أسفل فـ $a < 0$، و$F_{\text{الميزان}} = m(g + a) < mg$؛ فالقراءة أقل من الوزن رغم أن المصعد يتحرك إلى أعلى.', '["","اتجاه الحركة لا يحدد القراءة؛ الذي يحددها اتجاه التسارع، وهو هنا إلى أسفل.","تتساوى القراءة مع الوزن عندما يكون التسارع صفرًا فقط، والتسارع هنا لا يساوي صفرًا.","ما دام التسارع ثابتًا إلى أسفل تبقى القراءة أقل من الوزن طوال التباطؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-19T07:48:34.603Z"}'::jsonb),
('mcq', 3, 1, 'السرعة المتجهة منتظمة $\Leftarrow$ $\boldsymbol{a} = 0$ $\Leftarrow$ $\boldsymbol{F}_{\text{المحصلة}} = 0$، إذن $F_{\text{الميزان}} = mg$: القراءة تساوي الوزن الحقيقي، كما لو كان المصعد ساكنًا.', '["الهبوط وحده لا يقلل القراءة؛ الذي يقللها التسارع إلى أسفل، والتسارع هنا صفر.","","الحركة بسرعة منتظمة لا تغير القراءة لأن القوة المحصلة صفر.","القراءة تنعدم في السقوط الحر فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-19T07:48:34.604Z"}'::jsonb),
('mcq', 4, 3, 'الموجب إلى أعلى: التسارع إلى أعلى فـ $a > 0$، و$F_{\text{الميزان}} = m(g + a) > mg$. لذلك تشعر بأنك أثقل عند توقف المصعد الهابط.', '["يشعر بأنه أخف عندما يكون التسارع إلى أسفل؛ واتجاه الحركة (إلى أسفل) لا يحدد ذلك، والتسارع هنا إلى أعلى.","القراءة تساوي الوزن عندما يكون التسارع صفرًا، والمصعد هنا يتسارع إلى أعلى في أثناء التوقف.","انعدام الوزن الظاهري يحدث في السقوط الحر فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.604Z"}'::jsonb),
('mcq', 5, 1, 'ميل منحنى (السرعة المتجهة – الزمن) هو التسارع. من 8 s إلى 10 s الميل سالب ($a = \frac{0 - 2}{2} = -1\ \text{m/s}^2$) أي التسارع إلى أسفل، فتكون $F_{\text{الميزان}} = m(g + a) < mg$.', '["في هذه الفترة يتسارع المصعد إلى أعلى (الميل موجب)، فالقراءة أكبر من الوزن.","","السرعة المتجهة ثابتة (الميل صفر)، فالقراءة تساوي الوزن.","المصعد ساكن، فالقراءة تساوي الوزن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-19T07:48:34.604Z"}'::jsonb),
('mcq', 6, 3, '$F_{\text{الميزان}} = m(g + a)$ (الموجب إلى أعلى): القراءة تعتمد على التسارع لا على اتجاه الحركة؛ تقل عندما يكون التسارع إلى أسفل، وتزيد عندما يكون إلى أعلى، وتساوي الوزن عندما يكون صفرًا (سرعة منتظمة صعودًا أو هبوطًا).', '["في الهبوط بسرعة منتظمة تساوي القراءة الوزن، وفي التباطؤ أثناء الهبوط تزيد عليه.","اتجاه الحركة لا يحدد القراءة، بل اتجاه التسارع.","الوزن الحقيقي ثابت، لكن قراءة الميزان (الوزن الظاهري) تتغير بتغير التسارع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.604Z"}'::jsonb),
('mcq', 7, 0, 'عندما يبدأ المصعد الصعود من السكون تزداد سرعته إلى أعلى، فتسارعه إلى أعلى، وتكون $F_{\text{الميزان}} = m(g + a) > mg$.', '["","بدء الهبوط يعني تسارعًا إلى أسفل، فتقل القراءة.","السرعة المنتظمة تعني تسارعًا صفرًا، فتساوي القراءة الوزن.","التباطؤ في أثناء الصعود يعني تسارعًا إلى أسفل، فتقل القراءة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.605Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) التسارع إلى أعلى: الظاهري أكبر. (2) التسارع صفر: يساويه. (3) التسارع إلى أسفل: أقل. (4) التسارع إلى أسفل: أقل. (5) التسارع صفر: يساويه. (6) التسارع إلى أعلى: أكبر. القاعدة: $F_{\text{الميزان}} = m(g + a)$؛ اتجاه التسارع لا اتجاه الحركة هو الذي يحدد المقارنة. مخطط الجسم الحر للمرحلة (1): نقطة يخرج منها $\boldsymbol{F}_{\text{الميزان}}$ إلى أعلى أطول من $\boldsymbol{F}_g$ إلى أسفل.', '["المرحلتان 1 و6: أكبر (تسارع إلى أعلى)","المرحلتان 2 و5: يساوي (تسارع صفر)","المرحلتان 3 و4: أقل (تسارع إلى أسفل)","مخطط جسم حر صحيح الأطوال"]'::jsonb, '["$+y$ إلى أعلى: $F_{\\text{الميزان}} - mg = ma$ $\\Leftarrow$ $F_{\\text{الميزان}} = m(g + a)$","تحديد إشارة $a$ في كل مرحلة","المقارنة بين $F_{\\text{الميزان}}$ و$mg$"]'::jsonb, '[{"element":"المرحلتان 1 و6","marks":1},{"element":"المرحلتان 2 و5","marks":1},{"element":"المرحلتان 3 و4","marks":1},{"element":"مخطط الجسم الحر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المراحل الست صحيحة مع مخطط صحيح"},{"level":"2–3 درجات","description":"أربع مراحل صحيحة على الأقل"},{"level":"درجة واحدة","description":"مرحلتان صحيحتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط الزيادة بالصعود والنقص بالهبوط","جعل الوزن الظاهري أقل في الهبوط بسرعة منتظمة","رسم الأسهم متساوية في مرحلة متسارعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.605Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التسارع هو ميل المنحنى. (0–3 s): $a = \frac{-3 - 0}{3} = -1\ \text{m/s}^2$ أي 1 m/s² إلى أسفل، فالظاهري أقل من الحقيقي. (3–9 s): $a = 0$، فالظاهري يساوي الحقيقي رغم أن المصعد يهبط. (9–12 s): $a = \frac{0 - (-3)}{3} = +1\ \text{m/s}^2$ أي إلى أعلى، فالظاهري أكبر من الحقيقي رغم أن المصعد ما زال يهبط.', '["0–3 s: 1 m/s² إلى أسفل، الظاهري أقل","3–9 s: التسارع صفر، متساويان","9–12 s: 1 m/s² إلى أعلى، الظاهري أكبر"]'::jsonb, '["$a = \\frac{\\Delta v}{\\Delta t}$ لكل فترة","(0–3 s): $\\frac{-3}{3} = -1\\ \\text{m/s}^2$","(3–9 s): $0$","(9–12 s): $\\frac{+3}{3} = +1\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"الفترة الأولى","marks":1},{"element":"الفترة الثانية","marks":1},{"element":"الفترة الثالثة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الفترات الثلاث صحيحة تسارعًا ومقارنة"},{"level":"درجتان","description":"فترتان صحيحتان"},{"level":"درجة واحدة","description":"فترة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الظاهري أقل في الفترات الثلاث لأن المصعد يهبط","الخلط بين قيمة السرعة وميل المنحنى","إهمال إشارة التسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-19T07:48:34.605Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لا يستطيع. تساوي القراءة مع الوزن يعني $F_{\text{الميزان}} = mg$، أي $\boldsymbol{F}_{\text{المحصلة}} = 0$، فالتسارع صفر. والتسارع الصفري يحدث في ثلاث حالات: المصعد ساكن، أو يصعد بسرعة منتظمة، أو يهبط بسرعة منتظمة. الميزان يكشف التسارع لا السرعة.', '["الإجابة: لا","$F_{\\text{الميزان}} = mg$ $\\Leftarrow$ القوة المحصلة صفر $\\Leftarrow$ التسارع صفر","الحالات الثلاث: سكون، صعود منتظم، هبوط منتظم","الميزان يتأثر بالتسارع لا بالسرعة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل بقانون نيوتن الثاني","marks":1},{"element":"ذكر الحالات الثلاث","marks":1},{"element":"الربط بالتسارع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم وتعليل صحيحان مع الحالات الثلاث"},{"level":"2–3 درجات","description":"حكم صحيح مع حالتين فقط أو بتعليل ناقص"},{"level":"درجة واحدة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الجزم بأن المصعد ساكن","إغفال حالة الهبوط بسرعة منتظمة","القول إن الوزن الظاهري يقل في الهبوط المنتظم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.606Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
