from (values
('mcq', 1, 'ما المقصود بالقوة المعيقة؟', null, null, '["القوة التي يؤثر بها سطح صلب خشن في جسم ينزلق عليه","قوة الممانعة التي يؤثر بها مائع في جسم يتحرك خلاله","قوة جذب الأرض للجسم الساقط في الهواء","القوة التي يؤثر بها الميزان في جسم متسارع"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 109 — تعريف القوة المعيقة'),
('mcq', 2, 'ما الذي يؤثر بالقوة المعيقة في جسم متحرك؟', null, null, '["السطح الصلب الذي يلامسه الجسم","الأرض بقوة جاذبيتها للجسم","النابض المتصل بالجسم المتحرك","المائع الذي يتحرك خلاله كالهواء"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 109 — تعريف القوة المعيقة'),
('mcq', 3, 'يؤثر الهواء في الواقع بقوة كبيرة في الأجسام، ومع ذلك لا يظهر تأثيره في الأجسام الساكنة غالبًا. ما سبب ذلك؟', null, null, '["لأن الهواء يؤثر في جميع جوانب الجسم بقوى متوازنة","لأن الهواء لا كتلة له فلا يؤثر بأي قوة في الأجسام","لأن قوة الهواء تساوي دائمًا وزن الجسم","لأن الهواء يؤثر في الأجسام المتحركة فقط دون الساكنة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 109 — تأثير الهواء في الأجسام'),
('mcq', 4, 'تسبح سمكة في الماء، فيمانع الماء حركتها. ماذا تسمى القوة التي يؤثر بها الماء فيها ممانعًا حركتها؟', null, null, '["قوة الشد","القوة العمودية","القوة المعيقة","الاحتكاك السكوني"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 109 — القوة المعيقة'),
('mcq', 5, 'في أي الحالات الآتية لا تؤثر قوة معيقة في الجسم؟', null, null, '["كرة تسقط في الهواء","كرة تتحرك في فراغ تام","غواصة تتحرك في الماء","مظلي يهبط بمظلته"]'::jsonb, 'فهم', 'تطبيق تعريف', 'متوسط', 'الكتاب ص 109 — تعريف القوة المعيقة'),
('mcq', 6, 'عندما نقول في دراسة السقوط الحر: «أهمل مقاومة الهواء»، فأي قوة نهملها؟', null, null, '["قوة الجاذبية الأرضية","القوة المحصلة على الجسم","الوزن الظاهري للجسم","القوة المعيقة من الهواء"]'::jsonb, 'فهم', 'ربط مفاهيم', 'متوسط', 'الكتاب ص 109 — من باب التبسيط أهملنا تأثير قوة الهواء'),
('mcq', 7, 'ما الفرق بين القوة المعيقة وقوة الاحتكاك؟', null, null, '["المعيقة يؤثر بها مائع، والاحتكاك يؤثر به سطح صلب","المعيقة في اتجاه الحركة، والاحتكاك عكس اتجاهها","المعيقة قوة مجال، والاحتكاك قوة تلامس","المعيقة ثابتة المقدار، والاحتكاك يزداد بزيادة السرعة"]'::jsonb, 'فهم', 'مقارنة', 'صعب', 'الكتاب ص 109 — تعريف القوة المعيقة؛ ص 103 — الاحتكاك'),
('essay', 1, 'عرّف القوة المعيقة، واذكر مثالين عليها من حياتك اليومية، وحدد اتجاهها في كل مثال.', null, null, null, 'تذكر', 'تعريف', 'متوسط', 'الكتاب ص 109 — تعريف القوة المعيقة'),
('essay', 2, 'أهملنا مقاومة الهواء عند دراسة السقوط الحر. فسّر: (أ) لماذا يكون تأثير الهواء غير واضح في كثير من الأحيان مع أنه يؤثر بقوة كبيرة؟ (ب) متى يكون إهمال القوة المعيقة مقبولًا، ومتى لا يكون كذلك؟ أعط مثالًا لكل حالة.', null, null, null, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 110 — القوة المعيقة — الأجسام الخفيفة ذات السطوح الكبيرة'),
('essay', 3, 'قارن بين القوة المعيقة وقوة الاحتكاك من حيث: الجسم المؤثر بالقوة، ونوع القوة (تلامس أم مجال)، واتجاه القوة، ومثال على كل منهما.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 109 — القوة المعيقة؛ ص 103 — الاحتكاك')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
