('mcq', 3, 0, 'يؤثر الهواء بقوة كبيرة في الأجسام، لكنه في أكثر الحالات يؤثر في جميع جوانب الجسم بقوى متوازنة، فيكون تأثيره غير واضح.', '["","للهواء كتلة، وهو يؤثر بقوة كبيرة فعلًا.","قوة الهواء لا تساوي الوزن إلا في حالة خاصة كالسرعة الحدية.","الهواء يؤثر في الأجسام الساكنة أيضًا، لكن قواه متوازنة على جوانبها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.606Z"}'::jsonb),
('mcq', 4, 2, 'الماء مائع، والقوة التي يمانع بها حركة جسم خلاله هي القوة المعيقة.', '["قوة الشد يؤثر بها حبل أو خيط.","القوة العمودية قوة تلامس عمودية على سطح التلامس بين جسمين صلبين.","","الاحتكاك السكوني يؤثر بين سطحين صلبين ساكنين أحدهما بالنسبة إلى الآخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-19T07:48:34.606Z"}'::jsonb),
('mcq', 5, 1, 'القوة المعيقة يؤثر بها مائع في جسم يتحرك خلاله؛ وفي الفراغ التام لا يوجد مائع، فلا توجد قوة معيقة.', '["الكرة تتحرك خلال الهواء وهو مائع، فتتأثر بقوة معيقة.","","الماء مائع يمانع حركة الغواصة.","الهواء يؤثر في المظلي والمظلة بقوة معيقة كبيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-19T07:48:34.607Z"}'::jsonb),
('mcq', 6, 3, 'مقاومة الهواء هي القوة المعيقة التي يؤثر بها الهواء في الجسم المتحرك خلاله، ونهملها من باب التبسيط فتبقى قوة الجاذبية وحدها.', '["قوة الجاذبية هي القوة الوحيدة التي نبقيها في السقوط الحر.","القوة المحصلة لا تهمل؛ فهي في السقوط الحر تساوي الوزن.","الوزن الظاهري يتعلق بقوة تلامس كالميزان، لا بمقاومة الهواء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.607Z"}'::jsonb),
('mcq', 7, 0, 'القوة المعيقة يؤثر بها مائع (هواء أو ماء) في جسم يتحرك خلاله، أما قوة الاحتكاك فيؤثر بها سطح صلب ينزلق عليه الجسم؛ وكلتاهما قوة تلامس تعاكس اتجاه الحركة.', '["","كلتاهما تعاكس اتجاه الحركة.","القوة المعيقة تنتج عن تلامس المائع مع الجسم، فهي قوة تلامس لا قوة مجال.","القوة المعيقة ليست ثابتة المقدار؛ فهي تزداد بزيادة سرعة الجسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.607Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القوة المعيقة: قوة الممانعة التي يؤثر بها مائع في جسم يتحرك خلاله. مثال 1: الهواء يؤثر في كرة تسقط بقوة معيقة إلى أعلى. مثال 2: الماء يؤثر في سبّاح يتحرك إلى الأمام بقوة معيقة إلى الخلف. اتجاهها دائمًا معاكس لاتجاه حركة الجسم.', '["التعريف: ممانعة مائع لجسم يتحرك خلاله","مثالان صحيحان","الاتجاه معاكس للحركة في كل مثال"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثالان","marks":1},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف ومثالان واتجاه صحيح"},{"level":"درجتان","description":"التعريف مع مثال واحد أو دون الاتجاه"},{"level":"درجة واحدة","description":"التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر احتكاك سطح صلب مثالًا","جعل اتجاهها في اتجاه الحركة","تعريفها بأنها قوة الجاذبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.607Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) لأن الهواء يؤثر في جميع جوانب الجسم بقوى متوازنة في أكثر الحالات. (ب) يكون الإهمال مقبولًا للأجسام الثقيلة ذات السطوح الصغيرة التي تتحرك بسرعات صغيرة، مثل كرة حديدية تسقط مسافة قصيرة؛ ولا يكون مقبولًا للأجسام الخفيفة ذات السطوح الكبيرة أو السريعة، مثل ورقة أو ريشة أو مظلي، لأن تأثير القوة المعيقة يكون ملحوظًا في حركتها.', '["قوى الهواء متوازنة على جوانب الجسم","الإهمال مقبول للأجسام الثقيلة الصغيرة السطح","غير مقبول للأجسام الخفيفة الكبيرة السطح","مثالان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"الجزء (أ)","marks":1},{"element":"حالة القبول","marks":1},{"element":"حالة عدم القبول","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة بمثالين"},{"level":"2–3 درجات","description":"إجابة صحيحة لجزء مع نقص في الآخر"},{"level":"درجة واحدة","description":"نقطة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الهواء لا يؤثر بأي قوة","جعل الريشة مثالًا على الإهمال المقبول","إغفال دور مساحة السطح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.607Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القوة المعيقة $\boldsymbol{F}_{\text{d}}$: يؤثر بها مائع (هواء أو ماء) في جسم يتحرك خلاله، وهي قوة تلامس، واتجاهها معاكس لاتجاه حركة الجسم، ومثالها ممانعة الهواء لكرة تسقط. قوة الاحتكاك $\boldsymbol{f}_{f}$: يؤثر بها سطح في جسم ينزلق عليه، وهي قوة تلامس أيضًا، واتجاهها موازٍ للسطح في عكس اتجاه الحركة الانزلاقية، ومثالها احتكاك الأرضية بصندوق يُسحب عليها. ويزداد مقدار القوة المعيقة بزيادة سرعة الجسم، ويعتمد على شكله وحجمه وعلى خصائص المائع.', '["المؤثر: مائع مقابل سطح صلب","كلتاهما قوة تلامس","كلتاهما تعاكس الحركة (والاحتكاك موازٍ للسطح)","مثال صحيح لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"الجسم المؤثر","marks":1},{"element":"نوع القوة","marks":1},{"element":"الاتجاه","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في الجوانب كلها"},{"level":"2–3 درجات","description":"جانبان أو ثلاثة صحيحة"},{"level":"درجة واحدة","description":"جانب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل القوة المعيقة في اتجاه الحركة","القول إن القوة المعيقة قوة مجال","القول إن الاحتكاك يؤثر به الهواء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.607Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
