from (values
('mcq', 1, 'تسقط كرة في الهواء من السكون. كيف يتغير مقدار القوة المعيقة المؤثرة فيها كلما زادت سرعتها؟', null, null, '["يزداد مقداره","يقل مقداره","يبقى ثابتًا","يصبح صفرًا"]'::jsonb, 'فهم', 'استنتاج', 'سهل', 'الكتاب ص 109 — اعتماد القوة المعيقة على السرعة'),
('mcq', 2, 'يبين الشكل الآتي كرة تسقط في الهواء في أربعة مواضع متتالية (1 إلى 4)، مع القوتين المؤثرتين فيها والسرعة المتجهة. لماذا يزداد طول سهم القوة المعيقة من الموضع 1 إلى الموضع 4؟', null, '[{"src":"qimg/phys1/c4l2-o08-falling-seq.svg","alt":"أربعة مواضع لكرة صفراء تسقط، مرقمة 1 و2 و3 و4 من اليسار إلى اليمين وكل موضع أدنى من سابقه. عند كل موضع سهم أزرق إلى أسفل مكتوب عنده F_g بالطول نفسه في المواضع الأربعة، وسهم أزرق إلى أعلى مكتوب عنده F_d يزداد طوله من الموضع 1 إلى الموضع 4 حتى يساوي طول سهم F_g في الموضع 4، وبجانب الكرة سهم أحمر إلى أسفل مكتوب عنده v يزداد طوله من الموضع 1 إلى الموضع 4."}]'::jsonb, '["لأن وزن الكرة يزداد","لأن كتلة الكرة تزداد","لأن الهواء يصبح أكثر لزوجة","لأن سرعة الكرة تزداد"]'::jsonb, 'فهم', 'قراءة مخطط', 'متوسط', 'الكتاب ص 110 — الشكل 4-12 — تزداد القوة المعيقة كلما زادت السرعة'),
('mcq', 3, 'يمثل المنحنى الآتي العلاقة بين القوة المعيقة المؤثرة في جسم يتحرك في الهواء وسرعته المتجهة. ماذا تستنتج من المنحنى؟', null, '[{"src":"qimg/phys1/c4l2-o08-drag-speed.svg","alt":"منحنى باللون الأزرق؛ المحور الأفقي السرعة المتجهة (m/s) من 0 إلى 20 بخطوة 5، والمحور الرأسي القوة المعيقة (N) من 0 إلى 4 بخطوة 1. يبدأ المنحنى من (0، 0) ويرتفع بانحناء متزايد، وعليه نقطتان معلمتان: (10، 1.0) و(20، 4.0)."}]'::jsonb, '["القوة المعيقة تقل بزيادة السرعة","القوة المعيقة تزداد بزيادة السرعة","القوة المعيقة لا تعتمد على السرعة","القوة المعيقة تساوي صفرًا عند السرعات الكبيرة"]'::jsonb, 'فهم', 'قراءة منحنى', 'متوسط', 'الكتاب ص 109 — اعتماد القوة المعيقة على السرعة'),
('mcq', 4, 'يشعر راكب الدراجة بأن مقاومة الهواء تزداد كلما أسرع بدراجته. ما التفسير الصحيح؟', null, null, '["قوة الاحتكاك بين العجلات والطريق تزداد بالسرعة","كتلة الدراجة تزداد كلما زادت سرعتها","القوة المعيقة يزداد مقدارها بزيادة سرعة الجسم","الهواء يصبح أكثر كثافة عندما تزداد السرعة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 109 — اعتماد القوة المعيقة على السرعة'),
('mcq', 5, 'كرتان متماثلتان تتحركان في الهواء: الأولى تهبط بسرعة 5 m/s، والثانية قُذفت إلى أعلى وسرعتها في اللحظة نفسها 5 m/s. كيف تقارَن القوتان المعيقتان المؤثرتان فيهما في تلك اللحظة؟', null, null, '["المؤثرة في الهابطة أكبر؛ لأن وزنها في اتجاه حركتها","المؤثرة في الصاعدة أكبر؛ لأنها تتحرك عكس الجاذبية","متساويتان مقدارًا واتجاهًا؛ فكلتاهما إلى أعلى","متساويتان مقدارًا ومتعاكستان اتجاهًا"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 109 — اعتماد القوة المعيقة على السرعة'),
('mcq', 6, 'يركب سعيد دراجته بهيئة جلوس ثابتة، فكانت القوة المعيقة المؤثرة فيه 16 N عندما كانت سرعته 10 m/s. أيّ القيم الآتية يمكن أن تكون مقدار القوة المعيقة عندما تصبح سرعته 15 m/s في الهواء نفسه؟', null, null, '["36 N","16 N","9 N","0 N"]'::jsonb, 'فهم', 'استنتاج', 'سهل', 'الكتاب ص 109 — اعتماد القوة المعيقة على السرعة'),
('mcq', 7, 'قُذفت كرة رأسيًا إلى أعلى في الهواء. كيف يتغير مقدار القوة المعيقة المؤثرة فيها في أثناء صعودها؟', null, null, '["يزداد لأنها ترتفع إلى أعلى","يقل لأن سرعتها تتناقص","يبقى ثابتًا لأن الهواء نفسه","يزداد لأن وزنها يعاكس حركتها"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 109 — اعتماد القوة المعيقة على السرعة'),
('essay', 1, 'يبين الجدول الآتي بيانات افتراضية لسرعة كرة وزنها 0.47 N تسقط في الهواء من السكون، والقوة المعيقة المؤثرة فيها عند أزمنة مختلفة. (أ) صف العلاقة بين السرعة والقوة المعيقة. (ب) هل تبقى الكرة تتسارع بالمقدار نفسه؟ فسّر.', '{"headers":["الزمن (s)","السرعة (m/s)","القوة المعيقة (N)"],"rows":[["0","0","0"],["1","8.5","0.12"],["2","13.5","0.30"],["3","15.8","0.41"],["4","16.6","0.45"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 110 — الشكل 4-12'),
('essay', 2, 'يترك راكب دراجة دراجته تنحدر على طريق طويل منحدر دون أن يدوّس. لاحظ أن سرعته تزداد في البداية، ثم يصبح ازديادها أبطأ فأبطأ. فسّر ملاحظته مستعينًا بالعلاقة بين القوة المعيقة والسرعة.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 109 — اعتماد القوة المعيقة على السرعة'),
('essay', 3, 'تسير سيارة على طريق أفقي بسرعة منتظمة. لماذا يحتاج محركها إلى قوة دفع أكبر ليحافظ على سرعة منتظمة مقدارها 30 m/s مقارنة بسرعة منتظمة مقدارها 15 m/s؟ استخدم قانون نيوتن الأول وعلاقة القوة المعيقة بالسرعة.', null, null, null, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 109 — اعتماد القوة المعيقة على السرعة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L2-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'تعتمد القوة المعيقة على حركة الجسم؛ فكلما زادت سرعة الجسم زاد مقدار هذه القوة.', '["","القوة المعيقة تزداد بزيادة السرعة لا تقل.","القوة المعيقة تعتمد على حركة الجسم، فتتغير بتغير سرعته.","تنعدم القوة المعيقة عندما يكون الجسم ساكنًا بالنسبة إلى المائع، لا عندما تزداد سرعته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-19T07:48:34.608Z"}'::jsonb),
('mcq', 2, 3, 'طول السهم الأحمر (السرعة) يزداد من موضع إلى آخر، والقوة المعيقة $\boldsymbol{F}_{\text{d}}$ تزداد بزيادة السرعة، بينما يبقى الوزن $\boldsymbol{F}_g$ ثابتًا.', '["سهم الوزن ثابت الطول في المواضع الأربعة.","الكتلة لا تتغير في أثناء السقوط.","لم يتغير المائع؛ والذي تغير هو سرعة الكرة (طول السهم الأحمر).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.608Z"}'::jsonb),
('mcq', 3, 1, 'المنحنى يرتفع كلما زادت السرعة: القوة المعيقة 1.0 N عند 10 m/s، و4.0 N عند 20 m/s؛ فالقوة المعيقة تزداد بزيادة السرعة.', '["المنحنى متزايد؛ فعند 10 m/s القوة 1.0 N وعند 20 m/s تصبح 4.0 N.","","القوة تتغير بتغير السرعة، فالمنحنى ليس أفقيًا.","القوة أكبر ما يمكن عند أكبر سرعة في المنحنى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.608Z"}'::jsonb),
('mcq', 4, 2, 'مقاومة الهواء هي القوة المعيقة، وهي تعتمد على حركة الجسم؛ فكلما زادت سرعة الراكب زاد مقدارها.', '["الاحتكاك مع الطريق ليس مقاومة الهواء التي يشعر بها.","الكتلة لا تتغير بتغير السرعة.","","خصائص الهواء لا تتغير بسرعة الراكب؛ الذي يتغير هو سرعة الجسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-19T07:48:34.609Z"}'::jsonb),
('mcq', 5, 3, 'الكرتان متماثلتان وفي الهواء نفسه وسرعتاهما متساويتان (5 m/s)، ومقدار القوة المعيقة يعتمد على السرعة؛ فالمقداران متساويان. أما الاتجاه فيعاكس الحركة: إلى أعلى في الكرة الهابطة، وإلى أسفل في الكرة الصاعدة.', '["مقدار القوة المعيقة يعتمد على سرعة الجسم وخصائصه وخصائص المائع، لا على اتجاه الوزن؛ والسرعتان متساويتان.","اتجاه الحركة بالنسبة إلى الجاذبية لا يغير مقدار القوة المعيقة؛ الذي يحدده هنا السرعة، وهي متساوية.","المقداران متساويان، لكن القوة المعيقة تعاكس الحركة: إلى أعلى في الهابطة وإلى أسفل في الصاعدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.609Z"}'::jsonb),
('mcq', 6, 0, 'كلما زادت سرعة الجسم زاد مقدار القوة المعيقة؛ فعند 15 m/s يجب أن تكون أكبر من 16 N، والقيمة الممكنة هي 36 N.', '["","القوة المعيقة تعتمد على حركة الجسم، فلا تبقى ثابتة عندما تزداد سرعته.","زيادة السرعة تزيد القوة المعيقة ولا تنقصها.","الدراجة تتحرك في الهواء، فلا تنعدم القوة المعيقة ما دامت سرعتها لا تساوي صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.609Z"}'::jsonb),
('mcq', 7, 1, 'في أثناء الصعود تتناقص سرعة الكرة، والقوة المعيقة تعتمد على السرعة، فيقل مقدارها حتى ينعدم لحظة وصولها إلى أقصى ارتفاع.', '["الارتفاع وحده لا يزيد القوة المعيقة؛ هي تعتمد على السرعة، والسرعة تتناقص.","","المائع نفسه، لكن سرعة الكرة تتغير، فتتغير القوة المعيقة.","اتجاه الوزن لا يغير مقدار القوة المعيقة؛ مقدارها يعتمد على السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-19T07:48:34.610Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) كلما زادت سرعة الكرة زادت القوة المعيقة: من صفر عند السرعة صفر إلى 0.45 N عند 16.6 m/s. (ب) لا؛ فالوزن ثابت (0.47 N) والقوة المعيقة تزداد، فتقل القوة المحصلة (الوزن − القوة المعيقة) من 0.47 N إلى 0.35 N ثم 0.17 N ثم 0.06 N ثم 0.02 N، ويقل التسارع؛ ويظهر ذلك في الجدول إذ تقل الزيادة في السرعة في كل ثانية (8.5 ثم 5.0 ثم 2.3 ثم 0.8 m/s).', '["القوة المعيقة تزداد بزيادة السرعة","الوزن ثابت والمحصلة تقل","التسارع يقل","الاستدلال من تناقص الزيادة في السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف العلاقة","marks":1},{"element":"تحليل القوة المحصلة","marks":1},{"element":"استنتاج تناقص التسارع","marks":1},{"element":"الاستدلال من الجدول","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح وتحليل صحيح مستند إلى الجدول"},{"level":"2–3 درجات","description":"وصف صحيح مع تحليل ناقص"},{"level":"درجة واحدة","description":"وصف العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التسارع ثابت يساوي g","القول إن القوة المعيقة تقل بزيادة السرعة","الخلط بين السرعة والتسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.610Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تدفع مركبة الجاذبية على المنحدر الدراجة إلى الأسفل، فتزداد سرعتها. ومع زيادة السرعة تزداد القوة المعيقة التي يؤثر بها الهواء في عكس اتجاه الحركة، فتقل القوة المحصلة في اتجاه الحركة، فيقل التسارع ويصبح ازدياد السرعة أبطأ. وإذا تساوت القوى المعاكسة مع القوة الدافعة أصبحت السرعة منتظمة.', '["القوة المعيقة تزداد بزيادة السرعة","القوة المحصلة في اتجاه الحركة تقل","التسارع يقل فيبطؤ ازدياد السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"ربط القوة المعيقة بالسرعة","marks":1},{"element":"تناقص القوة المحصلة","marks":1},{"element":"تناقص التسارع","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير متسلسل صحيح"},{"level":"درجتان","description":"ربط صحيح دون إكمال السلسلة"},{"level":"درجة واحدة","description":"ذكر زيادة القوة المعيقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الوزن يقل","الخلط بين تناقص التسارع وتناقص السرعة","إغفال القوة المعيقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-19T07:48:34.610Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عند السرعة المنتظمة تكون القوة المحصلة صفرًا (قانون نيوتن الأول)، فيجب أن تساوي قوة الدفع مجموع القوى المعاكسة للحركة، ومنها القوة المعيقة. والقوة المعيقة تزداد بزيادة السرعة، فتكون عند 30 m/s أكبر منها عند 15 m/s؛ لذلك يلزم المحرك قوة دفع أكبر ليوازنها.', '["السرعة المنتظمة: القوة المحصلة صفر","قوة الدفع تساوي القوى المعاكسة","القوة المعيقة أكبر عند السرعة الأكبر","الاستنتاج: دفع أكبر"]'::jsonb, '[]'::jsonb, '[{"element":"قانون نيوتن الأول","marks":1},{"element":"توازن القوى","marks":1},{"element":"علاقة القوة المعيقة بالسرعة","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعليل كامل صحيح"},{"level":"2–3 درجات","description":"تعليل صحيح مع إغفال شرط الاتزان أو الاستنتاج"},{"level":"درجة واحدة","description":"ذكر زيادة القوة المعيقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السيارة تحتاج قوة محصلة لتبقى متحركة","إغفال القوة المعيقة","القول إن السرعة الكبيرة تعني تسارعًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.610Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L2-O08') and x.type = v.type and x.number = v.number
