insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L2-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا تقل سرعة المظلي كثيرًا عندما يفتح مظلته؟', null, null, '["لأن كتلته تقل عند فتح المظلة","لأن قوة الجاذبية المؤثرة فيه تنعدم بعد فتحها","لأن الهواء يصبح أقل لزوجة","لأن مساحة سطحه تكبر فتزداد القوة المعيقة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 110 — المظلي وفتح المظلة'),
('mcq', 2, 'أي الأجسام الآتية يكون تأثير القوة المعيقة في حركته أوضح عند سقوطه في الهواء؟', null, null, '["ورقة خفيفة كبيرة المساحة","كرة حديدية صغيرة وثقيلة جدًا","حجر ثقيل صغير الحجم","كرة رصاص صغيرة الحجم"]'::jsonb, 'فهم', 'تطبيق', 'متوسط', 'الكتاب ص 110 — الأجسام الخفيفة ذات السطوح الكبيرة'),
('mcq', 3, 'أُسقطت ورقتان متماثلتان في الوقت نفسه ومن الارتفاع نفسه، إحداهما مفرودة والأخرى مكوّرة على شكل كرة. أيهما تصل إلى الأرض أولًا، ولماذا؟', null, null, '["المفرودة، لأن سطحها أكبر فتجذبها الأرض بقوة أكبر","المكوّرة، لأن سطحها أصغر فتقل القوة المعيقة فيها","تصلان معًا، لأن كتلتيهما متساويتان","المفرودة، لأن القوة المعيقة تدفعها إلى أسفل"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 109 — اعتماد القوة المعيقة على شكل الجسم وحجمه'),
('mcq', 4, 'يغيّر المظليون اتجاه أجسامهم وهيئاتها في أثناء السقوط قبل فتح المظلة. ما الهدف من ذلك؟', null, null, '["تغيير كتلتهم في أثناء السقوط لتزيد سرعتهم","تقليل وزنهم الحقيقي في أثناء السقوط الحر","تغيير القوة المعيقة فتتغير سرعتهم الحدية","إلغاء القوة المعيقة كليًا عن أجسامهم"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 110 — تغيير المظليين هيئات أجسامهم'),
('mcq', 5, 'كرتان لهما الكتلة نفسها، إحداهما كبيرة الحجم والأخرى صغيرة الحجم، أُسقطتا في الهواء من السكون. أيهما تكون سرعتها الحدية أصغر، ولماذا؟', null, null, '["الكبيرة؛ لأن القوة المعيقة فيها أكبر عند السرعة نفسها، فتساوي وزنها عند سرعة أصغر","الصغيرة؛ لأن القوة المعيقة فيها أكبر عند السرعة نفسها بسبب صغر حجمها","متساويتان؛ لأن وزنيهما متساويان فتصلان إلى السرعة الحدية نفسها","الكبيرة؛ لأن وزنها أكبر من وزن الصغيرة بسبب كبر حجمها"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 110 — الأجسام الخفيفة ذات السطوح الكبيرة'),
('mcq', 6, 'تُصمَّم سيارات السباق والطائرات بأشكال انسيابية. ما الهدف من ذلك؟', null, null, '["زيادة كتلة المركبة لتزيد سرعتها القصوى","تقليل القوة المعيقة لأنها تعتمد على شكل الجسم","زيادة القوة المعيقة لتثبيت المركبة على الطريق","تقليل وزن المركبة الحقيقي"]'::jsonb, 'فهم', 'تطبيق', 'سهل', 'الكتاب ص 109 — اعتماد القوة المعيقة على شكل الجسم'),
('mcq', 7, 'أي مما يأتي من خصائص الجسم نفسه التي تعتمد عليها القوة المعيقة؟', null, null, '["لون سطحه الخارجي","لزوجة المائع","درجة حرارة المائع","شكله وحجمه"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 109 — العوامل المؤثرة في القوة المعيقة'),
('essay', 1, 'يهبط مظلي قبل فتح مظلته بسرعة حدية كبيرة، وبعد فتحها تصبح سرعته الحدية نحو 5 m/s. فسّر ذلك بدلالة اعتماد القوة المعيقة على شكل الجسم وحجمه.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 110 — المظلي وفتح المظلة'),
('essay', 2, 'صمّم تجربة بسيطة تبين أن القوة المعيقة تعتمد على شكل الجسم، باستخدام ورقتين متماثلتين. حدد المتغير المستقل والمتغيرات الثابتة، وتوقع النتيجة وفسّرها.', null, null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 109 — اعتماد القوة المعيقة على شكل الجسم وحجمه'),
('essay', 3, 'تبلغ السرعة الحدية لكرة تنس الطاولة في الهواء نحو 9 m/s، ولكرة السلة نحو 20 m/s، ولكرة البيسبول نحو 42 m/s. فسّر هذا الاختلاف مستعينًا بشرط الوصول إلى السرعة الحدية وبخصائص كل كرة.', null, null, null, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 110 — أمثلة السرعة الحدية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
