from (values
('mcq', 1, 3, 'عند فتح المظلة تتغير هيئته وتكبر مساحة سطحه، إذ يصبح جزءًا من جسم كبير (المظلي والمظلة)، فتؤثر فيه قوة معيقة كبيرة وتصبح سرعته الحدية صغيرة (نحو 5 m/s).', '["الكتلة لا تتغير بفتح المظلة؛ فالمظلة محمولة مع المظلي قبل فتحها وبعده.","الجاذبية تبقى مؤثرة؛ الذي يزداد هو القوة المعيقة.","خصائص الهواء لم تتغير؛ الذي تغير هو شكل الجسم وحجمه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-19T07:48:34.611Z"}'::jsonb),
('mcq', 2, 0, 'في الأجسام الخفيفة ذات السطوح الكبيرة يكون للقوة المعيقة تأثير ملحوظ في حركتها، وسرعان ما تصل إلى سرعتها الحدية.', '["","الأجسام الثقيلة ذات السطوح الصغيرة يكون تأثرها بالقوة المعيقة أقل كثيرًا.","الحجر ثقيل وسطحه صغير، فتأثره بالقوة المعيقة قليل.","كرة الرصاص ثقيلة وسطحها صغير، فتأثرها قليل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.611Z"}'::jsonb),
('mcq', 3, 1, 'الكتلتان والوزنان متساويان، لكن القوة المعيقة تعتمد على شكل الجسم وحجمه؛ فالمفرودة سطحها أكبر فتتأثر بقوة معيقة أكبر، فتصل المكوّرة أولًا.', '["قوة الجاذبية تعتمد على الكتلة لا على مساحة السطح، والكتلتان متساويتان.","","تصلان معًا فقط لو أهملنا مقاومة الهواء؛ لكن القوة المعيقة تختلف باختلاف الشكل.","القوة المعيقة تعاكس الحركة، أي إلى أعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.611Z"}'::jsonb),
('mcq', 4, 2, 'القوة المعيقة تعتمد على شكل الجسم وحجمه؛ فبتغيير الهيئة يغيّر المظلي القوة المعيقة، فيزيد سرعته الحدية أو يقللها.', '["الكتلة لا تتغير بتغير الهيئة.","الوزن الحقيقي $mg$ لا يتغير بتغير الهيئة.","","لا يمكن إلغاء القوة المعيقة ما دام المظلي يتحرك في الهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.611Z"}'::jsonb),
('mcq', 5, 0, 'الكرتان متساويتان في الوزن. والقوة المعيقة تعتمد على حجم الجسم، فتكون في الكرة الكبيرة أكبر عند السرعة نفسها؛ لذلك تتساوى القوة المعيقة مع وزنها عند سرعة أصغر، فتكون سرعتها الحدية أصغر.', '["","القوة المعيقة تعتمد على حجم الجسم، وتكون أكبر في الكرة الأكبر حجمًا عند السرعة نفسها، لا في الأصغر.","الوزنان متساويان، لكن القوة المعيقة تختلف باختلاف الحجم، فتساوي الوزن عند سرعتين مختلفتين.","الكتلتان متساويتان فالوزنان متساويان؛ والفرق سببه القوة المعيقة لا الوزن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.612Z"}'::jsonb),
('mcq', 6, 1, 'القوة المعيقة تعتمد على خصائص الجسم ومنها شكله؛ فالشكل الانسيابي يقلل ممانعة الهواء.', '["الشكل الانسيابي لا يغير الكتلة، وزيادة الكتلة لا تزيد السرعة.","","الهدف تقليل الممانعة لا زيادتها.","الشكل لا يغير الوزن $mg$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.612Z"}'::jsonb),
('mcq', 7, 3, 'تعتمد القوة المعيقة على حركة الجسم، وعلى خصائص الجسم ومنها شكله وحجمه، وعلى خصائص المائع ومنها لزوجته ودرجة حرارته.', '["اللون لا يؤثر في ممانعة المائع.","اللزوجة من خصائص المائع لا الجسم.","درجة الحرارة هنا من خصائص المائع لا الجسم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.612Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عند فتح المظلة تتغير هيئة المظلي ويصير جزءًا من جسم كبير (المظلي والمظلة) مساحة سطحه كبيرة، فتؤثر فيه قوة معيقة كبيرة عند السرعة نفسها. وبما أن السرعة الحدية تتحقق عندما تساوي القوة المعيقة الوزن، فإن القوة المعيقة الكبيرة تبلغ وزن المظلي عند سرعة أصغر، فتصبح السرعة الحدية صغيرة (نحو 5 m/s).', '["المظلة تزيد حجم الجسم ومساحة سطحه","القوة المعيقة أكبر عند السرعة نفسها","السرعة الحدية حين تساوي القوة المعيقة الوزن","الاستنتاج: سرعة حدية أصغر"]'::jsonb, '[]'::jsonb, '[{"element":"أثر المظلة في الشكل والحجم","marks":1},{"element":"زيادة القوة المعيقة","marks":1},{"element":"شرط السرعة الحدية","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير متكامل صحيح"},{"level":"2–3 درجات","description":"تفسير صحيح دون ربطه بشرط السرعة الحدية"},{"level":"درجة واحدة","description":"ذكر زيادة المساحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن كتلة المظلي تقل","القول إن الجاذبية تنعدم بعد فتح المظلة","الخلط بين السرعة الحدية والتسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.612Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التجربة: نكوّر إحدى الورقتين على شكل كرة ونترك الأخرى مفرودة، ثم نسقطهما معًا من الارتفاع نفسه ونلاحظ أيهما تصل أولًا (ويمكن قياس الزمن بساعة إيقاف). المتغير المستقل: شكل الورقة. الثوابت: الكتلة (ورقتان متماثلتان)، وارتفاع الإسقاط، والمائع (الهواء نفسه)، وبدء السقوط من السكون. التوقع: تصل المكوّرة أولًا؛ لأن سطحها أصغر فتؤثر فيها قوة معيقة أصغر، بينما الوزنان متساويان.', '["خطوات واضحة للتجربة","المتغير المستقل: الشكل","الثوابت: الكتلة والارتفاع والمائع","التوقع والتفسير"]'::jsonb, '[]'::jsonb, '[{"element":"الخطوات","marks":1},{"element":"المتغير المستقل","marks":1},{"element":"المتغيرات الثابتة","marks":1},{"element":"التوقع والتفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصميم كامل مع ضبط المتغيرات وتفسير صحيح"},{"level":"2–3 درجات","description":"تصميم صحيح مع نقص في الضبط أو التفسير"},{"level":"درجة واحدة","description":"وصف عام دون ضبط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استخدام ورقتين مختلفتي الكتلة","إسقاطهما من ارتفاعين مختلفين","تفسير النتيجة باختلاف الوزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.612Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تصل الكرة إلى سرعتها الحدية عندما تساوي القوة المعيقة وزنها. القوة المعيقة تزداد بزيادة السرعة وتعتمد على شكل الكرة وحجمها. كرة تنس الطاولة خفيفة جدًا بالنسبة إلى سطحها، فتبلغ القوة المعيقة وزنها الصغير عند سرعة صغيرة. كرة البيسبول ثقيلة وسطحها صغير نسبيًا، فلا تبلغ القوة المعيقة وزنها الكبير إلا عند سرعة كبيرة. وكرة السلة بينهما.', '["شرط السرعة الحدية: القوة المعيقة = الوزن","القوة المعيقة تزداد بالسرعة","تنس الطاولة: خفيفة بالنسبة لسطحها → سرعة حدية صغيرة","البيسبول: ثقيلة وسطح صغير → سرعة حدية كبيرة"]'::jsonb, '[]'::jsonb, '[{"element":"الشرط","marks":1},{"element":"اعتماد القوة المعيقة على السرعة والشكل والحجم","marks":1},{"element":"تحليل تنس الطاولة","marks":1},{"element":"تحليل البيسبول","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل كامل صحيح"},{"level":"2–3 درجات","description":"تحليل صحيح لكرة واحدة مع الشرط"},{"level":"درجة واحدة","description":"ذكر الشرط فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأثقل يسقط أسرع دون ربط بالقوة المعيقة","إغفال دور مساحة السطح","القول إن القوة المعيقة لا تؤثر في الكرات الثقيلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.612Z"}'::jsonb)
