('mcq', 4, 'أي العبارات الآتية تلخص تلخيصًا صحيحًا العوامل التي تحدد القوة المعيقة المؤثرة في جسم؟', null, null, '["كتلة الجسم وحدها دون غيرها من العوامل","حركة الجسم وخصائصه، وخصائص المائع","خصائص المائع وحدها دون خصائص الجسم","وزن الجسم وتسارع الجاذبية الأرضية فقط"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 124 — المفاهيم الرئيسة — القوة المعيقة'),
('mcq', 5, 'قيست القوة المعيقة المؤثرة في الكرة نفسها وهي تتحرك بالسرعة نفسها خلال ثلاثة سوائل عند درجة الحرارة نفسها، فكانت النتائج (بيانات افتراضية) كما في الجدول الآتي. ما الخاصية التي تفسر اختلاف القوة المعيقة؟', '{"headers":["السائل","القوة المعيقة (N)"],"rows":[["الماء","0.02"],["زيت الطعام","0.9"],["العسل","20"]]}'::jsonb, null, '["حجم الكرة","سرعة الكرة","لزوجة السائل","شكل الكرة"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 109 — اعتماد القوة المعيقة على لزوجة المائع'),
('mcq', 6, 'تتحرك ملعقة في وعاء عسل بصعوبة، وعندما يُسخَّن العسل تتحرك فيه بسهولة أكبر. ما الذي يبينه ذلك؟', null, null, '["القوة المعيقة تعتمد على كتلة الملعقة","القوة المعيقة تعتمد على لون المائع","القوة المعيقة لا تعتمد على المائع","القوة المعيقة تعتمد على درجة حرارة المائع"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 109 — اعتماد القوة المعيقة على درجة حرارة المائع'),
