('mcq', 3, 3, 'اللزوجة من خصائص المائع، أما الشكل والحجم فمن خصائص الجسم، والسرعة من خصائص حركته.', '["الحجم من خصائص الجسم.","الشكل من خصائص الجسم.","السرعة تصف حركة الجسم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.613Z"}'::jsonb),
('mcq', 4, 1, 'تأثير القوة المعيقة في جسم تحدده حركة الجسم (سرعته)، وخصائص الجسم (شكله وحجمه)، وخصائص المائع (لزوجته ودرجة حرارته).', '["الكتلة ليست من العوامل التي ذُكرت، والقوة المعيقة تعتمد على أكثر من عامل.","","خصائص المائع عامل واحد من ثلاثة.","هذه تحدد الوزن لا القوة المعيقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.613Z"}'::jsonb),
('mcq', 5, 2, 'الكرة والسرعة ودرجة الحرارة ثابتة، والمتغير الوحيد هو السائل؛ والسائل الأكثر لزوجة (العسل) يؤثر بأكبر قوة معيقة.', '["الكرة نفسها في التجارب الثلاث، فحجمها ثابت.","السرعة ثابتة في التجارب الثلاث.","","الكرة نفسها، فشكلها ثابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.614Z"}'::jsonb),
('mcq', 6, 3, 'لم يتغير الجسم، والذي تغير هو درجة حرارة العسل، فتغيرت القوة المعيقة؛ فهي تعتمد على درجة حرارة المائع (ولزوجته).', '["الملعقة نفسها في الحالتين، فكتلتها لم تتغير.","تسخين العسل لم يغير لونه؛ وتأثير اللون غير وارد.","تغيرت الممانعة بتغير حالة المائع، فهي تعتمد عليه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-19T07:48:34.614Z"}'::jsonb),
('mcq', 7, 0, 'اليد والسرعة لم تتغيرا، لكن المائع تغير؛ والقوة المعيقة تعتمد على خصائص المائع كلزوجته، فتكون في الماء أكبر كثيرًا.', '["","الماء أيضًا يحيط باليد، والمهم خصائص المائع.","القوة المعيقة تعتمد أيضًا على خصائص المائع، والمائعان مختلفان.","المائع الأقل لزوجة يمانع الحركة بقوة أقل لا أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.614Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المجموعة الأولى: حركة الجسم، مثل سرعته (كلما زادت سرعته زادت القوة المعيقة). المجموعة الثانية: خصائص الجسم، مثل شكله وحجمه (المظلة المفتوحة تزيد القوة المعيقة). المجموعة الثالثة: خصائص المائع، مثل لزوجته ودرجة حرارته (العسل يمانع الحركة أكثر من الماء).', '["حركة الجسم: السرعة","خصائص الجسم: الشكل والحجم","خصائص المائع: اللزوجة ودرجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"المجموعة الأولى مع مثال","marks":1},{"element":"المجموعة الثانية مع مثال","marks":1},{"element":"المجموعة الثالثة مع مثال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"المجموعات الثلاث صحيحة مع أمثلة"},{"level":"درجتان","description":"مجموعتان صحيحتان"},{"level":"درجة واحدة","description":"مجموعة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل اللزوجة من خصائص الجسم","ذكر الكتلة بدل الشكل والحجم","إغفال حركة الجسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.614Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) في الزيت؛ لأن الزيت أكثر لزوجة من الماء، فتكون القوة المعيقة المؤثرة في الكرة أكبر عند السرعة نفسها، فتساوي وزنها عند سرعة أصغر. (ب) القوة المعيقة تعتمد على درجة حرارة المائع؛ وتسخين الزيت يجعله أقل لزوجة عادة، فتقل القوة المعيقة عند السرعة نفسها وتتحرك الكرة فيه أسرع (تزداد سرعتها الحدية).', '["السرعة الحدية أصغر في الزيت","التفسير باللزوجة والقوة المعيقة الأكبر","القوة المعيقة تعتمد على درجة الحرارة","التسخين يقلل الممانعة فتتحرك الكرة أسرع"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم في (أ)","marks":1},{"element":"تفسير (أ)","marks":1},{"element":"التوقع في (ب)","marks":1},{"element":"تفسير (ب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"2–3 درجات","description":"جزء كامل صحيح مع نقص في الآخر"},{"level":"درجة واحدة","description":"حكم صحيح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكرة أثقل في الزيت","إغفال دور درجة الحرارة","الخلط بين اللزوجة والكثافة دون ربط بالقوة المعيقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-19T07:48:34.614Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نملأ الأنابيب بسوائل مختلفة اللزوجة (ماء، زيت، عسل) عند درجة الحرارة نفسها. نسقط كرة متماثلة في كل أنبوب، وبعد أن تصل إلى سرعة منتظمة نقيس الزمن الذي تقطع فيه مسافة محددة (مثلًا 0.30 m) ونحسب سرعتها الحدية. المتغير المستقل: نوع السائل (لزوجته). المتغير التابع: السرعة الحدية. الثوابت: الكرة (الشكل والحجم والكتلة)، درجة الحرارة، المسافة المقيسة. المقارنة: الكرات متماثلة الوزن، فعند السرعة الحدية القوة المعيقة = الوزن؛ والسائل الذي تبلغ فيه الكرة هذا التوازن عند سرعة أصغر يؤثر بقوة معيقة أكبر عند السرعة نفسها. التوقع: السرعة الحدية أصغر في السائل الأكثر لزوجة.', '["المتغير المستقل: اللزوجة (نوع السائل)","المتغير التابع: السرعة الحدية","الثوابت: الكرة ودرجة الحرارة","طريقة القياس والمقارنة","التوقع"]'::jsonb, '["السرعة الحدية = المسافة ÷ الزمن بعد استقرار السرعة"]'::jsonb, '[{"element":"المتغيرات","marks":2},{"element":"طريقة القياس","marks":1},{"element":"المقارنة والتوقع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصميم كامل منضبط مع توقع صحيح"},{"level":"2–3 درجات","description":"تصميم صحيح مع نقص في الضبط أو المقارنة"},{"level":"درجة واحدة","description":"وصف عام دون ضبط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تغيير الكرة مع تغيير السائل","قياس الزمن من لحظة الإسقاط قبل استقرار السرعة","إغفال تثبيت درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.615Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
