('mcq', 3, 'يبين الشكل الآتي كرة قُذفت رأسيًا وهي في أثناء صعودها، ويمثل السهم الأحمر سرعتها المتجهة. ما اتجاه القوة المعيقة المؤثرة فيها؟', null, '[{"src":"qimg/phys1/c4l2-o11-ball-up.svg","alt":"كرة صفراء، وبجانبها سهم أحمر رأسي إلى أعلى مكتوب عنده v يمثل سرعتها المتجهة. على يسار الشكل سهم أسود إلى أعلى مكتوب عنده +y."}]'::jsonb, '["رأسيًا إلى أسفل","رأسيًا إلى أعلى","أفقيًا إلى اليسار","لا اتجاه لها لأنها تصعد"]'::jsonb, 'فهم', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 109 — اتجاه القوة المعيقة'),
('mcq', 4, 'تسير سيارة على طريق أفقي متجهة نحو الشرق. ما اتجاه القوة المعيقة التي يؤثر بها الهواء فيها؟', null, null, '["نحو الشرق","إلى أسفل نحو الطريق","نحو الغرب","نحو الشمال"]'::jsonb, 'فهم', 'تحديد اتجاه', 'سهل', 'الكتاب ص 109 — اتجاه القوة المعيقة'),
('mcq', 5, 'يبين مخطط الجسم الحر الآتي القوتين المؤثرتين في كرة تتحرك رأسيًا في الهواء. في أي اتجاه تتحرك الكرة؟', null, '[{"src":"qimg/phys1/c4l2-o11-fbd-fd-up.svg","alt":"مخطط جسم حر: نقطة تمثل الكرة، يخرج منها سهم أزرق قصير إلى أعلى مكتوب عنده F_d، وسهم أزرق أطول إلى أسفل مكتوب عنده F_g. على يسار الشكل سهم أسود إلى أعلى مكتوب عنده +y."}]'::jsonb, '["رأسيًا إلى أعلى","رأسيًا إلى أسفل","لا يمكن تحديده","لا تتحرك (ساكنة)"]'::jsonb, 'تحليل', 'قراءة مخطط', 'صعب', 'الكتاب ص 110 — الشكل 4-12 — اتجاه القوة المعيقة'),
('mcq', 6, 'كرة قُذفت رأسيًا إلى أعلى في الهواء وما زالت تصعد. كيف يقارَن مقدار القوة المحصلة المؤثرة فيها بوزنها؟', null, null, '["أصغر من وزنها، لأن القوة المعيقة تعاكس الوزن","يساوي وزنها، لأن القوة المعيقة تساوي صفرًا","يساوي صفرًا، لأن القوتين متساويتان","أكبر من وزنها، لأن القوتين كلتيهما إلى أسفل"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 109 — اتجاه القوة المعيقة'),
('mcq', 7, 'ما العلاقة بين اتجاه القوة المعيقة واتجاه السرعة المتجهة لجسم يتحرك في مائع؟', null, null, '["متعاكستان دائمًا","في الاتجاه نفسه دائمًا","متعامدتان دائمًا","متعاكستان في الهبوط فقط"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 109 — اتجاه القوة المعيقة'),
('essay', 1, 'ارسم مخطط الجسم الحر لمظلي يسقط في الهواء قبل فتح مظلته وقبل أن يصل إلى سرعته الحدية، مسميًا كل قوة برمزها، ومبينًا الطول النسبي للأسهم والاتجاه الموجب. ثم فسّر لماذا رسمت الأسهم بهذه الأطوال.', null, null, null, 'تطبيق', 'رسم مخطط', 'متوسط', 'الكتاب ص 110 — الشكل 4-12'),
('essay', 2, 'قُذفت كرة رأسيًا إلى أعلى في الهواء. ارسم مخطط الجسم الحر للكرة في ثلاثة مواضع: في أثناء صعودها، وعند أقصى ارتفاع، وفي أثناء هبوطها، وحدد في كل موضع اتجاه القوة المعيقة أو انعدامها مع التعليل.', null, null, null, 'تحليل', 'رسم مخطط', 'صعب', 'الكتاب ص 125 — التقويم 47 مع القوة المعيقة'),
('essay', 3, 'اذكر رمز القوة المعيقة، ثم حدد اتجاهها في كل حالة مما يأتي مع التعليل: (أ) سباح يسبح نحو الشمال. (ب) طائرة تحلق أفقيًا نحو الغرب. (ج) قطرة مطر تسقط رأسيًا.', null, null, null, 'فهم', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 109 — اتجاه القوة المعيقة ورمزها')
