('mcq', 3, 0, 'الكرة تتحرك إلى أعلى، فتكون القوة المعيقة إلى أسفل؛ أي في اتجاه الوزن نفسه في أثناء الصعود.', '["","هذا اتجاه حركة الكرة؛ والقوة المعيقة تعاكس الحركة.","القوة المعيقة تعاكس الحركة، والحركة رأسية إلى أعلى.","القوة المعيقة تؤثر في أثناء الصعود أيضًا ما دامت الكرة تتحرك في الهواء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-19T07:48:34.616Z"}'::jsonb),
('mcq', 4, 2, 'القوة المعيقة تعاكس اتجاه حركة الجسم؛ فالسيارة تتحرك نحو الشرق، والقوة المعيقة نحو الغرب.', '["هذا اتجاه حركة السيارة، والقوة المعيقة تعاكسه.","القوة المعيقة تعاكس الحركة الأفقية، لا تتجه نحو الطريق.","","الشمال عمودي على اتجاه الحركة، لا معاكس لها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.616Z"}'::jsonb),
('mcq', 5, 1, 'القوة المعيقة $\boldsymbol{F}_{\text{d}}$ في المخطط إلى أعلى، وهي تعاكس اتجاه الحركة دائمًا؛ إذن الكرة تتحرك إلى أسفل.', '["لو كانت الكرة تصعد لكانت $\\boldsymbol{F}_{\\text{d}}$ إلى أسفل مثل $\\boldsymbol{F}_g$.","","يمكن تحديده: اتجاه $\\boldsymbol{F}_{\\text{d}}$ يعاكس الحركة دائمًا.","لو كانت ساكنة في الهواء لما أثرت فيها قوة معيقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.616Z"}'::jsonb),
('mcq', 6, 3, 'في الصعود: $\boldsymbol{F}_g$ إلى أسفل و$\boldsymbol{F}_{\text{d}}$ إلى أسفل (تعاكس الحركة)، فمقدار المحصلة $F_g + F_{\text{d}}$ أكبر من الوزن.', '["القوة المعيقة تعاكس الحركة لا الوزن؛ وفي الصعود هي إلى أسفل مثل الوزن.","الكرة تتحرك في الهواء، فالقوة المعيقة لا تساوي صفرًا.","القوتان في الاتجاه نفسه، فلا تلغي إحداهما الأخرى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.616Z"}'::jsonb),
('mcq', 7, 0, 'يؤثر المائع في الجسم المتحرك خلاله بقوة معيقة في اتجاه يعاكس حركته، أيًا كان اتجاه الحركة.', '["","القوة المعيقة تمانع الحركة فلا تكون في اتجاهها.","القوة المعيقة تعاكس الحركة ولا تتعامد معها.","القوة المعيقة تعاكس الحركة في الصعود أيضًا وفي الحركة الأفقية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.616Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المظلي نقطة يخرج منها سهم $\boldsymbol{F}_g$ إلى أسفل وسهم $\boldsymbol{F}_{\text{d}}$ إلى أعلى أقصر منه، مع سهم $+y$ (أو $+$ إلى أسفل) لتحديد الاتجاه الموجب. $\boldsymbol{F}_{\text{d}}$ إلى أعلى لأنها تعاكس الحركة (إلى أسفل)، وهي أقصر من $\boldsymbol{F}_g$ لأن المظلي لم يصل بعد إلى السرعة الحدية، فما زالت القوة المحصلة إلى أسفل وما زال يتسارع.', '["$\\boldsymbol{F}_g$ إلى أسفل","$\\boldsymbol{F}_{\\text{d}}$ إلى أعلى","$\\boldsymbol{F}_{\\text{d}}$ أقصر من $\\boldsymbol{F}_g$","تحديد الاتجاه الموجب","التفسير"]'::jsonb, '[]'::jsonb, '[{"element":"القوتان باتجاهيهما ورمزيهما","marks":2},{"element":"الأطوال النسبية والاتجاه الموجب","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مخطط صحيح كامل مع تفسير"},{"level":"2–3 درجات","description":"مخطط صحيح بأطوال غير مبررة أو بلا اتجاه موجب"},{"level":"درجة واحدة","description":"قوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم $\\boldsymbol{F}_{\\text{d}}$ إلى أسفل","رسم السهمين متساويين قبل السرعة الحدية","إضافة القوة المحصلة إلى المخطط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.616Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) الصعود: $\boldsymbol{F}_g$ إلى أسفل و$\boldsymbol{F}_{\text{d}}$ إلى أسفل، لأن الحركة إلى أعلى. (2) أقصى ارتفاع: السرعة صفر لحظيًا فلا قوة معيقة، وتبقى $\boldsymbol{F}_g$ وحدها إلى أسفل. (3) الهبوط: $\boldsymbol{F}_g$ إلى أسفل و$\boldsymbol{F}_{\text{d}}$ إلى أعلى، لأن الحركة إلى أسفل. القوة المعيقة تعاكس اتجاه الحركة دائمًا، ومقدارها يعتمد على السرعة.', '["الصعود: القوتان إلى أسفل","القمة: الوزن وحده","الهبوط: الوزن إلى أسفل والمعيقة إلى أعلى","التعليل: المعيقة تعاكس الحركة وتعتمد على السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"مخطط الصعود","marks":1},{"element":"مخطط القمة","marks":1},{"element":"مخطط الهبوط","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ثلاثة مخططات صحيحة مع التعليل"},{"level":"2–3 درجات","description":"مخططان صحيحان"},{"level":"درجة واحدة","description":"مخطط واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم القوة المعيقة إلى أعلى في الصعود","رسم قوة معيقة عند القمة","رسم قوة «دفع» إلى أعلى في أثناء الصعود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.617Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الرمز $\boldsymbol{F}_{\text{d}}$. القوة المعيقة تعاكس اتجاه حركة الجسم دائمًا: (أ) نحو الجنوب. (ب) نحو الشرق. (ج) إلى أعلى.', '["الرمز $\\boldsymbol{F}_{\\text{d}}$","(أ) نحو الجنوب","(ب) نحو الشرق","(ج) إلى أعلى","التعليل: تعاكس الحركة"]'::jsonb, '[]'::jsonb, '[{"element":"الرمز","marks":1},{"element":"الحالات الثلاث","marks":2},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الرمز والحالات الثلاث مع التعليل"},{"level":"2–3 درجات","description":"حالتان صحيحتان مع الرمز"},{"level":"درجة واحدة","description":"الرمز أو حالة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل القوة المعيقة في اتجاه الحركة","جعلها إلى أسفل دائمًا","استخدام $\\boldsymbol{f}_{f}$ رمزًا لها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.617Z"}'::jsonb)
