('mcq', 1, 2, 'السرعة الحدية هي السرعة المنتظمة التي يصل إليها الجسم الساقط عندما تتساوى القوة المعيقة مع قوة الجاذبية الأرضية.', '["هذه سرعة الإطلاق، ولا علاقة لها بتوازن القوة المعيقة مع الوزن.","هذه سرعة نهائية للسقوط الحر دون مقاومة هواء، وليست سرعة منتظمة.","","عند السرعة الحدية يكون التسارع صفرًا لا أكبر ما يمكن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.618Z"}'::jsonb),
('mcq', 2, 0, 'إذا وصلت سرعة جسم ساقط إلى حد تكون فيه القوة المعيقة مساوية لوزنه، فإنه يحتفظ بسرعة منتظمة تسمى السرعة الحدية.', '["","السرعة المتوسطة نسبة المسافة إلى الزمن، وليست مرتبطة بتوازن القوى.","السرعة الابتدائية سرعة الجسم عند بداية الحركة.","السرعة النسبية سرعة جسم بالنسبة إلى جسم آخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.618Z"}'::jsonb),
('mcq', 3, 3, 'عند السرعة الحدية $F_{\text{d}} = F_g$ والقوتان متعاكستان، فالقوة المحصلة صفر والتسارع صفر.', '["المحصلة تساوي الوزن في السقوط الحر فقط، أما هنا فالقوة المعيقة تلغي الوزن.","القوتان متعاكستان، فلا تُجمعان.","القوة المعيقة إحدى القوتين، والمحصلة هي ناتج جمعهما متجهيًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-19T07:48:34.618Z"}'::jsonb),
('mcq', 4, 1, 'السرعة الحدية هي القيمة التي تستقر عندها السرعة فيصبح المنحنى أفقيًا، وهي هنا نحو 20 m/s.', '["هذه سرعتها بعد نحو 1.4 s فقط، وما زالت تتزايد.","","هذا مقدار تسارع الجاذبية بوحدة مختلفة، وليس سرعة حدية.","هذا ميل المنحنى (التسارع) في النهاية، لا السرعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-19T07:48:34.618Z"}'::jsonb),
('mcq', 5, 0, 'عند السرعة الحدية القوة المحصلة صفر، فحسب قانون نيوتن الأول تستمر القطرة في الهبوط بسرعة منتظمة.', '["","القطرة لا تتوقف؛ فالقوة المحصلة صفر لكنها متحركة أصلًا، فتستمر في حركتها.","لا تتسارع بعد السرعة الحدية لأن المحصلة صفر.","التباطؤ يحتاج قوة محصلة إلى أعلى، والمحصلة هنا صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.618Z"}'::jsonb),
('mcq', 6, 2, 'تزداد سرعة الكرة الساقطة من السكون حتى تتساوى القوة المعيقة مع وزنها عند نحو 9 m/s، ثم تستمر بسرعة منتظمة لا تتجاوزها.', '["تبدأ من السكون بسرعة صفر، ثم تزداد سرعتها حتى 9 m/s.","السرعة الحدية سرعة لا تسارع، والتسارع يتناقص حتى يصبح صفرًا.","","لا تتوقف؛ بل تستمر في الهبوط بهذه السرعة المنتظمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.618Z"}'::jsonb),
('mcq', 7, 3, 'السرعة الحدية تتحقق عندما تساوي القوة المعيقة الوزن. في الأنبوب المفرّغ لا يوجد مائع ولا قوة معيقة، فتبقى القوة المحصلة تساوي الوزن وتظل سرعة الكرة تزداد بتسارع $g$.', '["9.8 m/s² قيمة تسارع الجاذبية لا سرعة حدية، والسرعة تزداد بلا توقف.","السرعة الحدية تحتاج قوة معيقة من مائع، ولا مائع في الأنبوب المفرّغ.","الوزن لا يتغير في أثناء السقوط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.619Z"}'::jsonb),
('essay', 1, null::int, null, null, 'السرعة الحدية: السرعة المنتظمة التي يصل إليها جسم يسقط في مائع عندما تتساوى القوة المعيقة مع قوة الجاذبية الأرضية (وزنه). الشرط: $F_{\text{d}} = F_g$. عندها القوة المحصلة صفر والتسارع صفر.', '["التعريف: سرعة منتظمة","الشرط $F_{\\text{d}} = F_g$","القوة المحصلة صفر","التسارع صفر"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"الشرط","marks":1},{"element":"القوة المحصلة والتسارع","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف وشرط ونتيجة صحيحة"},{"level":"درجتان","description":"تعريف وشرط صحيحان"},{"level":"درجة واحدة","description":"التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل التسارع عند السرعة الحدية يساوي g","تعريفها بأنها أكبر تسارع","جعل القوة المعيقة أكبر من الوزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.619Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) نحو 9 m/s، وهي القيمة التي يستقر عندها المنحنى. (ب) يصبح المنحنى أفقيًا تقريبًا بعد نحو 3.5–4 s. (ج) التسارع هو ميل المنحنى: يكون أكبر ما يمكن عند البداية (يقارب $g$)، ثم يتناقص الميل تدريجيًا، حتى يصبح صفرًا عندما يصبح المنحنى أفقيًا عند السرعة الحدية.', '["السرعة الحدية ≈ 9 m/s","زمن الوصول ≈ 3.5–4 s","التسارع = الميل ويتناقص","التسارع صفر عند السرعة الحدية"]'::jsonb, '[]'::jsonb, '[{"element":"السرعة الحدية","marks":1},{"element":"زمن الوصول","marks":1},{"element":"وصف تغير التسارع","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة صحيحة للأجزاء الثلاثة"},{"level":"2–3 درجات","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قراءة السرعة الحدية من بداية المنحنى","القول إن التسارع يزداد","الخلط بين السرعة والتسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-19T07:48:34.619Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) عند السرعة الحدية تتساوى القوة المعيقة مع الوزن: $F_{\text{d}} = F_g = mg = (0.20)(9.80) = 1.96 \approx 2.0\ \text{N}$، واتجاهها إلى أعلى معاكس لحركة الكرة. (ب) القوتان متساويتان مقدارًا ومتعاكستان اتجاهًا، فالقوة المحصلة صفر والتسارع صفر. (ج) تبقى سرعتها 15 m/s إلى أسفل؛ لأن السرعة الحدية سرعة منتظمة، فلا تتغير ما دامت القوة المحصلة صفرًا.', '["$F_{\\text{d}} \\approx 2.0$ N إلى أعلى","القوة المحصلة صفر والتسارع صفر","السرعة تبقى 15 m/s إلى أسفل","التعليل: السرعة الحدية سرعة منتظمة"]'::jsonb, '["$F_{\\text{d}} = F_g = mg = (0.20\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 1.96 \\approx 2.0\\ \\text{N}$","$F_{\\text{المحصلة}} = F_g - F_{\\text{d}} = 0$، إذن $a = 0$","السرعة منتظمة: تبقى 15 m/s"]'::jsonb, '[{"element":"القوة المعيقة واتجاهها","marks":1},{"element":"القوة المحصلة والتسارع","marks":1},{"element":"السرعة بعد 2.0 s مع التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة مع الاتجاه والتعليل"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل القوة المعيقة عند السرعة الحدية صفرًا","القول إن التسارع عند السرعة الحدية يساوي g","حساب سرعة جديدة بإضافة $gt$ بعد بلوغ السرعة الحدية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-19T07:48:34.619Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L2-O12') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

