('mcq', 2, 'شخص كتلته 75.0 kg يقف على ميزان في مصعد يهبط وتزداد سرعته بتسارع مقداره 2.00 m/s²، كما في الشكل الآتي. ما القوة التي يؤثر بها الميزان في الشخص؟ (الموجب إلى أعلى)', null, '[{"src":"qimg/phys1/c4l2-o13-elev-75-down.svg","alt":"مصعد معلّق بحبل، وفي داخله شخص يقف على ميزان موضوع على أرضية المصعد. على يسار المصعد سهم أسود رأسي إلى أعلى مكتوب عنده +y يمثل الاتجاه الموجب. على يمين المصعد سهم أحمر إلى أسفل مكتوب عنده v يمثل السرعة المتجهة، وبجانبه سهم بنفسجي إلى أسفل مكتوب عنده a يمثل التسارع."}]'::jsonb, '["585 N","885 N","735 N","150 N"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 109 — المسألة 20c'),
('mcq', 3, 'يهبط مصعد ثم يبدأ يتباطأ بمقدار 1.50 m/s² ليتوقف عند الطابق الأرضي، كما في الشكل الآتي. ما قراءة ميزان يقف عليه شخص كتلته 60.0 kg في أثناء التباطؤ؟ (الموجب إلى أعلى)', null, '[{"src":"qimg/phys1/c4l2-o13-elev-60-slow.svg","alt":"مصعد معلّق بحبل، وفي داخله شخص يقف على ميزان موضوع على أرضية المصعد. على يسار المصعد سهم أسود رأسي إلى أعلى مكتوب عنده +y يمثل الاتجاه الموجب. على يمين المصعد سهم أحمر إلى أسفل مكتوب عنده v يمثل السرعة المتجهة، وبجانبه سهم بنفسجي إلى أعلى مكتوب عنده a يمثل التسارع."}]'::jsonb, '["498 N","588 N","90.0 N","678 N"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 126 — التقويم 53e'),
('mcq', 4, 'يقف شخص كتلته 80.0 kg على ميزان في مصعد، فكانت قراءة الميزان 980 N. ما تسارع المصعد؟ (الموجب إلى أعلى)', null, null, '["$-2.45\\ \\text{m/s}^2$","$+2.45\\ \\text{m/s}^2$","$+12.3\\ \\text{m/s}^2$","$0.00\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 108 — المثال 2 (حل عكسي)'),
('mcq', 5, 'يقف طفل كتلته 40 kg على ميزان في مصعد انقطع حبله فأصبح يسقط سقوطًا حرًا. ما قراءة الميزان في أثناء السقوط؟ (أهمل مقاومة الهواء)', null, null, '["392 N","784 N","0 N","40 N"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 129 — الأسئلة الممتدة 8'),
('mcq', 6, 'يمثل المنحنى الآتي قراءة ميزان يقف عليه شخص كتلته 50.0 kg في مصعد خلال 8 s. ما تسارع المصعد في الفترة من 0 s إلى 2 s؟ (الموجب إلى أعلى)', null, '[{"src":"qimg/phys1/c4l2-o13-scale-graph.svg","alt":"منحنى باللون الأزرق؛ المحور الأفقي الزمن (s) من 0 إلى 8 بخطوة 1، والمحور الرأسي قراءة الميزان (N) من 0 إلى 700 بخطوة 100. القراءة ثابتة عند 590 N من 0 s إلى 2 s، ثم تنخفض فجأة إلى 490 N وتبقى ثابتة حتى 6 s، ثم تنخفض فجأة إلى 390 N وتبقى ثابتة حتى 8 s."}]'::jsonb, '["$-2.0\\ \\text{m/s}^2$","$+12\\ \\text{m/s}^2$","$+9.8\\ \\text{m/s}^2$","$+2.0\\ \\text{m/s}^2$"]'::jsonb, 'تحليل', 'قراءة منحنى', 'صعب', 'الكتاب ص 108 — المثال 2 — الوزن الظاهري'),
('mcq', 7, 'عُلّق جسم كتلته 2.0 kg بميزان نابضي مثبت في سقف مصعد يتسارع إلى أعلى بمقدار 1.2 m/s²، كما في الشكل الآتي. ما قراءة الميزان؟', null, '[{"src":"qimg/phys1/c4l2-o13-hang-scale.svg","alt":"مصعد معلّق بحبل، وفي سقفه من الداخل ميزان نابضي يتدلى منه صندوق. على يمين المصعد سهم بنفسجي إلى أعلى مكتوب عنده a يمثل التسارع، وعلى يساره سهم أسود إلى أعلى مكتوب عنده +y."}]'::jsonb, '["22 N","17 N","20 N","2.4 N"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 111 — المراجعة 24 (ميزان معلق في مصعد)'),
('essay', 1, 'شخص كتلته 75.0 kg يقف على ميزان في مصعد. احسب القوة التي يؤثر بها الميزان فيه في كل حالة، باعتبار الموجب إلى أعلى: (أ) يتحرك المصعد بسرعة منتظمة. (ب) يتباطأ المصعد بمقدار 2.00 m/s² في أثناء صعوده. (ج) تزداد سرعته بمقدار 2.00 m/s² في أثناء هبوطه. (د) يتحرك إلى أسفل بسرعة منتظمة. (هـ) يتباطأ بمقدار 2.00 m/s² في أثناء هبوطه حتى يتوقف.', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 109 — المسألة 20'),
('essay', 2, 'طفل كتلته 30.0 kg يقف على ميزان في مصعد. ارسم مخطط الجسم الحر للطفل، ثم صف بالكلمات والمعادلات ما يحدث لوزنه الظاهري، واحسبه في كل حالة: (أ) يتسارع المصعد إلى أعلى بمقدار 1.5 m/s². (ب) يهبط المصعد بسرعة منتظمة. (ج) يهبط المصعد في حالة سقوط حر.', null, null, null, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 129 — الأسئلة الممتدة 8'),
('essay', 3, 'ركب شخص كتلته 65.0 kg مصعدًا ساكنًا ووقف على ميزان، فلما تحرك المصعد كانت قراءة الميزان 702 N طوال أول 3.0 s. (أ) حدد اتجاه تسارع المصعد ومقداره. (ب) إذا كان المصعد قد بدأ من السكون، فما سرعته المتجهة بعد 3.0 s؟ وفي أي اتجاه يتحرك؟ (الموجب إلى أعلى)', null, null, null, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 108 — المثال 2 (تطبيق ممتد)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L2-O13') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, '$F_{\text{الميزان}} - mg = ma$، إذن $F_{\text{الميزان}} = m(a + g) = 53(2.0 + 9.80) = 625\ \text{N} \approx 6.3 \times 10^2\ \text{N}$.', '["استُخدم $m(g - a)$ كأن التسارع إلى أسفل.","هذا الوزن الحقيقي فقط؛ يصح لو كان التسارع صفرًا.","","هذه القوة المحصلة $ma$ وحدها، وقد أُهمل الوزن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-19T07:48:34.620Z"}'::jsonb),
('mcq', 2, 0, 'التسارع إلى أسفل: $\boldsymbol{a} = -2.00\ \text{m/s}^2$. $F_{\text{الميزان}} = m(g + a) = 75.0(9.80 - 2.00) = 585\ \text{N}$.', '["","استُخدم $m(g + a)$ كأن التسارع إلى أعلى.","هذا الوزن الحقيقي؛ يصح لو كانت السرعة منتظمة.","هذه القوة المحصلة $ma$ فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-19T07:48:34.620Z"}'::jsonb),
('mcq', 3, 3, 'المصعد يهبط ويتباطأ، فتسارعه إلى أعلى: $\boldsymbol{a} = +1.50\ \text{m/s}^2$. $F_{\text{الميزان}} = m(g + a) = 60.0(9.80 + 1.50) = 678\ \text{N}$.', '["استُخدم $m(g - a)$ كأن التسارع إلى أسفل لأن المصعد يهبط؛ لكن التباطؤ في الهبوط يعني تسارعًا إلى أعلى.","هذا الوزن الحقيقي؛ يصح عند التسارع الصفري فقط.","هذه القوة المحصلة $ma$ وحدها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-19T07:48:34.621Z"}'::jsonb),
('mcq', 4, 1, '$a = \frac{F_{\text{الميزان}}}{m} - g = \frac{980}{80.0} - 9.80 = 12.25 - 9.80 = +2.45\ \text{m/s}^2$، أي إلى أعلى.', '["المقدار صحيح والإشارة خطأ؛ القراءة أكبر من الوزن (784 N) فالتسارع إلى أعلى.","","قُسمت قراءة الميزان على الكتلة دون طرح $g$.","التسارع صفر فقط لو كانت القراءة تساوي الوزن (784 N)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-19T07:48:34.621Z"}'::jsonb),
('mcq', 5, 2, 'في السقوط الحر $\boldsymbol{a} = -9.80\ \text{m/s}^2$ (الموجب إلى أعلى): $F_{\text{الميزان}} = m(g + a) = 40(9.80 - 9.80) = 0\ \text{N}$.', '["هذا وزنه الحقيقي؛ يقرؤه الميزان لو كان المصعد ساكنًا أو يتحرك بسرعة منتظمة.","استُخدم $m(g + g)$ كأن التسارع إلى أعلى.","","هذا مقدار الكتلة لا قوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.621Z"}'::jsonb),
('mcq', 6, 3, '$mg = (50.0)(9.80) = 490\ \text{N}$. من المنحنى $F_{\text{الميزان}} = 590\ \text{N}$، إذن $a = \frac{590 - 490}{50.0} = +2.0\ \text{m/s}^2$.', '["القراءة (590 N) أكبر من الوزن (490 N)، فالتسارع إلى أعلى لا إلى أسفل.","قُسمت القراءة على الكتلة دون طرح $g$.","هذا مقدار تسارع الجاذبية، لا تسارع المصعد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-19T07:48:34.621Z"}'::jsonb),
('mcq', 7, 0, 'الموجب إلى أعلى: $F_{\text{الميزان}} - mg = ma$، إذن $F_{\text{الميزان}} = m(g + a) = 2.0(9.80 + 1.2) = 22\ \text{N}$.', '["","استُخدم $m(g - a)$ كأن التسارع إلى أسفل.","هذا وزن الجسم الحقيقي؛ يصح عند التسارع الصفري.","هذه القوة المحصلة $ma$ وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-11-19T07:48:34.622Z"}'::jsonb),
('essay', 1, null::int, null, null, '$F_{\text{الميزان}} = m(g + a)$: (أ) $a = 0$: 735 N. (ب) $a = -2.00$: $75.0(7.80) = 585\ \text{N}$. (ج) $a = -2.00$: 585 N. (د) $a = 0$: 735 N. (هـ) $a = +2.00$: $75.0(11.80) = 885\ \text{N}$.', '["(أ) 735 N","(ب) 585 N","(ج) 585 N","(د) 735 N","(هـ) 885 N"]'::jsonb, '["$+y$ إلى أعلى: $F_{\\text{الميزان}} - mg = ma$ $\\Leftarrow$ $F_{\\text{الميزان}} = m(g + a)$","$a = 0$: $F_{\\text{الميزان}} = (75.0)(9.80) = 735\\ \\text{N}$","$a = -2.00\\ \\text{m/s}^2$: $F_{\\text{الميزان}} = (75.0)(7.80) = 585\\ \\text{N}$","$a = +2.00\\ \\text{m/s}^2$: $F_{\\text{الميزان}} = (75.0)(11.80) = 885\\ \\text{N}$"]'::jsonb, '[{"element":"المعادلة العامة بالإشارات","marks":1},{"element":"الحالتان (أ) و(د)","marks":1},{"element":"الحالتان (ب) و(ج)","marks":1},{"element":"الحالة (هـ)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحالات الخمس صحيحة"},{"level":"2–3 درجات","description":"ثلاث حالات صحيحة على الأقل"},{"level":"درجة واحدة","description":"حالة واحدة أو المعادلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط إشارة التسارع باتجاه الحركة بدل التغير في السرعة","جعل القراءة في الهبوط المنتظم أقل من الوزن","نسيان إضافة الوزن إلى ma"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-19T07:48:34.622Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المخطط: نقطة يخرج منها $\boldsymbol{F}_{\text{الميزان}}$ إلى أعلى و$\boldsymbol{F}_g$ إلى أسفل، و$+y$ إلى أعلى. $F_{\text{الميزان}} = m(g + a)$. (أ) $a = +1.5$: $30.0(11.3) = 339\ \text{N}$، أكبر من الوزن (294 N) فيشعر أنه أثقل. (ب) $a = 0$: $F_{\text{الميزان}} = 294\ \text{N}$، يساوي وزنه. (ج) $a = -9.80$: $F_{\text{الميزان}} = 0$، ينعدم وزنه الظاهري مع أن وزنه الحقيقي 294 N.', '["مخطط جسم حر صحيح","(أ) 339 N أكبر من الوزن","(ب) 294 N يساوي الوزن","(ج) صفر"]'::jsonb, '["$mg = (30.0)(9.80) = 294\\ \\text{N}$","(أ) $F_{\\text{الميزان}} = 30.0(9.80 + 1.5) = 339\\ \\text{N}$","(ب) $F_{\\text{الميزان}} = 294\\ \\text{N}$","(ج) $F_{\\text{الميزان}} = 30.0(9.80 - 9.80) = 0$"]'::jsonb, '[{"element":"المخطط","marks":1},{"element":"الحالة (أ)","marks":1},{"element":"الحالة (ب)","marks":1},{"element":"الحالة (ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المخطط والحالات الثلاث صحيحة"},{"level":"2–3 درجات","description":"حالتان صحيحتان مع المخطط أو الحالات دون المخطط"},{"level":"درجة واحدة","description":"حالة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الوزن الظاهري أقل في الهبوط المنتظم","القول إن الوزن الحقيقي ينعدم في السقوط الحر","رسم القوة المحصلة على مخطط الجسم الحر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.622Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $mg = (65.0)(9.80) = 637\ \text{N}$. $a = \frac{702 - 637}{65.0} = +1.0\ \text{m/s}^2$، أي إلى أعلى. (ب) $v_f = v_i + at = 0 + (1.0)(3.0) = +3.0\ \text{m/s}$، أي 3.0 m/s إلى أعلى؛ فالمصعد بدأ من السكون وتسارعه إلى أعلى فهو يصعد.', '["الوزن 637 N","التسارع 1.0 m/s² إلى أعلى","السرعة 3.0 m/s إلى أعلى"]'::jsonb, '["$F_g = (65.0)(9.80) = 637\\ \\text{N}$","$a = \\frac{F_{\\text{الميزان}} - mg}{m} = \\frac{702 - 637}{65.0} = +1.0\\ \\text{m/s}^2$","$\\boldsymbol{v}_f = \\boldsymbol{v}_i + \\boldsymbol{a}t = 0 + (1.0)(3.0) = +3.0\\ \\text{m/s}$"]'::jsonb, '[{"element":"حساب الوزن","marks":1},{"element":"التسارع واتجاهه","marks":1},{"element":"السرعة واتجاه الحركة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابات صحيحة مع الاتجاهات"},{"level":"2–3 درجات","description":"التسارع صحيح مع خطأ في السرعة أو الاتجاه"},{"level":"درجة واحدة","description":"الوزن فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 702 على الكتلة دون طرح g","إهمال الاتجاه","استخدام 702 N وزنًا حقيقيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.623Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L2-O13') and x.type = v.type and x.number = v.number
