from (values
('mcq', 1, 'ما الذي يقيسه الميزان المنزلي النابضي فعليًا عندما تقف عليه؟', null, null, '["كتلتك مقيسة مباشرة بالكيلوجرام","وزنك (قوة جذب الأرض لك)","تسارعك وأنت عليه","كثافة جسمك ومادته"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 105 — الموازين'),
('mcq', 2, 'يبين مخطط الجسم الحر الآتي القوتين المؤثرتين في شخص يقف ساكنًا على ميزان منزلي. لماذا رُسم السهمان متساويين في الطول؟', null, '[{"src":"qimg/phys1/c4l2-o14-fbd-scale.svg","alt":"مخطط جسم حر: نقطة تمثل الشخص، يخرج منها سهم أزرق إلى أعلى مكتوب عنده F_sp، وسهم أزرق إلى أسفل مكتوب عنده F_g، والسهمان متساويان في الطول. على يسار الشكل سهم أسود إلى أعلى مكتوب عنده +y."}]'::jsonb, '["لأنهما زوجا تأثير متبادل حسب القانون الثالث","لأن قوة النابض تساوي كتلة الشخص","لأن الشخص لا يتسارع، فالقوة المحصلة صفر","لأن الميزان يقيس الكتلة"]'::jsonb, 'فهم', 'قراءة مخطط', 'متوسط', 'الكتاب ص 105 — الشكل 4-9'),
('mcq', 3, 'ميزان منزلي نابضي مدرّج بالكيلوجرام على سطح الأرض، نُقل إلى سطح القمر ووقف عليه الشخص نفسه. كيف تكون قراءته؟', null, null, '["أقل من قراءته على الأرض، لأن وزن الشخص أقل","مساوية لقراءته على الأرض، لأن الكتلة ثابتة","أكبر من قراءته على الأرض، لأن الشخص أخف","صفرًا، لأن القمر لا يجذب الأجسام"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 105 — الموازين — على كوكب آخر'),
('mcq', 4, 'يقف شخص ساكنًا على ميزان منزلي على سطح الأرض فيقرأ الميزان «65.0 kg». ما مقدار القوة التي يؤثر بها نابض الميزان في الشخص؟', null, null, '["65.0 N","6.63 N","0 N","637 N"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 105 — الموازين'),
('mcq', 5, 'ما الذي يحدد قراءة الميزان المنزلي النابضي؟', null, null, '["كتلة الشخص مباشرة دون أي قوة","قوة نوابضه المؤثرة في الشخص","سرعة الشخص لحظة وقوفه على الميزان","مساحة قدمي الشخص الملامسة للميزان"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 105 — الموازين'),
('mcq', 6, 'شخص كتلته 60.0 kg يقف على ميزان منزلي مدرّج بالكيلوجرام (على أساس $g = 9.80\ \text{m/s}^2$)، على سطح كوكب تسارع الجاذبية عليه 19.6 m/s². ماذا يقرأ الميزان، وما كتلة الشخص الحقيقية؟', null, null, '["يقرأ 120 kg، وكتلته 60.0 kg","يقرأ 60.0 kg، وكتلته 60.0 kg","يقرأ 120 kg، وكتلته 120 kg","يقرأ 30.0 kg، وكتلته 60.0 kg"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 105 — الموازين — على كوكب آخر'),
('mcq', 7, 'ميزان منزلي نابضي مدرّج بالكيلوجرام على أساس $g = 9.80\ \text{m/s}^2$. في أي الحالات الآتية تكون قراءته مساوية لكتلة الشخص الواقف عليه؟', null, null, '["على سطح القمر والشخص ساكن عليه","في مصعد على الأرض يتسارع إلى أعلى","على سطح الأرض والشخص ساكن عليه","في مصعد على الأرض يسقط سقوطًا حرًا"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 105 — الموازين'),
('essay', 1, 'وضّح كيف يعمل الميزان المنزلي النابضي، ولماذا نقول إنه يقيس الوزن لا الكتلة، ولماذا يُدرَّج مع ذلك بالكيلوجرام.', null, null, null, 'فهم', 'توضيح', 'سهل', 'الكتاب ص 121 — كيف يعمل الميزان المنزلي؟'),
('essay', 2, 'يقرأ ميزان منزلي مدرّج بالكيلوجرام «60.0 kg» عندما يقف عليه شخص على سطح الأرض. نُقل الميزان والشخص إلى سطح القمر ($g = 1.62\ \text{m/s}^2$). (أ) ما وزن الشخص على القمر؟ (ب) ماذا سيقرأ الميزان على القمر؟ (ج) ما كتلة الشخص الحقيقية على القمر؟ وماذا تستنتج عما يقيسه الميزان؟', null, null, null, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 105 — الموازين — على كوكب آخر'),
('essay', 3, 'في الميزان المنزلي تنقل رافعة (عتلة) وزن الشخص إلى نابض رئيس. إذا كانت أكبر قراءة على الميزان 1068 N، والنابض يؤثر بقوة أقصاها 89 N، (أ) فما النسبة التي تستعملها الرافعة؟ (ب) عند وقوف شخص ساكن على الميزان، ما العلاقة بين قوة النابض ووزنه؟', null, null, null, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 121 — كيف يعمل الميزان المنزلي؟ — التفكير الناقد 2')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L2-O14') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'قوة النابض $\boldsymbol{F}_{\text{sp}}$ التي تدفعك إلى أعلى تساوي وزنك $\boldsymbol{F}_g$، وقراءة الميزان تحددها هذه القوة؛ لذا فهو يقيس الوزن لا الكتلة.', '["الميزان يُدرَّج بالكيلوجرام لسهولة التحويل، لكنه يقيس قوة.","","أنت ساكن على الميزان، والميزان لا يقيس التسارع.","الميزان لا يقيس الكثافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-19T07:48:34.623Z"}'::jsonb),
('mcq', 2, 2, 'الشخص ساكن فتسارعه صفر، والقوة المحصلة صفر، فيكون $F_{\text{sp}} = F_g$؛ لذلك يقرأ الميزان الوزن.', '["قوة النابض والوزن تؤثران في الجسم نفسه، فليستا زوجي تأثير متبادل؛ وتساويهما سببه الاتزان.","القوة لا تساوي الكتلة؛ الكتلة تقاس بالكيلوجرام والقوة بالنيوتن.","","الميزان يقيس الوزن، والسؤال عن سبب تساوي القوتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.623Z"}'::jsonb),
('mcq', 3, 0, 'الميزان النابضي يقيس الوزن؛ وعلى القمر يكون الوزن أصغر فيكون مقدار انضغاط النابض مختلفًا (أقل) وتكون القراءة أقل، مع أن الكتلة لم تتغير.', '["","هذا يصح لو كان الميزان يقيس الكتلة، لكنه يقيس الوزن.","الشخص أخف وزنًا فينضغط النابض أقل، فتقل القراءة لا تزيد.","القمر يجذب الأجسام، لكن بقوة أصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.624Z"}'::jsonb),
('mcq', 4, 3, 'الشخص متزن، فـ $F_{\text{sp}} = F_g = mg = (65.0)(9.80) = 637\ \text{N}$.', '["هذا رقم القراءة بالكيلوجرام وليس القوة بالنيوتن.","قُسم 65.0 على 9.80 بدل الضرب.","الشخص ساكن، لكن قوة النابض لا تنعدم؛ هي تساوي وزنه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.624Z"}'::jsonb),
('mcq', 5, 1, 'تُحدَّد قراءة الميزان بواسطة القوة التي تؤثر بها نوابضه فيك، وهي تساوي وزنك عندما تكون ساكنًا وقوة الميزان هي القوة الوحيدة إلى أعلى.', '["الميزان لا يحس بالكتلة مباشرة؛ بل بالقوة التي تضغط نوابضه.","","الميزان لا يقيس السرعة.","مساحة القدمين لا تغير القوة التي يؤثر بها النابض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-19T07:48:34.624Z"}'::jsonb),
('mcq', 6, 0, 'الوزن على الكوكب $= (60.0)(19.6) = 1176\ \text{N}$؛ والميزان يحوّل القوة إلى كيلوجرام بالقسمة على 9.80، فيقرأ $\frac{1176}{9.80} = 120\ \text{kg}$. أما الكتلة الحقيقية فتبقى 60.0 kg.', '["","الميزان النابضي يقيس الوزن، والوزن هنا تضاعف فتتضاعف القراءة.","القراءة تضاعفت، لكن الكتلة لا تتغير بتغير الكوكب.","تضاعف $g$ يضاعف الوزن والقراءة، لا ينصفهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-19T07:48:34.624Z"}'::jsonb),
('mcq', 7, 2, 'قراءة الميزان تحددها قوة النابض $F_{\text{sp}}$، والميزان يقسمها على 9.80 m/s² ليعطي الكتلة. ولا تساوي القراءة الكتلة إلا إذا كانت $F_{\text{sp}} = mg$ و$g = 9.80\ \text{m/s}^2$، أي على سطح الأرض والشخص متزن.', '["وزن الشخص على القمر أصغر، فتكون قوة النابض أصغر وتقل القراءة عن كتلته.","قوة النابض هنا أكبر من وزن الشخص، فتكون القراءة أكبر من كتلته.","","قوة النابض تنعدم في السقوط الحر، فتكون القراءة صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.624Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عندما تقف على الميزان تنضغط نوابضه فتؤثر فيك بقوة $\boldsymbol{F}_{\text{sp}}$ إلى أعلى. ولأنك لا تتسارع تكون القوة المحصلة صفرًا، فتساوي $F_{\text{sp}}$ مقدار وزنك $F_g$. قراءة الميزان تحددها هذه القوة (مقدار انضغاط النابض)، لذلك فهو يقيس الوزن. ولسهولة التحويل بين الكتلة والوزن على سطح الأرض يُدرَّج بحيث يعطي الكتلة (بقسمة القوة على 9.80 m/s²)؛ لكن على كوكب آخر يختلف انضغاط النابض وتكون قراءته مختلفة.', '["انضغاط النابض يولد قوة إلى أعلى","الاتزان: $F_{\\text{sp}} = F_g$","القراءة تحددها القوة فهو يقيس الوزن","التدريج بالكيلوجرام للتسهيل ويصح على الأرض فقط"]'::jsonb, '[]'::jsonb, '[{"element":"آلية النابض","marks":1},{"element":"شرط الاتزان","marks":1},{"element":"يقيس الوزن","marks":1},{"element":"سبب التدريج بالكيلوجرام","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل صحيح"},{"level":"2–3 درجات","description":"توضيح صحيح ينقصه عنصر أو عنصران"},{"level":"درجة واحدة","description":"ذكر أنه يقيس الوزن دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إنه يقيس الكتلة لأن تدريجه بالكيلوجرام","جعل قوة النابض ووزن الشخص زوجي تأثير متبادل","إغفال شرط الاتزان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.625Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $F_g = (60.0)(1.62) = 97.2\ \text{N}$. (ب) الميزان يحول القوة إلى كيلوجرام بقسمتها على 9.80: $\frac{97.2}{9.80} = 9.92\ \text{kg}$. (ج) الكتلة الحقيقية 60.0 kg لم تتغير. الاستنتاج: الميزان النابضي يقيس الوزن (القوة)، فتتغير قراءته بتغير $g$ مع أن الكتلة ثابتة.', '["الوزن على القمر 97.2 N","قراءة الميزان 9.92 kg","الكتلة 60.0 kg","الاستنتاج: يقيس الوزن"]'::jsonb, '["$F_g = mg_{\\text{moon}} = (60.0)(1.62) = 97.2\\ \\text{N}$","القراءة $= \\frac{97.2\\ \\text{N}}{9.80\\ \\text{m/s}^2} = 9.92\\ \\text{kg}$","الكتلة ثابتة 60.0 kg"]'::jsonb, '[{"element":"الوزن على القمر","marks":1},{"element":"قراءة الميزان","marks":1},{"element":"الكتلة الحقيقية","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابات صحيحة واستنتاج صحيح"},{"level":"2–3 درجات","description":"جزءان أو ثلاثة صحيحة"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الميزان يقرأ 60.0 kg على القمر","القول إن الكتلة تصبح 9.92 kg","قسمة 60.0 على 6 دون حساب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-19T07:48:34.625Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) النسبة $= \frac{1068}{89} = 12$؛ أي أن الرافعة تجعل قوة النابض 1/12 من الوزن الواقع على الميزان. (ب) عندما تتساوى قوة النابض الناتجة عن استطالته مع ما تنقله الرافعة من الوزن $F_g$ يثبت المؤشر ويظهر الوزن على القرص؛ فالقراءة تحددها قوة النابض المتزنة مع الوزن، فالميزان يقيس الوزن.', '["النسبة 12","قوة النابض = الوزن ÷ 12","الاتزان يثبّت المؤشر ويظهر الوزن"]'::jsonb, '["$\\frac{1068\\ \\text{N}}{89\\ \\text{N}} = 12$"]'::jsonb, '[{"element":"حساب النسبة","marks":1},{"element":"العلاقة بين قوة النابض والوزن","marks":1},{"element":"ربط الاتزان بالقراءة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة صحيحة كاملة"},{"level":"درجتان","description":"النسبة صحيحة مع تفسير ناقص"},{"level":"درجة واحدة","description":"النسبة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 89 على 1068","القول إن الميزان يقيس الكتلة","إغفال دور الاتزان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.626Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L2-O14') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L2-O15'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمثل المنحنى الآتي السرعة المتجهة لجسم يسقط من السكون في الهواء، وعليه ثلاث نقاط A وB وC. عند أي نقطة تكون القوة المعيقة مساوية لوزن الجسم تقريبًا؟', null, '[{"src":"qimg/phys1/c4l2-o15-vt-points.svg","alt":"منحنى (السرعة المتجهة – الزمن) باللون الأحمر لجسم يسقط من السكون في الهواء؛ المحور الأفقي الزمن (s) من 0 إلى 10 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 25 بخطوة 5. يبدأ المنحنى من (0، 0) ويرتفع بسرعة في البداية ثم يقل ميله تدريجيًا حتى يصبح أفقيًا تقريبًا عند 20 m/s بعد نحو 8 s. على المنحنى ثلاث نقاط معلّمة: A عند 1 s (نحو 7.9 m/s)، وB عند 3 s (نحو 15.5 m/s)، وC عند 9 s (نحو 19.8 m/s)."}]'::jsonb, '["عند النقطة A","عند النقطة B","عند النقطة C","عند النقاط الثلاث"]'::jsonb, 'تحليل', 'قراءة منحنى', 'سهل', 'الكتاب ص 110 — الشكل 4-12'),
('mcq', 2, 'يمثل المنحنى الآتي السرعة المتجهة لجسم يسقط من السكون في الهواء، وعليه ثلاث نقاط K وM وN. عند أي نقطة يكون تسارع الجسم أكبر؟', null, '[{"src":"qimg/phys1/c4l2-o15-vt-accel.svg","alt":"منحنى (السرعة المتجهة – الزمن) باللون الأحمر لجسم يسقط من السكون في الهواء؛ المحور الأفقي الزمن (s) من 0 إلى 10 بخطوة 1، والمحور الرأسي السرعة المتجهة (m/s) من 0 إلى 25 بخطوة 5. يبدأ المنحنى من (0، 0) ويرتفع بسرعة في البداية ثم يقل ميله تدريجيًا حتى يصبح أفقيًا تقريبًا عند 20 m/s بعد نحو 8 s. على المنحنى ثلاث نقاط معلّمة: K عند 0.5 s (نحو 4.4 m/s)، وM عند 4 s (نحو 17.3 m/s)، وN عند 8 s (نحو 19.6 m/s)."}]'::jsonb, '["عند النقطة M","عند النقطة K","عند النقطة N","متساوٍ عند الثلاث"]'::jsonb, 'تحليل', 'قراءة منحنى', 'متوسط', 'الكتاب ص 110 — الشكل 4-12'),
('mcq', 3, 'أي التسلسلات الآتية يفسر تفسيرًا صحيحًا وصول كرة ساقطة في الهواء إلى سرعتها الحدية؟', null, null, '["تزداد السرعة ← تزداد القوة المعيقة ← تقل القوة المحصلة ← يقل التسارع حتى ينعدم","تزداد السرعة ← يقل الوزن تدريجيًا ← تقل القوة المحصلة ← يقل التسارع حتى ينعدم","تزداد السرعة ← تقل القوة المعيقة ← تزداد القوة المحصلة ← يزداد التسارع","تزداد السرعة ← تزداد القوة المعيقة ← تزداد القوة المحصلة ← يزداد التسارع"]'::jsonb, 'فهم', 'ترتيب تسلسل', 'سهل', 'الكتاب ص 110 — الشكل 4-12'),
('mcq', 4, 'مظلي يهبط بسرعته الحدية الكبيرة، ثم فتح مظلته فجأة. ماذا يحدث له مباشرة بعد فتحها؟', null, null, '["تبقى سرعته ثابتة لأنه كان يهبط بسرعته الحدية","يتسارع إلى أسفل لأن المظلة تزيد كتلته","يتحرك إلى أعلى ويرتفع في الهواء","يتباطأ لأن القوة المعيقة تصبح أكبر من وزنه"]'::jsonb, 'تحليل', 'استنتاج', 'متوسط', 'الكتاب ص 111 — المراجعة 26 (تسارع هبوط المظلي)'),
('mcq', 5, 'كرة وزنها 0.60 N تسقط في الهواء بسرعتها الحدية. ما مقدار القوة المعيقة المؤثرة فيها واتجاهها؟', null, null, '["0.60 N إلى أسفل","0.60 N إلى أعلى","0 N لأن سرعتها ثابتة","1.20 N إلى أعلى"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 110 — السرعة الحدية'),
('mcq', 6, 'يبين مخطط الجسم الحر الآتي القوتين المؤثرتين في كرة تهبط في الهواء في لحظة ما. ماذا يحدث للقوة المعيقة ولتسارع الكرة إذا استمرت في الهبوط مدة طويلة؟', null, '[{"src":"qimg/phys1/c4l2-o15-fbd-falling.svg","alt":"مخطط جسم حر: نقطة تمثل الكرة، يخرج منها سهم أزرق قصير إلى أعلى مكتوب عنده F_d، وسهم أزرق أطول منه كثيرًا إلى أسفل مكتوب عنده F_g. على يسار الشكل سهم أسود إلى أعلى مكتوب عنده +y يمثل الاتجاه الموجب."}]'::jsonb, '["تبقى القوة المعيقة ثابتة، ويبقى التسارع ثابتًا","تقل القوة المعيقة، فيزداد التسارع تدريجيًا","تزداد القوة المعيقة حتى تزيد على الوزن، فتتوقف الكرة","تزداد القوة المعيقة حتى تساوي الوزن، فيتناقص التسارع حتى ينعدم"]'::jsonb, 'تحليل', 'قراءة مخطط', 'متوسط', 'الكتاب ص 110 — الشكل 4-12'),
('mcq', 7, 'قال طالب: «تتوقف الكرة الساقطة عن التسارع لأن القوة المعيقة تصبح أكبر من وزنها». ما تقويم هذه العبارة؟', null, null, '["خاطئة؛ يتوقف التسارع حين تتساوى القوة المعيقة مع الوزن","صحيحة؛ لأن القوة المعيقة يجب أن تتغلب على الوزن","خاطئة؛ لأن الكرة الساقطة لا تتوقف عن التسارع أبدًا","صحيحة؛ لأن الوزن يقل حتى يصبح أصغر من القوة المعيقة"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 110 — الشكل 4-12'),
('essay', 1, 'أُسقطت كرة تنس طاولة من السكون في الهواء. فسّر باستخدام قانون نيوتن الثاني كيف تصل الكرة إلى سرعتها الحدية، مبينًا ما يحدث للقوة المعيقة والقوة المحصلة والتسارع في: لحظة الإفلات، وفي أثناء السقوط، وعند السرعة الحدية. ارسم مخطط الجسم الحر في كل مرحلة.', null, null, null, 'تحليل', 'تفسير', 'متوسط', 'الكتاب ص 110 — الشكل 4-12'),
('essay', 2, 'يهبط مظلي بسرعة منتظمة متخذًا هيئة الصقر المجنح. هل يتسارع المظلي بعد فتح مظلته؟ إذا كانت إجابتك نعم، ففي أي اتجاه؟ فسّر إجابتك باستخدام قوانين نيوتن، وصف حركته حتى تستقر.', null, null, null, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 111 — المراجعة 26'),
('essay', 3, 'كرة كتلتها 0.150 kg تسقط في الهواء (اعتبر الموجب إلى أسفل). (أ) في لحظة ما كان تسارعها 6.0 m/s² إلى أسفل؛ ما القوة المعيقة المؤثرة فيها في تلك اللحظة؟ (ب) ما القوة المعيقة عندما تصل إلى سرعتها الحدية؟ (ج) فسّر لماذا تكون القوة المعيقة في (ب) أكبر منها في (أ).', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 110 — السرعة الحدية والقوة المعيقة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L2-O15') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'عند C أصبح المنحنى أفقيًا تقريبًا (السرعة الحدية)، فالتسارع صفر والقوة المحصلة صفر، أي أن القوة المعيقة تساوي الوزن.', '["عند A ما زالت السرعة صغيرة، فالقوة المعيقة أصغر كثيرًا من الوزن.","عند B ما زال المنحنى يرتفع (يوجد تسارع)، فالقوة المعيقة أصغر من الوزن.","","القوة المعيقة تزداد مع السرعة، فهي مختلفة عند النقاط الثلاث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-19T07:48:34.626Z"}'::jsonb),
('mcq', 2, 1, 'التسارع هو ميل منحنى (السرعة المتجهة – الزمن). الميل أكبر عند K لأن السرعة صغيرة فالقوة المعيقة صغيرة والقوة المحصلة كبيرة، ثم يتناقص الميل مع زيادة السرعة.', '["عند M ميل المنحنى أقل منه عند K، لأن القوة المعيقة أصبحت أكبر.","","عند N يكاد الميل ينعدم، فالتسارع يقارب الصفر.","ميل المنحنى (التسارع) يتناقص من K إلى N."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-19T07:48:34.627Z"}'::jsonb),
('mcq', 3, 0, '$F_{\text{المحصلة}} = F_g - F_{\text{d}}$ (الموجب إلى أسفل): مع زيادة السرعة تزداد $F_{\text{d}}$ فتقل المحصلة ويقل التسارع، حتى تتساوى القوتان فتنعدم المحصلة والتسارع.', '["","الوزن ثابت لا يقل؛ الذي يتغير هو القوة المعيقة.","القوة المعيقة تزداد مع السرعة لا تقل.","زيادة القوة المعيقة المعاكسة للوزن تقلل القوة المحصلة لا تزيدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.627Z"}'::jsonb),
('mcq', 4, 3, 'فتح المظلة يزيد مساحة السطح فتصبح القوة المعيقة عند السرعة نفسها أكبر من الوزن، فتكون المحصلة إلى أعلى ويتباطأ؛ ومع تناقص سرعته تقل القوة المعيقة حتى تساوي وزنه من جديد عند سرعة حدية أصغر (نحو 5 m/s).', '["فتح المظلة يزيد القوة المعيقة فجأة، فتختل المساواة بين القوتين.","كتلة المظلي لا تتغير بفتح المظلة (فهي محمولة معه)؛ والذي يتغير هو القوة المعيقة التي تصبح أكبر من الوزن، فتصبح المحصلة إلى أعلى.","التسارع إلى أعلى يقلل سرعته الهابطة، لكنه لا يجعله يصعد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.627Z"}'::jsonb),
('mcq', 5, 1, 'عند السرعة الحدية القوة المحصلة صفر، فـ $F_{\text{d}} = F_g = 0.60\ \text{N}$، واتجاهها إلى أعلى معاكسًا للحركة.', '["القوة المعيقة تعاكس الحركة، والكرة تهبط، فالقوة إلى أعلى.","","السرعة الثابتة تعني محصلة صفرًا، لا قوة معيقة صفرًا؛ فالقوة المعيقة توازن الوزن.","لو كانت 1.20 N لكانت المحصلة إلى أعلى ولتباطأت الكرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.627Z"}'::jsonb),
('mcq', 6, 3, 'في هذه اللحظة $F_g > F_{\text{d}}$، فالمحصلة إلى أسفل ومقدارها $F_g - F_{\text{d}}$، فتزداد سرعة الكرة؛ ومع زيادة السرعة تزداد القوة المعيقة فيقل مقدار المحصلة ويقل التسارع، حتى تتساوى القوتان فينعدم التسارع وتهبط الكرة بسرعتها الحدية.', '["الكرة تتسارع إلى أسفل فتزداد سرعتها، فتزداد القوة المعيقة ولا تبقى ثابتة.","زيادة السرعة تزيد القوة المعيقة لا تقللها، فيقل التسارع لا يزداد.","تتوقف زيادة القوة المعيقة عند مساواتها للوزن، إذ ينعدم التسارع وتثبت السرعة؛ ولا تتوقف الكرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.627Z"}'::jsonb),
('mcq', 7, 0, 'ينعدم التسارع عندما تنعدم القوة المحصلة، أي عندما تتساوى القوة المعيقة مع الوزن؛ ولو زادت عليه لتباطأت الكرة.', '["","لو زادت القوة المعيقة على الوزن لكانت المحصلة إلى أعلى ولتباطأت الكرة، لا لتوقف تسارعها.","في الهواء تصل الكرة إلى السرعة الحدية فيتوقف تسارعها.","الوزن ثابت لا يقل في أثناء السقوط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.628Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لحظة الإفلات: السرعة صفر فالقوة المعيقة صفر، والقوة المحصلة تساوي الوزن والتسارع $g$؛ المخطط: $\boldsymbol{F}_g$ وحدها إلى أسفل. في أثناء السقوط: تزداد السرعة فتزداد $\boldsymbol{F}_{\text{d}}$ إلى أعلى، فتقل المحصلة $F_g - F_{\text{d}}$ ويقل التسارع؛ المخطط: $\boldsymbol{F}_{\text{d}}$ إلى أعلى أقصر من $\boldsymbol{F}_g$. عند السرعة الحدية: $F_{\text{d}} = F_g$، فالمحصلة صفر والتسارع صفر، وتهبط بسرعة منتظمة؛ المخطط: سهمان متساويان.', '["الإفلات: لا قوة معيقة، التسارع g","أثناء السقوط: المعيقة تزداد، المحصلة والتسارع يقلان","السرعة الحدية: القوتان متساويتان، المحصلة والتسارع صفر","ثلاثة مخططات صحيحة"]'::jsonb, '["$a = \\frac{F_g - F_{\\text{d}}}{m}$ (الموجب إلى أسفل)"]'::jsonb, '[{"element":"مرحلة الإفلات","marks":1},{"element":"مرحلة السقوط","marks":1},{"element":"مرحلة السرعة الحدية","marks":1},{"element":"المخططات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع مخططات صحيحة"},{"level":"2–3 درجات","description":"مرحلتان صحيحتان أو التفسير دون مخططات"},{"level":"درجة واحدة","description":"مرحلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القوة المعيقة أكبر من الوزن عند السرعة الحدية","رسم قوة معيقة لحظة الإفلات","القول إن الكرة تتوقف عند السرعة الحدية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.628Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نعم. قبل فتح المظلة كانت $F_{\text{d}} = F_g$ (سرعة حدية). عند فتحها تزداد القوة المعيقة فجأة لأن مساحة السطح كبرت، فتصبح $F_{\text{d}} > F_g$ والمحصلة إلى أعلى، فيتسارع إلى أعلى (أي تتناقص سرعته الهابطة) حسب قانون نيوتن الثاني. ومع تناقص سرعته تقل القوة المعيقة حتى تساوي الوزن من جديد، فتنعدم المحصلة ويهبط بسرعة حدية جديدة أصغر (نحو 5 m/s) حسب قانون نيوتن الأول.', '["نعم، يتسارع","الاتجاه إلى أعلى (تباطؤ في الهبوط)","السبب: القوة المعيقة تصبح أكبر من الوزن","يستقر عند سرعة حدية أصغر حين تتساوى القوتان"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم والاتجاه","marks":1},{"element":"تفسير نشوء المحصلة إلى أعلى","marks":1},{"element":"تناقص القوة المعيقة مع السرعة","marks":1},{"element":"الاستقرار عند سرعة حدية جديدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل صحيح"},{"level":"2–3 درجات","description":"حكم واتجاه صحيحان مع تفسير ناقص"},{"level":"درجة واحدة","description":"حكم صحيح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المظلي يصعد إلى أعلى","القول إنه لا يتسارع لأنه كان بسرعة منتظمة","جعل التسارع إلى أسفل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.628Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $F_g - F_{\text{d}} = ma$، إذن $F_{\text{d}} = m(g - a) = 0.150(9.80 - 6.0) = 0.57\ \text{N}$ إلى أعلى. (ب) عند السرعة الحدية $a = 0$: $F_{\text{d}} = mg = (0.150)(9.80) = 1.47\ \text{N}$ إلى أعلى. (ج) لأن سرعة الكرة عند السرعة الحدية أكبر منها في اللحظة (أ)، والقوة المعيقة تزداد بزيادة السرعة حتى تساوي الوزن فينعدم التسارع.', '["(أ) 0.57 N إلى أعلى","(ب) 1.47 N إلى أعلى","(ج) السرعة أكبر عند السرعة الحدية فالقوة المعيقة أكبر"]'::jsonb, '["$F_g = (0.150)(9.80) = 1.47\\ \\text{N}$","(أ) $F_{\\text{d}} = F_g - ma = 1.47 - (0.150)(6.0) = 0.57\\ \\text{N}$","(ب) $a = 0 \\Leftarrow F_{\\text{d}} = F_g = 1.47\\ \\text{N}$"]'::jsonb, '[{"element":"الجزء (أ)","marks":1},{"element":"الجزء (ب)","marks":1},{"element":"التفسير (ج)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب $F_{\\text{d}} = ma$ فقط","جمع ma مع الوزن","القول إن القوة المعيقة عند السرعة الحدية صفر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.628Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L2-O15') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L3-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما نص قانون نيوتن الثالث؟', null, null, '["تظهر القوى دائمًا في أزواج، وتؤثر قوتا كل زوج في الجسم نفسه، وهما متساويتان في المقدار ومتضادتان في الاتجاه دائمًا","تسارع الجسم يساوي القوة المحصلة المؤثرة فيه مقسومة على كتلته، ويكون في اتجاه القوة المحصلة","تظهر القوى دائمًا في أزواج، وتؤثر قوتا كل زوج في جسمين مختلفين، وهما متساويتان في المقدار ومتضادتان في الاتجاه","يبقى الجسم الساكن ساكنًا والمتحرك متحركًا بسرعة منتظمة في خط مستقيم ما لم تؤثر فيه قوة محصلة"]'::jsonb, 'تذكر', 'تذكر نص قانون', 'سهل', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 2, 'وفق قانون نيوتن الثالث، في أيّ الأجسام تؤثر قوتا زوج التأثير المتبادل الواحد؟', null, null, '["في جسمين مختلفين؛ كل قوة في أحدهما","في الجسم نفسه، وتلغي إحداهما الأخرى","في الجسم الأكبر كتلة من الجسمين فقط","في الجسم الذي بدأ بالتأثير فقط"]'::jsonb, 'تذكر', 'تذكر خاصية', 'سهل', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 3, 'ما الاسم الذي يُطلق أحيانًا على قوتي زوجي التأثير المتبادل؟', null, null, '["القوة المحصلة والقوة المعيقة","قوتا الاحتكاك السكوني والحركي","القوة العمودية وقوة الوزن","قوتا الفعل ورد الفعل"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 112 — تمييز قوى التأثير المتبادل'),
('mcq', 4, 'أكمل وفق قانون نيوتن الثالث: «القوة التي يؤثر بها الجسم A في الجسم B ............ القوة التي يؤثر بها B في A».', null, null, '["تساوي في المقدار ولها الاتجاه نفسه","تساوي في المقدار وتعاكس في الاتجاه","أكبر منها في المقدار وتعاكسها في الاتجاه","أصغر منها في المقدار ولها الاتجاه نفسه"]'::jsonb, 'تذكر', 'إكمال عبارة', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 5, 'في زوجي التأثير المتبادل، هل القوة التي يؤثر بها B في A هي سبب نشوء القوة التي يؤثر بها A في B؟', null, null, '["نعم؛ فالقوة التي تظهر أولًا هي التي تسبب الأخرى","نعم؛ لأن رد الفعل يظهر بعد الفعل بفترة زمنية قصيرة جدًا","لا؛ فالقوتان إما أن تكونا معًا وإما ألا توجدا أبدًا","لا؛ لأن إحداهما فقط حقيقية والأخرى وهمية"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 124 — دليل مراجعة الفصل (4-3)'),
('mcq', 6, 'أيّ المواقف الآتية يعبّر عنه قانون نيوتن الثالث؟', null, null, '["تستمر كرة في الحركة على أرض ملساء بسرعة منتظمة لعدم وجود قوة محصلة","يدفع سبّاح جدار المسبح بقدميه إلى الخلف، فيدفعه الجدار إلى الأمام","يزداد تسارع عربة كلما زادت القوة المحصلة المؤثرة فيها","يتسارع حجر ساقط نحو الأرض بتسارع ثابت مقداره 9.80 m/s²"]'::jsonb, 'فهم', 'تمييز تطبيق', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 7, 'على أيّ القوى ينطبق قانون نيوتن الثالث؟', null, null, '["على جميع القوى، تلامسًا كانت أم مجالًا","على قوى التلامس فقط مثل الدفع والسحب","على قوى المجال فقط مثل الجاذبية والمغناطيسية","على القوى المؤثرة في الأجسام الساكنة فقط"]'::jsonb, 'فهم', 'تعميم', 'صعب', 'الكتاب ص 112 — تمييز قوى التأثير المتبادل'),
('essay', 1, 'اكتب نص قانون نيوتن الثالث، ثم وضّحه بمثال من الحياة اليومية تحدّد فيه القوتين، والجسم الذي تؤثر فيه كل منهما، ومقارنة مقداريهما واتجاهيهما.', null, null, null, 'فهم', 'تعريف مع مثال', 'سهل', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('essay', 2, 'عندما تقرّب مغناطيسين أحدهما من الآخر تشعر بأن كلًا منهما يسحب الآخر. (أ) اكتب نص قانون نيوتن الثالث. (ب) طبّقه على المغناطيسين: قارن مقداري القوتين واتجاهيهما، وحدّد الجسم الذي تؤثر فيه كل منهما. (ج) هل يمكن أن يسحب أحد المغناطيسين الآخر دون أن يُسحب هو؟ علّل.', null, null, null, 'فهم', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 112 — تمييز قوى التأثير المتبادل'),
('essay', 3, 'قال طالب: «قوة رد الفعل تنشأ بعد قوة الفعل، وقوة الفعل هي التي تُنتجها؛ لذلك تكون قوة الفعل أكبر قليلًا». قوّم هذه العبارة مستندًا إلى نص قانون نيوتن الثالث، ثم أعد صياغتها صياغة صحيحة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 124 — دليل مراجعة الفصل (4-3)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
