select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'ينص قانون نيوتن الثالث على أن جميع القوى تظهر على شكل أزواج، وتؤثر قوتا كل زوج في جسمين مختلفين، وهما متساويتان في المقدار ومتضادتان في الاتجاه.', '["قوتا الزوج تؤثران في جسمين مختلفين لا في الجسم نفسه؛ فالقوتان المتعاكستان على الجسم نفسه ليستا زوجي تأثير متبادل.","هذا نص قانون نيوتن الثاني وليس الثالث.","","هذا نص قانون نيوتن الأول (القصور الذاتي) وليس الثالث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-19T07:48:34.629Z"}'::jsonb),
('mcq', 2, 0, 'تؤثر قوتا كل زوج في جسمين مختلفين: يؤثر A في B بقوة، ويؤثر B في A بقوة مساوية ومعاكسة.', '["","لو أثرتا في الجسم نفسه لما كانتا زوجي تأثير متبادل؛ فالقانون ينص على جسمين مختلفين.","الكتلة لا تحدد مكان تأثير القوتين؛ فكل جسم يتلقى قوة من الآخر.","لا يوجد جسم «بادئ»؛ فكل من الجسمين يؤثر في الآخر، وكل قوة تؤثر في جسم مختلف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.629Z"}'::jsonb),
('mcq', 3, 3, 'يُطلق على قوتي زوجي التأثير المتبادل أحيانًا «قوتا الفعل ورد الفعل»؛ إذ لا يمكن أن تظهر إحداهما دون الأخرى.', '["القوة المعيقة قوة يؤثر بها مائع في جسم متحرك، والمحصلة مجموع القوى؛ وليس هذا اسم زوجي التأثير المتبادل.","هذان نوعان من قوة الاحتكاك، وليسا اسمًا لزوجي التأثير المتبادل.","هاتان قوتان تؤثران عادة في الجسم نفسه، وليستا زوجي تأثير متبادل ولا تسميتهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.629Z"}'::jsonb),
('mcq', 4, 1, 'القوة التي يؤثر بها A في B تساوي في المقدار وتعاكس في الاتجاه القوة التي يؤثر بها B في A.', '["القوتان متعاكستان في الاتجاه؛ لذلك تظهر إشارة السالب في الصيغة الرياضية للقانون.","","القوتان متساويتان في المقدار دائمًا مهما اختلفت كتلتا الجسمين.","خطأ في المقدار والاتجاه معًا؛ فالقوتان متساويتان مقدارًا ومتعاكستان اتجاهًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.629Z"}'::jsonb),
('mcq', 5, 2, 'في زوجي التأثير المتبادل لا تكون إحدى القوتين سببًا في الأخرى؛ فهما إما أن تكونا معًا وإما ألا توجدا أبدًا، وكلتاهما تنتج عن التأثير المتبادل بين الجسمين.', '["لا تظهر إحداهما قبل الأخرى؛ فهما تنشآن معًا عن التأثير المتبادل نفسه.","لا توجد فترة زمنية بين القوتين؛ فهما توجدان معًا وتختفيان معًا.","","القوتان حقيقيتان كلتاهما، وكل منهما تؤثر في جسم مختلف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.630Z"}'::jsonb),
('mcq', 6, 1, 'يؤثر السبّاح في الجدار بقوة إلى الخلف، فيؤثر الجدار فيه بقوة مساوية في المقدار ومعاكسة في الاتجاه تدفعه إلى الأمام؛ قوتان في جسمين مختلفين، وهذا هو قانون نيوتن الثالث.', '["هذا تطبيق لقانون نيوتن الأول (القصور الذاتي).","","هذا تطبيق لقانون نيوتن الثاني (العلاقة بين القوة المحصلة والتسارع).","هذا وصف للسقوط الحر بتسارع الجاذبية الأرضية، ولا يصف زوجًا من القوى بين جسمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.630Z"}'::jsonb),
('mcq', 7, 0, 'ينص القانون على أن «جميع القوى» تظهر في أزواج؛ فهو ينطبق على قوى التلامس (تدافع المتزلجين) وقوى المجال (المغناطيسين، والأرض والكرة)، سواء أكانت الأجسام ساكنة أم متحركة.', '["","ينطبق أيضًا على قوى المجال؛ فالمغناطيسان يجذب كل منهما الآخر دون تلامس، والأرض والكرة يتجاذبان.","ينطبق أيضًا على قوى التلامس؛ مثل تدافع متزلجين بأيديهما.","ينطبق على الأجسام الساكنة والمتحركة والمتسارعة على حد سواء؛ فالمتزلجان يتسارعان عند التدافع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-19T07:48:34.630Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نص القانون: جميع القوى تظهر على شكل أزواج، وتؤثر قوتا كل زوج في جسمين مختلفين، وهما متساويتان في المقدار ومتضادتان في الاتجاه. مثال: عندما تدفع صديقك المتزلج إلى الأمام بيديك تؤثر فيه بقوة إلى الأمام (تؤثر في صديقك)، ويؤثر هو فيك بقوة إلى الخلف (تؤثر فيك)؛ القوتان متساويتان في المقدار ومتعاكستان في الاتجاه، لذلك تتحرك أنت إلى الخلف.', '["نص القانون كاملًا (أزواج، جسمان مختلفان، تساوٍ في المقدار، تضاد في الاتجاه)","مثال صحيح من الحياة","تحديد الجسم الذي تؤثر فيه كل قوة","مقارنة المقدارين والاتجاهين"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون","marks":2},{"element":"المثال","marks":1},{"element":"تحديد الجسم المتأثر بكل قوة","marks":1},{"element":"مقارنة المقدار والاتجاه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال أن القوتين تؤثران في جسمين مختلفين","اختيار مثال لقوتين تؤثران في الجسم نفسه مثل الوزن والقوة العمودية","القول إن القوة على الجسم الأصغر أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-19T07:48:34.630Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) جميع القوى تظهر على شكل أزواج، وتؤثر قوتا كل زوج في جسمين مختلفين، وهما متساويتان في المقدار ومتضادتان في الاتجاه. (ب) يؤثر المغناطيس الأول في الثاني بقوة نحو الأول، ويؤثر الثاني في الأول بقوة نحو الثاني؛ القوتان متساويتان في المقدار ومتعاكستان في الاتجاه، وكل منهما في مغناطيس مختلف. (ج) لا؛ لأن القوتين زوجا تأثير متبادل لا تظهر إحداهما دون الأخرى، وهذا يصح على قوى المجال كما يصح على قوى التلامس.', '["نص القانون","تساوي المقدارين وتعاكس الاتجاهين","كل قوة تؤثر في مغناطيس مختلف","لا تظهر إحدى القوتين دون الأخرى","القانون ينطبق على قوى المجال"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون","marks":1},{"element":"المقارنة","marks":1},{"element":"تحديد الجسم المتأثر","marks":1},{"element":"الإجابة عن (ج) مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الظن أن قانون نيوتن الثالث خاص بقوى التلامس","القول إن المغناطيس الأقوى يؤثر بقوة أكبر","جعل القوتين تؤثران في المغناطيس نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-19T07:48:34.630Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة في ثلاثة مواضع: (1) قوتا الفعل ورد الفعل لا تنشأ إحداهما بعد الأخرى، بل توجدان معًا وتختفيان معًا. (2) ليست إحداهما سببًا للأخرى؛ فكلتاهما تنتجان عن التأثير المتبادل (التلامس أو الجذب) بين الجسمين. (3) القوتان متساويتان في المقدار تمامًا وفق قانون نيوتن الثالث. الصياغة الصحيحة: «تظهر قوتا الفعل ورد الفعل معًا، وتؤثر كل منهما في جسم مختلف، وهما متساويتان في المقدار ومتعاكستان في الاتجاه».', '["القوتان توجدان معًا لا متعاقبتين","ليست إحداهما سببًا للأخرى","القوتان متساويتان في المقدار","صياغة صحيحة تتضمن الجسمين المختلفين والتعاكس"]'::jsonb, '[]'::jsonb, '[{"element":"نقد التعاقب الزمني","marks":1},{"element":"نقد السببية","marks":1},{"element":"نقد عدم التساوي","marks":1},{"element":"الصياغة الصحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–3 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول فكرة أن الفعل يسبق رد الفعل","نسيان تصحيح ادعاء أن قوة الفعل أكبر","إعادة صياغة لا تذكر أن القوتين تؤثران في جسمين مختلفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.630Z"}'::jsonb)
