('mcq', 1, 'يبين الشكل الآتي قوتي التأثير المتبادل عندما يدفع المتزلج A ظهر صديقه B بيديه، وقد رُسم كل جسم منفصلًا. القوتان متساويتان في المقدار ومتعاكستان في الاتجاه، فلماذا لا تلغي إحداهما الأخرى؟', null, '[{"src":"qimg/phys1/c4l3-o02-skaters.svg","alt":"شخصان واقفان على أرضية: الشخص A على اليسار والشخص B على اليمين، وبينهما مسافة. من صدر B يخرج سهم أزرق أفقي نحو اليمين مكتوب عنده F بخط عريض وحرفه السفلي «A في B». ومن صدر A يخرج سهم أزرق أفقي مساوٍ له في الطول نحو اليسار مكتوب عنده F بخط عريض وحرفه السفلي «B في A»."}]'::jsonb, '["لأن إحداهما أكبر قليلًا من الأخرى فتتغلب عليها","لأن القوتين لهما الاتجاه نفسه في الحقيقة","لأن إحداهما تظهر بعد الأخرى فلا تؤثران معًا","لأن القوتين تؤثران في جسمين مختلفين"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 112 — تمييز قوى التأثير المتبادل'),
('mcq', 2, 'يدفع متزلج A كتلته مثلا كتلة صديقه B ظهر صديقه وهما على أرضية جليدية. كيف تقارن مقدار القوة التي يؤثر بها A في B بمقدار القوة التي يؤثر بها B في A؟', null, null, '["القوتان متساويتان في المقدار","القوة التي يؤثر بها A في B أكبر؛ لأن كتلة A أكبر","القوة التي يؤثر بها B في A أكبر؛ لأن كتلة B أصغر","القوة التي يؤثر بها A في B أكبر؛ لأن A هو من بدأ الدفع"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 112 — تمييز قوى التأثير المتبادل'),
('mcq', 3, 'أيّ العبارات الآتية تصف قوتي التجاذب بين الأرض والقمر وصفًا صحيحًا؟', null, null, '["تجذب الأرض القمر بقوة أكبر من قوة جذب القمر للأرض؛ لأن كتلتها أكبر","تجذب الأرض القمر بقوة تساوي في المقدار قوة جذب القمر للأرض","يجذب القمر الأرض بقوة، لكن الأرض لا تؤثر فيه بأي قوة","القوتان متساويتان في المقدار ولهما الاتجاه نفسه"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 4, 'لماذا لا يمكن أن تظهر إحدى قوتي زوجي التأثير المتبادل دون الأخرى؟', null, null, '["لأن القوة الأولى تولّد الثانية بعد لحظة قصيرة من ظهورها","لأنهما تؤثران في الجسم نفسه فتتوازنان دائمًا","لأنهما تنتجان معًا عن التأثير المتبادل نفسه بين الجسمين","لأن كلًا منهما تساوي وزن أحد الجسمين دائمًا"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 112 — تمييز قوى التأثير المتبادل'),
('mcq', 5, 'تصطدم شاحنة كبيرة بسيارة صغيرة. كيف تقارن القوة التي تؤثر بها الشاحنة في السيارة بالقوة التي تؤثر بها السيارة في الشاحنة في أثناء التصادم؟', null, null, '["قوة الشاحنة أكبر في المقدار لأن كتلتها أكبر","قوة السيارة أكبر في المقدار لأن ضررها أكبر","متساويتان في المقدار ولهما الاتجاه نفسه","متساويتان في المقدار ومتعاكستان في الاتجاه"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 6, 'تدفع بيدك عربة نحو الشمال. ما اتجاه القوة التي تؤثر بها العربة في يدك؟', null, null, '["نحو الشمال، في اتجاه قوة يدك","نحو الجنوب، عكس اتجاه قوة يدك","رأسيًا إلى أسفل نحو الأرض","لا تؤثر العربة في يدك بأي قوة"]'::jsonb, 'تطبيق', 'تحديد اتجاه', 'سهل', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 7, 'أيّ صف مما يأتي يجمع خصائص قوتي زوجي التأثير المتبادل؟', null, null, '["متساويتان مقدارًا، متعاكستان اتجاهًا، تؤثران في الجسم نفسه","مختلفتان مقدارًا، متعاكستان اتجاهًا، تؤثران في جسمين مختلفين","متساويتان مقدارًا، متعاكستان اتجاهًا، تؤثران في جسمين مختلفين","متساويتان مقدارًا، متماثلتان اتجاهًا، تؤثران في جسمين مختلفين"]'::jsonb, 'فهم', 'تصنيف خصائص', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('essay', 1, 'يقف متزلجان A وB على أرضية جليدية ملساء، كتلة A تساوي 60 kg وكتلة B تساوي 40 kg، فيدفع A ظهر B. (أ) قارن القوة التي يؤثر بها A في B بالقوة التي يؤثر بها B في A مقدارًا واتجاهًا. (ب) حدّد الجسم الذي تؤثر فيه كل قوة. (ج) أيّ المتزلجين يكتسب تسارعًا أكبر؟ علّل دون حسابات عددية.', null, null, null, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 112 — تمييز قوى التأثير المتبادل'),
('essay', 2, 'قال صديقك: «إذا كانت قوتا الفعل ورد الفعل متساويتين ومتعاكستين دائمًا، فلا بد أن تلغي إحداهما الأخرى، ولذلك لا يمكن لأي جسم أن يتسارع». فسّر الخطأ في هذا الاستدلال، مستعينًا بمثال حصان يجر عربة.', null, null, null, 'تحليل', 'تفسير مغالطة', 'صعب', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('essay', 3, 'تصطدم شاحنة كتلتها كبيرة بسيارة صغيرة. (أ) قارن بين القوة التي تؤثر بها الشاحنة في السيارة والقوة التي تؤثر بها السيارة في الشاحنة. (ب) فسّر لماذا يكون تغير حركة السيارة أكبر كثيرًا من تغير حركة الشاحنة رغم ما توصلت إليه في (أ).', null, null, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 113 — قانون نيوتن الثالث')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
