from (values
('mcq', 1, 3, 'لا تُجمع إلا القوى المؤثرة في الجسم نفسه لإيجاد القوة المحصلة. أما قوتا زوجي التأثير المتبادل فتؤثر إحداهما في A والأخرى في B، لذلك لا تلغي إحداهما الأخرى، ويتسارع كل متزلج بالقوة المؤثرة فيه.', '["القوتان متساويتان في المقدار تمامًا؛ وسبب عدم الإلغاء أنهما في جسمين مختلفين.","القوتان متعاكستان في الاتجاه كما في الشكل.","القوتان توجدان معًا وتختفيان معًا؛ ولا تتعاقبان زمنيًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.631Z"}'::jsonb),
('mcq', 2, 0, 'وفق قانون نيوتن الثالث القوتان زوجا تأثير متبادل، فهما متساويتان في المقدار ومتعاكستان في الاتجاه، مهما كانت كتلتا المتزلجين أو أيهما بدأ الدفع.', '["","الكتلة لا تؤثر في مقداري قوتي زوجي التأثير المتبادل؛ فهما متساويتان دائمًا.","القوتان متساويتان في المقدار مهما اختلفت الكتلتان؛ الذي يختلف هو التسارع.","لا يوجد جسم بادئ؛ فالقوتان تنشآن معًا عن التلامس وتتساويان مقدارًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.631Z"}'::jsonb),
('mcq', 3, 1, 'التجاذب بين الأرض والقمر زوجا تأثير متبادل؛ فتؤثر الأرض في القمر بقوة نحو الأرض، ويؤثر القمر في الأرض بقوة نحو القمر، والقوتان متساويتان في المقدار ومتعاكستان في الاتجاه.', '["قوتا الجذب زوجا تأثير متبادل فهما متساويتان في المقدار مهما اختلفت الكتلتان.","","لا تظهر إحدى قوتي الزوج دون الأخرى؛ فإذا جذب القمر الأرض جذبته الأرض.","قوتا الزوج متعاكستان في الاتجاه: كل منهما نحو الجسم الآخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-19T07:48:34.632Z"}'::jsonb),
('mcq', 4, 2, 'كلتا القوتين تنتج عن التلامس (أو الجذب) بين الجسمين نفسيهما؛ فعندما تدفع صديقك تتلامسان فتنشأ القوتان معًا، ولا تُنتج إحداهما الأخرى.', '["لا تولّد إحداهما الأخرى ولا تتأخر عنها؛ فهما توجدان معًا.","قوتا الزوج تؤثران في جسمين مختلفين، ولا تتوازنان على جسم واحد.","","مقدار القوتين لا يساوي الوزن بالضرورة؛ فقد يكون أي مقدار بحسب التأثير بين الجسمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.632Z"}'::jsonb),
('mcq', 5, 3, 'قوتا التصادم زوجا تأثير متبادل، فهما متساويتان في المقدار ومتعاكستان في الاتجاه، وكل منهما تؤثر في جسم مختلف؛ ويختلف أثرهما (التسارع) لاختلاف الكتلتين.', '["القوتان زوجا تأثير متبادل فهما متساويتان؛ أما تسارع السيارة فأكبر لأن كتلتها أصغر.","الضرر الأكبر للسيارة سببه تسارعها الأكبر (كتلتها أصغر)، لا قوة أكبر.","القوتان متعاكستان في الاتجاه: الشاحنة تدفع السيارة إلى الأمام، والسيارة تدفع الشاحنة إلى الخلف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-19T07:48:34.632Z"}'::jsonb),
('mcq', 6, 1, 'القوة التي تؤثر بها العربة في يدك تشكل مع قوة يدك في العربة زوجي تأثير متبادل؛ فهي مساوية لها في المقدار ومعاكسة لها في الاتجاه، أي نحو الجنوب.', '["هذا اتجاه القوة التي تؤثر بها يدك في العربة؛ أما قوة العربة في يدك فمعاكسة لها.","","قوة رد الفعل على امتداد قوة الفعل نفسها وتعاكسها، فلا تكون رأسية هنا.","لا تظهر قوة دون زوجها؛ فالعربة تؤثر في يدك بقوة مساوية ومعاكسة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.632Z"}'::jsonb),
('mcq', 7, 2, 'خصائص قوتي زوجي التأثير المتبادل ثلاث: التساوي في المقدار، والتعاكس في الاتجاه، والتأثير في جسمين مختلفين.', '["قوتا الزوج لا تؤثران في الجسم نفسه؛ وهذا وصف لقوتين متوازنتين على جسم واحد.","قوتا الزوج متساويتان في المقدار دائمًا.","","قوتا الزوج متعاكستان في الاتجاه لا متماثلتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.632Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) القوتان زوجا تأثير متبادل: متساويتان في المقدار ومتعاكستان في الاتجاه؛ فإذا دُفع B إلى الأمام دُفع A إلى الخلف. (ب) القوة التي يؤثر بها A في B تؤثر في B، والقوة التي يؤثر بها B في A تؤثر في A. (ج) يكتسب B تسارعًا أكبر؛ لأن القوتين متساويتان في المقدار، ووفق قانون نيوتن الثاني ($a = \frac{F}{m}$) يكون التسارع أكبر للكتلة الأصغر.', '["تساوي المقدارين","تعاكس الاتجاهين","كل قوة في جسم مختلف مع التحديد","B يكتسب تسارعًا أكبر","التعليل بقانون نيوتن الثاني"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة مقدارًا واتجاهًا","marks":2},{"element":"تحديد الجسم المتأثر","marks":1},{"element":"تحديد الأكبر تسارعًا","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن A يؤثر بقوة أكبر لأن كتلته أكبر","الخلط بين تساوي القوتين وتساوي التسارعين","نسيان أن A يتحرك إلى الخلف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.633Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطأ أن صديقك جمع قوتين تؤثران في جسمين مختلفين. القوة المحصلة لجسم ما هي مجموع القوى المؤثرة فيه هو فقط. فالحصان يؤثر في العربة بقوة إلى الأمام، والعربة تؤثر في الحصان بقوة مساوية إلى الخلف؛ القوة الأولى تؤثر في العربة والثانية في الحصان، فلا تلغي إحداهما الأخرى. تتسارع العربة إذا كانت القوة التي يؤثر بها الحصان فيها أكبر من قوة الاحتكاك المؤثرة فيها، ويتسارع الحصان إذا كانت القوة التي تدفعه بها الأرض إلى الأمام أكبر من القوة التي تؤثر بها العربة فيه.', '["تحديد الخطأ: جمع قوتين في جسمين مختلفين","القوة المحصلة تُحسب من القوى المؤثرة في الجسم نفسه فقط","تطبيق ذلك على الحصان والعربة","تحديد ما يحدد تسارع العربة"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الخطأ","marks":2},{"element":"مفهوم القوة المحصلة","marks":1},{"element":"المثال وتحديد القوى","marks":1},{"element":"ما يحدد التسارع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن قوة الحصان أكبر من قوة العربة فيه","جمع قوتي الزوج في مخطط جسم حر واحد","إغفال قوى الاحتكاك والأرض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.633Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) القوتان زوجا تأثير متبادل، فهما متساويتان في المقدار ومتعاكستان في الاتجاه، وتؤثر إحداهما في السيارة والأخرى في الشاحنة. (ب) وفق قانون نيوتن الثاني يتناسب التسارع عكسيًا مع الكتلة عند القوة نفسها؛ وبما أن كتلة السيارة أصغر كثيرًا، فإن تسارعها (تغير سرعتها المتجهة) أكبر كثيرًا من تسارع الشاحنة.', '["تساوي القوتين مقدارًا","تعاكسهما اتجاهًا","كل قوة في جسم مختلف","التسارع يتناسب عكسيًا مع الكتلة","السيارة الأصغر كتلة أكبر تسارعًا"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) المقارنة","marks":2},{"element":"(ب) تطبيق قانون نيوتن الثاني","marks":2},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن قوة الشاحنة أكبر","الخلط بين القوة والتسارع","تجاهل أن القوتين في جسمين مختلفين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-19T07:48:34.633Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
