('mcq', 2, 'ماذا تعني إشارة السالب في العلاقة $\boldsymbol{F}_{\text{A في B}} = -\boldsymbol{F}_{\text{B في A}}$؟', null, null, '["أن القوتين متعاكستان في الاتجاه","أن مقدار القوة الثانية أصغر من مقدار الأولى","أن القوة الثانية قوة معيقة تقاوم الحركة","أن القوة الأولى تتجه نحو اليسار دائمًا"]'::jsonb, 'فهم', 'تفسير رمز', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 3, 'ماذا يمثل الرمز $\boldsymbol{F}_{\text{A في B}}$؟', null, null, '["القوة التي يؤثر بها الجسم B في الجسم A","القوة المحصلة المؤثرة في الجسمين A وB معًا","وزن الجسم A مضافًا إليه وزن الجسم B","القوة التي يؤثر بها الجسم A في الجسم B"]'::jsonb, 'تذكر', 'تفسير رمز', 'سهل', 'الكتاب ص 112 — تمييز قوى التأثير المتبادل'),
('mcq', 4, 'يبيّن الشكل الآتي جسمين A وB رُسم كل منهما منفصلًا، والقوة التي يؤثر بها A في B مقدارها 24 N في الاتجاه الموجب ($+x$ نحو اليمين). ما القوة التي يؤثر بها B في A؟', null, '[{"src":"qimg/phys1/c4l3-o03-pair.svg","alt":"جسمان مستطيلان على أرضية أفقية: A على اليسار وB على اليمين وبينهما مسافة. من الجانب الأيمن للجسم B يخرج سهم أزرق نحو اليمين مكتوب عنده F بخط عريض وحرفه السفلي «A في B» = 24 N. وفوق الجسم A مكتوب F بخط عريض وحرفه السفلي «B في A» = ؟ دون سهم. وفي أسفل الشكل سهم نحو اليمين مكتوب عنده +x."}]'::jsonb, '["$+24\\ \\text{N}$","$-48\\ \\text{N}$","$-24\\ \\text{N}$","$0\\ \\text{N}$"]'::jsonb, 'تطبيق', 'تطبيق صيغة', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 5, 'لماذا يُكتب الرمزان في العلاقة $\boldsymbol{F}_{\text{A في B}} = -\boldsymbol{F}_{\text{B في A}}$ بخط عريض؟', null, null, '["لأنهما كميتان متجهتان","لأنهما أكبر القوى المؤثرة في الجسمين","لأنهما قوتا تلامس لا قوتا مجال","لأنهما تُقاسان بوحدة النيوتن N"]'::jsonb, 'فهم', 'تفسير رمز', 'سهل', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 6, 'رُمز إلى طاولة بالحرف A وإلى كرة ساكنة عليها بالحرف B. أيّ العلاقات الآتية تربط القوة التي تؤثر بها الطاولة في الكرة بالقوة التي تؤثر بها الكرة في الطاولة؟', null, null, '["$\\boldsymbol{F}_{\\text{A في B}} = \\boldsymbol{F}_{\\text{B في A}}$","$\\boldsymbol{F}_{\\text{A في B}} = -\\boldsymbol{F}_{g}$","$\\boldsymbol{F}_{\\text{B في A}} = m_{\\text{B}}\\boldsymbol{a}$","$\\boldsymbol{F}_{\\text{A في B}} = -\\boldsymbol{F}_{\\text{B في A}}$"]'::jsonb, 'تطبيق', 'اختيار علاقة', 'صعب', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 7, 'أيّ العلاقات الآتية صحيحة بين مقداري قوتي زوجي التأثير المتبادل بين جسمين A وB، كتلة A ثلاثة أمثال كتلة B؟', null, null, '["$F_{\\text{A في B}} = 3F_{\\text{B في A}}$","$F_{\\text{A في B}} = F_{\\text{B في A}}$","$F_{\\text{B في A}} = 3F_{\\text{A في B}}$","$F_{\\text{A في B}} = \\frac{1}{3}F_{\\text{B في A}}$"]'::jsonb, 'فهم', 'تطبيق صيغة', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('essay', 1, 'اكتب الصيغة الرياضية لقانون نيوتن الثالث، ثم وضّح: (أ) معنى كل رمز فيها. (ب) معنى إشارة السالب. (ج) لماذا يُكتب رمزا القوتين بخط عريض.', null, null, null, 'تذكر', 'كتابة صيغة وتفسيرها', 'سهل', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('essay', 2, 'دفعتَ (A) صديقك (B) وأنتما على أرضية جليدية بقوة مقدارها 40 N نحو الشرق. اعتبر الشرق هو الاتجاه الموجب. (أ) اكتب العلاقة الرياضية لقانون نيوتن الثالث بين القوتين. (ب) احسب القوة التي يؤثر بها صديقك فيك بإشارتها، وصف اتجاهها. (ج) في أيّ الجسمين تؤثر كل قوة؟', null, null, null, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('essay', 3, 'تفاحة (A) معلقة ساكنة بغصن شجرة، والأرض (B) تجذبها بقوة مقدارها 1.5 N. اختر الاتجاه الموجب إلى أعلى. (أ) اكتب القوة التي تؤثر بها الأرض في التفاحة بإشارتها. (ب) استخدم قانون نيوتن الثالث لإيجاد القوة التي تؤثر بها التفاحة في الأرض بإشارتها. (ج) هل تشكّل قوة شد الغصن للتفاحة مع وزنها زوجي تأثير متبادل؟ علّل.', null, null, null, 'تحليل', 'حساب وتعليل', 'صعب', 'الكتاب ص 113 — قانون نيوتن الثالث')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
