select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الصيغة الرياضية لقانون نيوتن الثالث: $\boldsymbol{F}_{\text{A في B}} = -\boldsymbol{F}_{\text{B في A}}$؛ أي أن القوة التي يؤثر بها A في B تساوي في المقدار وتعاكس في الاتجاه القوة التي يؤثر بها B في A.', '["هذه تجعل القوتين في الاتجاه نفسه؛ والصحيح وجود إشارة السالب لأنهما متعاكستان.","","هذه صيغة قانون نيوتن الثاني.","هذه علاقة قوة الجاذبية الأرضية (الوزن) بالكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.634Z"}'::jsonb),
('mcq', 2, 0, 'إشارة السالب تدل على أن القوة التي يؤثر بها A في B معاكسة في الاتجاه للقوة التي يؤثر بها B في A، مع تساويهما في المقدار.', '["","القوتان متساويتان في المقدار؛ والإشارة تدل على الاتجاه لا على المقدار.","القوة المعيقة يؤثر بها مائع في جسم متحرك؛ ولا علاقة لها بالإشارة هنا.","الإشارة تدل على أن القوتين متعاكستان، لا على اتجاه ثابت لإحداهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.634Z"}'::jsonb),
('mcq', 3, 3, 'يُقرأ الرمز «القوة التي يؤثر بها A في B»: الجسم A هو المؤثِّر، والجسم B هو الذي تؤثر فيه القوة.', '["هذه القوة رمزها $\\boldsymbol{F}_{\\text{B في A}}$؛ فالحرف الأول في الرمز هو المؤثِّر والثاني هو المتأثِّر.","الرمز يمثل قوة واحدة من جسم في آخر، وليس قوة محصلة.","الرمز لا يمثل وزنًا؛ بل القوة التي يؤثر بها A في B.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.634Z"}'::jsonb),
('mcq', 4, 2, 'وفق $\boldsymbol{F}_{\text{A في B}} = -\boldsymbol{F}_{\text{B في A}}$ تكون $\boldsymbol{F}_{\text{B في A}} = -(+24\ \text{N}) = -24\ \text{N}$، أي 24 N نحو اليسار.', '["القوتان متعاكستان في الاتجاه، فإذا كانت إحداهما موجبة كانت الأخرى سالبة.","القوتان متساويتان في المقدار؛ لا تتضاعف القوة.","","لا تظهر إحدى قوتي الزوج دون الأخرى؛ فالجسم B يؤثر في A حتمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.635Z"}'::jsonb),
('mcq', 5, 0, 'القوة كمية متجهة لها مقدار واتجاه، لذلك يُكتب رمزها بخط عريض؛ والعلاقة تقارن متجهين متساويين مقدارًا ومتعاكسين اتجاهًا.', '["","الخط العريض يدل على أن الكمية متجهة، ولا علاقة له بمقدار القوة.","القانون ينطبق على قوى التلامس والمجال، والخط العريض يدل على الكمية المتجهة.","جميع القوى تقاس بالنيوتن، والخط العريض لا يدل على الوحدة بل على أن الكمية متجهة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.635Z"}'::jsonb),
('mcq', 6, 3, 'القوة التي تؤثر بها الطاولة (A) في الكرة (B) والقوة التي تؤثر بها الكرة في الطاولة زوجا تأثير متبادل، فترتبطان بالعلاقة $\boldsymbol{F}_{\text{A في B}} = -\boldsymbol{F}_{\text{B في A}}$.', '["القوتان متعاكستان في الاتجاه، فلا بد من إشارة السالب.","هذه علاقة اتزان الكرة بين القوة العمودية ووزنها (قوتان على الجسم نفسه)، وليست علاقة قانون نيوتن الثالث بين الطاولة والكرة.","هذه صيغة من قانون نيوتن الثاني، ولا تربط قوتي الزوج.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.635Z"}'::jsonb),
('mcq', 7, 1, 'من $\boldsymbol{F}_{\text{A في B}} = -\boldsymbol{F}_{\text{B في A}}$ يكون مقدارا القوتين متساويين دائمًا: $F_{\text{A في B}} = F_{\text{B في A}}$، والكتلة تؤثر في التسارع لا في مقدار قوتي الزوج.', '["مقدارا قوتي الزوج متساويان مهما كانت نسبة الكتلتين.","","الكتلة الأصغر لا تجعل قوتها أكبر؛ المقداران متساويان.","نسبة الكتلتين لا تظهر في قانون نيوتن الثالث؛ المقداران متساويان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.635Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الصيغة: $\boldsymbol{F}_{\text{A في B}} = -\boldsymbol{F}_{\text{B في A}}$. (أ) $\boldsymbol{F}_{\text{A في B}}$ القوة التي يؤثر بها الجسم A في الجسم B، و$\boldsymbol{F}_{\text{B في A}}$ القوة التي يؤثر بها B في A. (ب) إشارة السالب تعني أن القوتين متعاكستان في الاتجاه مع تساويهما في المقدار. (ج) لأن القوة كمية متجهة لها مقدار واتجاه.', '["الصيغة صحيحة","معنى الرمزين (المؤثر والمتأثر)","معنى إشارة السالب","سبب الخط العريض"]'::jsonb, '[]'::jsonb, '[{"element":"الصيغة","marks":1},{"element":"معنى الرمزين","marks":1},{"element":"إشارة السالب","marks":1},{"element":"الخط العريض","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–3 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حذف إشارة السالب","تبديل المؤثر والمتأثر في قراءة الرمز","تفسير إشارة السالب بأن إحدى القوتين أصغر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.636Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $\boldsymbol{F}_{\text{A في B}} = -\boldsymbol{F}_{\text{B في A}}$. (ب) $\boldsymbol{F}_{\text{A في B}} = +40\ \text{N}$، إذن $\boldsymbol{F}_{\text{B في A}} = -(+40\ \text{N}) = -40\ \text{N}$، أي 40 N نحو الغرب. (ج) القوة $\boldsymbol{F}_{\text{A في B}}$ تؤثر في صديقك B، والقوة $\boldsymbol{F}_{\text{B في A}}$ تؤثر فيك أنت A.', '["كتابة العلاقة","التعويض بالإشارة الصحيحة","الناتج −40 N","الاتجاه نحو الغرب","تحديد الجسم المتأثر بكل قوة"]'::jsonb, '["$\\boldsymbol{F}_{\\text{A في B}} = +40\\ \\text{N}$","$\\boldsymbol{F}_{\\text{B في A}} = -\\boldsymbol{F}_{\\text{A في B}} = -(+40\\ \\text{N})$","$\\boldsymbol{F}_{\\text{B في A}} = -40\\ \\text{N}$، أي 40 N نحو الغرب"]'::jsonb, '[{"element":"العلاقة","marks":1},{"element":"التعويض والناتج بالإشارة","marks":2},{"element":"الاتجاه","marks":1},{"element":"تحديد الجسم المتأثر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الناتج +40 N","جعل مقدار القوة 80 N","القول إن القوتين تؤثران في الصديق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.636Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $\boldsymbol{F}_{\text{B في A}} = -1.5\ \text{N}$ (إلى أسفل). (ب) $\boldsymbol{F}_{\text{A في B}} = -\boldsymbol{F}_{\text{B في A}} = -(-1.5\ \text{N}) = +1.5\ \text{N}$، أي 1.5 N إلى أعلى نحو التفاحة. (ج) لا؛ لأن قوة الغصن والوزن تؤثران في الجسم نفسه (التفاحة)، أما قوتا الزوج فتؤثران في جسمين مختلفين.', '["قوة الأرض في التفاحة −1.5 N","تطبيق الصيغة","قوة التفاحة في الأرض +1.5 N إلى أعلى","الشد والوزن ليسا زوجًا لأنهما في الجسم نفسه"]'::jsonb, '["$\\boldsymbol{F}_{\\text{B في A}} = -1.5\\ \\text{N}$","$\\boldsymbol{F}_{\\text{A في B}} = -\\boldsymbol{F}_{\\text{B في A}} = -(-1.5\\ \\text{N}) = +1.5\\ \\text{N}$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب) التطبيق والناتج","marks":2},{"element":"(ج) الحكم والتعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان إشارة السالب عند كتابة قوة الأرض في التفاحة","القول إن التفاحة لا تؤثر في الأرض لأنها لا تلامسها","اعتبار الشد والوزن زوجي تأثير متبادل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.636Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L3-O03') and x.type = v.type and x.number = v.number
