insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L3-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبيّن الشكل الآتي كرة على طاولة موضوعة على الأرض، وقد رُسم كل جسم منفصلًا مع أسهم مرقمة للقوى المؤثرة فيه. السهم 1 يمثل القوة التي تؤثر بها الطاولة في الكرة، والسهم 4 القوة التي تؤثر بها الأرضية في الطاولة، والسهم 5 وزن الطاولة. أيّ الأسهم يشكل مع السهم 1 زوجي تأثير متبادل؟', null, '[{"src":"qimg/phys1/c4l3-o04-ball-table.svg","alt":"ثلاثة أجسام مرسومة منفصلة من أعلى إلى أسفل: كرة صفراء، ثم طاولة، ثم جزء من سطح الأرض مكتوب عليه «الأرض». من أعلى الكرة سهم أزرق إلى أعلى رقمه 1، ومن أسفلها سهم أزرق إلى أسفل رقمه 2. ومن منتصف سطح الطاولة سهم أزرق إلى أسفل رقمه 3، ومن الطرف الأيسر لسطح الطاولة سهم أزرق إلى أعلى رقمه 4، ومن أسفل الرجل اليمنى للطاولة سهم أزرق إلى أسفل رقمه 5."}]'::jsonb, '["السهم 2","السهم 3","السهم 4","السهم 5"]'::jsonb, 'تطبيق', 'تحديد زوج من شكل', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 2, 'تمسك كتابًا ساكنًا بيدك. ما القوة التي تشكل زوجي تأثير متبادل مع القوة التي تؤثر بها يدك في الكتاب إلى أعلى؟', null, null, '["القوة التي يؤثر بها الكتاب في يدك إلى أسفل","قوة جذب الأرض للكتاب المتجهة إلى أسفل","قوة جذب الكتاب للأرض إلى أعلى","القوة التي تؤثر بها الأرض في يدك رأسيًا إلى أسفل"]'::jsonb, 'تطبيق', 'تحديد زوج', 'سهل', 'الكتاب ص 120 — مراجعة 4-3'),
('mcq', 3, 'كرة قدم ساكنة على طاولة. ما القوة التي تشكل زوجي تأثير متبادل مع قوة جذب الأرض للكرة (وزن الكرة)؟', null, null, '["القوة التي تؤثر بها الطاولة في الكرة إلى أعلى","القوة التي تؤثر بها الكرة في الطاولة إلى أسفل","قوة جذب الأرض للطاولة إلى أسفل","قوة جذب الكرة للأرض إلى أعلى"]'::jsonb, 'تطبيق', 'تحديد زوج', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 4, 'عندما تمشي تدفع الأرض بقدمك إلى الخلف. ما القوة التي تؤثر فيك فتدفعك إلى الأمام؟', null, null, '["القوة التي تؤثر بها قدمك في الأرض إلى الخلف","وزنك المؤثر فيك إلى أسفل","القوة التي تؤثر بها الأرض في قدمك إلى الأمام","القوة العمودية التي تؤثر بها الأرض فيك إلى أعلى"]'::jsonb, 'تطبيق', 'تطبيق في الحياة', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 5, 'تسقط طوبة من فوق سقالة بناء (أهمل مقاومة الهواء). أيّ العبارات الآتية تصف القوى المؤثرة في الطوبة والقوى التي تؤثر بها الطوبة وصفًا صحيحًا؟', null, null, '["تجذب الأرض الطوبة إلى أسفل، ولا تؤثر الطوبة في الأرض لعدم التلامس","تجذب الأرض الطوبة إلى أسفل، وتجذب الطوبة الأرض إلى أعلى بقوة مساوية","يؤثر الهواء في الطوبة بقوة إلى أعلى تساوي وزنها","تجذب الأرض الطوبة إلى أسفل، وتجذب الطوبة الأرض بقوة أصغر لأن كتلتها أصغر"]'::jsonb, 'تطبيق', 'تحديد قوى وأزواج', 'متوسط', 'الكتاب ص 115 — مسائل تدريبية 28–31'),
('mcq', 6, 'وُضعت حقيبة سفر على عربة أمتعة ساكنة. أيّ الأزواج الآتية زوجا تأثير متبادل؟', null, null, '["قوة العربة في الحقيبة إلى أعلى، ووزن الحقيبة المتجه إلى أسفل","وزن الحقيبة إلى أسفل، ووزن العربة إلى أسفل","قوة الحقيبة في العربة إلى أسفل، وقوة الأرض في العربة المتجهة إلى أعلى","قوة العربة في الحقيبة إلى أعلى، وقوة الحقيبة في العربة إلى أسفل"]'::jsonb, 'تطبيق', 'تحديد زوج', 'سهل', 'الكتاب ص 115 — مسائل تدريبية 28–31'),
('mcq', 7, 'ترفع بيدك كرة بولنج وتُكسبها تسارعًا إلى أعلى. أيّ العبارات الآتية تصف القوة التي تؤثر بها الكرة في يدك؟', null, null, '["قوة إلى أسفل تساوي وزن الكرة فقط","قوة إلى أعلى تساوي في المقدار القوة التي تؤثر بها يدك في الكرة","قوة إلى أسفل تساوي في المقدار القوة التي تؤثر بها يدك في الكرة","قوة إلى أسفل أصغر من قوة يدك في الكرة؛ لأن الكرة تتسارع إلى أعلى"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 115 — مسائل تدريبية 28–31'),
('essay', 1, 'مُدّ ذراعك أمامك في الهواء، وأسند كتابًا إلى راحة يدك بحيث يكون مستقرًا. (أ) حدّد القوى المؤثرة في الكتاب، ومسبب كل منها. (ب) حدّد زوج التأثير المتبادل لكل قوة من هذه القوى، والجسم الذي يؤثر فيه.', null, null, null, 'تطبيق', 'تحديد قوى وأزواج', 'متوسط', 'الكتاب ص 120 — مراجعة 4-3'),
('essay', 2, 'قذفت كرة رأسيًا إلى أعلى، وهي الآن في أثناء صعودها (أهمل مقاومة الهواء). (أ) حدّد القوى المؤثرة في الكرة وارسم مخطط الجسم الحر لها. (ب) حدّد القوى التي تؤثر بها الكرة، والأجسام التي تؤثر فيها هذه القوى. (ج) هل تؤثر يدك في الكرة بعد أن تفارقها؟ علّل.', null, null, null, 'تحليل', 'تحديد قوى وأزواج', 'صعب', 'الكتاب ص 115 — مسائل تدريبية 28–31'),
('essay', 3, 'يدفع الطالب A زميله B وهما يرتديان حذاءَي التزلج، فيتحرك B إلى الأمام ويتحرك A إلى الخلف. (أ) حدّد زوجي التأثير المتبادل الأفقيين، واكتب رمز كل منهما. (ب) ارسم لكل طالب مخطط جسم حر أفقي مستقلًا يبين القوة المؤثرة فيه. (ج) فسّر لماذا يتحرك A إلى الخلف مع أنه هو الذي دفع.', null, null, null, 'تطبيق', 'تمثيل وتفسير', 'متوسط', 'الكتاب ص 112 — تمييز قوى التأثير المتبادل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L3-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'زوج القوة التي تؤثر بها الطاولة في الكرة إلى أعلى هو القوة التي تؤثر بها الكرة في الطاولة إلى أسفل؛ تؤثر في جسم مختلف (الطاولة) وتعاكسها، وهي السهم 3.', '["السهم 2 وزن الكرة، وهو يؤثر في الكرة نفسها؛ وقوتا الزوج لا تؤثران في الجسم نفسه.","","السهم 4 قوة الأرضية في الطاولة، وهي من تفاعل الطاولة مع الأرض لا مع الكرة، واتجاهها مماثل للسهم 1.","السهم 5 وزن الطاولة (تفاعل الأرض والطاولة)، وليس قوة الكرة في الطاولة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.637Z"}'::jsonb),
('mcq', 2, 0, 'زوج «اليد في الكتاب» هو «الكتاب في اليد»: الجسمان نفساهما بترتيب معكوس، والقوة مساوية في المقدار ومعاكسة في الاتجاه (إلى أسفل).', '["","هذه القوة تؤثر في الكتاب نفسه؛ فهي توازن قوة اليد ولا تشكل معها زوجًا.","هذه زوج وزن الكتاب (تفاعل الكتاب والأرض) لا زوج قوة اليد.","هذه من تفاعل يدك مع الأرض، وليست من تفاعل يدك مع الكتاب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.637Z"}'::jsonb),
('mcq', 3, 3, 'الوزن هو قوة الأرض في الكرة، وزوجه قوة الكرة في الأرض: تجذب الكرة الأرض إلى أعلى بقوة مساوية في المقدار.', '["هذه قوة تؤثر في الكرة نفسها؛ فهي توازن الوزن ولا تشكل معه زوجًا.","هذه زوج القوة العمودية (تفاعل الكرة والطاولة) لا زوج الوزن.","هذا وزن الطاولة، من تفاعل الأرض والطاولة لا الأرض والكرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.637Z"}'::jsonb),
('mcq', 4, 2, 'تدفع قدمك الأرض إلى الخلف، فتؤثر الأرض في قدمك بقوة مساوية ومعاكسة إلى الأمام؛ وهذه القوة المؤثرة فيك هي التي تحركك إلى الأمام.', '["هذه القوة تؤثر في الأرض لا فيك؛ فلا يمكن أن تحركك.","الوزن رأسي إلى أسفل، فلا يدفعك أفقيًا إلى الأمام.","","القوة العمودية رأسية إلى أعلى، ولا تدفعك إلى الأمام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.637Z"}'::jsonb),
('mcq', 5, 1, 'القوة الوحيدة المؤثرة في الطوبة وزنها (جذب الأرض لها إلى أسفل)، وتؤثر الطوبة في الأرض بقوة جذب مساوية في المقدار إلى أعلى؛ وهذان زوجا تأثير متبادل.', '["الجاذبية قوة مجال لا تحتاج إلى تلامس، وتظهر في زوج كغيرها.","","طُلب إهمال مقاومة الهواء، ولو وجدت لما ساوت الوزن لأن الطوبة تتسارع.","قوتا الزوج متساويتان في المقدار مهما اختلفت الكتلتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.638Z"}'::jsonb),
('mcq', 6, 3, 'قوتا الزوج تنتجان عن تفاعل الجسمين نفسيهما وتؤثر كل منهما في أحدهما: العربة تدفع الحقيبة إلى أعلى، والحقيبة تدفع العربة إلى أسفل بقوة مساوية.', '["القوتان تؤثران في الحقيبة نفسها؛ فهما متوازنتان وليستا زوجًا.","القوتان في الاتجاه نفسه وفي جسمين لا يتفاعلان بهما؛ كل منهما من تفاعل مع الأرض.","القوتان تؤثران في العربة نفسها، وليستا من تفاعل جسمين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.638Z"}'::jsonb),
('mcq', 7, 2, 'القوتان «اليد في الكرة» و«الكرة في اليد» زوجا تأثير متبادل، فهما متساويتان مقدارًا ومتعاكستان اتجاهًا دائمًا حتى لو تسارعت الكرة؛ وتسارع الكرة إلى أعلى يعني أن قوة اليد فيها أكبر من وزنها.', '["لأن الكرة تتسارع إلى أعلى تكون قوة اليد فيها أكبر من وزنها، وقوة الكرة في اليد تساوي قوة اليد لا الوزن.","قوة الكرة في اليد تعاكس قوة اليد في الكرة، فهي إلى أسفل.","","تسارع الكرة سببه أن قوة اليد أكبر من وزن الكرة، لا أن قوتي الزوج غير متساويتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.638Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) يؤثر في الكتاب قوتان: وزنه $\boldsymbol{F}_{g}$ إلى أسفل ومسببه جذب الأرض، والقوة العمودية $\boldsymbol{F}_{\text{N}}$ التي تؤثر بها اليد فيه إلى أعلى ومسببها التلامس مع اليد. (ب) زوج الوزن: قوة جذب الكتاب للأرض إلى أعلى وتؤثر في الأرض. زوج قوة اليد في الكتاب: قوة الكتاب في اليد إلى أسفل وتؤثر في اليد. وكل زوج متساوي المقدار ومتعاكس الاتجاه.', '["الوزن ومسببه","القوة العمودية من اليد ومسببها","زوج الوزن: الكتاب يجذب الأرض إلى أعلى","زوج قوة اليد: الكتاب يدفع اليد إلى أسفل","كل زوج متساو ومتعاكس وفي جسمين مختلفين"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) القوتان ومسبباهما","marks":2},{"element":"(ب) زوج الوزن","marks":1},{"element":"(ب) زوج قوة اليد","marks":1},{"element":"الخصائص","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الوزن والقوة العمودية زوجي تأثير متبادل","إغفال أن الكتاب يجذب الأرض","إدخال قوى تؤثر في اليد ضمن القوى المؤثرة في الكتاب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.638Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) القوة الوحيدة المؤثرة في الكرة هي وزنها $\boldsymbol{F}_{g}$ إلى أسفل (جذب الأرض لها)؛ ويُرسم مخطط الجسم الحر نقطة يخرج منها سهم واحد إلى أسفل مع سهم $+y$ إلى أعلى. (ب) تؤثر الكرة في الأرض بقوة جذب إلى أعلى تساوي وزنها في المقدار، وتؤثر في الأرض. (ج) لا؛ فقوة اليد قوة تلامس تزول بزوال التلامس، وحركة الكرة إلى أعلى استمرار لسرعتها المتجهة لا بسبب قوة إلى أعلى.', '["الوزن القوة الوحيدة","مخطط جسم حر صحيح","الكرة تجذب الأرض إلى أعلى بقوة مساوية","لا قوة من اليد بعد المفارقة مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) القوى والمخطط","marks":2},{"element":"(ب) القوة وزوجها والجسم المتأثر","marks":2},{"element":"(ج) الحكم والتعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم سهم إلى أعلى يمثل «قوة القذف»","إغفال أن الكرة تجذب الأرض","الظن أن الحركة إلى أعلى تحتاج إلى قوة إلى أعلى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.639Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) القوة التي يؤثر بها A في B ورمزها $\boldsymbol{F}_{\text{A في B}}$ (إلى الأمام، تؤثر في B)، والقوة التي يؤثر بها B في A ورمزها $\boldsymbol{F}_{\text{B في A}}$ (إلى الخلف، تؤثر في A). (ب) مخطط B: نقطة يخرج منها سهم أزرق إلى الأمام $\boldsymbol{F}_{\text{A في B}}$؛ ومخطط A: نقطة يخرج منها سهم أزرق مساوٍ في الطول إلى الخلف $\boldsymbol{F}_{\text{B في A}}$. (ج) لأن B يؤثر في A في أثناء التلامس بقوة مساوية في المقدار ومعاكسة في الاتجاه، وهي القوة الأفقية المؤثرة في A فتكسبه تسارعًا إلى الخلف.', '["تحديد القوتين ورمزيهما","مخططان منفصلان صحيحان","تساوي طولي السهمين وتعاكسهما","تفسير حركة A بقوة B فيه"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم القوتين على مخطط جسم واحد","تبديل رمزي القوتين","القول إن A يتحرك إلى الخلف بسبب قوته هو"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-19T07:48:34.639Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L3-O04') and x.type = v.type and x.number = v.number
