insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L3-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تسقط كرة كتلتها 0.50 kg نحو الأرض بتسارع يساوي تسارع الجاذبية الأرضية. اعتبر الاتجاه الموجب إلى أعلى ($+y$). ما القوة التي تؤثر بها الكرة في الأرض؟', null, null, '["$-4.9\\ \\text{N}$","$+4.9\\ \\text{N}$","$+0.50\\ \\text{N}$","$+0.051\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 114–115 — مثال 3: تسارع الأرض'),
('mcq', 2, 'تؤثر كرة كتلتها 0.50 kg في الأرض بقوة مقدارها 4.9 N أثناء سقوطها. إذا كانت كتلة الأرض $6.0\times10^{24}\ \text{kg}$، فما مقدار التسارع الذي تكتسبه الأرض؟', null, null, '["$8.2\\times10^{-25}\\ \\text{m/s}^2$","$9.80\\ \\text{m/s}^2$","$8.3\\times10^{-26}\\ \\text{m/s}^2$","$1.2\\times10^{24}\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 114–115 — مثال 3: تسارع الأرض'),
('mcq', 3, 'تسقط قطرة مطر كتلتها 2.45 mg نحو الأرض. ما مقدار القوة التي تؤثر بها القطرة في الأرض في أثناء سقوطها؟', null, null, '["$2.40\\times10^{-2}\\ \\text{N}$","$2.45\\times10^{-6}\\ \\text{N}$","$2.40\\times10^{-5}\\ \\text{N}$","$2.40\\times10^{1}\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 126 — تقويم الفصل 4 (4-3 قوى التأثير المتبادل)'),
('mcq', 4, 'وُضع مكعب حديد كتلته 6.0 kg على مكعب آخر كتلته 7.0 kg يستقر على طاولة أفقية، كما في الشكل الآتي. ما مقدار القوة التي يؤثر بها المكعب العلوي في المكعب السفلي واتجاهها؟', null, '[{"src":"qimg/phys1/c4l3-o05-cubes.svg","alt":"طاولة أفقية يستقر عليها مكعب كبير مكتوب عليه 7.0 kg، وفوقه مكعب أصغر مكتوب عليه 6.0 kg. على اليسار سهم إلى أعلى مكتوب عنده +y."}]'::jsonb, '["59 N إلى أعلى","127 N إلى أسفل","69 N إلى أسفل","59 N إلى أسفل"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 126 — تقويم الفصل 4 (4-3 قوى التأثير المتبادل)'),
('mcq', 5, 'يُدفع صندوقان متلاصقان على سطح أفقي مهمل الاحتكاك بقوة أفقية مقدارها 15 N تؤثر في الصندوق الأول الذي كتلته 3.0 kg، فيدفع هو الصندوق الثاني الذي كتلته 2.0 kg. ما مقدار القوة التي يؤثر بها الصندوق الأول في الثاني؟', null, null, '["15 N","6.0 N","9.0 N","3.0 N"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 126 — تقويم الفصل 4 (4-3 قوى التأثير المتبادل)'),
('mcq', 6, 'يلعب شخصان لعبة شد الحبل. أحدهما كتلته 90.0 kg يشد الحبل بحيث يكتسب الشخص الآخر الذي كتلته 55 kg تسارعًا مقداره $0.025\ \text{m/s}^2$ (أهمل الاحتكاك). ما مقدار القوة التي يؤثر بها الحبل في الشخص ذي الكتلة الكبرى؟', null, null, '["2.3 N","882 N","1.4 N","0.025 N"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 126 — تقويم الفصل 4 (4-3 قوى التأثير المتبادل)'),
('mcq', 7, 'يقف متزلجان على جليد أملس: A كتلته 75 kg وB كتلته 50 kg. دفع A صديقه B بقوة 60 N. ما مقدار تسارع A واتجاهه؟', null, null, '["0.80 m/s² عكس اتجاه دفعه","1.2 m/s² عكس اتجاه دفعه","0.80 m/s² في اتجاه دفعه","صفر؛ لأن A هو الذي دفع"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 112 — تمييز قوى التأثير المتبادل'),
('essay', 1, 'وُضع صندوق كتلته 4.0 kg على صندوق آخر كتلته 9.0 kg، والصندوقان ساكنان على أرضية أفقية. اختر الاتجاه الموجب إلى أعلى. احسب: (أ) القوة التي يؤثر بها الصندوق السفلي في العلوي (مقدارًا واتجاهًا). (ب) القوة التي يؤثر بها الصندوق العلوي في السفلي. (ج) القوة التي تؤثر بها الأرضية في الصندوق السفلي.', null, null, null, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 126 — تقويم الفصل 4 (4-3 قوى التأثير المتبادل)'),
('essay', 2, 'تسقط صخرة صغيرة كتلتها 0.25 kg نحو الأرض بتسارع يساوي تسارع الجاذبية الأرضية، وكتلة الأرض $6.0\times10^{24}\ \text{kg}$. اعتبر الاتجاه الموجب إلى أعلى. (أ) احسب القوة التي تؤثر بها الأرض في الصخرة. (ب) استخدم قانون نيوتن الثالث لإيجاد القوة التي تؤثر بها الصخرة في الأرض. (ج) احسب تسارع الأرض واذكر اتجاهه.', null, null, null, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 114–115 — مثال 3: تسارع الأرض'),
('essay', 3, 'يُدفع صندوقان متلاصقان على سطح أفقي مهمل الاحتكاك بقوة أفقية مقدارها 22.5 N، كما في الشكل الآتي. احسب: (أ) تسارع الصندوقين. (ب) القوة التي يؤثر بها الصندوق الذي كتلته 4.3 kg في الصندوق الذي كتلته 5.4 kg. (ج) القوة التي يؤثر بها الصندوق الذي كتلته 5.4 kg في الصندوق الذي كتلته 4.3 kg.', null, '[{"src":"qimg/phys1/c4l3-o05-push.svg","alt":"صندوقان متلاصقان على أرضية أفقية: الأيسر مكتوب عليه 4.3 kg والأيمن 5.4 kg. سهم أزرق أفقي نحو اليمين يدفع الصندوق الأيسر مكتوب عنده 22.5 N. تحت الأرضية عبارة «سطح أفقي مهمل الاحتكاك»، وسهم نحو اليمين مكتوب عنده +x."}]'::jsonb, null, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 126 — تقويم الفصل 4 (4-3 قوى التأثير المتبادل)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
