insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'قوة الأرض في الكرة: $\boldsymbol{F}_{\text{الأرض في الكرة}} = m_{\text{الكرة}}(-\boldsymbol{g}) = (0.50\ \text{kg})(-9.80\ \text{m/s}^2) = -4.9\ \text{N}$. ووفق قانون نيوتن الثالث: $\boldsymbol{F}_{\text{الكرة في الأرض}} = -\boldsymbol{F}_{\text{الأرض في الكرة}} = -(-4.9\ \text{N}) = +4.9\ \text{N}$، أي إلى أعلى.', '["هذه القوة التي تؤثر بها الأرض في الكرة (إلى أسفل)؛ وزوجها يعاكسها فيكون موجبًا.","","استُخدمت الكتلة بدل القوة؛ يجب الضرب في $g$ أولًا.","قُسمت الكتلة على $g$ بدل ضربها فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (49%)"}],"at":"2026-11-19T07:48:34.640Z"}'::jsonb),
('mcq', 2, 0, 'من قانون نيوتن الثاني للأرض: $a_{\text{الأرض}} = \frac{F_{\text{المحصلة}}}{m_{\text{الأرض}}} = \frac{4.9\ \text{N}}{6.0\times10^{24}\ \text{kg}} = 8.2\times10^{-25}\ \text{m/s}^2$ في اتجاه الكرة.', '["","هذا تسارع الكرة؛ أما الأرض فكتلتها هائلة فتسارعها متناهٍ في الصغر.","قُسمت كتلة الكرة (0.50 kg) على كتلة الأرض بدل قسمة القوة.","قُلبت العلاقة فقُسمت كتلة الأرض على القوة؛ والصحيح $a = \\frac{F}{m}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.640Z"}'::jsonb),
('mcq', 3, 2, 'كتلة القطرة $2.45\ \text{mg} = 2.45\times10^{-6}\ \text{kg}$، وقوة الأرض فيها $F = mg = (2.45\times10^{-6})(9.80) = 2.40\times10^{-5}\ \text{N}$، وقوة القطرة في الأرض تساويها في المقدار وفق قانون نيوتن الثالث.', '["حُوّلت الكتلة خطأ إلى $2.45\\times10^{-3}\\ \\text{kg}$؛ والصحيح أن 1 mg يساوي $10^{-6}\\ \\text{kg}$.","هذه الكتلة بالكيلوجرام؛ لم تُضرب في $g$.","","لم تُحوّل الكتلة إلى kg، بل ضُرب العدد 2.45 في 9.80 مباشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-19T07:48:34.640Z"}'::jsonb),
('mcq', 4, 3, 'المكعب العلوي متزن، فالقوة العمودية من السفلي فيه تساوي وزنه: $F = (6.0\ \text{kg})(9.80\ \text{m/s}^2) = 59\ \text{N}$ إلى أعلى. ووفق قانون نيوتن الثالث يؤثر العلوي في السفلي بقوة 59 N إلى أسفل.', '["هذه القوة التي يؤثر بها المكعب السفلي في العلوي؛ أما قوة العلوي في السفلي فإلى أسفل.","جُمع وزنا المكعبين؛ وهذه القوة التي يؤثر بها المكعبان معًا في الطاولة.","استُخدمت كتلة المكعب السفلي (7.0 kg) بدل العلوي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-19T07:48:34.641Z"}'::jsonb),
('mcq', 5, 1, 'التسارع المشترك $a = \frac{15\ \text{N}}{5.0\ \text{kg}} = 3.0\ \text{m/s}^2$، والقوة الأفقية الوحيدة على الصندوق الثاني هي قوة الأول فيه: $F = (2.0\ \text{kg})(3.0\ \text{m/s}^2) = 6.0\ \text{N}$، ويؤثر الثاني في الأول بقوة 6.0 N معاكسة.', '["هذه القوة الخارجية المؤثرة في الصندوق الأول؛ أما الثاني فيحتاج فقط إلى ما يكسبه التسارع المشترك.","","هذه القوة المحصلة على الصندوق الأول ($3.0 \\times 3.0$)، لا القوة التي يؤثر بها في الثاني.","هذا مقدار التسارع بوحدة m/s²، وليس قوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-19T07:48:34.641Z"}'::jsonb),
('mcq', 6, 2, 'القوة في الحبل المؤثرة في الشخص الأصغر: $F = (55\ \text{kg})(0.025\ \text{m/s}^2) = 1.4\ \text{N}$. والحبل مهمل الكتلة فينقل القوة نفسها، فيؤثر في الشخص الأكبر بقوة 1.4 N في الاتجاه المعاكس.', '["ضُربت كتلة الشخص الأكبر (90.0 kg) في تسارع الشخص الآخر.","هذا وزن الشخص الأكبر، ولا علاقة له بالقوة الأفقية في الحبل.","","هذا مقدار التسارع، وقد نُسي ضربه في الكتلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-19T07:48:34.641Z"}'::jsonb),
('mcq', 7, 0, 'وفق قانون نيوتن الثالث يؤثر B في A بقوة 60 N عكس اتجاه الدفع، ووفق الثاني: $a = \frac{60\ \text{N}}{75\ \text{kg}} = 0.80\ \text{m/s}^2$ عكس اتجاه الدفع.', '["","استُخدمت كتلة B (50 kg)؛ وهذا تسارع B لا A.","القوة المؤثرة في A معاكسة لاتجاه دفعه، فيتسارع إلى الخلف.","يؤثر B في A بقوة 60 N معاكسة، فيتسارع A وفق قانون نيوتن الثاني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-19T07:48:34.642Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) العلوي متزن: $F_{\text{N}} = mg = (4.0)(9.80) = 39\ \text{N}$ إلى أعلى. (ب) وفق قانون نيوتن الثالث: 39 N إلى أسفل. (ج) السفلي متزن تحت وزنه (88.2 N) وقوة العلوي فيه (39.2 N) إلى أسفل، فتكون قوة الأرضية فيه $88.2 + 39.2 = 127.4$، أي $1.3\times10^{2}\ \text{N}$ إلى أعلى.', '["اتزان الصندوق العلوي","39 N إلى أعلى","تطبيق القانون الثالث: 39 N إلى أسفل","اتزان الصندوق السفلي","$1.3\\times10^{2}$ N إلى أعلى"]'::jsonb, '["قوة السفلي في العلوي تساوي وزن العلوي: $(4.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 39.2\\ \\text{N} \\approx 39\\ \\text{N}$ إلى أعلى","قوة العلوي في السفلي = 39 N إلى أسفل (قانون نيوتن الثالث)","وزن السفلي: $(9.0)(9.80) = 88.2\\ \\text{N}$","قوة الأرضية في السفلي: $88.2 + 39.2 = 127.4\\ \\text{N} \\approx 1.3\\times10^{2}\\ \\text{N}$ إلى أعلى"]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل قوة العلوي في السفلي إلى أعلى","إغفال قوة العلوي عند اتزان السفلي","كتابة الناتج بأرقام معنوية أكثر من المعطيات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-19T07:48:34.642Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $\boldsymbol{F} = m(-\boldsymbol{g}) = (0.25)(-9.80) = -2.5\ \text{N}$. (ب) $= -(-2.5\ \text{N}) = +2.5\ \text{N}$. (ج) $a = \frac{2.45}{6.0\times10^{24}} = 4.1\times10^{-25}\ \text{m/s}^2$ إلى أعلى نحو الصخرة.', '["قوة الأرض في الصخرة −2.5 N","تطبيق القانون الثالث: +2.5 N","تطبيق القانون الثاني على الأرض","$4.1\\times10^{-25}\\ \\text{m/s}^2$ نحو الصخرة"]'::jsonb, '["$F = (0.25\\ \\text{kg})(-9.80\\ \\text{m/s}^2) = -2.45\\ \\text{N} \\approx -2.5\\ \\text{N}$","قوة الصخرة في الأرض $= -(-2.5\\ \\text{N}) = +2.5\\ \\text{N}$","$a = \\frac{F}{m} = \\frac{2.45\\ \\text{N}}{6.0\\times10^{24}\\ \\text{kg}} = 4.1\\times10^{-25}\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج) العلاقة والتعويض","marks":2},{"element":"الاتجاه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان الإشارة السالبة لقوة الأرض في الصخرة","قسمة كتلة الصخرة على كتلة الأرض","القول إن تسارع الأرض صفر تمامًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (49%)"}],"at":"2026-11-19T07:48:34.642Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) $a = \frac{22.5}{4.3 + 5.4} = 2.3\ \text{m/s}^2$ في اتجاه القوة. (ب) القوة الأفقية الوحيدة على الصندوق 5.4 kg: $F = (5.4)(2.32) = 13\ \text{N}$ في اتجاه الحركة. (ج) وفق قانون نيوتن الثالث: 13 N عكس اتجاه الحركة.', '["التسارع من الكتلة الكلية","2.3 m/s²","القوة على 5.4 kg = 13 N","القوة على 4.3 kg = 13 N معاكسة (القانون الثالث)"]'::jsonb, '["$a = \\frac{F}{m_1 + m_2} = \\frac{22.5\\ \\text{N}}{9.7\\ \\text{kg}} = 2.32\\ \\text{m/s}^2 \\approx 2.3\\ \\text{m/s}^2$","قوة الصندوق 4.3 kg في 5.4 kg: $(5.4\\ \\text{kg})(2.32\\ \\text{m/s}^2) = 12.5\\ \\text{N} \\approx 13\\ \\text{N}$","قوة الصندوق 5.4 kg في 4.3 kg: 13 N عكس اتجاه الحركة"]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب)","marks":2},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب التسارع بكتلة صندوق واحد","جعل القوة بين الصندوقين 22.5 N","إغفال الاتجاه المعاكس في (ج)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-19T07:48:34.643Z"}'::jsonb)
