from (values
('mcq', 1, 'يُسحب حبل أفقي ساكن مهمل الكتلة من طرفيه بقوتين مقدار كل منهما 400 N، كما في الشكل الآتي. ما مقدار قوة الشد عند النقطة Q؟', null, '[{"src":"qimg/phys1/c4l3-o06-rope-points.svg","alt":"حبل أفقي عليه ثلاث نقاط من اليسار إلى اليمين: P وQ (في المنتصف) وR. عند الطرف الأيسر سهم أزرق نحو اليسار مكتوب تحته 400 N، وعند الطرف الأيمن سهم أزرق نحو اليمين مكتوب تحته 400 N. وتحت الحبل عبارة «الحبل ساكن ومهمل الكتلة»."}]'::jsonb, '["800 N","400 N","0 N","200 N"]'::jsonb, 'تحليل', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 2, 'دلو وزنه 120 N معلق ساكنًا بحبل مهمل الكتلة مثبت في السقف، وعلى الحبل ثلاث نقاط X وY وZ كما في الشكل الآتي. كيف تقارن قوى الشد عند النقاط الثلاث؟', null, '[{"src":"qimg/phys1/c4l3-o06-hanging.svg","alt":"حبل رأسي مثبت في سقف، يتدلى منه دلو في الأسفل. على الحبل ثلاث نقاط من أعلى إلى أسفل: X قرب السقف، وY في المنتصف، وZ فوق الدلو مباشرة. وبجانب الدلو عبارة «الوزن: 120 N»."}]'::jsonb, '["متساوية، ومقدار كل منها 120 N","أكبرها عند X قرب السقف وأصغرها عند Z","أكبرها عند Z لقربها من الدلو","متساوية، ومقدار كل منها 40 N"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 3, 'ربط أحد فريقي لعبة شد الحبل طرف الحبل الذي من جهته بشجرة، وسحب الفريق الآخر الطرف الثاني بقوة 500 N والحبل ساكن. ما قوة الشد المتولدة في الحبل؟', null, null, '["1000 N","0 N","250 N","500 N"]'::jsonb, 'تحليل', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 120 — مراجعة 4-3'),
('mcq', 4, 'لماذا تتساوى قوة الشد في جميع نقاط حبل مهمل الكتلة يحمل دلوًا ساكنًا؟', null, null, '["لأن الحبل يتحمل القوة القصوى نفسها عند جميع نقاطه","لأن قوة الشد قوة مجال تتوزع بانتظام في الحبل","لأن كل جزء من الحبل متزن، فالشد أسفله يساوي الشد أعلاه","لأن وزن الحبل يتوزع بالتساوي على جميع نقاطه من أعلاه إلى أسفله"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 125 — تقويم الفصل 4 (إتقان المفاهيم)'),
('mcq', 5, 'عُلّق مصباح وزنه 30 N بخيط مثبت في السقف، وعُلّق أسفله مصباح آخر وزنه 20 N بخيط ثانٍ، والمصباحان ساكنان والخيطان مهملا الكتلة. ما قوة الشد في الخيط العلوي؟', null, null, '["30 N","50 N","20 N","10 N"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 6, 'ميزان نابضي مهمل الكتلة يُسحب من طرفيه بحبلين أفقيين، يسحب كل منهما بقوة 50 N، والميزان ساكن. ما قراءة الميزان؟', null, null, '["100 N","0 N","25 N","50 N"]'::jsonb, 'تحليل', 'تطبيق مفهوم', 'صعب', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 7, 'يسحب شخص صندوقًا على أرضية أفقية بحبل أفقي مهمل الكتلة، فيؤثر في طرف الحبل بقوة 80 N، والصندوق يتحرك بسرعة متجهة منتظمة. ما القوة التي يؤثر بها الحبل في الصندوق؟', null, null, '["80 N","160 N","40 N","0 N"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('essay', 1, 'فسّر لماذا يكون الشد ثابتًا في كل نقاط حبل مهمل الكتلة يحمل دلوًا ساكنًا معلقًا بالسقف، مستعينًا بنقطة من الحبل تقع مباشرة فوق الدلو، ثم استنتج مقدار الشد في الحبل بدلالة وزن الدلو.', null, null, null, 'تحليل', 'تفسير', 'متوسط', 'الكتاب ص 125 — تقويم الفصل 4 (إتقان المفاهيم)'),
('essay', 2, 'في لعبة شد الحبل يسحب الفريق A الحبل نحو اليسار بقوة 500 N، ويسحبه الفريق B نحو اليمين بقوة 500 N، ولا يتحرك الحبل. قال طالب: «الشد الكلي في الحبل 1000 N». (أ) هل توافقه؟ (ب) فسّر إجابتك بدراسة النصف الأيسر من الحبل منفردًا، مع ذكر زوج التأثير المتبادل بين نصفي الحبل.', null, null, null, 'تحليل', 'تقويم واستنتاج', 'صعب', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('essay', 3, 'عُلّقت ثلاثة أجسام رأسيًا بثلاثة خيوط مهملة الكتلة: الخيط الأول من السقف إلى الجسم العلوي (وزنه 10 N)، والثاني من العلوي إلى الأوسط (وزنه 15 N)، والثالث من الأوسط إلى السفلي (وزنه 25 N)، والمجموعة ساكنة. (أ) احسب الشد في كل خيط. (ب) لماذا يكون الشد ثابتًا على طول كل خيط رغم اختلافه من خيط إلى آخر؟', null, null, null, 'تحليل', 'حساب وتعليل', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
