from (values
('mcq', 1, 1, 'الحبل مهمل الكتلة ومتزن، فالشد ثابت في جميع نقاطه ويساوي القوة التي يسحب بها كل طرف: 400 N عند P وQ وR.', '["جُمعت قوتا الطرفين؛ لكن كل جزء من الحبل يُسحب بـ 400 N من كل جهة، فالشد 400 N.","","القوة المحصلة على الحبل صفر، لكن الشد ليس صفرًا؛ فالحبل مشدود بقوة 400 N.","لا ينقسم الشد بين الطرفين؛ فهو يساوي القوة التي يسحب بها كل طرف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.643Z"}'::jsonb),
('mcq', 2, 0, 'كل نقطة من الحبل متزنة: الشد أسفلها إلى أسفل يساوي الشد أعلاها إلى أعلى، والحبل مهمل الكتلة؛ لذلك الشد في كل مكان يساوي وزن الدلو 120 N.', '["","الحبل مهمل الكتلة، فلا يوجد وزن للحبل يزيد الشد قرب السقف.","كل نقطة متزنة: الشد أسفلها يساوي الشد أعلاها، فلا يزيد الشد قرب الدلو.","لا يتوزع وزن الدلو على النقاط؛ فكل نقطة تحمل وزن ما تحتها كاملًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.644Z"}'::jsonb),
('mcq', 3, 3, 'الحبل ساكن، فالشجرة تؤثر في طرفه بقوة 500 N تعاكس قوة الفريق؛ والشد في الحبل يساوي القوة التي يُسحب بها كل طرف: 500 N، كما لو أمسك فريق آخر الطرف وسحب بقوة 500 N.', '["الشجرة تؤثر بقوة 500 N فقط؛ والشد يساوي القوة عند كل طرف ولا يُجمع.","الحبل ساكن لأن القوة المحصلة عليه صفر، لكنه مشدود بقوة 500 N.","لا يُقسم الشد على طرفي الحبل؛ فهو يساوي القوة عند كل طرف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.644Z"}'::jsonb),
('mcq', 4, 2, 'كل نقطة من الحبل في حالة اتزان: الجزء أسفلها يسحبها إلى أسفل بقوة تساوي سحب الجزء أعلاها إلى أعلى (وهاتان القوتان بين جزأي الحبل زوجا تأثير متبادل)، وبما أن الحبل مهمل الكتلة فالشد ثابت في كل نقاطه.', '["أقصى شد يتحمله الحبل لا يحدد الشد الفعلي فيه.","قوة الشد قوة تلامس لا قوة مجال.","","الحبل مهمل الكتلة فلا وزن له؛ والسبب اتزان كل جزء منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.644Z"}'::jsonb),
('mcq', 5, 1, 'الشد في الحبل يساوي وزن جميع الأجسام المعلقة أسفله: $30 + 20 = 50\ \text{N}$ في الخيط العلوي، و20 N في الخيط السفلي.', '["هذا وزن المصباح العلوي وحده؛ والخيط العلوي يحمل المصباحين معًا.","","هذا الشد في الخيط السفلي الذي يحمل المصباح السفلي فقط.","طُرح الوزنان؛ والصحيح جمعهما لأن الخيط يحمل كل ما تحته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.644Z"}'::jsonb),
('mcq', 6, 3, 'الميزان كالحبل المهمل الكتلة: متزن ويُسحب من كل طرف بـ 50 N، فالشد فيه 50 N، وهي قراءته (كما لو ثُبّت أحد طرفيه في جدار وسُحب الآخر بـ 50 N).', '["جُمعت القوتان؛ لكن الميزان يقيس الشد، وهو يساوي القوة عند كل طرف.","القوة المحصلة على الميزان صفر، لكن قراءته تساوي الشد فيه وهو 50 N.","لا يُقسم الشد على الطرفين؛ الشد يساوي القوة عند كل طرف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.645Z"}'::jsonb),
('mcq', 7, 0, 'الحبل مهمل الكتلة، فالشد ثابت في جميع نقاطه ويساوي القوة التي يسحب بها الشخص طرفه: 80 N، فيؤثر الحبل في الصندوق بقوة 80 N.', '["","لا تُجمع القوتان عند طرفي الحبل؛ فالشد في الحبل كله 80 N.","قُسمت القوة على طرفي الحبل؛ والحبل مهمل الكتلة فالشد ثابت ويساوي 80 N.","عدم التسارع يعني أن محصلة القوى على الصندوق صفر، لا أن الحبل لا يؤثر فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.645Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الدلو متزن، فقوة وزنه إلى أسفل تساوي في المقدار وتعاكس في الاتجاه قوة الشد فيه إلى أعلى. النقطة من الحبل التي فوق الدلو مباشرة متزنة أيضًا: الشد في الحبل أسفلها يسحبها إلى أسفل، ويساوي الشد أعلاها الذي يسحبها إلى أعلى. وينطبق هذا على كل نقطة في الحبل، وبما أن الحبل مهمل الكتلة فلا يضيف وزنًا. لذلك الشد في كل مكان من الحبل يساوي وزن الدلو.', '["الدلو متزن: الشد يساوي الوزن","النقطة فوق الدلو متزنة","الشد أسفل النقطة يساوي الشد أعلاها","التعميم على كل النقاط","إهمال كتلة الحبل","الشد = وزن الدلو"]'::jsonb, '[]'::jsonb, '[{"element":"اتزان الدلو","marks":1},{"element":"اتزان النقطة والمقارنة","marks":2},{"element":"التعميم وإهمال الكتلة","marks":1},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الشد أكبر عند السقف","إغفال دور إهمال كتلة الحبل","الخلط بين الشد ووزن الحبل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.645Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) لا؛ الشد في الحبل 500 N. (ب) النصف الأيسر لا يتحرك، فالقوة المحصلة عليه صفر: يسحبه الفريق A نحو اليسار بـ 500 N، فلا بد أن يسحبه النصف الأيمن نحو اليمين بـ 500 N. والقوة التي يؤثر بها النصف الأيمن في الأيسر والقوة التي يؤثر بها الأيسر في الأيمن زوجا تأثير متبادل، فهما متساويتان (500 N) ومتعاكستان. أي أن الشد الكلي في الحبل يساوي القوة التي يسحب بها كل فريق: 500 N.', '["رفض 1000 N","اتزان النصف الأيسر","قوة النصف الأيمن فيه 500 N","قوتا النصفين زوجا تأثير متبادل","الشد = 500 N"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"تحليل النصف الأيسر","marks":2},{"element":"زوج التأثير المتبادل","marks":1},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جمع قوتي الفريقين","اعتبار الشد صفرًا لأن الحبل ساكن","اعتبار قوتي الفريقين زوجي تأثير متبادل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.645Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الشد في الحبل يساوي وزن جميع الأجسام المعلقة أسفله: الخيط الثالث 25 N، والثاني $15 + 25 = 40\ \text{N}$، والأول $10 + 15 + 25 = 50\ \text{N}$. (ب) لأن كل خيط مهمل الكتلة وكل جزء منه متزن، فالشد أسفل أي نقطة فيه يساوي الشد أعلاها؛ أما الأجسام فلها أوزان، لذلك يتغير الشد عند المرور بجسم من خيط إلى آخر.', '["الخيط الثالث 25 N","الخيط الثاني 40 N","الخيط الأول 50 N","التعليل: كتلة الخيط مهملة وكل جزء متزن","التغير عند الأجسام بسبب أوزانها"]'::jsonb, '["الخيط الثالث: 25 N","الخيط الثاني: $15 + 25 = 40\\ \\text{N}$","الخيط الأول: $10 + 15 + 25 = 50\\ \\text{N}$"]'::jsonb, '[{"element":"(أ) الخيوط الثلاثة","marks":3},{"element":"(ب) التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء كل خيط وزن الجسم المعلق به مباشرة فقط","جعل الشد متساويًا في الخيوط الثلاثة","إهمال أن الخيط يحمل كل ما تحته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.646Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
