('mcq', 1, 'يبيّن الشكل الآتي أربعة مخططات للجسم الحر رُسمت لدلو معلق ساكن بحبل رأسي، وطول كل سهم يتناسب مع مقدار القوة. أيّ المخططات يمثل الدلو تمثيلًا صحيحًا؟', null, '[{"src":"qimg/phys1/c4l3-o07-bucket-fbds.svg","alt":"أربعة مخططات جسم حر مرقمة من اليسار إلى اليمين (1) و(2) و(3) و(4)، في كل منها نقطة تمثل الدلو. (1): سهم أزرق إلى أعلى F_T وسهم أزرق إلى أسفل F_g متساويان في الطول. (2): سهم F_T إلى أعلى أطول من سهم F_g إلى أسفل. (3): سهم F_T إلى أعلى أقصر من سهم F_g إلى أسفل. (4): سهم F_g إلى أسفل فقط. وعلى اليسار سهم إلى أعلى مكتوب عنده +y."}]'::jsonb, '["المخطط (2)","المخطط (3)","المخطط (1)","المخطط (4)"]'::jsonb, 'فهم', 'قراءة مخطط', 'سهل', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 2, 'دلو وزنه 85 N معلق ساكنًا بحبل رأسي. ما قوة الشد التي يؤثر بها الحبل في الدلو؟', null, null, '["85 N إلى أسفل","85 N إلى أعلى","170 N إلى أعلى","0 N لأن الدلو ساكن"]'::jsonb, 'تطبيق', 'تطبيق الاتزان', 'سهل', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 3, 'لماذا يبقى الدلو المعلق بحبل ساكنًا؟', null, null, '["لأن القوة المحصلة عليه صفر؛ إذ يساوي الشد وزنه ويعاكسه","لأن قوة الشد أكبر قليلًا من وزنه فتمنعه دائمًا من السقوط","لأن الحبل لا يؤثر فيه بأي قوة ما دام ساكنًا","لأن وزنه يصبح صفرًا عندما يُعلق بالحبل"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 4, 'دلو كتلته 4.0 kg معلق ساكنًا بحبل رأسي. ما مقدار قوة الشد في الحبل؟', null, null, '["4.0 N","0 N","78 N","39 N"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 5, 'أُضيف ماء إلى دلو معلق ساكن بحبل فزاد وزنه، ثم عاد ساكنًا. ماذا يحدث لقوة الشد في الحبل؟', null, null, '["لا تتغير لأن الدلو ما زال ساكنًا","تقل لأن الحبل يتمدد","تزداد بمقدار الزيادة في الوزن","تصبح صفرًا بعد أن يسكن الدلو"]'::jsonb, 'فهم', 'تنبؤ', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 6, 'دلو معلق ساكن بحبل رأسي، والاتجاه الموجب إلى أعلى. أيّ العلاقات الآتية تعبّر عن اتزانه بمقادير القوى؟', null, null, '["$F_{\\text{T}} - F_g = 0$","$F_{\\text{T}} + F_g = 0$","$F_{\\text{T}} - F_g = mg$","$F_{\\text{T}} = 0$"]'::jsonb, 'تطبيق', 'كتابة معادلة', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('mcq', 7, 'يُرفع دلو بحبل رأسي بسرعة متجهة منتظمة (أهمل مقاومة الهواء). كيف تقارن قوة الشد في الحبل بوزن الدلو؟', null, null, '["أكبر منه؛ لأن الدلو يتحرك إلى أعلى","أصغر منه؛ لأن الحبل يتعب مع الحركة","ضعفه؛ لأن الحبل يرفع الدلو ويحمله","تساويه؛ لأن الدلو متزن"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('essay', 1, 'يُعلّق دلو كتلته 6.0 kg ساكنًا في نهاية حبل مثبت في السقف. (أ) ارسم مخطط الجسم الحر للدلو، مع تحديد الاتجاه الموجب. (ب) فسّر اتزان الدلو. (ج) احسب قوة الشد في الحبل.', null, null, null, 'فهم', 'تفسير وحساب', 'سهل', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('essay', 2, 'قارن بين قوة الشد في حبل ووزن الدلو المعلق به في ثلاث حالات: (أ) الدلو معلق ساكن. (ب) الدلو يُرفع بسرعة متجهة منتظمة. (ج) الدلو يُنزل بسرعة متجهة منتظمة. فسّر إجابتك في كل حالة (أهمل مقاومة الهواء).', null, null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('essay', 3, 'قال طالب: «الدلو المعلق الساكن لا تؤثر فيه أي قوة؛ لأنه لا يتحرك». قوّم هذه العبارة، وبيّن ماذا يحدث للدلو لو قُطع الحبل، مستعينًا بمفهوم الاتزان.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L3-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الدلو الساكن متزن: قوة الشد إلى أعلى تساوي وزنه إلى أسفل في المقدار وتعاكسه في الاتجاه، فيكون السهمان متساويين في الطول ومتعاكسين، وهذا المخطط (1).', '["قوة الشد فيه أكبر من الوزن، فتكون القوة المحصلة إلى أعلى ويتسارع الدلو إلى أعلى؛ وهذا لا يناسب دلوًا ساكنًا.","قوة الشد فيه أصغر من الوزن، فيتسارع الدلو إلى أسفل؛ وهذا لا يناسب دلوًا ساكنًا.","","أُهملت قوة الشد؛ والحبل يؤثر في الدلو بقوة إلى أعلى ما دام مشدودًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.646Z"}'::jsonb),
('mcq', 2, 1, 'الدلو متزن، فقوة الشد إلى أعلى تساوي وزنه في المقدار وتعاكسه في الاتجاه: 85 N إلى أعلى.', '["الحبل يسحب الدلو نحو نقطة التعليق، أي إلى أعلى؛ والوزن هو الذي إلى أسفل.","","لا يُضاعف الوزن؛ الاتزان يتطلب أن يساوي الشد الوزن فقط.","سكون الدلو يعني أن محصلة القوى صفر، لا أن الشد صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-19T07:48:34.646Z"}'::jsonb),
('mcq', 3, 0, 'الدلو متزن: يؤثر فيه وزنه إلى أسفل وقوة الشد إلى أعلى، وهما متساويتان في المقدار ومتعاكستان، فالقوة المحصلة صفر ويبقى ساكنًا.', '["","لو كان الشد أكبر لكانت القوة المحصلة إلى أعلى ولتسارع الدلو إلى أعلى.","الحبل المشدود يؤثر في الدلو بقوة شد إلى أعلى، ولولاها لسقط الدلو.","الوزن قوة جذب الأرض للدلو، ولا يزول بتعليقه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.647Z"}'::jsonb),
('mcq', 4, 3, 'الدلو متزن: $F_{\text{T}} = F_g = mg = (4.0\ \text{kg})(9.80\ \text{m/s}^2) = 39\ \text{N}$.', '["كُتبت الكتلة بدل الوزن؛ يجب الضرب في $g$.","الدلو ساكن لكن الحبل مشدود؛ الشد يساوي الوزن لا الصفر.","ضوعف الوزن؛ والاتزان يتطلب أن يساوي الشد الوزن مرة واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-19T07:48:34.647Z"}'::jsonb),
('mcq', 5, 2, 'ما دام الدلو متزنًا يجب أن يساوي الشد وزنه؛ فإذا زاد الوزن زاد الشد بالمقدار نفسه.', '["الاتزان يتطلب أن يساوي الشد الوزن الجديد، فيزداد الشد.","الشد يحدده اتزان الدلو، ويجب أن يزداد ليوازن الوزن الأكبر.","","لو صار الشد صفرًا لسقط الدلو؛ فالشد يوازن الوزن دائمًا ما دام متزنًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-19T07:48:34.647Z"}'::jsonb),
('mcq', 6, 0, 'القوة المحصلة على الدلو بالإشارات: $F_{\text{T}} + (-F_g) = ma = 0$، أي $F_{\text{T}} - F_g = 0$، ومنها $F_{\text{T}} = F_g$.', '["","المقداران موجبان دائمًا، فمجموعهما لا يكون صفرًا؛ ويجب طرح الوزن لأنه في الاتجاه السالب.","الدلو ساكن فتسارعه صفر، والطرف الأيمن يجب أن يكون $ma = 0$.","هذا يعني عدم وجود شد، والدلو لن يبقى معلقًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.647Z"}'::jsonb),
('mcq', 7, 3, 'السرعة المتجهة منتظمة، فالتسارع صفر والدلو متزن كالدلو الساكن؛ لذلك القوة المحصلة صفر والشد يساوي الوزن.', '["الحركة إلى أعلى بسرعة منتظمة لا تتطلب قوة محصلة؛ التسارع صفر.","الشد يحدده قانون نيوتن؛ والتسارع صفر فالشد يساوي الوزن.","لا يوجد سبب لمضاعفة الشد؛ الاتزان يتطلب تساوي الشد والوزن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-19T07:48:34.647Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) نقطة يخرج منها سهم أزرق إلى أعلى $\boldsymbol{F}_{\text{T}}$ وسهم أزرق إلى أسفل $\boldsymbol{F}_{g}$ متساويان في الطول، وسهم $+y$ إلى أعلى. (ب) الدلو ساكن فهو متزن: وزنه إلى أسفل يساوي في المقدار ويعاكس في الاتجاه قوة الشد إلى أعلى، فالقوة المحصلة صفر. (ج) $F_{\text{T}} = F_g = mg = (6.0)(9.80) = 59\ \text{N}$.', '["مخطط صحيح بسهمين متساويين","الاتجاه الموجب","الاتزان: الشد يساوي الوزن ويعاكسه","الناتج 59 N"]'::jsonb, '["$F_{\\text{T}} - F_g = 0$","$F_{\\text{T}} = mg = (6.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 58.8\\ \\text{N} \\approx 59\\ \\text{N}$"]'::jsonb, '[{"element":"(أ) المخطط","marks":2},{"element":"(ب) التفسير","marks":1},{"element":"(ج) الحساب","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم سهمين مختلفين في الطول لدلو ساكن","كتابة الكتلة بدل الوزن","إضافة سهم للقوة المحصلة في المخطط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.648Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في الحالات الثلاث يساوي الشد وزن الدلو. التفسير: في (أ) الدلو ساكن، وفي (ب) و(ج) سرعته المتجهة منتظمة فتسارعه صفر؛ والجسم الذي تسارعه صفر متزن، فالقوة المحصلة عليه صفر، أي أن الشد إلى أعلى يساوي الوزن إلى أسفل في المقدار. اتجاه الحركة لا يحدد الشد، بل التسارع.', '["الحالة (أ): الشد = الوزن","الحالة (ب): الشد = الوزن","الحالة (ج): الشد = الوزن","التعليل: التسارع صفر فالجسم متزن","اتجاه الحركة لا يغير الشد"]'::jsonb, '[]'::jsonb, '[{"element":"الحالات الثلاث","marks":3},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الشد أكبر في أثناء الرفع","القول إن الشد أصغر في أثناء الإنزال","ربط الشد بالسرعة بدل التسارع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-19T07:48:34.648Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة؛ فالدلو تؤثر فيه قوتان: وزنه إلى أسفل وقوة الشد إلى أعلى، وسكونه لأن القوتين متساويتان في المقدار ومتعاكستان في الاتجاه فمحصلتهما صفر (اتزان)، لا لأنه لا تؤثر فيه قوى. ولو قُطع الحبل لزالت قوة الشد وبقي الوزن وحده، فتصبح القوة المحصلة إلى أسفل ويسقط الدلو متسارعًا.', '["الحكم بخطأ العبارة","ذكر القوتين المؤثرتين","السكون سببه محصلة صفرية","عند القطع يزول الشد","يسقط الدلو متسارعًا بسبب الوزن"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم وذكر القوتين","marks":2},{"element":"مفهوم الاتزان","marks":1},{"element":"ما يحدث عند القطع مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين انعدام القوى وانعدام القوة المحصلة","القول إن الدلو يبقى ساكنًا لحظة بعد القطع","إغفال الوزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-19T07:48:34.648Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
