on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L3-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يُرفع دلو كتلته 30.0 kg بحبل يتحمل قوة شد قصوى مقدارها 350 N، ويتسارع الدلو إلى أعلى بتسارع ثابت مقداره $2.0\ \text{m/s}^2$. هل ينقطع الحبل؟', null, null, '["لا؛ لأن وزن الدلو 294 N فقط، وهو أقل من 350 N","لا؛ لأن الشد اللازم 60.0 N فقط","لا؛ لأن الشد اللازم 234 N، وهو أقل من 350 N","نعم؛ لأن الشد اللازم 354 N، وهو أكبر من 350 N"]'::jsonb, 'تحليل', 'حكم بالحساب', 'متوسط', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('mcq', 2, 'متى ينقطع حبل يُرفع به جسم؟', null, null, '["عندما يكون وزن الجسم أكبر من كتلته عدديًا","عندما تتطلب حركة الجسم شدًا أكبر مما يتحمله الحبل","عندما يتحرك الجسم إلى أعلى بسرعة متجهة منتظمة كبيرة","عندما يتسارع الجسم إلى أسفل في أثناء إنزاله"]'::jsonb, 'فهم', 'استنتاج قاعدة', 'سهل', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('mcq', 3, 'يُحمل الدلو نفسه بالحبل نفسه في أربع حالات. في أيّ الحالات يكون احتمال انقطاع الحبل أكبر؟', null, null, '["عندما يُرفع الدلو ويتسارع إلى أعلى","عندما يُرفع الدلو بسرعة متجهة منتظمة","عندما يكون الدلو معلقًا ساكنًا","عندما يُنزل الدلو ويتسارع إلى أسفل"]'::jsonb, 'تحليل', 'مقارنة حالات', 'سهل', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('mcq', 4, 'وُضعت معدات في دلو فأصبحت كتلته 42 kg، ويُرفع الدلو بحبل يتحمل شدًا لا يتجاوز 450 N. ما أقصى تسارع يمكن أن يكتسبه الدلو إلى أعلى دون أن ينقطع الحبل؟', null, null, '["$11\\ \\text{m/s}^2$","$21\\ \\text{m/s}^2$","$0.91\\ \\text{m/s}^2$","$0\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 118 — مسألة تدريبية 32'),
('mcq', 5, 'رجل كتلته 70.0 kg (وزنه 686 N) يريد النزول من نافذة بحبل يتحمل شدًا أقصاه 600 N. ماذا يجب أن يفعل لكي لا ينقطع الحبل؟', null, null, '["ينزل ببطء بسرعة متجهة منتظمة صغيرة جدًا","ينزل متسارعًا إلى أسفل فيقل الشد عن وزنه","يبقى معلقًا ساكنًا قبل أن يبدأ النزول","يتسلق الحبل صاعدًا إلى أعلى ويتسارع"]'::jsonb, 'تحليل', 'حل مشكلة', 'صعب', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('mcq', 6, 'سحبتَ دلوًا ممتلئًا إلى أعلى بسرعة متجهة منتظمة دون أن ينقطع الحبل، ثم جذبته فجأة بقوة فانقطع الحبل. ما التفسير الصحيح؟', null, null, '["الجذب المفاجئ زاد كتلة الدلو فزاد وزنه","عند السرعة المنتظمة لا يؤثر الحبل في الدلو بأي شد","الجذب المفاجئ جعل الدلو يتسارع إلى أسفل فزاد الشد في الحبل كثيرًا","أكسب الجذب الدلو تسارعًا إلى أعلى فلزم شد أكبر مما يتحمله الحبل"]'::jsonb, 'تحليل', 'تفسير', 'سهل', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('mcq', 7, 'يبين الجدول الآتي أربعة حبال، يُرفع بكل منها جسم يتسارع إلى أعلى. أيّ الحبال ينقطع؟', '{"headers":["الحبل","أقصى شد يتحمله (N)","كتلة الجسم (kg)","التسارع إلى أعلى (m/s²)"],"rows":[["1","200","15","2.0"],["2","300","25","1.0"],["3","400","30","4.0"],["4","500","45","0.50"]]}'::jsonb, null, '["الحبل 1","الحبل 2","الحبل 3","الحبل 4"]'::jsonb, 'تحليل', 'مقارنة بالحساب', 'صعب', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('essay', 1, 'يُرفع دلو كتلته 40.0 kg بحبل يتحمل قوة شد قصوى مقدارها 450 N، ويبدأ الدلو حركته من السكون بتسارع ثابت. (أ) إذا كانت سرعته 2.0 m/s عندما أصبح على ارتفاع 2.0 m، فهل ينقطع الحبل؟ (ب) أعد الحكم إذا كانت سرعته عند الارتفاع نفسه 3.0 m/s.', null, null, null, 'تحليل', 'حكم بالحساب', 'صعب', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('essay', 2, 'يُرفع صندوق بحبل يتحمل شدًا لا يتجاوز 540 N، ويُراد أن يتسارع الصندوق إلى أعلى بمقدار $1.20\ \text{m/s}^2$. (أ) احسب أكبر كتلة يمكن رفعها بهذا التسارع دون أن ينقطع الحبل. (ب) استنتج ما يحدث للحبل إذا رُفع بالتسارع نفسه صندوق كتلته 55.0 kg، مع التعليل بالحساب.', null, null, null, 'تطبيق', 'حساب واستنتاج', 'متوسط', 'الكتاب ص 118 — مسألة تدريبية 32'),
('essay', 3, 'حبل أقصى شد يتحمله أكبر بقليل من وزن جسم معين. حلّل ما يحدث للحبل في كل حالة مما يأتي، مع التعليل بقانون نيوتن الثاني: (أ) الجسم معلق ساكن. (ب) الجسم يُرفع ويتسارع إلى أعلى بتسارع كبير. (ج) الجسم يُنزل ويتسارع إلى أسفل. ثم اذكر مثالًا من الحياة على انقطاع حبل لهذا السبب.', null, null, null, 'تحليل', 'تحليل حالات', 'متوسط', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P1-C4-L3-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'بأخذ أعلى موجبًا وتطبيق قانون نيوتن الثاني: $F_{\text{T}} = m(a + g) = (30.0\ \text{kg})(2.0 + 9.80)\ \text{m/s}^2 = 354\ \text{N}$، وهي أكبر من أقصى شد يتحمله الحبل (350 N)، لذلك ينقطع الحبل.', '["الدلو يتسارع إلى أعلى، فالشد اللازم أكبر من الوزن؛ ومقارنة الوزن وحده لا تكفي.","هذه القوة المحصلة $ma$ فقط؛ ونُسي أن الشد يجب أن يوازن الوزن أيضًا.","استُخدم $m(g - a)$ كأن التسارع إلى أسفل؛ والتسارع هنا إلى أعلى.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.649Z"}'::jsonb),
('mcq', 2, 1, 'ينقطع الحبل إذا كانت قوة الشد التي تتطلبها حركة الجسم (وتُحسب بقانون نيوتن الثاني) أكبر من أقصى قوة شد يتحملها الحبل.', '["مقارنة الوزن بالكتلة لا معنى لها؛ الوحدتان مختلفتان.","","عند السرعة المنتظمة يساوي الشد الوزن مهما كبرت السرعة.","التسارع إلى أسفل يجعل الشد أقل من الوزن، فهو يقلل احتمال الانقطاع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.649Z"}'::jsonb),
('mcq', 3, 0, 'الشد $F_{\text{T}} = m(a + g)$ بأخذ أعلى موجبًا؛ فيكون أكبر ما يمكن عندما يكون التسارع إلى أعلى، فيزيد على الوزن، وهنا يكون احتمال الانقطاع أكبر.', '["","الشد هنا يساوي الوزن فقط لأن التسارع صفر.","الشد هنا يساوي الوزن فقط.","الشد هنا أقل من الوزن: $F_{\\text{T}} = m(g - a)$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.649Z"}'::jsonb),
('mcq', 4, 2, 'من $F_{\text{T}} = m(a + g)$: $a = \frac{F_{\text{T}}}{m} - g = \frac{450}{42} - 9.80 = 0.91\ \text{m/s}^2$؛ وأي تسارع أكبر يتطلب شدًا يتجاوز 450 N فينقطع الحبل.', '["قُسم أقصى شد على الكتلة دون طرح $g$؛ أي أُهمل الوزن.","أُضيف $g$ بدل طرحه.","","الحبل يتحمل أكثر من وزن الدلو (412 N)، فيمكن إكسابه تسارعًا صغيرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.650Z"}'::jsonb),
('mcq', 5, 1, 'الشد $F_{\text{T}} = m(g - a)$ عندما يتسارع إلى أسفل، فيكون أقل من الوزن. ليصبح أقل من 600 N يجب أن يكون $a > \frac{686 - 600}{70.0} = 1.2\ \text{m/s}^2$ إلى أسفل.', '["عند السرعة المنتظمة يساوي الشد الوزن 686 N، وهو أكبر من 600 N فينقطع الحبل.","","وهو ساكن يكون الشد 686 N، وهو أكبر مما يتحمله الحبل.","التسارع إلى أعلى يجعل الشد أكبر من الوزن، فينقطع الحبل أسرع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.650Z"}'::jsonb),
('mcq', 6, 3, 'عند السرعة المنتظمة يكون $F_{\text{T}} = mg$، وعند الجذب المفاجئ يتسارع الدلو إلى أعلى فيصبح $F_{\text{T}} = m(a + g)$ أكبر من الوزن، فإذا تجاوز أقصى شد يتحمله الحبل انقطع.', '["الكتلة والوزن لا يتغيران بطريقة السحب.","عند السرعة المنتظمة يساوي الشد وزن الدلو، وليس صفرًا.","الجذب إلى أعلى يُكسب الدلو تسارعًا إلى أعلى؛ والتسارع إلى أسفل يقلل الشد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.650Z"}'::jsonb),
('mcq', 7, 2, 'الشد اللازم $F_{\text{T}} = m(a + g)$: للحبل 3 يساوي $30(4.0 + 9.80) = 414\ \text{N}$، وهو أكبر من أقصى شد يتحمله (400 N)، فينقطع. أما الحبال الأخرى فالشد اللازم فيها أقل من أقصى ما تتحمله.', '["الشد اللازم $15(2.0 + 9.80) = 177\\ \\text{N}$ وهو أقل من 200 N.","الشد اللازم $25(1.0 + 9.80) = 270\\ \\text{N}$ وهو أقل من 300 N.","","الشد اللازم $45(0.50 + 9.80) = 464\\ \\text{N}$ تقريبًا وهو أقل من 500 N؛ وأكبر كتلة لا تعني بالضرورة أكبر شد مقارنة بما يتحمله الحبل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-19T07:48:34.650Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) $a = \frac{v_f^2 - v_i^2}{2d} = \frac{(2.0)^2}{2(2.0)} = 1.0\ \text{m/s}^2$، و$F_{\text{T}} = m(a + g) = 40.0(1.0 + 9.80) = 432\ \text{N}$، وهي أقل من 450 N فلا ينقطع الحبل. (ب) $a = \frac{(3.0)^2}{2(2.0)} = 2.25\ \text{m/s}^2$، و$F_{\text{T}} = 40.0(2.25 + 9.80) = 482\ \text{N}$، وهي أكبر من 450 N فينقطع الحبل.', '["حساب التسارع من معادلة الحركة","تطبيق قانون نيوتن الثاني $F_{\\text{T}} = m(a + g)$","(أ) 432 N لا ينقطع","(ب) 482 N ينقطع"]'::jsonb, '["$a = \\frac{v_f^2 - v_i^2}{2d} = \\frac{(2.0\\ \\text{m/s})^2 - 0}{2(2.0\\ \\text{m})} = 1.0\\ \\text{m/s}^2$","$F_{\\text{T}} = m(a + g) = (40.0\\ \\text{kg})(1.0 + 9.80)\\ \\text{m/s}^2 = 432\\ \\text{N} < 450\\ \\text{N}$","$a = \\frac{(3.0\\ \\text{m/s})^2}{2(2.0\\ \\text{m})} = 2.25\\ \\text{m/s}^2$","$F_{\\text{T}} = (40.0\\ \\text{kg})(2.25 + 9.80)\\ \\text{m/s}^2 = 482\\ \\text{N} > 450\\ \\text{N}$"]'::jsonb, '[{"element":"(أ) التسارع","marks":1},{"element":"(أ) الشد والحكم","marks":2},{"element":"(ب) الشد والحكم","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مقارنة الوزن 392 N وحده بأقصى شد","نسيان تربيع السرعة","استخدام قانون نيوتن الثالث لحساب الشد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.650Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) من قانون نيوتن الثاني بأخذ أعلى موجبًا: $F_{\text{T}} - mg = ma$، إذن $F_{\text{T}} = m(a + g)$، وأكبر كتلة $m = \frac{F_{\text{T}}}{a + g} = \frac{540\ \text{N}}{(1.20 + 9.80)\ \text{m/s}^2} = 49.1\ \text{kg}$. (ب) الشد اللازم للصندوق 55.0 kg: $(55.0)(1.20 + 9.80) = 605\ \text{N}$، وهو أكبر من 540 N التي يتحملها الحبل، فينقطع الحبل؛ لأن حركة الصندوق تتطلب شدًا أكبر من أقصى شد يتحمله.', '["كتابة القانون الثاني للصندوق $F_{\\text{T}} = m(a + g)$","أكبر كتلة 49.1 kg","الشد اللازم للصندوق 55.0 kg يساوي 605 N","الاستنتاج: 605 N أكبر من 540 N فينقطع الحبل"]'::jsonb, '["$F_{\\text{T}} - mg = ma \\Rightarrow F_{\\text{T}} = m(a + g)$","$m = \\frac{540\\ \\text{N}}{11.00\\ \\text{m/s}^2} = 49.1\\ \\text{kg}$","$F_{\\text{T}} = (55.0\\ \\text{kg})(11.00\\ \\text{m/s}^2) = 605\\ \\text{N} > 540\\ \\text{N}$"]'::jsonb, '[{"element":"(أ) المعادلة والتعويض","marks":2},{"element":"(أ) الناتج","marks":1},{"element":"(ب) الاستنتاج مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة 540 على $g$ وحده فتكون الكتلة 55.1 kg","طرح $a$ من $g$ بدل جمعهما","مقارنة وزن الصندوق 539 N وحده بأقصى شد فيُظن أن الحبل لا ينقطع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.650Z"}'::jsonb),
('essay', 3, null::int, null, null, 'بأخذ أعلى موجبًا: $F_{\text{T}} - mg = ma$. (أ) $a = 0$ فيكون $F_{\text{T}} = mg$، وهو أقل بقليل من أقصى ما يتحمله الحبل فلا ينقطع. (ب) $a$ إلى أعلى فيكون $F_{\text{T}} = m(g + a)$ أكبر من الوزن، فيتجاوز أقصى ما يتحمله الحبل وينقطع. (ج) $a$ إلى أسفل فيكون $F_{\text{T}} = m(g - a)$ أقل من الوزن، فلا ينقطع. مثال: رفع دلو ماء من بئر بحبل قديم بجذبة مفاجئة فينقطع، مع أنه كان يحمله معلقًا.', '["المعادلة العامة","(أ) الشد = الوزن","(ب) الشد أكبر فينقطع","(ج) الشد أقل فلا ينقطع","مثال صحيح"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة","marks":1},{"element":"الحالات الثلاث","marks":3},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط الانقطاع باتجاه الحركة لا بالتسارع","القول إن الإنزال يزيد الشد","مثال لا يتضمن تسارعًا إلى أعلى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.651Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
