from (values
('mcq', 1, 'يُرفع دلو كتلته 50.0 kg بحبل رأسي، فيتسارع إلى أعلى بتسارع ثابت كما في الشكل الآتي. ما مقدار قوة الشد في الحبل؟', null, '[{"src":"qimg/phys1/c4l3-o09-bucket-up.svg","alt":"دلو مكتوب عليه 50.0 kg معلق بحبل رأسي. على يمينه سهم أحمر إلى أعلى مكتوب عنده v، وسهم بنفسجي إلى أعلى مكتوب عنده a، وتحتهما عبارة a = 1.5 m/s². وعلى اليسار سهم إلى أعلى مكتوب عنده +y."}]'::jsonb, '["490 N","75 N","565 N","415 N"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('mcq', 2, 'يُرفع دلو كتلته 20.0 kg بحبل رأسي، وفي أثناء صعوده يتباطأ بتسارع مقداره $2.0\ \text{m/s}^2$ (أهمل مقاومة الهواء). ما مقدار قوة الشد في الحبل؟', null, null, '["156 N","236 N","196 N","40.0 N"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('mcq', 3, 'تتدلى من السقف قطعة طوب مربوطة بحبل مهمل الكتلة، ومربوط بها من أسفل قطعة طوب أخرى بحبل مهمل الكتلة، كما في الشكل الآتي، والمجموعة ساكنة. ما قوة الشد في الحبل العلوي؟', null, '[{"src":"qimg/phys1/c4l3-o09-bricks.svg","alt":"سقف يتدلى منه حبل رأسي مكتوب بجانبه «الحبل العلوي» مربوط بقطعة طوب مكتوب عليها 5.0 kg، وأسفلها حبل ثانٍ مكتوب بجانبه «الحبل السفلي» مربوط بقطعة طوب أخرى مكتوب عليها 5.0 kg. وعلى اليسار سهم إلى أعلى مكتوب عنده +y."}]'::jsonb, '["49 N","10 N","25 N","98 N"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 120 — مراجعة 4-3'),
('mcq', 4, 'يجلس طفل كتلته 45 kg في أرجوحة كتلتها 3.2 kg مربوطة بغصن شجرة بحبل واحد، والأرجوحة ساكنة. ما مقدار قوة الشد في حبل الأرجوحة؟', null, null, '["$4.4\\times10^{2}\\ \\text{N}$","$4.7\\times10^{2}\\ \\text{N}$","$3.1\\times10^{1}\\ \\text{N}$","$48\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 128–129 — اختبار مقنن'),
('mcq', 5, 'تتدلى قطعتا طوب من السقف بحبلين: العلوي بين السقف والقطعة العليا، والسفلي بين القطعتين. كتلة القطعة السفلى 3.0 kg، وقوة الشد في الحبل العلوي 63.0 N، والمجموعة ساكنة. ما كتلة القطعة العليا؟', null, null, '["3.4 kg","6.4 kg","3.0 kg","60.0 kg"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 120 — مراجعة 4-3'),
('mcq', 6, 'يُرفع صندوق كتلته 12 kg بحبل رأسي بسرعة متجهة منتظمة. ما مقدار قوة الشد في الحبل؟', null, null, '["$12\\ \\text{N}$","$0\\ \\text{N}$","$1.2\\times10^{2}\\ \\text{N}$","$2.4\\times10^{2}\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('mcq', 7, 'يُرفع دلو كتلته 12.0 kg بحبل رأسي بادئًا من السكون بتسارع ثابت، فتصبح سرعته 2.0 m/s بعد أن يرتفع 1.0 m. ما مقدار قوة الشد في الحبل؟', null, null, '["$118\\ \\text{N}$","$24.0\\ \\text{N}$","$130\\ \\text{N}$","$142\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('essay', 1, 'يُرفع دلو كتلته 30.0 kg بحبل رأسي بادئًا حركته من السكون بتسارع ثابت، فتصبح سرعته 2.0 m/s عندما يكون على ارتفاع 2.0 m. (أ) ارسم مخطط الجسم الحر للدلو مع الاتجاه الموجب وسهم التسارع. (ب) احسب التسارع. (ج) احسب قوة الشد في الحبل باستخدام قانون نيوتن الثاني، وقارنها بوزن الدلو.', null, null, null, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل'),
('essay', 2, 'تتدلى من السقف قطعة طوب كتلتها 4.0 kg بحبل مهمل الكتلة، ومربوط بها من أسفل قطعة طوب كتلتها 6.0 kg بحبل آخر مهمل الكتلة. (أ) احسب الشد في كل من الحبلين والمجموعة ساكنة. (ب) أعد الحساب إذا رُفعت المجموعة كلها بتسارع $2.0\ \text{m/s}^2$ إلى أعلى.', null, null, null, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 120 — مراجعة 4-3'),
('essay', 3, 'يُرفع دلو كتلته 15.0 kg بحبل رأسي في ثلاث مراحل: يتسارع إلى أعلى بمقدار $1.20\ \text{m/s}^2$، ثم يتحرك إلى أعلى بسرعة متجهة منتظمة، ثم يتباطأ وهو صاعد بتسارع مقداره $1.20\ \text{m/s}^2$ إلى أسفل حتى يتوقف. احسب الشد في كل مرحلة بقانون نيوتن الثاني، ورتّب المراحل تنازليًا حسب الشد.', null, null, null, 'تحليل', 'حساب ومقارنة', 'صعب', 'الكتاب ص 117–118 — مثال 4: رفع دلو بحبل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
