from (values
('mcq', 1, 2, 'بأخذ أعلى موجبًا: $F_{\text{T}} - F_g = ma$، إذن $F_{\text{T}} = m(a + g) = (50.0)(1.5 + 9.80) = 565\ \text{N}$.', '["هذا وزن الدلو فقط؛ يكون الشد مساويًا له لو كان التسارع صفرًا.","هذه القوة المحصلة $ma$ فقط؛ ونُسي أن الشد يجب أن يوازن الوزن أيضًا.","","استُخدم $m(g - a)$ كأن التسارع إلى أسفل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-19T07:48:34.651Z"}'::jsonb),
('mcq', 2, 0, 'الدلو يصعد ويتباطأ، فتسارعه إلى أسفل. بأخذ أعلى موجبًا يكون $a = -2.0\ \text{m/s}^2$، ومن قانون نيوتن الثاني $F_{\text{T}} - F_g = ma$: $F_{\text{T}} = m(a + g) = (20.0\ \text{kg})(-2.0 + 9.80)\ \text{m/s}^2 = 156\ \text{N}$، أي أقل من الوزن رغم أن الدلو صاعد.', '["","ظُن أن الصعود يعني تسارعًا إلى أعلى فاستُخدم $m(g + a)$؛ لكن الدلو يتباطأ وهو صاعد فتسارعه إلى أسفل.","هذا وزن الدلو؛ ويساويه الشد لو كانت السرعة منتظمة، لكن الدلو يتباطأ.","هذه القوة المحصلة $ma$ فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-19T07:48:34.651Z"}'::jsonb),
('mcq', 3, 3, 'الحبل العلوي يحمل القطعتين معًا: $F_{\text{T}} = (5.0 + 5.0)(9.80) = 98\ \text{N}$، والحبل السفلي يحمل القطعة السفلى: 49 N.', '["هذا الشد في الحبل السفلي الذي يحمل قطعة واحدة؛ أما العلوي فيحمل القطعتين.","جُمعت الكتلتان دون الضرب في $g$.","قُسم وزن قطعة واحدة على الحبلين؛ والصحيح أن كل حبل يحمل كل ما تحته كاملًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-19T07:48:34.651Z"}'::jsonb),
('mcq', 4, 1, 'الحبل يحمل الطفل والأرجوحة معًا وهما متزنان: $F_{\text{T}} = (45 + 3.2)(9.80) = 472\ \text{N} \approx 4.7\times10^{2}\ \text{N}$.', '["هذا وزن الطفل وحده؛ ونُسي وزن الأرجوحة المعلقة أيضًا بالحبل.","","هذا وزن الأرجوحة وحدها.","جُمعت الكتلتان دون الضرب في $g$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-19T07:48:34.652Z"}'::jsonb),
('mcq', 5, 0, 'الحبل العلوي يحمل القطعتين: $m = \frac{63.0}{9.80} = 6.43\ \text{kg}$، إذن كتلة العليا $= 6.43 - 3.0 = 3.4\ \text{kg}$.', '["","هذه الكتلة الكلية للقطعتين؛ يجب طرح كتلة القطعة السفلى.","افتُرض أن القطعتين متساويتان في الكتلة دون حساب.","طُرحت الكتلة (3.0) من القوة (63.0) مباشرة دون القسمة على $g$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-19T07:48:34.652Z"}'::jsonb),
('mcq', 6, 2, 'التسارع صفر، فمن قانون نيوتن الثاني $F_{\text{T}} = m(0 + g) = (12)(9.80) = 118\ \text{N} \approx 1.2\times10^{2}\ \text{N}$.', '["كُتبت الكتلة بدل الوزن.","السرعة المنتظمة تعني قوة محصلة صفرًا، لا شدًا صفرًا.","","ضوعف الوزن ظنًا أن الحركة إلى أعلى تحتاج إلى شد إضافي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-19T07:48:34.652Z"}'::jsonb),
('mcq', 7, 3, 'من معادلة الحركة: $a = \frac{v_f^2 - v_i^2}{2d} = \frac{(2.0\ \text{m/s})^2}{2(1.0\ \text{m})} = 2.0\ \text{m/s}^2$ إلى أعلى. ومن قانون نيوتن الثاني: $F_{\text{T}} = m(a + g) = (12.0\ \text{kg})(2.0 + 9.80)\ \text{m/s}^2 = 142\ \text{N}$.', '["هذا وزن الدلو؛ لكن الدلو يتسارع إلى أعلى فيكون الشد أكبر من الوزن.","هذه القوة المحصلة $ma$ فقط؛ ونُسي أن الشد يجب أن يوازن الوزن أيضًا.","نُسي تربيع السرعة عند حساب التسارع فكان $1.0\\ \\text{m/s}^2$ بدل $2.0\\ \\text{m/s}^2$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-19T07:48:34.652Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) نقطة يخرج منها سهم أزرق طويل إلى أعلى $\boldsymbol{F}_{\text{T}}$ وسهم أزرق أقصر إلى أسفل $\boldsymbol{F}_{g}$، وبجانبها سهم بنفسجي إلى أعلى $\boldsymbol{a}$، و$+y$ إلى أعلى. (ب) $a = \frac{v_f^2}{2d} = \frac{(2.0)^2}{2(2.0)} = 1.0\ \text{m/s}^2$. (ج) $F_{\text{T}} = m(a + g) = 30.0(1.0 + 9.80) = 324\ \text{N}$، وهي أكبر من الوزن (294 N) لأن الدلو يتسارع إلى أعلى.', '["مخطط صحيح (الشد أطول)","التسارع 1.0 m/s²","المعادلة $F_{\\text{T}} - F_g = ma$","324 N","المقارنة بالوزن 294 N"]'::jsonb, '["$a = \\frac{v_f^2 - v_i^2}{2d} = \\frac{(2.0\\ \\text{m/s})^2}{2(2.0\\ \\text{m})} = 1.0\\ \\text{m/s}^2$","$F_{\\text{T}} - F_g = ma \\Rightarrow F_{\\text{T}} = m(a + g)$","$F_{\\text{T}} = (30.0\\ \\text{kg})(1.0 + 9.80)\\ \\text{m/s}^2 = 324\\ \\text{N}$","$F_g = (30.0)(9.80) = 294\\ \\text{N}$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج) المعادلة والناتج","marks":2},{"element":"المقارنة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب الشد بقانون نيوتن الثالث بجعله مساويًا للوزن","نسيان تربيع السرعة","جعل سهمي الشد والوزن متساويين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-19T07:48:34.652Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) الحبل السفلي يحمل القطعة السفلى: $(6.0)(9.80) = 59\ \text{N}$؛ والعلوي يحمل القطعتين: $(10.0)(9.80) = 98\ \text{N}$. (ب) بتطبيق قانون نيوتن الثاني: السفلي $6.0(2.0 + 9.80) = 71\ \text{N}$، والعلوي $10.0(2.0 + 9.80) = 118\ \text{N} \approx 1.2\times10^{2}\ \text{N}$.', '["الحبل السفلي 59 N","الحبل العلوي 98 N","تطبيق $m(a + g)$ للقطعة السفلى: 71 N","تطبيق $m(a + g)$ للقطعتين: $1.2\\times10^{2}$ N"]'::jsonb, '["ساكنة: $F_{\\text{T}} = (6.0)(9.80) = 58.8 \\approx 59\\ \\text{N}$","ساكنة: الحبل العلوي $= (4.0 + 6.0)(9.80) = 98\\ \\text{N}$","متسارعة: الحبل السفلي $= (6.0)(2.0 + 9.80) = 70.8 \\approx 71\\ \\text{N}$","متسارعة: الحبل العلوي $= (10.0)(2.0 + 9.80) = 118 \\approx 1.2\\times10^{2}\\ \\text{N}$"]'::jsonb, '[{"element":"(أ) الحبلان","marks":2},{"element":"(ب) الحبل السفلي","marks":1},{"element":"(ب) الحبل العلوي","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الحبل العلوي يحمل القطعة العليا فقط","استخدام الوزن فقط في حالة التسارع","استخدام كتلة واحدة لحساب الحبل العلوي في (ب)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-19T07:48:34.652Z"}'::jsonb),
('essay', 3, null::int, null, null, 'بأخذ أعلى موجبًا و$F_{\text{T}} = m(a + g)$: المرحلة الأولى $15.0(1.20 + 9.80) = 165\ \text{N}$؛ الثانية $15.0(0 + 9.80) = 147\ \text{N}$؛ الثالثة $15.0(-1.20 + 9.80) = 129\ \text{N}$. الترتيب: الأولى ثم الثانية ثم الثالثة.', '["العلاقة $F_{\\text{T}} = m(a + g)$ مع الإشارة","165 N","147 N","129 N","الترتيب الصحيح"]'::jsonb, '["$F_{\\text{T}1} = (15.0)(1.20 + 9.80) = 165\\ \\text{N}$","$F_{\\text{T}2} = (15.0)(9.80) = 147\\ \\text{N}$","$F_{\\text{T}3} = (15.0)(-1.20 + 9.80) = 129\\ \\text{N}$"]'::jsonb, '[{"element":"العلاقة والإشارات","marks":1},{"element":"المراحل الثلاث","marks":3},{"element":"الترتيب","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الشد أكبر في المرحلة الثالثة لأن الدلو ما زال صاعدًا","إهمال إشارة التسارع في المرحلة الثالثة","جعل الشد في المرحلة الثانية أكبر من الوزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.653Z"}'::jsonb)
