from (values
('mcq', 1, 'يستند سلّم إلى جدار رأسي أملس كما في الشكل الآتي. أيّ الأسهم المرقمة يمثل اتجاه القوة العمودية التي يؤثر بها الجدار في السلّم عند نقطة التلامس؟', null, '[{"src":"qimg/phys1/c4l3-o10-ladder.svg","alt":"جدار رأسي على يمين الشكل، وسلّم مائل يستند طرفه السفلي إلى الأرض على اليسار وطرفه العلوي إلى الجدار. من نقطة تلامس السلّم بالجدار تخرج أربعة أسهم زرقاء مرقمة: 1 أفقي نحو اليسار بعيدًا عن الجدار، و2 رأسي إلى أعلى بمحاذاة الجدار، و3 مائل إلى أعلى ونحو اليسار عموديًا على السلّم، و4 رأسي إلى أسفل بمحاذاة الجدار."}]'::jsonb, '["السهم 2","السهم 1","السهم 3","السهم 4"]'::jsonb, 'فهم', 'تحديد اتجاه من شكل', 'متوسط', 'الكتاب ص 119 — القوة العمودية'),
('mcq', 2, 'كرة ساكنة داخل مجرى على شكل حرف V، يميل كل من جداريه بزاوية $45^\circ$ عن الأفقي، كما في الشكل الآتي. أيّ الأسهم المرقمة يمثل اتجاه القوة العمودية التي يؤثر بها الجدار الأيمن في الكرة؟', null, '[{"src":"qimg/phys1/c4l3-o10-vgroove.svg","alt":"مجرى على شكل حرف V جداراه مائلان بزاوية 45° عن الأفقي، وداخله كرة تلامس الجدارين. من نقطة تلامس الكرة بالجدار الأيمن تخرج أربعة أسهم زرقاء مرقمة: 1 رأسي إلى أعلى، و2 مائل إلى أعلى ونحو اليسار عموديًا على الجدار الأيمن ويتجه نحو مركز الكرة، و3 مائل إلى أعلى ونحو اليمين موازيًا للجدار الأيمن، و4 أفقي نحو اليسار."}]'::jsonb, '["السهم 2","السهم 1","السهم 3","السهم 4"]'::jsonb, 'تطبيق', 'تحديد اتجاه من شكل', 'صعب', 'الكتاب ص 119 — القوة العمودية'),
('mcq', 3, 'تضغط بيدك صندوقًا على جدار رأسي بقوة مائلة تتجه نحو الجدار وإلى أعلى بزاوية $30^\circ$ فوق الأفقي، فيبقى الصندوق ساكنًا. ما اتجاه القوة العمودية التي يؤثر بها الجدار في الصندوق؟', null, null, '["مائلة بزاوية $30^\\circ$ تحت الأفقي، عكس اتجاه قوة يدك","رأسية إلى أعلى، موازية لسطح الجدار","أفقية، عمودية على سطح الجدار ومبتعدة عنه","أفقية، عمودية على سطح الجدار ومتجهة نحوه"]'::jsonb, 'فهم', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 119 — القوة العمودية'),
('mcq', 4, 'يُسحب صندوق على أرضية أفقية بحبل يميل بزاوية $30^\circ$ فوق الأفقي. ما اتجاه القوة العمودية التي تؤثر بها الأرضية في الصندوق؟', null, null, '["مائلة بزاوية $30^\\circ$ عن الرأسي، عكس ميل الحبل","أفقية، عكس اتجاه السحب","على امتداد الحبل نحو الصندوق","رأسية إلى أعلى، عمودية على الأرضية"]'::jsonb, 'فهم', 'تحديد اتجاه', 'سهل', 'الكتاب ص 119 — القوة العمودية'),
('mcq', 5, 'صندوق ساكن على منحدر يميل عن الأفقي بزاوية $25^\circ$. ما الزاوية بين القوة العمودية المؤثرة فيه وسطح المنحدر؟', null, null, '["$25^\\circ$","$90^\\circ$","$65^\\circ$","$0^\\circ$"]'::jsonb, 'فهم', 'تطبيق قاعدة', 'سهل', 'الكتاب ص 119 — القوة العمودية'),
('mcq', 6, 'أيّ العبارات الآتية عن القوة العمودية صحيحة؟', null, null, '["قوة مجال تؤثر بها الأرض في الجسم إلى أعلى دائمًا","قوة تلامس يؤثر بها سطح في جسم موازية لمستوى التلامس","قوة تلامس من سطح في جسم، عمودية على مستوى التلامس","قوة تلامس رأسية دائمًا وتساوي وزن الجسم"]'::jsonb, 'فهم', 'تمييز عبارة', 'متوسط', 'الكتاب ص 124 — دليل مراجعة الفصل (4-3)'),
('mcq', 7, 'يُضغط صندوق بعصا رأسية إلى أعلى على سقف مائل يميل بزاوية $30^\circ$ عن الأفقي، فيبقى ساكنًا ملاصقًا له. ما اتجاه القوة العمودية التي يؤثر بها السقف في الصندوق؟', null, null, '["عمودية على السقف المائل ومتجهة إلى أسفل نحو الصندوق","رأسية إلى أسفل، عكس اتجاه قوة العصا","موازية لسطح السقف المائل، إلى أسفل","عمودية على السقف المائل ومتجهة إلى أعلى نحوه"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 119 — القوة العمودية'),
('essay', 1, 'سلّم يستند طرفه العلوي إلى جدار رأسي أملس وطرفه السفلي إلى أرضية أفقية. (أ) صف اتجاه القوة العمودية التي يؤثر بها الجدار في السلّم. (ب) صف اتجاه القوة العمودية التي تؤثر بها الأرضية في السلّم. (ج) ما القاعدة التي اعتمدت عليها؟ ولماذا لا تكون القوة العمودية من الجدار عمودية على السلّم نفسه؟', null, null, null, 'فهم', 'وصف وتعليل', 'متوسط', 'الكتاب ص 119 — القوة العمودية'),
('essay', 2, 'كرة ساكنة على منحدر أملس يرتفع نحو اليمين بزاوية $30^\circ$ عن الأفقي، ويمنعها من التدحرج جدار رأسي عند الطرف الأيسر السفلي للمنحدر تستند إليه. (أ) صف اتجاه القوة العمودية التي يؤثر بها المنحدر في الكرة، واذكر زاويتها مع الرأسي. (ب) صف اتجاه القوة العمودية التي يؤثر بها الجدار في الكرة. (ج) لماذا لا تكون أيّ من القوتين معاكسة للوزن تمامًا؟', null, null, null, 'تطبيق', 'وصف وتعليل', 'صعب', 'الكتاب ص 119 — القوة العمودية'),
('essay', 3, 'صندوق صغير ساكن فوق صندوق كبير، والصندوقان ساكنان على منحدر يميل بزاوية $20^\circ$ عن الأفقي، والسطح العلوي للصندوق الكبير موازٍ لسطح المنحدر. صف اتجاه كل من: (أ) القوة العمودية التي يؤثر بها المنحدر في الصندوق الكبير. (ب) القوة العمودية التي يؤثر بها الصندوق الكبير في الصغير. (ج) القوة التي يؤثر بها الصندوق الصغير في الكبير عند سطح تلامسهما. ثم اكتب القاعدة التي استخدمتها.', null, null, null, 'فهم', 'تطبيق قاعدة', 'سهل', 'الكتاب ص 119 — القوة العمودية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
