from (values
('mcq', 1, 1, 'مستوى التلامس هو سطح الجدار الرأسي، فالقوة العمودية أفقية وتتجه بعيدًا عن الجدار نحو السلّم، وهذا السهم 1.', '["هذا السهم موازٍ لسطح الجدار؛ والقوة العمودية عمودية على مستوى التلامس.","","هذا السهم عمودي على السلّم لا على الجدار؛ والمعتبر مستوى التلامس وهو سطح الجدار.","هذا السهم موازٍ للجدار وإلى أسفل؛ والقوة العمودية عمودية على الجدار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-19T07:48:34.653Z"}'::jsonb),
('mcq', 2, 0, 'مستوى التلامس هو سطح الجدار الأيمن المائل بزاوية $45^\circ$، والقوة العمودية عمودية عليه وتتجه بعيدًا عنه نحو الكرة، أي إلى أعلى ونحو اليسار بزاوية $45^\circ$ عن الرأسي، وهو السهم 2.', '["","هذا السهم رأسي؛ والقوة العمودية عمودية على سطح الجدار المائل لا رأسية.","هذا السهم موازٍ لسطح الجدار الأيمن؛ والقوة العمودية عمودية عليه.","هذا السهم أفقي؛ والجدار مائل فالعمودي عليه ليس أفقيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-19T07:48:34.653Z"}'::jsonb),
('mcq', 3, 2, 'مستوى التلامس هو سطح الجدار الرأسي، والقوة العمودية عمودية عليه دائمًا ومتجهة من الجدار نحو الصندوق؛ فهي أفقية مبتعدة عن الجدار مهما كان ميل قوة اليد.', '["القوة العمودية لا تحددها قوة اليد بل مستوى التلامس؛ وسطح الجدار رأسي فالعمودي عليه أفقي.","هذا اتجاه موازٍ لمستوى التلامس؛ والقوة العمودية عمودية عليه.","","القوة العمودية يؤثر بها الجدار في الصندوق فتتجه من السطح نحو الجسم، أي مبتعدة عن الجدار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-19T07:48:34.653Z"}'::jsonb),
('mcq', 4, 3, 'مستوى التلامس بين الصندوق والأرضية أفقي، والقوة العمودية عمودية عليه دائمًا، فهي رأسية إلى أعلى مهما كان اتجاه الحبل؛ قد يتغير مقدارها لا اتجاهها.', '["ميل الحبل لا يغير اتجاه القوة العمودية؛ فمستوى التلامس أفقي والعمودي عليه رأسي.","القوة الأفقية المعاكسة للسحب موازية لسطح التلامس، وهي قوة الاحتكاك لا القوة العمودية.","هذا اتجاه مرتبط بالحبل لا بسطح التلامس؛ والقوة العمودية يؤثر بها سطح الأرضية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-19T07:48:34.654Z"}'::jsonb),
('mcq', 5, 1, 'القوة العمودية عمودية دائمًا على مستوى التلامس، فالزاوية بينها وبين سطح المنحدر $90^\circ$ مهما كانت زاوية الميل.', '["هذه زاوية ميل المنحدر عن الأفقي، وهي أيضًا زاوية القوة العمودية عن الرأسي لا عن السطح.","","هذه الزاوية بين السطح والرأسي؛ والقوة العمودية تصنع زاوية قائمة مع السطح.","هذا يجعل القوة موازية للسطح؛ وهي عمودية عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.654Z"}'::jsonb),
('mcq', 6, 2, 'القوة العمودية قوة تلامس يؤثر بها سطح في جسم آخر، وتكون دائمًا عمودية على مستوى التلامس بين الجسمين.', '["القوة العمودية قوة تلامس لا مجال، واتجاهها يتبع مستوى التلامس.","القوة الموازية لسطح التلامس هي الاحتكاك؛ أما العمودية فعمودية عليه.","","ليست رأسية دائمًا (الجدار، المنحدر)، ولا تساوي الوزن دائمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.654Z"}'::jsonb),
('mcq', 7, 0, 'مستوى التلامس هو سطح السقف المائل بزاوية $30^\circ$ عن الأفقي، فالعمودي عليه يميل بزاوية $30^\circ$ عن الرأسي، والقوة العمودية تتجه من السقف نحو الصندوق، أي إلى أسفل مائلة.', '["","القوة العمودية لا تعاكس قوة العصا بالضرورة؛ فالسقف مائل والقوة عمودية على سطحه، أي تميل بزاوية $30^\\circ$ عن الرأسي.","الاتجاه الموازي لسطح التلامس ليس اتجاه القوة العمودية.","القوة العمودية يؤثر بها السقف في الصندوق فتتجه من السطح نحو الجسم، أي إلى أسفل لا نحو السقف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-19T07:48:34.654Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) أفقية، عمودية على سطح الجدار، وتتجه بعيدًا عن الجدار نحو السلّم. (ب) رأسية إلى أعلى، عمودية على سطح الأرضية. (ج) القوة العمودية عمودية دائمًا على مستوى التلامس بين الجسمين؛ ومستوى التلامس عند الطرف العلوي هو سطح الجدار لا السلّم، لذلك تكون عمودية على الجدار.', '["قوة الجدار أفقية بعيدًا عنه","قوة الأرضية رأسية إلى أعلى","القاعدة: عمودية على مستوى التلامس","مستوى التلامس هو سطح الجدار"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج) القاعدة","marks":1},{"element":"(ج) التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–3 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم قوة الجدار عمودية على السلّم","رسم قوة الجدار رأسية","جعل قوة الأرضية عمودية على السلّم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-19T07:48:34.654Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) عمودية على سطح المنحدر، تتجه إلى أعلى ونحو اليسار مبتعدة عن السطح، وتصنع زاوية $30^\circ$ مع الرأسي (العمودي على سطح مائل بزاوية $30^\circ$ عن الأفقي يميل بزاوية $30^\circ$ عن الرأسي). (ب) أفقية نحو اليمين، عمودية على سطح الجدار ومبتعدة عنه. (ج) لأن القوة العمودية لا تُحدد باتجاه الوزن، بل تكون دائمًا عمودية على مستوى التلامس بين الجسمين؛ ومستوى التلامس مع المنحدر مائل ومع الجدار رأسي، فلا تكون أي منهما رأسية.', '["قوة المنحدر عمودية على سطحه إلى أعلى ونحو اليسار","زاويتها $30^\\circ$ مع الرأسي","قوة الجدار أفقية نحو اليمين مبتعدة عنه","التعليل بقاعدة التعامد على مستوى التلامس"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الاتجاه","marks":1},{"element":"(أ) الزاوية","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–3 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم قوة المنحدر رأسية إلى أعلى","جعل قوة الجدار نحو الجدار أو مائلة","الخلط بين زاوية الميل عن الأفقي والزاوية مع الرأسي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-19T07:48:34.655Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) عمودية على سطح المنحدر، إلى أعلى ومبتعدة عنه، وتميل بزاوية $20^\circ$ عن الرأسي. (ب) عمودية على سطح التلامس بين الصندوقين، وهو موازٍ للمنحدر، فهي في اتجاه القوة في (أ): تميل بزاوية $20^\circ$ عن الرأسي ومتجهة نحو الصندوق الصغير. (ج) وفق قانون نيوتن الثالث تساوي القوة في (ب) في المقدار وتعاكسها في الاتجاه: عمودية على سطح التلامس ومتجهة نحو الصندوق الكبير (إلى أسفل مائلة بزاوية $20^\circ$ عن الرأسي). القاعدة: القوة العمودية قوة تلامس تكون دائمًا عمودية على مستوى التلامس بين الجسمين.', '["(أ) عمودية على المنحدر بميل $20^\\circ$ عن الرأسي","(ب) عمودية على سطح التلامس بين الصندوقين نحو الصغير","(ج) معاكسة للقوة في (ب) نحو الكبير","القاعدة العامة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"القاعدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–3 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم قوة الصندوق الكبير في الصغير رأسية إلى أعلى","جعل القوة في (ج) في اتجاه القوة في (ب)","نسيان أن سطح تلامس الصندوقين موازٍ للمنحدر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-19T07:48:34.655Z"}'::jsonb)
