('mcq', 1, 'يبيّن الشكل الآتي صندوقًا كتلته 10.0 kg ساكنًا على أرضية أفقية في ثلاث حالات. ما مقدار القوة العمودية التي تؤثر بها الأرضية في الصندوق في الحالة (2)، حيث يسحبه خيط رأسي إلى أعلى بقوة لا تكفي لرفعه؟', null, '[{"src":"qimg/phys1/c4l3-o11-three.svg","alt":"ثلاث حالات مرقمة (1) و(2) و(3) لصندوق مكتوب عليه 10.0 kg على أرضية أفقية. (1): الصندوق وحده. (2): خيط رأسي مربوط بأعلى الصندوق، وبجانبه سهم أزرق إلى أعلى مكتوب عنده 30.0 N. (3): سهم أزرق إلى أسفل فوق الصندوق مكتوب عنده 30.0 N وبجانبه عبارة «يد تضغط»."}]'::jsonb, '["98.0 N","128 N","30.0 N","68.0 N"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 119 — القوة العمودية'),
('mcq', 2, 'صندوق كتلته 5.0 kg ساكن على طاولة أفقية، وتضغط عليه بيدك رأسيًا إلى أسفل بقوة مقدارها 20 N. ما مقدار القوة العمودية التي تؤثر بها الطاولة في الصندوق؟', null, null, '["69 N","49 N","29 N","20 N"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 119 — القوة العمودية'),
('mcq', 3, 'يُسلم صالح صندوقًا كتلته 13 kg إلى شخص كتلته 61 kg يقف على منصة. ما مقدار القوة العمودية التي تؤثر بها المنصة في الشخص وهو يحمل الصندوق ساكنًا؟', null, null, '["$6.0\\times10^{2}\\ \\text{N}$","$1.3\\times10^{2}\\ \\text{N}$","$7.3\\times10^{2}\\ \\text{N}$","$74\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 120 — مراجعة 4-3'),
('mcq', 4, 'يجلس طفل كتلته 45 kg في أرجوحة كتلتها 3.2 kg مربوطة بغصن شجرة. تدلّى الغصن حتى استندت قدما الطفل إلى الأرض وأصبحت قوة الشد في حبل الأرجوحة 220 N، والطفل ساكن. اعتبر الطفل والأرجوحة نظامًا واحدًا، فما مقدار القوة العمودية التي تؤثر بها الأرض في قدمي الطفل؟', null, null, '["$2.2\\times10^{2}\\ \\text{N}$","$2.5\\times10^{2}\\ \\text{N}$","$6.9\\times10^{2}\\ \\text{N}$","$4.7\\times10^{2}\\ \\text{N}$"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 128–129 — اختبار مقنن'),
('mcq', 5, 'يبيّن الشكل الآتي صندوقًا وزنه 60 N ساكنًا على أرضية أفقية في أربعة أوضاع: (1) وحده، (2) يسحبه خيط رأسي إلى أعلى بقوة 20 N، (3) يوضع فوقه ثقل وزنه 20 N، (4) يسحبه خيط رأسي إلى أعلى بقوة 40 N. ما ترتيب الأوضاع تنازليًا حسب مقدار القوة العمودية بين الصندوق والأرضية؟', null, '[{"src":"qimg/phys1/c4l3-o11-rank.svg","alt":"أربعة أوضاع مرقمة (1) إلى (4) لصندوق مكتوب عليه 60 N على أرضية أفقية. (1): الصندوق وحده. (2): خيط رأسي مربوط بأعلى الصندوق وبجانبه سهم أزرق إلى أعلى مكتوب عنده 20 N. (3): ثقل أصفر صغير فوق الصندوق مكتوب فوقه 20 N. (4): خيط رأسي مربوط بأعلى الصندوق وبجانبه سهم أزرق إلى أعلى مكتوب عنده 40 N."}]'::jsonb, '["(3) ثم (1) ثم (2) ثم (4)","(4) ثم (2) ثم (1) ثم (3)","(1) ثم (2) ثم (3) ثم (4)","(3) ثم (1) ثم (4) ثم (2)"]'::jsonb, 'تحليل', 'ترتيب', 'متوسط', 'الكتاب ص 125 — تقويم الفصل 4 (إتقان المفاهيم)'),
('mcq', 6, 'في أيّ الحالات الآتية يساوي مقدار القوة العمودية المؤثرة في صندوق وزنَه؟', null, null, '["في جميع الحالات التي يلامس فيها الصندوق سطحًا أيًا كان","على أرضية أفقية وخيط رأسي يسحبه إلى أعلى","على أرضية أفقية مع يد تضغط عليه رأسيًا إلى أسفل","على أرضية أفقية دون قوى رأسية أخرى ودون تسارع رأسي"]'::jsonb, 'فهم', 'استنتاج', 'سهل', 'الكتاب ص 119 — القوة العمودية'),
('mcq', 7, 'صندوق كتلته 4.0 kg على أرضية أفقية مربوط بخيط رأسي. ما أقل قوة شد في الخيط تجعل القوة العمودية بين الصندوق والأرضية صفرًا؟', null, null, '["4.0 N","0 N","39 N","78 N"]'::jsonb, 'تحليل', 'استنتاج بالحساب', 'صعب', 'الكتاب ص 119 — القوة العمودية'),
('essay', 1, 'صندوق كتلته 8.00 kg على طاولة أفقية. احسب القوة العمودية التي تؤثر بها الطاولة في الصندوق بتطبيق قانون نيوتن الثاني في كل حالة، ثم استنتج هل القوة العمودية تساوي الوزن دائمًا: (أ) الصندوق وحده ساكن. (ب) يسحبه خيط رأسي إلى أعلى بقوة 50.0 N فيبقى ساكنًا. (ج) تضغط عليه يد رأسيًا إلى أسفل بقوة 50.0 N.', null, null, null, 'تطبيق', 'حساب واستنتاج', 'متوسط', 'الكتاب ص 119 — القوة العمودية'),
('essay', 2, 'شخص كتلته 61 kg يقف على منصة ويحمل صندوقًا كتلته 13 kg. (أ) احسب القوة العمودية التي تؤثر بها المنصة في الشخص وهو يحمل الصندوق ساكنًا. (ب) إذا رفع الصندوق بيديه بتسارع $1.0\ \text{m/s}^2$ إلى أعلى وبقي جسمه ساكنًا، فاحسب القوة العمودية الجديدة، وفسّر سبب تغيرها.', null, null, null, 'تحليل', 'حساب وتفسير', 'صعب', 'الكتاب ص 120 — مراجعة 4-3'),
('essay', 3, 'صندوق كتلته 6.0 kg على طاولة أفقية، وفوقه كتاب كتلته 2.0 kg، ويسحب خيط رأسي مربوط بالصندوق إلى أعلى بقوة 30.0 N، والمجموعة ساكنة. باعتبار الاتجاه الموجب إلى أعلى: (أ) احسب القوة العمودية التي يؤثر بها الصندوق في الكتاب. (ب) ما القوة التي يؤثر بها الكتاب في الصندوق؟ (ج) احسب القوة العمودية التي تؤثر بها الطاولة في الصندوق بتطبيق قانون نيوتن الثاني على الصندوق. (د) قارن القوة في (ج) بوزن الصندوق.', null, null, null, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 119 — القوة العمودية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
