select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'الصندوق ساكن: $F_{\text{N}} + F_{\text{T}} - F_g = 0$، إذن $F_{\text{N}} = F_g - F_{\text{T}} = (10.0)(9.80) - 30.0 = 68.0\ \text{N}$.', '["هذا وزن الصندوق؛ والقوة العمودية لا تساويه هنا لأن الخيط يحمل جزءًا منه.","أُضيفت قوة الخيط إلى الوزن؛ وهذا يصح عند الضغط إلى أسفل لا عند السحب إلى أعلى.","هذه قوة الخيط نفسها لا القوة العمودية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-19T07:48:34.655Z"}'::jsonb),
('mcq', 2, 0, 'الصندوق ساكن: $F_{\text{N}} - F_g - F = 0$، إذن $F_{\text{N}} = (5.0)(9.80) + 20 = 69\ \text{N}$، وهي أكبر من الوزن، حيث $F$ قوة اليد.', '["","هذا وزن الصندوق فقط؛ ونُسيت قوة اليد إلى أسفل.","طُرحت قوة اليد من الوزن كأنها إلى أعلى.","هذه قوة اليد وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-19T07:48:34.656Z"}'::jsonb),
('mcq', 3, 2, 'الشخص والصندوق نظام ساكن: $F_{\text{N}} = (61 + 13)(9.80) = 725\ \text{N} \approx 7.3\times10^{2}\ \text{N}$.', '["هذا وزن الشخص وحده؛ ونُسي أن الصندوق يضغط على يديه إلى أسفل.","هذا وزن الصندوق وحده.","","جُمعت الكتلتان دون الضرب في $g$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (51%)"}],"at":"2026-11-19T07:48:34.656Z"}'::jsonb),
('mcq', 4, 1, 'النظام (الطفل والأرجوحة) متزن، ويؤثر فيه الشد والقوة العمودية إلى أعلى ووزنه إلى أسفل: $F_{\text{N}} + F_{\text{T}} - F_g = 0$، إذن $F_{\text{N}} = (45 + 3.2)(9.80) - 220 = 472 - 220 = 252\ \text{N} \approx 2.5\times10^{2}\ \text{N}$.', '["هذا مقدار قوة الشد، وهو أيضًا ما ينتج عن طرح الشد من وزن الطفل وحده (441 N)؛ لكن النظام الطفل والأرجوحة معًا، فيُستخدم وزنهما معًا.","","جُمع الشد مع الوزن؛ والشد إلى أعلى فيُطرح.","هذا وزن الطفل والأرجوحة؛ ونُسي أن الحبل يحمل جزءًا منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.656Z"}'::jsonb),
('mcq', 5, 0, 'من الاتزان: (1) $F_{\text{N}} = 60\ \text{N}$، (2) $60 - 20 = 40\ \text{N}$، (3) $60 + 20 = 80\ \text{N}$، (4) $60 - 40 = 20\ \text{N}$؛ فالترتيب التنازلي (3) ثم (1) ثم (2) ثم (4).', '["","هذا ترتيب تصاعدي معكوس؛ فالسحب إلى أعلى يقلل القوة العمودية.","هذا ترتيب الأرقام لا القوى؛ والثقل في (3) يزيد القوة العمودية فهي الأكبر.","السحب بـ 40 N يقلل القوة العمودية أكثر من السحب بـ 20 N، فالوضع (4) هو الأصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-19T07:48:34.656Z"}'::jsonb),
('mcq', 6, 3, 'بتطبيق قانون نيوتن الثاني رأسيًا مع تسارع صفر: إذا لم تؤثر في الصندوق قوى رأسية غير الوزن والقوة العمودية، كان $F_{\text{N}} = F_g$؛ وأي قوة رأسية إضافية تغير القوة العمودية.', '["القوة العمودية لا تساوي الوزن دائمًا؛ فتتغير بالسحب أو الضغط أو التسارع.","الخيط يحمل جزءًا من الوزن، فتصبح القوة العمودية أقل من الوزن.","قوة اليد تُضاف إلى الوزن، فتصبح القوة العمودية أكبر من الوزن.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.656Z"}'::jsonb),
('mcq', 7, 2, 'من $F_{\text{N}} = F_g - F_{\text{T}}$: تصبح $F_{\text{N}} = 0$ عندما $F_{\text{T}} = F_g = (4.0)(9.80) = 39\ \text{N}$.', '["كُتبت الكتلة بدل الوزن.","دون شد تكون القوة العمودية مساوية للوزن لا صفرًا.","","يكفي أن يساوي الشد الوزن مرة واحدة لتصبح القوة العمودية صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-19T07:48:34.657Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الوزن $F_g = (8.00)(9.80) = 78.4\ \text{N}$، والتسارع صفر في الحالات الثلاث. (أ) $F_{\text{N}} = 78.4\ \text{N}$. (ب) $F_{\text{N}} + 50.0 - 78.4 = 0$، إذن $F_{\text{N}} = 28.4\ \text{N}$. (ج) $F_{\text{N}} - 50.0 - 78.4 = 0$، إذن $F_{\text{N}} = 128.4\ \text{N}$. الاستنتاج: القوة العمودية لا تساوي وزن الجسم دائمًا؛ فهي أقل منه عند السحب إلى أعلى وأكبر منه عند الضغط إلى أسفل.', '["الوزن 78.4 N","(أ) 78.4 N","(ب) 28.4 N","(ج) 128.4 N","الاستنتاج"]'::jsonb, '["$F_g = (8.00\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 78.4\\ \\text{N}$","(أ) $F_{\\text{N}} - F_g = 0 \\Rightarrow F_{\\text{N}} = 78.4\\ \\text{N}$","(ب) $F_{\\text{N}} + F_{\\text{T}} - F_g = 0 \\Rightarrow F_{\\text{N}} = 78.4 - 50.0 = 28.4\\ \\text{N}$","(ج) $F_{\\text{N}} = 78.4 + 50.0 = 128.4\\ \\text{N}$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–3 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل القوة العمودية تساوي الوزن في الحالات الثلاث","عكس إشارة قوة الخيط أو اليد","كتابة الكتلة بدل الوزن"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.657Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) $F_{\text{N}} = (61 + 13)(9.80) = 725\ \text{N} \approx 7.3\times10^{2}\ \text{N}$. (ب) القوة التي يؤثر بها الشخص في الصندوق: $13(1.0 + 9.80) = 140\ \text{N}$ إلى أعلى، فيؤثر الصندوق في يديه بقوة 140 N إلى أسفل (قانون نيوتن الثالث). جسم الشخص ساكن: $F_{\text{N}} = (61)(9.80) + 140 = 738\ \text{N} \approx 7.4\times10^{2}\ \text{N}$. زادت القوة العمودية لأن الصندوق المتسارع يضغط على اليدين بقوة أكبر من وزنه.', '["(أ) $7.3\\times10^{2}$ N","قوة اليدين في الصندوق 140 N","تطبيق القانون الثالث على اليدين","(ب) $7.4\\times10^{2}$ N","تفسير الزيادة"]'::jsonb, '["(أ) $F_{\\text{N}} = (74\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 725\\ \\text{N}$","(ب) قوة الشخص في الصندوق: $m(a + g) = (13)(1.0 + 9.80) = 140\\ \\text{N}$","قوة الصندوق في اليدين: 140 N إلى أسفل","$F_{\\text{N}} = (61)(9.80) + 140 = 598 + 140 = 738\\ \\text{N}$"]'::jsonb, '[{"element":"(أ)","marks":2},{"element":"(ب) قوة الصندوق في اليدين","marks":1},{"element":"(ب) القوة العمودية","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب القوة العمودية في (ب) مساوية لـ (أ)","إغفال قانون نيوتن الثالث بين اليدين والصندوق","جمع الكتل دون الضرب في g"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (51%)"}],"at":"2026-11-19T07:48:34.657Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الكتاب متزن: $F_{\text{N}} = m g = (2.0)(9.80) = 19.6\ \text{N}$ إلى أعلى. (ب) وفق قانون نيوتن الثالث: 19.6 N إلى أسفل. (ج) القوى على الصندوق: القوة العمودية من الطاولة والشد (30.0 N) إلى أعلى، ووزنه (58.8 N) وقوة الكتاب (19.6 N) إلى أسفل، وتسارعه صفر: $F_{\text{N}} + 30.0 - 58.8 - 19.6 = 0$، إذن $F_{\text{N}} = 48.4\ \text{N}$ إلى أعلى. (د) 48.4 N أقل من وزن الصندوق (58.8 N)؛ فالقوة العمودية لا تساوي وزن الجسم دائمًا، بل تُحدد بقانون نيوتن الثاني من جميع القوى المؤثرة فيه.', '["(أ) 19.6 N إلى أعلى","(ب) 19.6 N إلى أسفل بقانون نيوتن الثالث","(ج) معادلة القانون الثاني للصندوق بأربع قوى","(ج) 48.4 N","(د) المقارنة والاستنتاج"]'::jsonb, '["قوة الصندوق في الكتاب: $(2.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 19.6\\ \\text{N}$","$F_g = (6.0\\ \\text{kg})(9.80\\ \\text{m/s}^2) = 58.8\\ \\text{N}$","$F_{\\text{N}} + F_{\\text{T}} - F_g - 19.6\\ \\text{N} = 0$","$F_{\\text{N}} = 58.8 + 19.6 - 30.0 = 48.4\\ \\text{N}$"]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: جميع القيم صحيحة بالإشارات والوحدات مع المقارنة والاستنتاج"},{"level":"1–4 درجات","description":"بعض العناصر صحيحة، أو خطأ في إحدى القوى المؤثرة في الصندوق أو في الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال قوة الكتاب في الصندوق","جمع قوة الشد مع الوزن بدل طرحها","جعل القوة العمودية تساوي وزن الصندوق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-11-19T07:48:34.657Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L3-O11') and x.type = v.type and x.number = v.number
