insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P1-C4-L3-O12'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبيّن الشكل الآتي كتابًا على طاولة، ومخطط الجسم الحر لكل منهما منفصلًا. السهم 1 قوة الطاولة في الكتاب، و2 وزن الكتاب، و3 قوة الكتاب في الطاولة، و4 قوة الأرضية في الطاولة، و5 وزن الطاولة. أيّ سهمين يمثلان قوتين متعاكستين تؤثران في الجسم نفسه وليستا زوجي تأثير متبادل؟', null, '[{"src":"qimg/phys1/c4l3-o12-book-table.svg","alt":"شكلان منفصلان. على اليسار كتاب (مستطيل أحمر) يخرج من أعلاه سهم أزرق إلى أعلى رقمه 1، ومن أسفله سهم أزرق إلى أسفل رقمه 2. وعلى اليمين طاولة: من منتصف سطحها سهم أزرق إلى أسفل رقمه 3، ومن الطرف الأيسر لسطحها سهم أزرق إلى أعلى رقمه 4، ومن أسفل رجلها اليمنى سهم أزرق إلى أسفل رقمه 5."}]'::jsonb, '["السهمان 1 و3","السهمان 2 و3","السهمان 1 و2","السهمان 3 و5"]'::jsonb, 'تحليل', 'تمييز من شكل', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 2, 'كرة ساكنة على طاولة. القوة العمودية التي تؤثر بها الطاولة في الكرة ووزن الكرة متساويتان في المقدار ومتعاكستان في الاتجاه. لماذا لا تُعدّان زوجي تأثير متبادل؟', null, null, '["لأنهما تؤثران في الجسم نفسه وهو الكرة","لأنهما غير متساويتين في المقدار في الحقيقة","لأنهما تؤثران في الاتجاه نفسه","لأن الكرة ساكنة، والأزواج للأجسام المتحركة فقط"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 3, 'أيّ الأزواج الآتية زوجا تأثير متبادل؟', null, null, '["وزن تفاحة معلقة بغصن، وقوة شد الغصن لها إلى أعلى","القوة العمودية على كتاب، ووزن الكتاب","قوة دفع شخص لعربة، وقوة الاحتكاك على العربة","قوة جذب الأرض لتفاحة، وقوة جذب التفاحة للأرض"]'::jsonb, 'تحليل', 'تمييز', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 4, 'يقف شخص في مصعد يتسارع إلى أعلى، فتكون القوة العمودية المؤثرة فيه أكبر من وزنه. قال طالب: «هذا يخالف قانون نيوتن الثالث». ما الرد الصحيح؟', null, null, '["يخالفه؛ لأن القوة العمودية والوزن زوجا تأثير متبادل","لا يخالفه؛ فهما في الشخص نفسه وليستا زوجًا","لا يخالفه؛ لأن القانون الثالث لا ينطبق على الأجسام المتسارعة","يخالفه؛ ولذلك يكون وزن الشخص أكبر من القوة العمودية"]'::jsonb, 'تحليل', 'تقويم ادعاء', 'صعب', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 5, 'أيّ القوى الآتية يمكن أن يلغي بعضها بعضًا عند جمعها لإيجاد القوة المحصلة؟', null, null, '["قوتان متعاكستان تؤثران في الجسم نفسه","قوتا زوجي التأثير المتبادل","أيّ قوتين متساويتين في المقدار في أي جسمين","قوتان متعاكستان تؤثران في جسمين مختلفين"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 6, 'كتاب وزنه 10 N ساكن على طاولة أفقية، وتضغط عليه بيدك رأسيًا إلى أسفل بقوة 4 N. أيّ العبارات الآتية صحيحة؟', null, null, '["القوة العمودية على الكتاب 10 N؛ لأنها زوج تأثير متبادل مع وزنه","قوة يدك في الكتاب وقوة الطاولة فيه زوجا تأثير متبادل","القوة العمودية على الكتاب 14 N، وزوجها وزن الكتاب","القوة العمودية على الكتاب 14 N، وزوجها قوة الكتاب في الطاولة"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 7, 'مصباح معلق ساكن بسلك رأسي. ما القوة التي تشكّل زوجي تأثير متبادل مع قوة الشد التي يؤثر بها السلك في المصباح؟', null, null, '["وزن المصباح الذي تؤثر به الأرض فيه رأسيًا إلى أسفل","قوة جذب المصباح للأرض المتجهة إلى أعلى","القوة التي يؤثر بها المصباح في السلك إلى أسفل","القوة التي يؤثر بها السقف في السلك إلى أعلى"]'::jsonb, 'تطبيق', 'تحديد زوج', 'سهل', 'الكتاب ص 116 — قوى الشد في الحبال والخيوط'),
('essay', 1, 'يقف طائر على قمة مبنى. (أ) ارسم مخطط الجسم الحر لكل من الطائر والمبنى منفصلين (ارسم القوى الرأسية فقط). (ب) أشر إلى أزواج التأثير المتبادل بين المخططين. (ج) حدّد في مخطط الطائر قوتين متعاكستين ليستا زوجي تأثير متبادل، وعلّل.', null, null, null, 'تحليل', 'تمثيل وتمييز', 'متوسط', 'الكتاب ص 125 — تقويم الفصل 4 (إتقان المفاهيم)'),
('essay', 2, 'قال طالب: «القوة العمودية التي تؤثر بها الطاولة في كتاب هي رد فعل وزن الكتاب». قوّم هذه العبارة، ثم حدّد الزوج الصحيح لكل من القوتين.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('essay', 3, 'قارن في جدول بين قوتي زوجي التأثير المتبادل وقوتين متعاكستين متوازنتين تؤثران في الجسم نفسه، من حيث: (أ) الجسم الذي تؤثر فيه كل قوة. (ب) مقدار القوتين. (ج) إمكانية جمعهما لإيجاد القوة المحصلة. ثم أعط مثالًا لكل منهما من حالة كرة ساكنة على طاولة.', null, null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 113 — قانون نيوتن الثالث')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
