insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'السهمان 1 و2 يؤثران في الكتاب نفسه وهما متعاكستان (ومتساويتان لأن الكتاب متزن)، لكنهما من تفاعلين مختلفين (الكتاب مع الطاولة، والكتاب مع الأرض)، فليسا زوجي تأثير متبادل.', '["هذان زوجا تأثير متبادل (الطاولة في الكتاب، والكتاب في الطاولة)، ويؤثران في جسمين مختلفين.","يؤثران في جسمين مختلفين ولهما الاتجاه نفسه، فلا يحققان الوصف.","","يؤثران في الطاولة لكنهما في الاتجاه نفسه (إلى أسفل) لا متعاكستين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.658Z"}'::jsonb),
('mcq', 2, 0, 'قوتا زوج التأثير المتبادل تؤثران في جسمين مختلفين؛ أما هاتان القوتان فتؤثران في الكرة نفسها، فهما مجرد قوتين على الجسم نفسه تحققان اتزانه.', '["","هما متساويتان في هذه الحالة لأن الكرة متزنة؛ والسبب أنهما في الجسم نفسه.","هما متعاكستان في الاتجاه؛ والسبب أنهما تؤثران في الكرة نفسها.","زوجا التأثير المتبادل موجودان في الأجسام الساكنة والمتحركة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.658Z"}'::jsonb),
('mcq', 3, 3, 'زوجا التأثير المتبادل ينتجان عن تفاعل الجسمين نفسيهما ويؤثر كل منهما في أحدهما: الأرض تجذب التفاحة، والتفاحة تجذب الأرض.', '["القوتان تؤثران في التفاحة نفسها؛ فهما متوازنتان وليستا زوجًا.","القوتان تؤثران في الكتاب نفسه، ومن تفاعلين مختلفين.","القوتان تؤثران في العربة نفسها، ومسبباهما جسمان مختلفان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.658Z"}'::jsonb),
('mcq', 4, 1, 'القانون الثالث يتطلب تساوي قوتي الزوج (أرضية المصعد في الشخص، والشخص في الأرضية). أما القوة العمودية والوزن فيؤثران في الشخص نفسه، والفرق بينهما هو القوة المحصلة التي تكسبه التسارع.', '["القوة العمودية والوزن ليسا زوجًا؛ فهما في الجسم نفسه ومن تفاعلين مختلفين.","","القانون الثالث ينطبق دائمًا، حتى على الأجسام المتسارعة.","الشخص يتسارع إلى أعلى، فالقوة العمودية أكبر من وزنه وفق قانون نيوتن الثاني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-19T07:48:34.658Z"}'::jsonb),
('mcq', 5, 0, 'القوة المحصلة لجسم هي مجموع القوى المؤثرة فيه هو فقط؛ فقوتان متعاكستان متساويتان على الجسم نفسه تلغي إحداهما الأخرى، أما قوتا الزوج فكل منهما في جسم مختلف.', '["","قوتا الزوج تؤثران في جسمين مختلفين، فلا تُجمعان في محصلة جسم واحد.","لا تُجمع إلا القوى المؤثرة في الجسم نفسه.","القوى في أجسام مختلفة لا تُجمع معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-19T07:48:34.658Z"}'::jsonb),
('mcq', 6, 3, 'الكتاب متزن: $F_{\text{N}} = 10 + 4 = 14\ \text{N}$ إلى أعلى. وهذه القوة تؤثر بها الطاولة في الكتاب، فزوجها القوة التي يؤثر بها الكتاب في الطاولة (14 N إلى أسفل) وتؤثر في جسم آخر هو الطاولة؛ أما الوزن وقوة اليد فقوتان أخريان على الكتاب نفسه.', '["القوة العمودية والوزن يؤثران في الكتاب نفسه فليسا زوجًا؛ ومن اتزان الكتاب تساوي القوة العمودية 14 N.","القوتان تؤثران في الكتاب نفسه، ومن تفاعلين مختلفين (مع اليد ومع الطاولة)، فليستا زوجًا.","مقدار 14 N صحيح، لكن الوزن يؤثر في الكتاب نفسه؛ وزوج القوة العمودية هو قوة الكتاب في الطاولة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-19T07:48:34.658Z"}'::jsonb),
('mcq', 7, 2, 'قوة الشد هي قوة السلك في المصباح، وزوجها قوة المصباح في السلك: مساوية في المقدار ومعاكسة في الاتجاه (إلى أسفل) وتؤثر في السلك.', '["الوزن يؤثر في المصباح نفسه ويوازن الشد، فلا يشكل معه زوجًا.","هذه زوج الوزن (تفاعل المصباح والأرض) لا زوج الشد.","","هذه من تفاعل السقف والسلك لا السلك والمصباح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-19T07:48:34.659Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الطائر: نقطة يخرج منها $\boldsymbol{F}_{\text{N}}$ إلى أعلى (قوة المبنى في الطائر) و$\boldsymbol{F}_{g}$ إلى أسفل (جذب الأرض للطائر). المبنى: من بين قواه قوة الطائر فيه إلى أسفل، إضافة إلى وزنه إلى أسفل وقوة الأرض فيه إلى أعلى. (ب) قوة المبنى في الطائر إلى أعلى وقوة الطائر في المبنى إلى أسفل زوجا تأثير متبادل، ويُوصل بينهما بخط متقطع. (ج) القوة العمودية ووزن الطائر متعاكستان ومتساويتان، لكنهما تؤثران في الطائر نفسه ومن تفاعلين مختلفين (مع المبنى ومع الأرض)، فليستا زوجًا.', '["مخطط الطائر","مخطط المبنى متضمنًا قوة الطائر فيه","تحديد الزوج بين المخططين","تحديد القوتين على الطائر وتعليل أنهما ليستا زوجًا"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) المخططان","marks":2},{"element":"(ب)","marks":1},{"element":"(ج)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم المخططين في مخطط واحد","اعتبار الوزن والقوة العمودية زوجي تأثير متبادل","إغفال قوة الطائر في المبنى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.659Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العبارة خاطئة؛ لأن القوة العمودية ووزن الكتاب تؤثران في الكتاب نفسه، ومسبباهما مختلفان (الطاولة والأرض)، وقد لا يتساويان (مثلًا عند الضغط على الكتاب)؛ أما قوتا الزوج فتؤثران في جسمين مختلفين ومتساويتان دائمًا. الزوج الصحيح للقوة العمودية: القوة التي يؤثر بها الكتاب في الطاولة إلى أسفل. والزوج الصحيح للوزن: القوة التي يجذب بها الكتاب الأرض إلى أعلى.', '["الحكم بخطأ العبارة","التعليل: الجسم نفسه ومسببان مختلفان","زوج القوة العمودية","زوج الوزن"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل","marks":1},{"element":"زوج القوة العمودية","marks":1},{"element":"زوج الوزن","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–3 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على العبارة لأن القوتين متساويتان ومتعاكستان","جعل زوج الوزن هو القوة العمودية","نسيان أن الكتاب يجذب الأرض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.659Z"}'::jsonb),
('essay', 3, null::int, null, null, 'زوجا التأثير المتبادل: (أ) تؤثران في جسمين مختلفين. (ب) متساويتان في المقدار دائمًا. (ج) لا تُجمعان في محصلة جسم واحد. مثاله: قوة الطاولة في الكرة إلى أعلى وقوة الكرة في الطاولة إلى أسفل. القوتان المتعاكستان على الجسم نفسه: (أ) تؤثران في الجسم نفسه. (ب) تتساويان فقط إذا كان الجسم متزنًا. (ج) تُجمعان، وقد تلغي إحداهما الأخرى. مثالهما: قوة الطاولة في الكرة إلى أعلى ووزن الكرة إلى أسفل.', '["(أ) جسمان مختلفان / الجسم نفسه","(ب) تساوٍ دائم / تساوٍ عند الاتزان فقط","(ج) لا تُجمعان / تُجمعان","مثال الزوج","مثال القوتين على الكرة"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة (أ)","marks":1},{"element":"المقارنة (ب)","marks":1},{"element":"المقارنة (ج)","marks":1},{"element":"المثالان","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القوتين على الجسم نفسه متساويتان دائمًا","جمع قوتي الزوج","اختيار الوزن والقوة العمودية مثالًا للزوج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.659Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
