('mcq', 1, 'يبيّن الشكل الآتي كرة كتلتها 0.18 kg تسقط نحو الأرض، والسهمان 1 و2 زوجا تأثير متبادل بين الكرة والأرض. لماذا لا نلاحظ تسارع الأرض نحو الكرة؟', null, '[{"src":"qimg/phys1/c4l3-o13-ball-earth.svg","alt":"الأرض دائرة زرقاء كبيرة مكتوب عليها «الأرض» وتحتها 6.0 × 10^24 kg، وفوقها كرة صغيرة مكتوب بجانبها «الكرة» و0.18 kg. من الكرة يخرج سهم أزرق إلى أسفل رقمه 1، ومن سطح الأرض يخرج سهم أزرق إلى أعلى رقمه 2 مساوٍ له في الطول، وبينهما خط متقطع يصل بينهما. وعلى اليمين سهم إلى أعلى مكتوب عنده +y."}]'::jsonb, '["لأن القوة 2 أصغر كثيرًا من القوة 1 في المقدار","لأن كتلة الأرض هائلة فتسارعها متناهٍ في الصغر","لأن الكرة لا تؤثر في الأرض بأي قوة","لأن القوة 2 تلغي القوة 1 فلا تتسارع الأرض"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 114–115 — مثال 3: تسارع الأرض'),
('mcq', 2, 'تسقط كرة نحو الأرض. كيف يقارن مقدار تسارع الكرة بمقدار تسارع الأرض؟', null, null, '["متساويان؛ لأن القوتين المؤثرتين فيهما متساويتان في المقدار","تسارع الأرض أكبر؛ لأن كتلتها أكبر","تسارع الكرة أكبر بنسبة كتلة الأرض إلى كتلة الكرة","تسارع الأرض صفر تمامًا؛ لأنها لا تتأثر"]'::jsonb, 'فهم', 'مقارنة', 'صعب', 'الكتاب ص 114–115 — مثال 3: تسارع الأرض'),
('mcq', 3, 'يقفز شخص كتلته 60 kg، فيكون وزنه 588 N. ما مقدار التسارع الذي تكتسبه الأرض (كتلتها $6.0\times10^{24}\ \text{kg}$) نتيجة القوة التي يؤثر بها الشخص فيها في أثناء وجوده في الهواء؟', null, null, '["$9.8\\times10^{-23}\\ \\text{m/s}^2$","$9.80\\ \\text{m/s}^2$","$1.0\\times10^{-23}\\ \\text{m/s}^2$","$0\\ \\text{m/s}^2$"]'::jsonb, 'تطبيق', 'حساب وتفسير', 'متوسط', 'الكتاب ص 114–115 — مثال 3: تسارع الأرض'),
('mcq', 4, 'لماذا نتعامل عادة مع الأرض باعتبارها جزءًا من المحيط الخارجي للجسم، لا نظامًا آخر يتسارع؟', null, null, '["لأن الأرض لا تتأثر بأي قوة تؤثر بها الأجسام الصغيرة فيها","لأن الجاذبية قوة مجال لا تخضع لقانون نيوتن الثالث مطلقًا","لأن الأرض ساكنة دائمًا ولا تتحرك تحت تأثير أي قوة مهما كانت","لأن تسارعها الناتج عن الأجسام الصغيرة متناهٍ في الصغر"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 113 — قانون نيوتن الثالث'),
('mcq', 5, 'لو تضاعفت كتلة الكرة الساقطة نحو الأرض، فماذا يحدث لمقدار التسارع الذي تكتسبه الأرض؟', null, null, '["لا يتغير مقداره","يتضاعف مقداره","يقل إلى النصف","يصبح أربعة أمثاله"]'::jsonb, 'تحليل', 'تنبؤ', 'صعب', 'الكتاب ص 114–115 — مثال 3: تسارع الأرض'),
('mcq', 6, 'أيّ العبارات الآتية تصف القوتين والتسارعين في تفاعل كرة ساقطة مع الأرض وصفًا صحيحًا؟', null, null, '["القوتان متساويتان في المقدار، والتسارعان مختلفان كثيرًا","القوتان متساويتان في المقدار، والتسارعان متساويان كذلك تمامًا","القوتان مختلفتان، والتسارعان متساويان","القوتان مختلفتان، والتسارعان مختلفان"]'::jsonb, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 114–115 — مثال 3: تسارع الأرض'),
('mcq', 7, 'عند تفسير عدم ملاحظة تسارع الأرض نحو جسم ساقط، أيّ القوانين نستخدم؟', null, null, '["قانون نيوتن الأول وحده لأن الأرض متزنة","قانون نيوتن الثالث وحده؛ لأنه يعطي القوتين والتسارعين","الثالث لمساواة القوتين، ثم الثاني لحساب تسارع الأرض","الثاني وحده؛ لأن القوتين مختلفتان في المقدار"]'::jsonb, 'فهم', 'تحديد قوانين', 'متوسط', 'الكتاب ص 114–115 — مثال 3: تسارع الأرض'),
('essay', 1, 'سقطت صخرة من جسر إلى وادٍ، فتسارعت نتيجة قوة جذب الأرض لها إلى أسفل. وبحسب قانون نيوتن الثالث فإن الصخرة تؤثر أيضًا في الأرض بقوة جذب، ولكن لا يبدو أن الأرض تتسارع إلى أعلى. فسّر ذلك.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 125 — تقويم الفصل 4 (إتقان المفاهيم)'),
('essay', 2, 'تسقط كرة كتلتها 0.18 kg نحو الأرض بتسارع 9.80 m/s²، وكتلة الأرض $6.0\times10^{24}\ \text{kg}$. (أ) بيّن باستخدام قانوني نيوتن الثالث والثاني أن نسبة مقدار تسارع الكرة إلى مقدار تسارع الأرض تساوي نسبة كتلة الأرض إلى كتلة الكرة. (ب) احسب هذه النسبة، ثم استنتج تسارع الأرض. (ج) فسّر لماذا نتعامل مع الأرض عادة باعتبارها جزءًا من المحيط الخارجي للكرة لا نظامًا آخر.', null, null, null, 'تطبيق', 'حساب وتفسير', 'متوسط', 'الكتاب ص 114–115 — مثال 3: تسارع الأرض'),
('essay', 3, 'متزلجان متساويان في الكتلة يدفع أحدهما الآخر فيتحركان متباعدين بتسارعين متساويين في المقدار، بينما عندما تسقط كرة نحو الأرض تتسارع الكرة وحدها بشكل ملحوظ. حلّل الحالتين مبينًا ما هو مشترك بينهما وما يختلف، ولماذا يكون تسارع الأرض غير ملحوظ.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 113 — قانون نيوتن الثالث')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
