from (values
('mcq', 1, 1, 'القوتان زوجا تأثير متبادل متساويتان في المقدار (نحو 1.8 N): $\boldsymbol{F}_{\text{الكرة في الأرض}} = -\boldsymbol{F}_{\text{الأرض في الكرة}}$. لكن وفق قانون نيوتن الثاني $a_{\text{الأرض}} = \frac{F_{\text{المحصلة}}}{m_{\text{الأرض}}}$، وكتلة الأرض $6.0\times10^{24}\ \text{kg}$ فيكون تسارعها نحو $2.9\times10^{-25}\ \text{m/s}^2$، وهو متناهٍ في الصغر لا يُلاحظ.', '["القوتان زوجا تأثير متبادل، فهما متساويتان في المقدار.","","الكرة تجذب الأرض بقوة (السهم 2) مساوية لقوة جذب الأرض لها.","القوتان في جسمين مختلفين، فلا تلغي إحداهما الأخرى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.660Z"}'::jsonb),
('mcq', 2, 2, 'القوتان متساويتان في المقدار $F$، فتسارع الكرة $\frac{F}{m_{\text{الكرة}}}$ وتسارع الأرض $a_{\text{الأرض}} = \frac{F}{m_{\text{الأرض}}}$؛ ونسبة الأول إلى الثاني تساوي $\frac{m_{\text{الأرض}}}{m_{\text{الكرة}}}$، وهي عدد هائل.', '["تساوي القوتين لا يعني تساوي التسارعين؛ فالتسارع يعتمد على الكتلة أيضًا.","الكتلة الأكبر تعني تسارعًا أصغر عند القوة نفسها.","","الأرض تتسارع فعلًا، لكن تسارعها متناهٍ في الصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-19T07:48:34.660Z"}'::jsonb),
('mcq', 3, 0, 'الشخص يجذب الأرض بقوة 588 N (قانون نيوتن الثالث)، فتسارعها $a = \frac{588\ \text{N}}{6.0\times10^{24}\ \text{kg}} = 9.8\times10^{-23}\ \text{m/s}^2$ (قانون نيوتن الثاني)، وهو مقدار لا يمكن ملاحظته.', '["","هذا تسارع الشخص لا الأرض؛ فكتلة الأرض أكبر كثيرًا.","قُسمت كتلة الشخص على كتلة الأرض بدل قسمة القوة.","الأرض تتسارع فعلًا وإن كان تسارعها متناهيًا في الصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-19T07:48:34.660Z"}'::jsonb),
('mcq', 4, 3, 'التسارع الذي تكتسبه الأرض من قوة جسم يتفاعل معها يكون عادة متناهيًا في الصغر بسبب كتلتها الهائلة، لذلك يُتعامل معها باعتبارها جزءًا من المحيط الخارجي لا نظامًا آخر.', '["الأجسام تؤثر في الأرض بقوى مساوية لقوى الأرض فيها.","قانون نيوتن الثالث ينطبق على قوى المجال أيضًا.","الأرض تتسارع بالقوى المؤثرة فيها، لكن تسارعها صغير جدًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.660Z"}'::jsonb),
('mcq', 5, 1, 'قوة الكرة في الأرض تساوي في المقدار وزن الكرة $m_{\text{الكرة}}g$، فإذا تضاعفت كتلة الكرة تضاعفت القوة، ومن $a_{\text{الأرض}} = \frac{F}{m_{\text{الأرض}}}$ يتضاعف تسارع الأرض، ويبقى متناهيًا في الصغر.', '["القوة التي تجذب بها الكرة الأرض تساوي وزن الكرة، فتتضاعف بتضاعف كتلتها، فيتضاعف تسارع الأرض.","","زيادة كتلة الكرة تزيد القوة المؤثرة في الأرض ولا تقللها.","القوة تتناسب طرديًا مع كتلة الكرة لا مع مربعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-19T07:48:34.660Z"}'::jsonb),
('mcq', 6, 0, 'وفق قانون نيوتن الثالث القوتان متساويتان في المقدار، ووفق الثاني يكون التسارع أكبر كثيرًا للكرة الصغيرة الكتلة ومتناهيًا في الصغر للأرض.', '["","التسارع يعتمد على الكتلة، والكتلتان مختلفتان كثيرًا.","القوتان متساويتان وفق قانون نيوتن الثالث، والتسارعان مختلفان.","القوتان زوجا تأثير متبادل فهما متساويتان في المقدار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-19T07:48:34.660Z"}'::jsonb),
('mcq', 7, 2, 'قانون نيوتن الثالث يبين أن $\boldsymbol{F}_{\text{الكرة في الأرض}} = -\boldsymbol{F}_{\text{الأرض في الكرة}}$، ثم يعطي قانون نيوتن الثاني تسارع الأرض $a_{\text{الأرض}} = \frac{F_{\text{المحصلة}}}{m_{\text{الأرض}}}$، وبكتلتها الهائلة يكون متناهيًا في الصغر.', '["القانون الأول يصف الحالة عند انعدام القوة المحصلة، ولا يحسب التسارع.","الثالث يعطي القوة فقط؛ ونحتاج إلى الثاني لتحويل القوة إلى تسارع.","","القوتان متساويتان، ونحتاج إلى الثالث لمعرفة القوة المؤثرة في الأرض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-19T07:48:34.661Z"}'::jsonb),
('essay', 1, null::int, null, null, 'وفق قانون نيوتن الثالث تجذب الصخرة الأرض بقوة إلى أعلى تساوي في المقدار قوة جذب الأرض للصخرة (وزن الصخرة). لكن وفق قانون نيوتن الثاني $a = \frac{F}{m}$، وكتلة الأرض هائلة جدًا مقارنة بكتلة الصخرة، فيكون تسارع الأرض متناهيًا في الصغر (من رتبة $10^{-24}\ \text{m/s}^2$ أو أقل) فلا يمكن ملاحظته، بينما تتسارع الصخرة بمقدار 9.80 m/s².', '["القوتان متساويتان (القانون الثالث)","التسارع = القوة ÷ الكتلة (القانون الثاني)","كتلة الأرض هائلة","تسارع الأرض متناهٍ في الصغر فلا يُلاحظ"]'::jsonb, '[]'::jsonb, '[{"element":"القانون الثالث","marks":1},{"element":"القانون الثاني","marks":1},{"element":"دور كتلة الأرض","marks":1},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–3 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن قوة الصخرة في الأرض أصغر من قوة الأرض فيها","القول إن تسارع الأرض صفر تمامًا","إغفال قانون نيوتن الثاني"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-19T07:48:34.661Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) وفق قانون نيوتن الثالث $\boldsymbol{F}_{\text{الكرة في الأرض}} = -\boldsymbol{F}_{\text{الأرض في الكرة}}$، فمقدارا القوتين متساويان $F$. ووفق قانون نيوتن الثاني: تسارع الكرة $a = \frac{F}{m_{\text{الكرة}}}$ وتسارع الأرض $a_{\text{الأرض}} = \frac{F}{m_{\text{الأرض}}}$، وبالقسمة: $\frac{a}{a_{\text{الأرض}}} = \frac{m_{\text{الأرض}}}{m_{\text{الكرة}}}$. (ب) $\frac{6.0\times10^{24}}{0.18} = 3.3\times10^{25}$، إذن $a_{\text{الأرض}} = \frac{9.80}{3.3\times10^{25}} = 2.9\times10^{-25}\ \text{m/s}^2$ نحو الكرة. (ج) لأن تسارع الأرض متناهٍ في الصغر لا يمكن ملاحظته، فيُهمل أثر الكرة في حركة الأرض.', '["تساوي مقداري القوتين بالقانون الثالث","التسارع = القوة ÷ الكتلة لكل من الجسمين","نسبة التسارعين = نسبة الكتلتين معكوسة","النسبة $3.3\\times10^{25}$","تسارع الأرض $2.9\\times10^{-25}$ m/s²","التفسير: تسارع غير ملحوظ فتُعامل الأرض محيطًا خارجيًا"]'::jsonb, '["$F = m_{\\text{الكرة}} a = m_{\\text{الأرض}} a_{\\text{الأرض}}$","$\\frac{a}{a_{\\text{الأرض}}} = \\frac{m_{\\text{الأرض}}}{m_{\\text{الكرة}}} = \\frac{6.0\\times10^{24}\\ \\text{kg}}{0.18\\ \\text{kg}} = 3.3\\times10^{25}$","$a_{\\text{الأرض}} = \\frac{9.80\\ \\text{m/s}^2}{3.3\\times10^{25}} = 2.9\\times10^{-25}\\ \\text{m/s}^2$"]'::jsonb, '[{"element":"(أ) الاستدلال بالقانونين","marks":2},{"element":"(ب) النسبة والتسارع","marks":2},{"element":"(ج) التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القوة على الأرض أصغر من القوة على الكرة","قلب النسبة بين الكتلتين","أخطاء في الأسس عند القسمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-19T07:48:34.661Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المشترك: في الحالتين زوجا تأثير متبادل متساويان في المقدار ومتعاكسان في الاتجاه، وكل قوة تؤثر في جسم مختلف (القانون الثالث). المختلف: نسبة الكتلتين؛ ففي المتزلجين الكتلتان متساويتان، فوفق القانون الثاني $a = \frac{F}{m}$ يتساوى التسارعان. أما في الكرة والأرض فكتلة الأرض أكبر من كتلة الكرة بمرات هائلة، فيكون تسارع الأرض أصغر من تسارع الكرة بالنسبة نفسها، أي متناهيًا في الصغر لا يُلاحظ.', '["المشترك: قوتان متساويتان متعاكستان في جسمين","المتزلجان: كتلتان متساويتان فتسارعان متساويان","الكرة والأرض: نسبة كتل هائلة","تسارع الأرض متناهٍ في الصغر بالقانون الثاني"]'::jsonb, '[]'::jsonb, '[{"element":"المشترك","marks":1},{"element":"حالة المتزلجين","marks":1},{"element":"حالة الأرض","marks":2},{"element":"الربط بالقانون الثاني","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة: يذكر جميع العناصر صحيحة مع التعليل والوحدات"},{"level":"1–4 درجات","description":"يذكر بعض العناصر صحيحة أو يخطئ في التعليل أو الحساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن القوة على الأرض أصغر","نسبة الاختلاف إلى نوع القوة (تلامس/مجال)","إغفال دور الكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-19T07:48:34.661Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P1-C4-L3-O13') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

commit;
